# plan-gating-v1: プラン順位。上位ほど数値が大きい。free=未契約、monitor=自社等(全機能相当)。
PLAN_RANK = {"free": 0, "starter": 1, "standard": 2, "pro": 3, "monitor": 99}
# 各 tier に必要な順位と、体験中に見せるバッジ表記。
TIER_RANK = {"standard": 2, "pro": 3}
TIER_BADGE = {"standard": "スタンダード", "pro": "PRO"}


def _plan_rank(plan):  # plan-gating-v1
    return PLAN_RANK.get((plan or "free").lower(), 0)


def _facility_plan_state(supabase, f_code):  # plan-gating-v1
    """施設のプラン状態を1回のDB照会で返す（バッジ判定と enforcement の共有元）。
    返り値: {plan, rank, in_trial, is_monitor}。"""
    state = {"plan": "free", "rank": 0, "in_trial": False, "is_monitor": False}
    try:
        pr = (supabase.table("facilities")
              .select("plan,trial_ends_at,is_monitor")
              .eq("facility_code", f_code).execute())
        if pr.data:
            row = pr.data[0]
            plan = row.get("plan") or "free"
            state["is_monitor"] = bool(row.get("is_monitor"))
            if state["is_monitor"]:
                plan = "monitor"  # 自社等・全機能相当
            state["plan"] = plan
            te = row.get("trial_ends_at")
            if te:
                try:
                    ted = datetime.fromisoformat(str(te).replace("Z", "+00:00"))
                    if ted > datetime.now(timezone.utc):
                        state["in_trial"] = True
                except (ValueError, TypeError):
                    pass
    except Exception as e:
        print("_facility_plan_state error: %s" % e, flush=True)
    state["rank"] = _plan_rank(state["plan"])
    return state


def _tier_ok(state, tier):  # plan-gating-v1
    """この施設のプランで tier 機能を『契約上』使えるか。体験中・モニターは常に可。"""
    if not tier:
        return True
    if state.get("in_trial") or state.get("is_monitor"):
        return True
    return state.get("rank", 0) >= TIER_RANK.get(tier, 0)


# plan-enforce-v1: プラン階層による強制アクセス制御のキルスイッチ。
#   既定 False（＝ブロックしない・バッジ表示のみ。体験開放と同じ見た目のまま）。
#   DEVで各施設の plan 値を検証してから True にすると、tier を満たさない施設は
#   該当ページで /pricing に誘導される（体験中・モニターは常に許可。既存の施設別トグルとは AND）。
PLAN_ENFORCE = False


def _plan_block_redirect(tier):  # plan-enforce-v1
    """PLAN_ENFORCE 有効時、tier を満たさない施設を /pricing へ誘導する。
    満たす／フラグ無効／未ログインなら None を返し、呼び出し側は通常処理を続ける。"""
    if not PLAN_ENFORCE or not tier:
        return None
    try:
        f_code = session.get("f_code")
        if not f_code:
            return None
        state = _facility_plan_state(get_supabase(), f_code)
        if _tier_ok(state, tier):
            return None
        return redirect(url_for("pricing"))
    except Exception as e:
        print("_plan_block_redirect error: %s" % e, flush=True)
        return None  # 判定に失敗したら安全側（通す）


STAFF_SETTING_KEYS = ("top_style", "top_layout", "drawer_side", "nav_hidden",
                      "drawer_pos", "rc_cat_order", "rc_gap_cats",
                      "assessment_pref")   # 受け付けるキーはこれだけ  assessment-select-v1


def _menu_items_visible(supabase, f_code, my_name):  # top-grid-v1
    """その職員に見せてよいメニューだけを返す。判定は既存の関数を使い回す。"""
    # 判定は既存の context_processor をそのまま呼ぶ（同じ条件がボトムナビにも効いているので、
    # ここで別の判定を書くと「ナビには出るのにグリッドに出ない」がいずれ起きる）。
    try:
        can_ledger = bool(inject_can_ledger().get("can_ledger"))
    except Exception:
        can_ledger = False
    try:
        is_dev = bool(inject_is_dev_user().get("is_dev_user"))
    except Exception:
        is_dev = False
    try:
        can_rec = bool(is_rec_expense_enabled(supabase, f_code))
    except Exception:
        can_rec = False
    try:
        can_photo = bool(is_photo_sales_enabled(supabase, f_code))  # photo-sales-v1
    except Exception:
        can_photo = False

    # plan-gating-v1: 施設プランと体験期間を判定（共有ヘルパー）。
    #   体験中(in_trial)は上位機能も表示（開放）し、プランを上回る項目に badge を付ける。
    #   体験外でプランを上回る項目は locked=True（enforcement 用の印。表示は従来どおり通す）。
    state = _facility_plan_state(supabase, f_code)
    rank = state["rank"]
    in_trial = state["in_trial"]
    # plan-gating-v1: 無料(free)・モニター施設は「永久無料」扱いとしてバッジを出さない
    #   （どちらの方法で無料にしてもバッジが出っ放しにならないようにする安全網）。
    plan_exempt = state["plan"] in ("free", "monitor")

    out = []
    for it in MENU_ITEMS:
        need = it.get("need")
        if need == "ledger" and not can_ledger:
            continue
        if need == "rec_expense" and not can_rec:
            continue
        if need == "photo" and not can_photo:  # photo-sales-v1: 既定OFF。開発者MENUで許可した施設のみ
            continue
        if need == "dev" and not is_dev:
            continue
        item = {"href": it["href"], "icon": it["icon"], "label": it["label"]}
        # plan-gating-v1: プラン下限を上回る（この施設のプランに含まれない）機能。
        #   バッジは「体験中のみ」表示する（有料運用に入ったら邪魔になるため出さない）。
        #   locked は enforcement 用のフラグで、体験外のときだけ立てる（表示はしない）。
        tier = it.get("tier")
        if tier and not plan_exempt and rank < TIER_RANK.get(tier, 0):
            if in_trial:
                item["badge"] = TIER_BADGE.get(tier)
                item["tier"] = tier
            else:
                item["locked"] = True
        out.append(item)
    return out


def get_staff_setting(supabase, f_code, staff_name, key, default=None):  # staff-settings-v1
    """職員の個人設定。無ければ default。"""
    try:
        r = (supabase.table("staff_settings").select("value")
             .eq("facility_code", f_code).eq("staff_name", staff_name)
             .eq("key", key).execute())
        if r.data and r.data[0].get("value") is not None:
            return r.data[0]["value"]
    except Exception as e:
        print("get_staff_setting error: %s" % e, flush=True)
    return default


def set_staff_setting(supabase, f_code, staff_name, key, value):  # staff-settings-v1
    """職員の個人設定を書く（既存パターンに合わせた手書き upsert）。"""
    row = {"facility_code": f_code, "staff_name": staff_name, "key": key,
           "value": value, "updated_at": datetime.now(timezone.utc).isoformat()}
    try:
        r = (supabase.table("staff_settings").select("id")
             .eq("facility_code", f_code).eq("staff_name", staff_name)
             .eq("key", key).execute())
        if r.data:
            supabase.table("staff_settings").update(row).eq("id", r.data[0]["id"]).execute()
        else:
            supabase.table("staff_settings").insert(row).execute()
        return True
    except Exception as e:
        print("set_staff_setting error: %s" % e, flush=True)
        return False


@app.context_processor
def inject_app_drawer():  # app-drawer-v1
    """引き出しメニュー（全画面）。メニュー項目と、出る端（利き手）を渡す。

    毎リクエスト DB を叩くので flask.g に1回だけキャッシュする
    （can_rec_expense が同じ作りなので、それに合わせた）。"""
    from flask import g as _g   # 既存コードに合わせてローカルで import する
    try:
        f_code = session.get("f_code")
        my_name = session.get("my_name")
        if not f_code or not my_name:
            return {"drawer_items": [], "drawer_side": "right", "drawer_layout": "",
                    "nav_hidden": False, "drawer_pos": 46}
        if not hasattr(_g, "_drawer_cache"):
            supabase = get_supabase()
            # app-drawer-4way-v1: 左右に加えて上下も
            side = get_staff_setting(supabase, f_code, my_name, "drawer_side", "right")
            if side not in ("left", "right", "top", "bottom"):
                side = "right"
            # app-drawer-edit-v1: 配置（自由配置・フォルダ）。中身の解釈は画面側でやる。
            layout = get_staff_setting(supabase, f_code, my_name, "top_layout", "") or ""
            # nav-hide-v1: ボトムナビを隠しているか（個人設定）
            nav_hidden = (get_staff_setting(supabase, f_code, my_name, "nav_hidden", "false") == "true")
            # nav-hide-v3 / app-drawer-perside-v1:
            # 取っ手の位置。向きごとに持つ（JSON文字列）。旧形式（数値）もそのまま渡し、画面側で読み替える。
            pos = get_staff_setting(supabase, f_code, my_name, "drawer_pos", "") or ""
            _g._drawer_cache = {
                "drawer_items": _menu_items_visible(supabase, f_code, my_name),
                "drawer_side": side,
                "drawer_layout": layout,
                "nav_hidden": nav_hidden,
                "drawer_pos": pos,
            }
        return _g._drawer_cache
    except Exception as e:
        print("inject_app_drawer error: %s" % e, flush=True)
        return {"drawer_items": [], "drawer_side": "right", "drawer_layout": "",
                "nav_hidden": False, "drawer_pos": 46}


@app.route("/api/me/setting", methods=["GET"])  # staff-settings-v1
@login_required
def api_me_setting_get():
    key = (request.args.get("key") or "").strip()
    if key not in STAFF_SETTING_KEYS:
        return jsonify({"status": "error", "message": "不正なキーです"}), 400
    v = get_staff_setting(get_supabase(), session["f_code"], session["my_name"], key)
    return jsonify({"status": "success", "key": key, "value": v})


@app.route("/api/me/setting", methods=["PUT"])  # staff-settings-v1
@login_required
def api_me_setting_put():
    data = request.json or {}
    key = str(data.get("key") or "").strip()
    if key not in STAFF_SETTING_KEYS:
        return jsonify({"status": "error", "message": "不正なキーです"}), 400
    val = data.get("value")
    val = "" if val is None else str(val)
    if len(val) > 20000:
        return jsonify({"status": "error", "message": "設定が大きすぎます"}), 400
    ok = set_staff_setting(get_supabase(), session["f_code"], session["my_name"], key, val)
    if not ok:
        return jsonify({"status": "error", "message": "保存できませんでした"}), 500
    return jsonify({"status": "success"})

# ===== /top-grid-v1 =====


@app.route('/top')
@login_required
def top():
    f_code = session["f_code"]
    my_name = session["my_name"]
    supabase = get_supabase()

    hist_limit = 30
    try:
        res_l = supabase.table("admin_settings").select("value").eq("key", "history_limit").eq("facility_code", f_code).execute()
        if res_l.data:
            hist_limit = int(res_l.data[0]['value'])
    except:
        pass

    records = []
    try:
        res_hist = supabase.table("records").select(
            "id, user_name, staff_name, created_at"
        ).eq("facility_code", f_code).order("id", desc=True).limit(hist_limit * 2).execute()
        if res_hist.data:
            # id降順（DB挿入順）でソートすることで、未来日付の記録が上に鎮座しなくなる
            filtered = [r for r in res_hist.data if r['staff_name'] != "AI統合記録"][:hist_limit]
            for r in filtered:
                records.append({
                    "user_name": r["user_name"],
                    "time": parse_jst(r["created_at"]),
                    "date": str(parse_jst_date(r["created_at"])),
                })
    except:
        pass

    # 自分のアイコン情報を取得
    my_icon_emoji = ""
    my_icon_image_url = ""
    try:
        icon_res = supabase.table("staffs").select("icon_emoji,icon_image_url").eq("facility_code", f_code).eq("staff_name", my_name).execute()
        if icon_res.data:
            my_icon_emoji = icon_res.data[0].get("icon_emoji") or ""
            my_icon_image_url = icon_res.data[0].get("icon_image_url") or ""
    except:
        pass

    # タスク取得（自分が関わる未完了のみ）
    my_tasks = []
    try:
        task_res = supabase.table("tasks").select("id,title,due_date,priority,status,assigned_to,created_by").eq("facility_code", f_code).neq("status", "done").order("due_date").execute()
        # top-task-meta: 期限の緊急/超過フラグと優先度ラベルを付与
        from datetime import datetime as _dttsk, date as _dtsk
        _today_tsk = _dtsk.today()
        _prio_lbl = {"high": "高", "medium": "中", "low": "低"}
        for t in (task_res.data or []):
            if t.get("created_by") == my_name or my_name in (t.get("assigned_to") or []) or not t.get("assigned_to"):
                t["priority_label"] = _prio_lbl.get(t.get("priority") or "medium", "中")
                t["due_urgent"] = False
                t["overdue"] = False
                if t.get("due_date"):
                    try:
                        _dd = _dttsk.strptime(str(t["due_date"]), "%Y-%m-%d").date()
                        _diff = (_dd - _today_tsk).days
                        if _diff < 0:
                            t["overdue"] = True
                        elif _diff <= 7:
                            t["due_urgent"] = True
                    except Exception:
                        pass
                my_tasks.append(t)
    except:
        pass
    # app-drawer-v1: TOP は従来どおり。アイコン一覧は全画面の引き出し（base.html）へ移した。
    return render("top.html", f_code=f_code, my_name=my_name, records=records,
        birthday_users=get_birthday_users(supabase, f_code),
        my_tasks=my_tasks,
        my_icon_emoji=my_icon_emoji,
        my_icon_image_url=my_icon_image_url,
        my_color=staff_color(my_name),
        my_initial=staff_initial(my_name),
        contract=_contract_overview(f_code),  # pricing-rebuild-v1
    )

def _rc_staff_view(supabase, f_code, my_name, cats):  # record-check-view-v1
    """充足チェックの個人ビュー。並び順(rc_cat_order)と未記入対象(rc_gap_cats)を適用。
    cats: [{'name','color'}...](sort_order順)。各要素に 'target'(未記入判定の対象か) を付けて、
    個人の並び順に並べ替えたリストを返す。設定が無ければ元の順・全カテゴリ対象。"""
    import json as _sv_json
    order = []
    try:
        raw = get_staff_setting(supabase, f_code, my_name, "rc_cat_order")
        if raw:
            order = [str(x) for x in _sv_json.loads(raw)]
    except Exception:
        order = []
    ordered, seen = [], set()
    for nm in order:
        for c in cats:
            if c.get("name") == nm and nm not in seen:
                ordered.append(c)
                seen.add(nm)
    for c in cats:
        if c.get("name") not in seen:
            ordered.append(c)
            seen.add(c.get("name"))
    names = set(c.get("name") for c in cats)
    target = None
    try:
        raw2 = get_staff_setting(supabase, f_code, my_name, "rc_gap_cats")
        if raw2:
            lst = [str(x) for x in _sv_json.loads(raw2)]
            target = set(n for n in lst if n in names)
    except Exception:
        target = None
    for c in ordered:
        c["target"] = True if target is None else (c.get("name") in target)
    return ordered


# ===== record-check-v1 : 記録の充足チェック =====
# その日に来ている利用者 × カテゴリ別の記録件数。「来ているのに記録が無い」を見つける。


@app.route("/record_check")   # record-check-v1
@login_required
def record_check():
    f_code = session["f_code"]
    my_name = session["my_name"]
    supabase = get_supabase()

    date_str = (request.args.get("date") or "").strip()
    try:
        sel = datetime.strptime(date_str, "%Y-%m-%d").date()
    except (TypeError, ValueError):
        sel = datetime.now(tokyo_tz).date()
    date_str = sel.strftime("%Y-%m-%d")

    # --- 来ている人（その日のバイタル）。連絡帳・請求額計算と同じ判定にする ---
    try:
        vres = (supabase.table("vitals").select("patient_id")
                .eq("facility_code", f_code).eq("measured_date", date_str).execute())
    except Exception as e:
        print("record_check vitals error: %s" % e, flush=True)
        vres = None
    pids, seen = [], set()
    for v in ((vres.data if vres else None) or []):
        pid = str(v.get("patient_id") or "")
        if pid and pid not in seen:
            seen.add(pid)
            pids.append(pid)

    plist = get_patients(supabase, f_code)
    pmap = dict((str(p["id"]), p) for p in plist)
    people = []
    for pid in pids:
        prof = pmap.get(pid) or {}
        nm = prof.get("user_name") or ""
        if not nm:
            continue
        people.append({
            "user_name": nm,
            "user_kana": prof.get("user_kana") or "",
            "patient_number": prof.get("patient_number") or "",
        })
    people.sort(key=lambda x: (x.get("user_kana") or x.get("user_name") or ""))

    # --- カテゴリ（施設ごと。色と並び順つき） ---
    cats = []
    try:
        cres = (supabase.table("record_categories").select("name,color,sort_order")
                .eq("facility_code", f_code).order("sort_order").order("id").execute())
        cats = [{"name": c.get("name") or "", "color": c.get("color") or "#5f6368"}
                for c in (cres.data or []) if (c.get("name") or "").strip()]
    except Exception as e:
        print("record_check categories error: %s" % e, flush=True)
    if not cats:
        cats = [{"name": n, "color": "#5f6368"} for n in ("入浴", "食事", "排泄", "その他")]
    cat_names = [c["name"] for c in cats]
    if "その他" not in cat_names:
        cats.append({"name": "その他", "color": "#9aa0a6"})   # 登録に無いカテゴリの受け皿

    # record-check-view-v1: 個人ごとの並び順(rc_cat_order)と未記入対象(rc_gap_cats)を適用
    cats = _rc_staff_view(supabase, f_code, my_name, cats)
    cat_names = [c["name"] for c in cats]
    import json as _rc_json
    cats_json = _rc_json.dumps([{"name": c["name"], "target": bool(c.get("target", True))}
                               for c in cats], ensure_ascii=False)

    # --- その日の記録（JSTの日境界。records は patient_id を持たず user_name で突合） ---
    t_start = tokyo_tz.localize(datetime.combine(sel, dt_time.min))
    counts = {}     # user_name -> {category -> 件数}
    total_records = 0
    try:
        rres = (supabase.table("records").select("user_name,category")
                .eq("facility_code", f_code)
                .gte("created_at", t_start.isoformat())
                .lt("created_at", (t_start + timedelta(days=1)).isoformat())
                .execute())
        for r in (rres.data or []):
            nm = (r.get("user_name") or "").strip()
            if not nm:
                continue
            cat = (r.get("category") or "その他").strip() or "その他"
            if cat not in cat_names:
                cat = "その他"      # 登録に無いカテゴリはその他にまとめる
            counts.setdefault(nm, {})
            counts[nm][cat] = counts[nm].get(cat, 0) + 1
            total_records += 1
    except Exception as e:
        print("record_check records error: %s" % e, flush=True)

    target_names = set(c["name"] for c in cats if c.get("target", True))
    rows = []
    zero = 0
    for p in people:
        c = counts.get(p["user_name"], {})
        tot = sum(c.values())
        has_gap = any((c.get(cn, 0) == 0) for cn in target_names) if target_names else False
        if has_gap:
            zero += 1
        rows.append({
            "user_name": p["user_name"],
            "patient_number": p["patient_number"],
            "cells": [c.get(cn, 0) for cn in cat_names],
            "total": tot,
            "has_gap": has_gap,
        })

    return render("record_check.html", f_code=f_code, my_name=my_name,
                  date=date_str,
                  date_label=sel.strftime("%-m月%-d日"),
                  cats=cats, rows=rows, cats_json=cats_json,
                  n_people=len(rows), n_zero=zero, n_records=total_records)

# ===== /record-check-v1 =====


# ===== monitoring-check-v1 : 月間の記録充足チェック（その月に来所した利用者×カテゴリ別の件数。0件=赤） =====
