DEFAULT_VITAL_SETTINGS = {
    "bp_high_max": 140, "bp_high_min": 90,
    "bp_low_max": 90,   "bp_low_min": 60,
    "pulse_max": 100,   "pulse_min": 50,
    "temp_max": 37.5,   "temp_min": 35.0,
    "spo2_min": 94,
    "recheck_notify": True,
    "recheck_time": "10:00",
    "recheck_times": "10:00",
}

def get_vital_settings(supabase, f_code):
    try:
        res = supabase.table("vital_alert_settings").select("*").eq("facility_code", f_code).execute()
        if res.data:
            d = res.data[0]
            return {k: d.get(k, v) for k, v in DEFAULT_VITAL_SETTINGS.items()}
    except: pass
    return DEFAULT_VITAL_SETTINGS.copy()

# ===== visit-mgmt-v1 / visit-mgmt-idfix-v1: 利用管理(予定×実績 月間集約・閲覧ハブ) =====
def _visit_weekday_of(date_str):
    """date_str(YYYY-MM-DD)の曜日を JS getDay基準(日曜=0〜土曜=6)で返す。"""
    from datetime import datetime as _dt
    d = _dt.strptime(date_str, "%Y-%m-%d")
    return (d.weekday() + 1) % 7  # Python月=0..日=6 → 日=0..土=6

def _visit_is_planned_weekday(weekdays, date_str, nth_per_day=None):
    """weekdays(例 '135', 日曜=0基準の数字並び)に その日の曜日が含まれるか。

    visit-nth-apply-v1: 「第N週のみ」の指定があれば、その週でないと予定日ではない。
    （例: 火曜が第2週のみ → 第1・3・4火曜は予定日でない）
    """
    if not weekdays:
        return False
    wd = _visit_weekday_of(date_str)
    if str(wd) not in str(weekdays):
        return False
    if nth_per_day and not visit_nth_ok(nth_per_day, wd, date_str):
        return False
    return True

def _visit_planned_weekdays_for(supabase, f_code, patient_int_id):
    """指定患者(patients.id=patient_int_id)の weekdays 文字列を返す。"""
    try:
        res = supabase.table("patient_visit_days").select("weekdays").eq("facility_code", f_code).eq("patient_id", patient_int_id).execute()
        if res.data:
            return res.data[0].get("weekdays") or ""
    except Exception as e:
        # visit-unknown-not-transfer-v1: 失敗は None。
        # ★"" を返すと「予定曜日の登録が無い」と同じ意味になり、振替として保存されてしまう。
        print(f"visit planned weekdays error: {e}", flush=True)
        return None
    return ""

def _visit_nth_for(supabase, f_code, patient_int_id):  # visit-nth-apply-v1
    """指定患者の「第N週のみ」設定。無ければ {}（＝毎週）。"""
    try:
        res = (supabase.table("patient_visit_days").select("nth_per_day")
               .eq("facility_code", f_code).eq("patient_id", patient_int_id).execute())
        if res.data:
            return _visit_norm_nth(res.data[0].get("nth_per_day"))
    except Exception as e:
        print(f"visit nth fetch error: {e}", flush=True)
    return {}

def _visit_lookup_int_id_light(supabase, f_code, patient_pid):
    """visit-resolve-light-v1: 1人ぶんだけ引いて patients.id を求める。
    返り値 (patient_int_id, ok, 理由)。
      理由: 'ok' / 'error'(問い合わせ失敗) / 'no_profile' / 'no_match' / 'ambiguous'
      ★'error' のときだけ再試行する意味がある。他は何度やっても同じ。

    ★なぜ get_patients() を使わないか:
      あちらは patient_profiles を select("*") で全件・全列、patients も全件取ってくる。
      1人ぶんのID変換にそれをやると重く、混雑時に落ちやすい。
      2026-08-25 09:14 に実際に落ちて、来所記録が「振替」に化けた。
    """
    try:
        _pr = (supabase.table("patient_profiles").select("user_name")
               .eq("facility_code", f_code).eq("id", str(patient_pid)).limit(1).execute())
    except Exception as _e1:
        print(f"[visit] 突合(軽量): patient_profiles の取得に失敗: {_e1}", flush=True)
        return (None, False, "error")
    _rows = _pr.data or []
    if not _rows:
        return (None, False, "no_profile")
    _name = (_rows[0].get("user_name") or "").strip()
    if not _name:
        return (None, False, "no_profile")
    try:
        _pt = (supabase.table("patients").select("id")
               .eq("facility_code", f_code).eq("user_name", _name).limit(2).execute())
    except Exception as _e2:
        print(f"[visit] 突合(軽量): patients の取得に失敗: {_e2}", flush=True)
        return (None, False, "error")
    _prows = _pt.data or []
    if not _prows:
        return (None, False, "no_match")
    if len(_prows) > 1:
        # ★同じ氏名の行が2つ以上ある。get_patients() の辞書だと後の方で黙って上書きされ、
        #   予定曜日を持たない側を掴むことがあった。どちらが正しいか決められないので書かない。
        print("[visit] 突合(軽量): 同じ氏名の patients 行が複数。判定を見送る", flush=True)
        return (None, False, "ambiguous")
    return (_prows[0].get("id"), True, "ok")


def _visit_resolve_int_id(supabase, f_code, patient_pid):
    """visit-unknown-not-transfer-v1: patient_profiles.id から patients.id を解決する。
    返り値 (patient_int_id, ok)。ok=False は「調べられなかった」。

    ★ok=False のとき、呼び出し側は来所記録を書かないこと。
      書くと「判定できなかった日」が「振替」として業務データに残り、
      本物の振替と見分けられなくなる。請求・実績に効く数字なので影響が大きい。
    ★突合は patient_profiles.user_name と patients.user_name の文字列一致。
      漢字1字・全角半角スペースの違いでも成立しない。だから失敗を無視できない。
    """
    import time as _t_retry
    # visit-resolve-retry-v1: 一瞬の混雑で失敗しただけなら、少し待てば通る。
    # ★再試行するのは「問い合わせに失敗した」ときだけ。
    #   該当者がいない/氏名が一致しない/同姓が複数 はデータの問題で、
    #   何度やっても同じ。待つだけバイタル保存の応答が遅くなるので即あきらめる。
    _why = "error"
    for _attempt in (1, 2, 3):
        # visit-resolve-light-v1: 名簿の全件取得をやめ、1人ぶんだけ引く
        _vint, _ok, _why = _visit_lookup_int_id_light(supabase, f_code, patient_pid)
        if _ok:
            if _attempt > 1:
                print(f"[visit] 突合: {_attempt}回目で成功(混雑からの復帰)", flush=True)
            return (_vint, True)
        if _why != "error":
            print(f"[visit] 突合できず({_why})。データの問題なので再試行しない", flush=True)
            return (None, False)
        if _attempt < 3:
            _t_retry.sleep(0.5 * _attempt)   # 0.5秒 → 1.0秒
    print("[visit] 突合できず(3回とも問い合わせに失敗)", flush=True)
    return (None, False)


def _visit_auto_upsert(supabase, f_code, patient_pid, date_str, staff_name, patient_int_id):
    """バイタル保存時の自動実績。予定曜日なら present、予定外なら transfer。
    手動(source=manual)レコードは上書きしない。"""
    try:
        from datetime import datetime as _dt, timezone as _tz
        now_iso = _dt.now(_tz.utc).isoformat()
        weekdays = _visit_planned_weekdays_for(supabase, f_code, patient_int_id) if patient_int_id else ""
        # visit-unknown-not-transfer-v1: None は「調べられなかった」。書かずに次回に任せる。
        # 空欄は直せるが、誤った「振替」は本物と区別が付かなくなる。
        if weekdays is None:
            print(f"[visit] 予定曜日を取得できず、来所記録を書かない date={date_str}", flush=True)
            return
        nth = _visit_nth_for(supabase, f_code, patient_int_id) if patient_int_id else {}  # visit-nth-apply-v1
        status = 'present' if _visit_is_planned_weekday(weekdays, date_str, nth) else 'transfer'
        existing = supabase.table('visit_records').select('id,status,source').eq('facility_code', f_code).eq('patient_id', str(patient_pid)).eq('visit_date', date_str).execute()
        if existing.data:
            row = existing.data[0]
            if row.get('source') == 'manual':
                return  # 手動は尊重
            supabase.table('visit_records').update({'status': status, 'source': 'vital_auto', 'checked_at': now_iso, 'updated_at': now_iso}).eq('id', row['id']).execute()
        else:
            supabase.table('visit_records').insert({
                'facility_code': f_code, 'patient_id': str(patient_pid), 'visit_date': date_str,
                'status': status, 'source': 'vital_auto', 'checked_at': now_iso, 'staff_name': staff_name,
            }).execute()
    except Exception as e:
        print(f"visit auto upsert error: {e}", flush=True)

def _visit_cleanup_on_vital_delete(supabase, f_code, patient_pid, date_str):
    """バイタル削除後、その日に他バイタルが無ければ vital_auto の visit_records を削除。"""
    try:
        if not patient_pid or not date_str:
            return
        remain = supabase.table('vitals').select('id').eq('facility_code', f_code).eq('patient_id', patient_pid).eq('measured_date', date_str).execute()
        if remain.data:
            return  # まだバイタルが残っている
        # 自動分のみ削除(手動は残す)
        supabase.table('visit_records').delete().eq('facility_code', f_code).eq('patient_id', str(patient_pid)).eq('visit_date', date_str).eq('source', 'vital_auto').execute()
    except Exception as e:
        print(f"visit cleanup on vital delete error: {e}", flush=True)

