@app.route('/api/add_vital', methods=['POST'])
@login_required
def api_add_vital():
    """新規測定をINSERT(同じpatient_id+date があっても新しいレコード作成)"""
    try:
        data = request.json
        f_code = session["f_code"]
        my_name = session["my_name"]
        supabase = get_supabase()
        now_iso = datetime.now(timezone.utc).isoformat()

        if not data.get("patient_id") or not data.get("measured_date"):
            return jsonify({"status": "error", "message": "patient_idとmeasured_dateは必須です"}), 400

        # offline-dedup-v1: 同じ client_uid が既に登録済みなら二重登録しない（オフライン再送対策）
        _cuid = (data.get("client_uid") or "").strip()
        if _cuid:
            try:
                _dup = supabase.table("vitals").select("id").eq("facility_code", f_code).eq("client_uid", _cuid).limit(1).execute()
                if _dup.data:
                    return jsonify({"status": "success", "id": _dup.data[0]["id"], "duplicate": True})
            except Exception as _de:
                print(f"[add_vital dedup] {_de}", flush=True)

        payload = {
            "facility_code": f_code,
            "client_uid": _cuid or None,
            "patient_id": str(data.get("patient_id")),
            "user_name": data.get("user_name", ""),
            "measured_date": data.get("measured_date"),
            "measured_at": data.get("measured_at") or now_iso,
            "bp_high": data.get("bp_high"),
            "bp_low": data.get("bp_low"),
            "pulse": data.get("pulse"),
            "temperature": data.get("temperature"),
            "spo2": data.get("spo2"),
            "note": data.get("note", ""),
            "recheck": data.get("recheck", False),
            "staff_name": my_name,
        }
        res = supabase.table("vitals").insert(payload).execute()
        rid = res.data[0]["id"] if res.data else None
        # visit-mgmt-v1: バイタル保存で来所自動記録
        try:
            # visit-unknown-not-transfer-v1: 突合に失敗した日は書かない(振替に化けるため)
            _vint, _vok = _visit_resolve_int_id(supabase, f_code, data.get("patient_id"))
            if _vok:
                _visit_auto_upsert(supabase, f_code, data.get("patient_id"), data.get("measured_date"), my_name, _vint)
            else:
                print(f"[visit] 来所記録を見送り date={data.get('measured_date')}", flush=True)
        except Exception as _vae:
            # visit-guard-failclosed-v1: 記録に残す（理由は上の api_save_vital と同じ）
            print("[visit] 来所自動記録に失敗: date=%s err=%s"
                  % (data.get('measured_date'), _vae), flush=True)
        return jsonify({"status": "success", "id": rid})
    except Exception as e:
        print(f"add_vital error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500

