@app.route('/admin_auth', methods=['POST'])
@login_required
def admin_auth():
    f_code = session["f_code"]
    pw = request.form.get("admin_pw", "")
    mode = request.form.get("mode", "admin")  # admin or dev
    # admin-lockout-v1 : 認証段ごとに失敗ロック(施設コード#段 + IP)
    _al_ip = _login_client_ip()
    _al_key = f"{f_code}#dev" if mode == "dev" else f"{f_code}#admin"
    if _login_is_locked(get_supabase(), _al_key, _al_ip):
        return render_template("admin.html",
            authenticated=False, dev_mode=(mode == "dev"),
            patients=[], blocked=[], staff_list=[],
            hist_limit=30,
            error="認証に何度も失敗したため、しばらくロックされています。約15分後に再度お試しください。",
            claude_url=None, registered_staffs=[], f_code=f_code,
            board_editors=[], admin_managers=[])

    # 開発者認証
    if mode == "dev":
        dev_pw = get_secret("DEV_PASSWORD") or "tasukaru-dev-2024"
        if pw == dev_pw:
            _login_clear_fail(get_supabase(), _al_key, _al_ip)  # admin-lockout-v1
            session["dev_authenticated"] = True
            return redirect(url_for("dev_menu"))
        else:
            _login_record_fail(get_supabase(), _al_key, _al_ip)  # admin-lockout-v1
            return render_template("admin.html",
                authenticated=False, dev_mode=True,
                patients=[], blocked=[], staff_list=[],
                hist_limit=30, error="開発者パスワードが違います。",
                claude_url=None, registered_staffs=[], f_code=f_code
            ,
            board_editors=[], admin_managers=[])

    # 管理者認証(個人パスワード + admin_managers リストに含まれているかチェック)
    try:
        import hashlib
        def verify_password(p, h):
            return hashlib.sha256(p.encode()).hexdigest() == h
        supabase = get_supabase()
        my_name = session.get("my_name", "")

        # まず、ログイン中スタッフの個人パスワードと一致するか確認
        staff_res = supabase.table("staffs").select("staff_name,password_hash,email,line_user_id").eq(  # admin-2fa-select-fix-v1
            "facility_code", f_code
        ).eq("staff_name", my_name).eq("is_active", True).execute()

        if not staff_res.data:
            return render_template("admin.html",
                authenticated=False, dev_mode=False,
                patients=[], blocked=[], staff_list=[],
                hist_limit=30, error="ログイン情報が確認できません。",
                claude_url=None, registered_staffs=[], f_code=f_code,
                board_editors=[], admin_managers=[])

        s = staff_res.data[0]
        if not verify_password(pw, s.get("password_hash", "")):
            _login_record_fail(supabase, _al_key, _al_ip)  # admin-lockout-v1
            return render_template("admin.html",
                authenticated=False, dev_mode=False,
                patients=[], blocked=[], staff_list=[],
                hist_limit=30, error="パスワードが違います。",
                claude_url=None, registered_staffs=[], f_code=f_code,
                board_editors=[], admin_managers=[])

        # パスワードはOK、次に管理者として認可されているかチェック
        # (admin_managers リスト OR facilities.admin_email スタッフ = 超管理者)
        if not is_admin_user(supabase, f_code, my_name):
            return render_template("admin.html",
                authenticated=False, dev_mode=False,
                patients=[], blocked=[], staff_list=[],
                hist_limit=30, error="管理者権限がありません。施設の管理者にお問い合わせください。",
                claude_url=None, registered_staffs=[], f_code=f_code,
                board_editors=[], admin_managers=[])

        _login_clear_fail(supabase, _al_key, _al_ip)  # admin-lockout-v1
        # ===== admin-2fa-v1 : パスワード+権限OK。ここで2FAゲート =====
        _2fa_line_uid = (s.get("line_user_id") or "").strip()
        if not _2fa_line_uid:
            # 厳格: LINE未紐付けの管理者は入れない
            return render_template("admin.html",
                authenticated=False, dev_mode=False,
                patients=[], blocked=[], staff_list=[],
                hist_limit=30,
                error="管理者機能の利用にはLINEの紐づけが必要です。リッチメニューの「利用開始」からLINE連携を完了してから再度お試しください。",
                claude_url=None, registered_staffs=[], f_code=f_code,
                board_editors=[], admin_managers=[])
        # コード発行 + LINE送信
        if not _admin_2fa_issue(supabase, f_code, my_name, _2fa_line_uid):
            return render_template("admin.html",
                authenticated=False, dev_mode=False,
                patients=[], blocked=[], staff_list=[],
                hist_limit=30,
                error="認証コードのLINE送信に失敗しました。時間をおいて再度お試しください。",
                claude_url=None, registered_staffs=[], f_code=f_code,
                board_editors=[], admin_managers=[])
        # 認証保留状態をセッションに置く(まだ admin_authenticated にしない)
        session["pending_admin_2fa"] = {"f_code": f_code, "staff_name": my_name}
        return render_template("admin_2fa.html", staff_name=my_name, error=None)
    except Exception as e:
        return render_template("admin.html",
            authenticated=False, dev_mode=False,
            patients=[], blocked=[], staff_list=[],
            hist_limit=30, error=f"認証中にエラーが発生しました: {e}",
            claude_url=None, registered_staffs=[], f_code=f_code,
            board_editors=[], admin_managers=[])

@app.route('/admin_2fa_verify', methods=['POST'])  # admin-2fa-v1
@login_required
def admin_2fa_verify():
    pend = session.get("pending_admin_2fa") or {}
    f_code = session.get("f_code")
    my_name = session.get("my_name", "")
    # 保留状態の整合性チェック
    if not pend or pend.get("f_code") != f_code or pend.get("staff_name") != my_name:
        return redirect(url_for("admin"))
    code = (request.form.get("code", "") or "").strip()
    supabase = get_supabase()
    ok, reason = _admin_2fa_verify(supabase, f_code, my_name, code)
    if ok:
        session.pop("pending_admin_2fa", None)
        session["admin_authenticated"] = True
        return redirect(url_for("admin"))
    msg_map = {
        "expired": "コードの有効期限が切れました。最初からやり直してください。",
        "too_many": "入力回数の上限に達しました。最初からやり直してください。",
        "no_code": "有効なコードがありません。最初からやり直してください。",
    }
    if reason in ("expired", "too_many", "no_code"):
        session.pop("pending_admin_2fa", None)
        return render_template("admin.html",
            authenticated=False, dev_mode=False,
            patients=[], blocked=[], staff_list=[],
            hist_limit=30, error=msg_map.get(reason),
            claude_url=None, registered_staffs=[], f_code=f_code,
            board_editors=[], admin_managers=[])
    return render_template("admin_2fa.html", staff_name=my_name,
        error="認証コードが違います。もう一度入力してください。")

@app.route('/api/scan_patients_from_image', methods=['POST'])
@login_required
def api_scan_patients_from_image():
    """写真から利用者の名前・生年月日をGeminiで読み取る"""
    try:
        data = request.json
        image_base64 = data.get('image', '')
        mime_type    = data.get('mime_type', 'image/jpeg')

        from utils import get_generative_model, upload_audio_to_supabase
        model = get_generative_model()

        prompt = """この画像を詳しく解析してください。利用者名簿・介護ソフトの画面・紙の名簿・Excel表など、人の名前と情報が含まれている可能性があります。

画像に含まれる全ての人物の情報を読み取り、以下のJSON形式のみで返してください（前置きや説明文は一切不要）：

{"patients": [
  {
    "name": "氏名（漢字。姓と名の間のスペースは除去）",
    "kana": "ふりがな（ひらがな。読み取れなければ空文字）",
    "birth_date": "生年月日をYYYY-MM-DD形式で（和暦も西暦に変換。例：昭和30年3月15日→1955-03-15、S30.3.15→1955-03-15）",
    "chart": "カルテ番号・利用者番号・IDなど（なければ空文字）",
    "weekdays": "利用曜日の数字を連結（月=1,火=2,水=3,木=4,金=5,土=6,日=0。例：月水金→135。わからなければ空文字）",
    "ampm": "AM（午前）かPM（午後）かBOTH（両方/不明）"
  }
]}

重要な注意：
- 表の中の全ての行を漏れなく読み取ること
- 生年月日は必ず西暦YYYY-MM-DDに変換すること
- 昭和元年=1926年、平成元年=1989年、令和元年=2019年
- 読み取れない文字はそのままにせず、前後の文脈から推測すること
- 絶対にJSON以外の文字を返さないこと"""

        import json as _json
        import re as _re

        resp = model.generate_content([
            {"mime_type": mime_type, "data": image_base64},
            prompt
        ])

        text = resp.text.strip()
        # JSONを抽出
        m = _re.search(r'\{.*\}', text, _re.DOTALL)
        if not m:
            return jsonify({"status": "error", "message": "JSONを取得できませんでした", "patients": []})

        result = _json.loads(m.group())
        patients = result.get("patients", [])

        if not patients:
            return jsonify({"status": "error", "message": "利用者情報が見つかりませんでした", "patients": []})

        return jsonify({"status": "success", "patients": patients, "count": len(patients)})

    except Exception as e:
        print(f"scan_patients error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e), "patients": []}), 500

# ==========================================
# admin-patient-api-v1: 利用者管理サーバAPI (admin.htmlの直叩き置換)
# patient_profiles のみを操作(現状挙動を維持)。
# facility_code はサーバ側で session 値を強制適用し、
# フロント由来の値は信用しない。
# ==========================================
# ==========================================
# patients-sync-b1: patients連動ヘルパ(方針B 第1段)
# profilesに利用者を追加したら patients にも行を作る(孤児防止)。
# chart_number = profiles.patient_number をコピー(空ならフォールバック採番)。
# 同名patients行があれば何もしない(重複防止)。曜日は作らない(第2段)。
# ==========================================
# patient-number-zerofill-v1: 利用者番号の最低3桁ゼロ埋め整形
def _normalize_patient_number(pn):
    """数字のみなら最低3桁ゼロ埋め。3桁以上/英字含む/空はそのまま。"""
    s = (str(pn) if pn is not None else "").strip()
    if s.isdigit():
        return s.zfill(3)
    return s


# ==========================================
# clh-history-v1: 介護度履歴の記録ヘルパ
# care_level_history に「介護度＋適用開始日」を積む。
# 最新履歴と同じ介護度なら何もしない（重複防止）。
# valid_from は 'YYYY-MM-DD' 文字列 or None（Noneなら本日）。
# ==========================================
def _record_care_level_history(supabase, f_code, patient_id, new_level, valid_from=None):
    """clh-history-v1: 介護度が変わったときだけ care_level_history に1件追加。"""
    try:
        nl = (new_level or "").strip()
        if not nl:
            return False
        if not patient_id:
            return False
        # 既存履歴の最新(care_level)を取得
        prev = supabase.table("care_level_history") \
            .select("care_level") \
            .eq("facility_code", f_code).eq("patient_id", patient_id) \
            .order("valid_from", desc=True).limit(1).execute()
        prev_level = (prev.data[0]["care_level"] if prev.data else None)
        if prev_level is not None and (prev_level or "").strip() == nl:
            return False  # 変化なし
        vf = (valid_from or "").strip() or datetime.now(tokyo_tz).date().isoformat()
        supabase.table("care_level_history").insert({
            "facility_code": f_code,
            "patient_id": patient_id,
            "care_level": nl,
            "valid_from": vf,
        }).execute()
        return True
    except Exception as e:
        print("_record_care_level_history error: %s" % e, flush=True)
        return False


# ===== goal-history-on-save-v1 : 目標を変えたら、その場で履歴に残す =====
#
#   ★介護度(clh-history-v1)とまったく同じ考え方。
#     「いつから有効か(valid_from)」を持たせて、月ごとの目標はそこから決める。
#   ★これが無かったので、利用者基本情報で目標を書き換えても
#     誰が・いつ・何を・いつから変えたのかが一切残らなかった。
_GOAL_HISTORY_FIELDS = {
    "short_goal": "短期目標",
    "long_goal": "長期目標",
    "short_goal_function": "短期目標（心身機能）",
    "short_goal_activity": "短期目標（活動）",
    "short_goal_participation": "短期目標（参加）",
    "long_goal_function": "長期目標（心身機能）",
    "long_goal_activity": "長期目標（活動）",
    "long_goal_participation": "長期目標（参加）",
    "short_goal_period_from": "短期目標期間(開始)",
    "short_goal_period_to": "短期目標期間(終了)",
    "long_goal_period_from": "長期目標期間(開始)",
    "long_goal_period_to": "長期目標期間(終了)",
}


def _goal_norm(v):
    """比べるための正規化。None/'none'/'null' は空として扱う。"""
    s = "" if v is None else str(v).strip()
    return "" if s.lower() in ("none", "null") else s


def _record_goal_history(supabase, f_code, patient_id, user_name,
                         before, after, valid_from, changed_by):
    """変わった目標だけ goal_history に残す。戻り値: 残した件数。

    before / after は patient_profiles の辞書（変更前・変更後）。
    ★変わっていない項目は書かない。履歴が意味の無い行で埋まると読めなくなる。
    ★valid_from が空なら今日（日本時間）。UTCだと月初・月末に1日ずれる。
    """
    rows = []
    try:
        vf = (valid_from or "").strip() or datetime.now(tokyo_tz).date().isoformat()
        for field, label in _GOAL_HISTORY_FIELDS.items():
            if field not in after:
                continue          # 今回の保存に含まれていない項目は触らない
            old_v = _goal_norm((before or {}).get(field))
            new_v = _goal_norm(after.get(field))
            if old_v == new_v:
                continue          # 変化なし
            rows.append({
                "facility_code": f_code,
                "patient_profile_id": str(patient_id),
                "user_name": user_name,
                "field": field,
                "field_label": label,
                "old_value": old_v,
                "new_value": new_v,
                "year_month": None,     # 基本情報からの変更は「評価月」を持たない
                "valid_from": vf,
                "changed_by": changed_by,
            })
        if rows:
            supabase.table("goal_history").insert(rows).execute()
        return len(rows)
    except Exception as e:
        print("_record_goal_history error: %s" % e, flush=True)
        return 0


# ===== patients-dup-guard-v1 : 利用者の行が二重にできるのを止める =====
#
#   ★2026-08-28 小倉愈さんの事故を受けて追加。
#     patients に行を作る場所が4か所に散らばり、どれも【氏名だけ】で
#     「もう居るか」を見ていた。氏名が一時的に食い違うと2行目ができ、
#     利用曜日が2つに分かれて、画面ごとに午前・午後が違って見えていた。
#   ★これからは、行を足すときは必ずここを通す。


def _patients_find_existing(supabase, f_code, name, chart):
    """同じ人とみなせる patients 行を探す。

    戻り値: (見つかった行 または None, 確かめられたか True/False)

    ★【居なかった】と【確かめられなかった】を必ず分ける。
      通信や権限で問い合わせが失敗したとき、None だけを返すと、
      呼ぶ側が「居ないから作ろう」と判断して二重に作ってしまう。
      ＝データが無いのではなく、答えが返ってこなかっただけ。
      （実績の振替でも同じ壊れ方をした・HIROさん指摘 2026-08-28）
    ★氏名 と カルテ番号 の【両方】で探す。
      氏名だけでは今回の事故を止められない（氏名が食い違ったのが原因）。
    ★'臨時' は番号ではなく仮の印なので、番号としては照合しない。
      これで照合すると、別人どうしが同じ人にされてしまう。
    """
    name = (name or "").strip()
    chart = str(chart or "").strip()
    try:
        if name:
            r = (supabase.table("patients").select("id,user_name,chart_number")
                 .eq("facility_code", f_code).eq("user_name", name).limit(1).execute())
            if r.data:
                return r.data[0], True
        if chart and chart != "臨時":
            r = (supabase.table("patients").select("id,user_name,chart_number")
                 .eq("facility_code", f_code).eq("chart_number", chart).limit(1).execute())
            if r.data:
                return r.data[0], True
    except Exception as e:
        print("_patients_find_existing error: %s" % e, flush=True)
        return None, False       # 確かめられていない。居ないとは言えない。
    return None, True            # 確かに居ない


def _patients_insert_guarded(supabase, f_code, row, source):
    """patients に行を作る。ただし同じ人が居たら作らない。

    戻り値: (id文字列 または None, 新しく作ったか True/False)
    ★見つかったのに中身が食い違うときは、黙って使わずLINEで知らせる。
      食い違いこそが「橋が切れかけている」合図で、放っておくと必ず再発する。
    ★確かめられなかったときは【作らない】。
      作って二重になるより、作らずに失敗として返すほうが直しやすい。
      消すのは手間だが、作らなかっただけならもう一度押せば済む。
    """
    name = (row.get("user_name") or "").strip()
    chart = str(row.get("chart_number") or "").strip()
    exist, checked = _patients_find_existing(supabase, f_code, name, chart)
    if not checked:
        try:
            line_notify_admin(
                "【TASUKARU】利用者の登録を見送りました\n"
                "事業所: %s\n"
                "対象: %s (No.%s)\n"
                "きっかけ: %s\n"
                "※すでに登録済みかを確かめられませんでした（通信エラー等）。\n"
                "　二重登録を避けるため作成していません。もう一度お試しください。"
                % (f_code, name or "(空)", chart or "-", source))
        except Exception:
            pass
        return None, False
    if exist:
        _en = (exist.get("user_name") or "").strip()
        _ec = str(exist.get("chart_number") or "").strip()
        if _en != name or (chart and _ec != chart):
            try:
                line_notify_admin(
                    "【TASUKARU】利用者の二重登録を止めました\n"
                    "事業所: %s\n"
                    "登録しようとした: %s (No.%s)\n"
                    "すでにある行: %s (No.%s) / id=%s\n"
                    "きっかけ: %s\n"
                    "※名前か番号が食い違っています。利用者基本情報をご確認ください。"
                    % (f_code, name or "(空)", chart or "-",
                       _en or "(空)", _ec or "-", exist.get("id"), source))
            except Exception:
                pass
        return str(exist.get("id")), False
    try:
        ins = supabase.table("patients").insert(row).execute()
        if ins.data:
            return str(ins.data[0]["id"]), True
    except Exception as e:
        print("_patients_insert_guarded error (%s): %s" % (source, e), flush=True)
    return None, False


def _patients_dup_groups(supabase, f_code):
    """氏名が同じ／カルテ番号が同じ patients 行が2つ以上ある組を返す。

    戻り値: (組の一覧, 確かめられたか True/False)
    ★ここでも【重複が無かった】と【確かめられなかった】を分ける。
      失敗を「重複なし」と読むと、控えを『重複なし』で上書きしてしまい、
      本当に重複しているのに知らせが出なくなる。
    """
    groups = []
    try:
        r = (supabase.table("patients").select("id,user_name,chart_number")
             .eq("facility_code", f_code).execute())
        by_name, by_chart = {}, {}
        for x in (r.data or []):
            n = (x.get("user_name") or "").strip()
            c = str(x.get("chart_number") or "").strip()
            if n:
                by_name.setdefault(n, []).append(x)
            if c and c != "臨時":
                by_chart.setdefault(c, []).append(x)
        seen = set()
        for key, xs in list(by_name.items()) + list(by_chart.items()):
            if len(xs) < 2:
                continue
            ids = tuple(sorted(str(x["id"]) for x in xs))
            if ids in seen:
                continue      # 氏名でも番号でも当たる組は1回だけ数える
            seen.add(ids)
            groups.append({"key": key, "ids": list(ids), "rows": xs})
    except Exception as e:
        print("_patients_dup_groups error: %s" % e, flush=True)
        return [], False
    return groups, True


def _patients_dup_notify(supabase, f_code):
    """二重になっている利用者が居たらLINEで知らせる。戻り値: 組の数。

    ★同じ内容を何度も送らない。前に送った内容を admin_settings に控えて比べる。
      毎回送ると、通知そのものが読まれなくなる。
    ★直ったときも控えを更新する。そうしないと、次に別の重複が出ても
      「前と同じ」と判定されて送られなくなる。
    """
    try:
        groups, _checked = _patients_dup_groups(supabase, f_code)
        if not _checked:
            return 0                     # 確かめられていない。控えは触らない。
        sig = ";".join("|".join(g["ids"]) for g in groups)
        cur = (supabase.table("admin_settings").select("id,value")
               .eq("facility_code", f_code).eq("key", "patients_dup_notified").execute())
        prev = (cur.data[0].get("value") if cur.data else "") or ""
        if sig == prev:
            return len(groups)           # 変わっていないので送らない
        if groups:
            _lines = ["【TASUKARU】利用者が二重に登録されています",
                      "事業所: %s" % f_code]
            for g in groups[:10]:
                _lines.append("・%s → id %s" % (g["key"], " / ".join(g["ids"])))
            _lines.append("※利用曜日やバイタルが分かれている可能性があります。")
            line_notify_admin("\n".join(_lines))
        if cur.data:
            (supabase.table("admin_settings").update({"value": sig})
             .eq("id", cur.data[0]["id"]).execute())
        else:
            supabase.table("admin_settings").insert(
                {"facility_code": f_code, "key": "patients_dup_notified",
                 "value": sig}).execute()
        return len(groups)
    except Exception as e:
        print("_patients_dup_notify error: %s" % e, flush=True)
        return 0


def _ensure_patient_row(supabase, f_code, profile_row):
    """profile_row(dict: user_name/user_name_kana/birth_date/patient_number)に対応する
    patients行を必要なら作成する。戻り値: 作成したら True / 既存なら False。"""
    try:
        name = (profile_row.get("user_name") or "").strip()
        if not name:
            return False
        # chart_number: patient_number をコピー。空ならフォールバック採番
        chart = str(profile_row.get("patient_number") or "").strip()
        if not chart:
            ex = supabase.table("patients").select("chart_number").eq("facility_code", f_code).execute()
            nums = []
            for p in (ex.data or []):
                try: nums.append(int(p["chart_number"]))
                except: pass
            chart = str(max(nums, default=0) + 1).zfill(3)
        birth = profile_row.get("birth_date") or None
        # patients-dup-guard-v1: 氏名だけの確認をやめ、番号でも照合してから作る。
        #   ★以前はここで「同名が居なければ作る」だった。氏名が食い違うと
        #     2行目ができ、利用曜日が分かれた（2026-08-28 小倉さん）。
        _pid, _created = _patients_insert_guarded(supabase, f_code, {
            "facility_code": f_code,
            "user_name":     name,
            "user_kana":     profile_row.get("user_name_kana") or "",
            "birth_date":    birth,
            "chart_number":  chart,
        }, "利用者基本情報からの自動作成")
        return _created
    except Exception as e:
        print(f"_ensure_patient_row error: {e}", flush=True)
        return False


@app.route('/api/admin/patient/add', methods=['POST'])
@login_required
def api_admin_patient_add():
    """1名手入力登録 (patient_profiles)"""
    try:
        data = request.json or {}
        f_code = session["f_code"]
        name = (data.get("user_name") or "").strip()
        # patient-number-zerofill-v1: 利用者番号を整形
        if data.get("patient_number"):
            data["patient_number"] = _normalize_patient_number(data.get("patient_number"))
        if not name:
            return jsonify({"status": "error", "message": "氏名は必須です"}), 400
        row = {
            "facility_code":  f_code,
            "patient_number": (data.get("patient_number") or None),
            "user_name":      name,
            "user_name_kana": (data.get("user_name_kana") or None),
            "birth_date":     (data.get("birth_date") or None),
            "care_level":     (data.get("care_level") or None),
            "updated_at":     datetime.now(tokyo_tz).isoformat(),
        }
        supabase = get_supabase()
        supabase.table("patient_profiles").insert(row).execute()
        # patients-sync-b1: patients連動
        _ensure_patient_row(supabase, f_code, row)
        return jsonify({"status": "success"})
    except Exception as e:
        print(f"admin_patient_add error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route('/api/admin/patient/save', methods=['POST'])
@login_required
def api_admin_patient_save():
    """admin-patient-save-v1: 利用者情報の保存 (patient_profiles)。
    idあり=update / idなし=insert。facility_codeはサーバ側で強制。
    フロントが組み立てたフィールドをそのまま通す(現状挙動を維持)。"""
    try:
        data = request.json or {}
        f_code = session["f_code"]
        pid = (data.get("id") or "").strip()
        # idは書き込み対象カラムから除外し、facility_codeは強制
        # clh-history-v1-fix1: care_level_valid_from は履歴用なので patient_profiles へは書かない
        # goal-history-on-save-v1: goal_valid_from は履歴用。patient_profiles へは書かない
        #   （care_level_valid_from と同じ扱い）
        row = {k: v for k, v in data.items()
               if k not in ("id", "facility_code", "care_level_valid_from", "goal_valid_from")}
        row["facility_code"] = f_code
        row["updated_at"] = datetime.now(tokyo_tz).isoformat()
        # patient-number-zerofill-v1: 利用者番号を整形
        if row.get("patient_number"):
            row["patient_number"] = _normalize_patient_number(row.get("patient_number"))

        # user_name 必須(新規時)
        if not pid and not (row.get("user_name") or "").strip():
            return jsonify({"status": "error", "message": "氏名は必須です"}), 400

        supabase = get_supabase()
        if pid:
            # patient-int-link-fix-v1: 改名検知のため、更新前の氏名を控える。
            # patients 行は氏名で紐づくので、氏名変更時に patients 側も同名へ更新しないと
            # patient_int_id が引けなくなり曜日等が切れる。
            _new_name = (row.get("user_name") or "").strip()
            _old_name = None
            if _new_name:
                try:
                    _prev = supabase.table("patient_profiles").select("user_name") \
                        .eq("id", pid).eq("facility_code", f_code).single().execute()
                    _old_name = ((_prev.data or {}).get("user_name") or "").strip()
                except Exception:
                    _old_name = None
            # goal-history-on-save-v1: 目標が変わったかを見るため、【更新の前に】控える。
            #   ★更新したあとでは、変更前の値がもう分からない。
            _goal_before = None
            if any(k in row for k in _GOAL_HISTORY_FIELDS):
                try:
                    _gb = supabase.table("patient_profiles") \
                        .select(",".join(list(_GOAL_HISTORY_FIELDS.keys()) + ["user_name"])) \
                        .eq("id", pid).eq("facility_code", f_code).single().execute()
                    _goal_before = _gb.data or {}
                except Exception as _gbe:
                    print("goal before-fetch error: %s" % _gbe, flush=True)
                    _goal_before = None

            # 更新: id + facility_code の二条件でログイン施設のみ
            res = supabase.table("patient_profiles").update(row) \
                .eq("id", pid).eq("facility_code", f_code).execute()
            if not res.data:
                return jsonify({"status": "error", "message": "対象が見つかりません"}), 404
            # patient-int-link-fix-v1: 氏名が変わったら patients 側の氏名も追随（橋を保つ）。
            if _new_name and _old_name and _old_name != _new_name:
                try:
                    supabase.table("patients").update({"user_name": _new_name}) \
                        .eq("facility_code", f_code).eq("user_name", _old_name).execute()
                except Exception as _sync_e:
                    print(f"patients rename sync error: {_sync_e}", flush=True)
            # patient-number-sync-v1: 利用者番号を patients.chart_number へ追随させる。
            # patients.chart_number は行の作成時に一度コピーされるだけだったため、
            # 基本情報で番号を直してもケース記録閲覧・バイタル等が古い番号を出し続けていた。
            # 記録の紐づけは氏名と id で行っており chart_number は表示専用なので、
            # ここで上書きしても記録が迷子になることはない。
            if "patient_number" in row:
                _sync_no = (row.get("patient_number") or "").strip()
                _sync_name = _new_name or (_old_name or "")
                if not _sync_name:
                    # 氏名がリクエストに含まれない部分保存でも同期できるよう DB から引く
                    try:
                        _pn = supabase.table("patient_profiles").select("user_name") \
                            .eq("id", pid).eq("facility_code", f_code).single().execute()
                        _sync_name = ((_pn.data or {}).get("user_name") or "").strip()
                    except Exception:
                        _sync_name = ""
                if _sync_name and _sync_no:
                    try:
                        supabase.table("patients").update({"chart_number": _sync_no}) \
                            .eq("facility_code", f_code).eq("user_name", _sync_name).execute()
                    except Exception as _num_e:
                        print(f"patients chart_number sync error: {_num_e}", flush=True)
            # 更新後、対応する patients 行がまだ無ければ作成（旧データ救済）。
            try:
                _chk = supabase.table("patients").select("id") \
                    .eq("facility_code", f_code).eq("user_name", _new_name or (row.get("user_name") or "")).execute()
                if not _chk.data and (_new_name or row.get("user_name")):
                    _ensure_patient_row(supabase, f_code, {**row, "user_name": _new_name or row.get("user_name")})
            except Exception as _ens_e:
                print(f"patients ensure(update) error: {_ens_e}", flush=True)
            # clh-history-v1: 介護度履歴を記録（変わったときだけ）
            if "care_level" in row:
                _record_care_level_history(supabase, f_code, pid, row.get("care_level"), data.get("care_level_valid_from"))
            # goal-history-on-save-v1: 目標が変わっていたら、その場で履歴に残す
            _goal_logged = 0
            if _goal_before is not None:
                _goal_logged = _record_goal_history(
                    supabase, f_code, pid,
                    (_new_name or _goal_before.get("user_name") or ""),
                    _goal_before, row,
                    data.get("goal_valid_from"),
                    session.get("my_name", ""))
            return jsonify({"status": "success", "id": pid, "goal_history_added": _goal_logged})
        else:
            # 新規: insert して id を返す
            res = supabase.table("patient_profiles").insert(row).execute()
            new_id = res.data[0]["id"] if res.data else None
            # patients-sync-b1: patients連動(新規時のみ)
            _ensure_patient_row(supabase, f_code, row)
            # clh-history-v1: 初回介護度履歴を記録。valid_fromは認定開始日→無ければ本日
            if new_id and row.get("care_level"):
                _vf = data.get("care_level_valid_from") or row.get("certification_start_date")
                _record_care_level_history(supabase, f_code, new_id, row.get("care_level"), _vf)
            return jsonify({"status": "success", "id": new_id})
    except Exception as e:
        print(f"admin_patient_save error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


