@app.route('/api/admin/patient/csv_map', methods=['POST'])
@login_required
def api_admin_patient_csv_map():
    """CSV列見出しをAIが利用者項目に自動対応付け（施設ごとの形式差を吸収）。csv-ai-map-v1"""
    try:
        data = request.json or {}
        headers = data.get('headers', []) or []
        samples = data.get('samples', []) or []
        if not headers:
            return jsonify({"status": "error", "message": "見出しがありません"}), 400
        import json as _json, re as _re
        from utils import get_generative_model
        model = get_generative_model()
        fields_desc = (
            "patient_number: 利用者番号・カルテNo・ID\n"
            "user_name: 氏名・利用者氏名・お名前\n"
            "user_name_kana: ふりがな・カナ・フリガナ\n"
            "birth_date: 生年月日\n"
            "gender: 性別\n"
            "care_level: 介護度・要介護度\n"
            "postal_code: 郵便番号\n"
            "address: 住所\n"
            "certification_start_date: 認定有効期間の開始\n"
            "certification_end_date: 認定有効期間の終了\n"
            "support_office: 支援事業所・居宅介護支援事業所\n"
            "care_manager_name: 担当介護支援専門員・ケアマネ\n"
            "delegate_office: 委託先事業所\n"
        )
        sample_txt = ""
        for row in (samples or [])[:3]:
            try:
                sample_txt += " | ".join([str(c) for c in row]) + "\n"
            except Exception:
                pass
        prompt = (
            "介護施設の利用者CSVの列見出しを、システム項目に対応付けてください。\n\n"
            "【システム項目】\n" + fields_desc + "\n"
            "【CSVの見出し】\n" + _json.dumps(headers, ensure_ascii=False) + "\n\n"
            "【先頭データ(参考)】\n" + sample_txt + "\n"
            "各見出しが上のどの項目に当たるかを判定。どれにも当たらない見出しはnull(不要な列は無視)。"
            "同じ項目に複数該当する場合は最適な1つだけ対応させ他はnull。\n"
            "次のJSONのみで返答(説明不要): {\"mapping\": {\"見出し名\": \"項目名 or null\"}}"
        )
        resp = model.generate_content([prompt])
        text = (resp.text or "").strip()
        m = _re.search(r'\{.*\}', text, _re.DOTALL)
        if not m:
            return jsonify({"status": "error", "message": "AI応答を解釈できませんでした"}), 500
        result = _json.loads(m.group())
        mapping = result.get("mapping", {}) or {}
        allowed = {"patient_number", "user_name", "user_name_kana", "birth_date",
                   "gender", "care_level", "postal_code", "address",
                   "certification_start_date", "certification_end_date",
                   "support_office", "care_manager_name", "delegate_office"}
        clean = {}
        for h, fld in mapping.items():
            if isinstance(fld, str) and fld in allowed:
                clean[h] = fld
        return jsonify({"status": "success", "mapping": clean})
    except Exception as e:
        print("csv_map error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route('/api/admin/patient/bulk_import', methods=['POST'])
@login_required
def api_admin_patient_bulk_import():
    """CSV一括取込 (patient_profiles upsert / merge-duplicates)。
    パース済み records[] を受け、facility_code はサーバ側で強制上書き。"""
    try:
        data = request.json or {}
        f_code = session["f_code"]
        records = data.get("records", []) or []
        if not records:
            return jsonify({"status": "error", "message": "取込データがありません"}), 400
        now_iso = datetime.now(tokyo_tz).isoformat()
        clean = []
        for r in records:
            if not isinstance(r, dict):
                continue
            row = dict(r)
            # facility_code はフロント由来を捨ててsession値で強制
            row["facility_code"] = f_code
            row["updated_at"] = now_iso
            # patient-number-zerofill-v1: 利用者番号を整形
            if row.get("patient_number"):
                row["patient_number"] = _normalize_patient_number(row.get("patient_number"))
            clean.append(row)
        if not clean:
            return jsonify({"status": "error", "message": "取込データがありません"}), 400
        supabase = get_supabase()
        supabase.table("patient_profiles").upsert(clean).execute()
        # patients-sync-b1: 各行をpatients連動
        for _r in clean:
            _ensure_patient_row(supabase, f_code, _r)
        return jsonify({"status": "success", "count": len(clean)})
    except Exception as e:
        print(f"admin_patient_bulk_import error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route('/api/bulk_register_patients', methods=['POST'])
@login_required
def api_bulk_register_patients():
    """読み取った利用者を一括登録"""
    try:
        data = request.json
        f_code   = session["f_code"]
        patients = data.get("patients", [])
        supabase = get_supabase()

        # 既存のカルテ番号の最大値を取得
        existing = supabase.table("patients").select("chart_number").eq("facility_code", f_code).execute()
        existing_nums = []
        for p in (existing.data or []):
            try: existing_nums.append(int(p["chart_number"]))
            except: pass
        next_num = max(existing_nums, default=0) + 1

        registered = 0
        for p in patients:
            name = p.get("name", "").strip()
            if not name:
                continue
            # カルテ番号
            chart = p.get("chart", "").strip()
            if not chart:
                chart = str(next_num).zfill(3)
                next_num += 1

            # 生年月日の整形
            birth_date = p.get("birth_date", "") or None
            if birth_date and len(birth_date) == 10:
                try:
                    from datetime import datetime as dt
                    dt.strptime(birth_date, "%Y-%m-%d")
                except:
                    birth_date = None

            # patients-dup-guard-v1: 確認せずに足していたので、同じ人が二重に入り得た
            _pid, _created = _patients_insert_guarded(supabase, f_code, {
                "facility_code": f_code,
                "user_name":     name,
                "user_kana":     p.get("kana", "") or "",
                "birth_date":    birth_date,
                "chart_number":  chart,
            }, "一括登録")

            # 利用曜日・AM/PMをpatient_visit_daysに保存
            weekdays = p.get("weekdays", "") or ""
            ampm     = p.get("ampm", "BOTH") or "BOTH"
            if weekdays:
                # patients-dup-guard-v1: 追加時に返ってきた id をそのまま使う。
                #   ★氏名＋番号で引き直すと、番号だけ直された行を取り違える。
                pid = _pid
                if pid:
                    # patients-dup-guard-v1: すでに曜日がある人には足さない。
                    #   ★足すと曜日の行が二重になり、今回と同じ壊れ方をする。
                    #   ★continue で飛ばすと、この下の「登録件数」を数え損なう。
                    #     だから飛ばさず、「無いときだけ作る」で囲う。
                    _vd_exist = (supabase.table("patient_visit_days").select("id")
                                 .eq("facility_code", f_code).eq("patient_id", pid)
                                 .limit(1).execute())
                    if not _vd_exist.data:
                        # Session 18: weekdays から ampm_per_day を生成(全曜日 ALL)
                        ampm_per_day_init = {ch: "ALL" for ch in weekdays if ch in "0123456"}
                        try:
                            supabase.table("patient_visit_days").insert({
                                "facility_code": f_code,
                                "patient_id":    pid,
                                "user_name":     name,
                                "weekdays":      weekdays,
                                "ampm":          ampm,
                                "ampm_per_day":  ampm_per_day_init,
                            }).execute()
                        except:
                            pass
            registered += 1

        return jsonify({"status": "success", "count": registered})
    except Exception as e:
        print(f"bulk_register error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500

