@app.route('/patient_profile')
@login_required
def patient_profile():
    supabase = get_supabase()
    f_code   = session.get('f_code', '')
    sel_id   = request.args.get('id')
    try:
        res = supabase.table('patient_profiles') \
            .select('id, user_name, user_name_kana, patient_number') \
            .eq('facility_code', f_code) \
            .order('user_name_kana') \
            .execute()
        patients = res.data or []
    except Exception:
        patients = []
    selected = None
    if sel_id:
        try:
            res = supabase.table('patient_profiles') \
                .select('*') \
                .eq('id', sel_id) \
                .eq('facility_code', f_code) \
                .single() \
                .execute()
            selected = res.data
        except Exception:
            selected = None
            # patient_id と利用日データを取得
    # patients-dup-guard-v1: この画面は管理者しか開かない。開いたときに点検して、
    #   二重登録が残っていたらLINEで知らせる（内容が変わったときだけ送る）。
    #   ★開発者MENUに置くだけだと、見に行かないと気づけない（HIROさん指摘）。
    try:
        _patients_dup_notify(supabase, f_code)
    except Exception:
        pass
    patient_id = None
    visit_day_data = {}
    if selected:
        try:
            pr = supabase.table('patients').select('id').eq('facility_code', f_code).eq('user_name', selected['user_name']).execute()
            if not pr.data:
                # patient-int-link-fix-v1: 対応する patients 行(整数ID)が無いと曜日の保存も表示も
                # できない（PATIENT_ID が null になり保存が無言で失敗する）。開いた時点で自動作成して橋を張る。
                _ensure_patient_row(supabase, f_code, selected)
                pr = supabase.table('patients').select('id').eq('facility_code', f_code).eq('user_name', selected['user_name']).execute()
            if pr.data:
                patient_id = pr.data[0]['id']
                vr = supabase.table('patient_visit_days').select('weekdays,ampm_per_day,nth_per_day,half_start_date,full_start_date').eq('facility_code', f_code).eq('patient_id', patient_id).execute()  # visit-nth-v1 / visit-type-start-v1
                if vr.data:
                    visit_day_data = vr.data[0]
        except Exception:
            pass
    return render_template(
        'patient_profile.html',
        patients=patients,
        selected=selected,
        patient_id=patient_id,
        visit_day_data=visit_day_data
    )

