@app.route('/api/record_dates')
@login_required
def api_record_dates():
    """カレンダーのドット表示用：指定月の記録がある日付一覧を返す"""
    try:
        f_code = session["f_code"]
        year = int(request.args.get("year", datetime.now(tokyo_tz).year))
        month = int(request.args.get("month", datetime.now(tokyo_tz).month))
        supabase = get_supabase()
        month_start = tokyo_tz.localize(datetime(year, month, 1))
        if month == 12:
            next_month = tokyo_tz.localize(datetime(year + 1, 1, 1))
        else:
            next_month = tokyo_tz.localize(datetime(year, month + 1, 1))
        res = supabase.table("records").select("created_at").eq("facility_code", f_code).gte(
            "created_at", month_start.isoformat()
        ).lt("created_at", next_month.isoformat()).execute()
        dates_set = set()
        if res.data:
            for r in res.data:
                d = parse_jst_date(r["created_at"])
                dates_set.add(d.strftime("%Y-%m-%d"))
        return jsonify({"dates": list(dates_set)})
    except Exception as e:
        return jsonify({"dates": [], "error": str(e)})

@app.route('/api/transcribe', methods=['POST'])
@login_required
def api_transcribe():
    try:
        data = request.json
        if not data or not data.get("audio_data"):
            return jsonify({"error": "音声データがありません"}), 400
        from utils import get_generative_model, upload_audio_to_supabase
        try:
            audio_bytes = base64.b64decode(data["audio_data"])
        except Exception:
            return jsonify({"error": "音声データのデコードに失敗しました"}), 400
        # halluc-guard-v2: 極端に短い(=ほぼ無音)録音はAIに送らない。創作の入口を塞ぐ。
        if len(audio_bytes) < 2048:
            return jsonify({"error": "音声が短すぎます。もう一度お話しください。", "no_retry": True}), 400
        # asr-name-hint-v1: 選択中の利用者の氏名・読み仮名を聞き取りヒントに加える。
        #   クライアント入力はそのまま使わず、施設の名簿に実在する氏名だけを採用する（偽名の混入防止）。
        _name_hint = ""
        try:
            _sel = (data.get("patient") or "").strip()
            _m = re.search(r'\(No\.(.*?)\) \[(.*?)\]', _sel)
            if _m:
                _cand = (_m.group(2) or "").strip()
                if _cand and len(_cand) <= 40:
                    _pr = get_supabase().table("patient_profiles").select(
                        "user_name,user_name_kana"
                    ).eq("facility_code", session["f_code"]).eq("user_name", _cand).limit(1).execute()
                    if _pr.data:
                        _n = (_pr.data[0].get("user_name") or "").strip()
                        _k = (_pr.data[0].get("user_name_kana") or "").strip()
                        if _n:
                            # asr-name-hint-v2: 介護現場は下の名前で呼ぶことが多い。姓・名の読みを個別に示す。
                            _nt = [t for t in _n.replace("\u3000", " ").split(" ") if t]
                            _kt = [t for t in (_k or "").replace("\u3000", " ").split(" ") if t]
                            _parts = ""
                            if len(_nt) >= 2 and len(_kt) >= 2:
                                _parts = (
                                    "　介護現場では下の名前で呼ぶことが多いため、"
                                    "「" + _kt[0] + "」と聞こえたら「" + _nt[0] + "」、"
                                    "「" + "".join(_kt[1:]) + "」と聞こえたら「" + "".join(_nt[1:]) + "」"
                                    "と書いてください。\n"
                                )
                            _name_hint = (
                                "・この記録の対象は「" + _n + "」さん"
                                + ("（読み：" + _k + "）" if _k else "")
                                + "です。音声にこの読みの名前が出てきたら、必ずこの漢字表記で書いてください"
                                "（当て字・難読名の取り違え防止）。\n"
                                + _parts +
                                "　ただし名前が呼ばれていないのに書き足してはいけません。\n"
                            )
        except Exception as _nh_e:
            print(f"[transcribe name-hint skip] {_nh_e}", flush=True)
            _name_hint = ""
        model = get_generative_model()
        # halluc-guard-v3: 介護語彙は「聞き取りのヒント」として渡し（同音語の誤変換対策）、
        #   「書くべき内容」ではないと明示することで創作は封じたままにする。
        prompt = (
            "これは介護施設(デイサービス)の職員が、その場の出来事を記録用に吹き込んだ音声です。\n"
            "あなたの仕事は「聞こえた言葉を正確に文字にすること」だけです。文章を作る仕事ではありません。\n"
            "\n"
            "【同じ音で迷いやすい言葉（介護記録ではこちらが正解）】\n"
            "・かいじょ → 介助（「解除」ではない）"
            "※センサー・アラーム・ロックなど機器の話のときだけ「解除」\n"
            "・にゅうよく → 入浴（「ニューヨーク」ではない）\n"
            "・いじょう → 体を移す話なら「移乗」／様子の話なら「異常」／数量の話なら「以上」\n"
            "・せいしき → 清拭（「正式」ではない）\n"
            "・こうい → 更衣（「行為」「好意」ではない）\n"
            "・ごえん → 誤嚥（「ご縁」ではない）\n"
            "・けいちょう → 傾聴（「軽重」ではない）\n"
            "・そうげい → 送迎（「造影」ではない）\n"
            "・ほこう → 歩行（「奉公」ではない）\n"
            "・てんとう → 転倒（「店頭」ではない）\n"
            "・こうくうケア → 口腔ケア／じょくそう → 褥瘡／ふしゅ → 浮腫／こうしゅく → 拘縮\n"
            "・はいせつ → 排泄／ふくやく → 服薬／たいいへんかん → 体位変換／きのうくんれん → 機能訓練\n"
            "\n"
            "【文脈から判断する】\n"
            "・介護記録は「利用者の生活を支えた行動」の記録です。音の候補で迷ったら、"
            "体のケア・食事・排泄・移動・見守りに関する言葉を選んでください。\n"
            "・同じ文の中に「入浴」「食事」「排泄」「移乗」「更衣」などのケア動作があれば、"
            "その文の「かいじょ」は必ず「介助」です。\n"
            "・一文だけで判断せず、前後の文の話題（入浴の話か、食事の話か等）も踏まえて漢字を選んでください。\n"
            "\n"
            "【よくある誤変換（絶対にこう書かない）】\n"
            "×「ニューヨークを解除しました」→ ○「入浴を介助しました」\n"
            "×「異常の際に見守りを行いました」→ ○「移乗の際に見守りを行いました」\n"
            "×「正式と行為で対応しました」→ ○「清拭と更衣で対応しました」\n"
            "×「ご縁に注意しました」→ ○「誤嚥に注意しました」\n"
            "\n"
            "【その他よく出る言葉】\n"
            "おむつ交換／トイレ誘導／水分／口腔ケア／車椅子／声かけ／リハビリ／"
            "レクリエーション／通所／バイタル／血圧／体温／脈拍／発熱／認知症／"
            "利用者／ご家族／ケアマネ／看護師／相談員\n"
            + _name_hint +
            "※上記はすべて「聞き取りのヒント」であって「書くべき内容」ではありません。"
            "聞こえていない語や名前を、ここから持ってきては絶対にいけません。\n"
            "\n"
            "【厳守ルール】\n"
            "・実際に聞こえた言葉だけを書く。聞こえていないことは絶対に追加・推測・創作しない。\n"
            "・介護記録らしく整えるために内容を足さない。短い発話は短いまま書く。\n"
            "・音声が無音・雑音のみ・聞き取れない場合は、内容を作らず [NO_SPEECH] とだけ出力する"
            "（もっともらしい介護記録の文章を作ってはいけない）。\n"
            "・「あー」「えー」「えっと」などのフィラーは省略する。\n"
            "・職員名や「利用者様は」などの主語は補わない。\n"
            "・語尾はです・ます調に整えてよいが、内容は変えない。\n"
            "出力は文字起こし本文のみ。前置き・説明・マークダウンは不要。"
        )
        mime = data.get("audio_mime", "audio/webm")
        contents = [prompt, {"mime_type": mime, "data": audio_bytes}]
        result = model.generate_content(contents, generation_config={"temperature": 0.1})  # halluc-guard-v2
        _txt = (result.text or "").strip()
        # halluc-guard-v2: 聞き取れなかった合図。テキスト欄には何も入れない。
        if (not _txt) or ("[NO_SPEECH]" in _txt.upper()):
            return jsonify({"error": "音声を聞き取れませんでした。もう一度お話しください。", "no_retry": True}), 200
        return jsonify({"text": _txt})
    except Exception as e:
        print(f"[transcribe error] {e}")
        return jsonify({"error": f"音声変換に失敗しました: {str(e)}"}), 500

# ===== translation-v1: 外国人スタッフ向け翻訳入力 =====
@app.route('/api/translate/text', methods=['POST'])
@login_required
def api_translate_text():
    """任意言語のテキストを日本語に翻訳する。Gemini API使用。"""
    data = request.json or {}
    text = (data.get('text') or '').strip()
    if not text:
        return jsonify({'status': 'error', 'message': 'テキストが空です'}), 400
    from utils import get_generative_model
    model = get_generative_model()
    try:
        prompt = (
            "以下のテキストを自然な介護記録向けの日本語に翻訳してください。"
            "翻訳後のテキストのみ出力してください。"
            "元のテキストが既に日本語の場合はそのまま返してください。\n\n" + text
        )
        result = model.generate_content([prompt])
        return jsonify({'status': 'success', 'translated': result.text.strip()})
    except Exception as e:
        print(f"api_translate_text error: {e}", flush=True)
        return jsonify({'status': 'error', 'message': str(e)}), 500


@app.route('/api/translate/voice', methods=['POST'])
@login_required
def api_translate_voice():
    """音声を受け取り、文字起こし＋日本語翻訳して返す。Gemini API使用。"""
    data = request.json or {}
    audio_data = data.get('audio_data')
    if not audio_data:
        return jsonify({'status': 'error', 'message': '音声データがありません'}), 400
    try:
        audio_bytes = base64.b64decode(audio_data)
    except Exception:
        return jsonify({'status': 'error', 'message': '音声データのデコードに失敗しました'}), 400
    # halluc-guard-v2: 極端に短い(=ほぼ無音)録音はAIに送らない。
    if len(audio_bytes) < 2048:
        return jsonify({'status': 'error', 'message': '音声が短すぎます。もう一度お話しください。'}), 400
    mime = data.get('audio_mime', 'audio/webm')
    from utils import get_generative_model
    model = get_generative_model()
    try:
        # halluc-guard-v3: 聞こえた言葉だけを訳す。介護語彙はヒントとしてのみ与える。
        prompt = (
            "この音声を文字起こしし、日本語で出力してください。"
            "音声が日本語以外の場合は日本語に翻訳してから出力してください。"
            "介護施設での発話です。入浴・清拭・更衣・排泄・食事・服薬・移乗・歩行・見守り・"
            "介助・バイタル・血圧・体温・脈拍・転倒・誤嚥 などの介護用語がよく出てくるため、"
            "同じ音・似た音で迷ったときはこれらを優先して聞き取ってください。"
            "ただしこれは聞き取りのヒントであり、聞こえていない語をここから持ってきてはいけません。"
            "【厳守】実際に聞こえた言葉だけを出力し、聞こえていないことは絶対に追加・推測・創作しないこと。"
            "介護記録らしく整えるために内容を足さないこと。"
            "音声が無音・雑音のみ・聞き取れない場合は、内容を作らず [NO_SPEECH] とだけ出力すること。"
            "テキストのみ出力してください。"
        )
        result = model.generate_content([prompt, {"mime_type": mime, "data": audio_bytes}],
                                        generation_config={"temperature": 0.1})  # halluc-guard-v2
        _tt = (result.text or "").strip()
        if (not _tt) or ("[NO_SPEECH]" in _tt.upper()):
            return jsonify({'status': 'error', 'message': '音声を聞き取れませんでした。もう一度お話しください。'})
        return jsonify({'status': 'success', 'translated': _tt})
    except Exception as e:
        print(f"api_translate_voice error: {e}", flush=True)
        return jsonify({'status': 'error', 'message': str(e)}), 500
@app.route('/api/translate/ui', methods=['POST'])
@login_required
def api_translate_ui():
    """UI要素のテキストを指定言語に翻訳する。翻訳レンズ用。translation-v1"""
    data = request.json or {}
    text = (data.get('text') or '').strip()
    target_lang = (data.get('target_lang') or '').strip()
    if not text or not target_lang:
        return jsonify({'status': 'error', 'message': 'textとtarget_langが必要です'}), 400
    lang_names = {
        'en': '英語', 'zh-CN': '中国語(簡体字)', 'zh-TW': '中国語(繁体字)',
        'ko': '韓国語', 'vi': 'ベトナム語', 'tl': 'フィリピン語(タガログ語)',
        'id': 'インドネシア語', 'pt': 'ポルトガル語', 'es': 'スペイン語',
        'th': 'タイ語', 'my': 'ミャンマー語',
    }
    from utils import get_generative_model
    model = get_generative_model()
    try:
        lang_name = lang_names.get(target_lang, target_lang)
        prompt = (
            f"以下の日本語テキストを{lang_name}に翻訳してください。"
            "翻訳後のテキストのみ出力してください。短いラベルや単語は簡潔に訳してください。\n\n" + text
        )
        result = model.generate_content([prompt])
        return jsonify({'status': 'success', 'translated': result.text.strip(), 'original': text})
    except Exception as e:
        print(f"api_translate_ui error: {e}", flush=True)
        return jsonify({'status': 'error', 'message': str(e)}), 500


