# ==========================================================
# leave-dates-edit-v1 : 休み連絡の日付を、あとから直せるようにする
#
#   ★何が抜けていたか
#     作るときは飛び飛びの日を入れられて、日ごとに calendar_events が1件ずつ作られる。
#     ところが【編集】は leave_date_start / leave_date_end しか扱っておらず、
#     カレンダーも calendar_event_id の【1件だけ】を書き換えていた。
#     その結果、
#       ・飛び飛びの休みを直せない
#       ・直すと、先頭以外の古い「お休み」がカレンダーに残る
#     残った古い休みは送迎の運行表で「お休み」と出るので、
#     【来るはずの方を休み扱いにする】ところまで行く。
#
#   ★直し方
#     編集も作成と同じく「日付の一覧」で扱う。保存のたびに
#     その記録に紐づくカレンダーを【全部消して作り直す】。
#     1件だけ直す作りに戻さないこと。必ず食い違う。
# ==========================================================
def _leave_event_rows(supabase, f_code, record_id):
    """その記録に紐づく「お休み」カレンダーを全部取る。

    ★読めなかったときは None を返す。[] と同じにしないこと。
      「1件も無い」と「読めなかった」を混同すると、
      消すべき行を消し損ねて【来る方が休み扱いのまま】残る。
    """
    try:
        r = (supabase.table("calendar_events").select("id,event_date,end_date")
             .eq("facility_code", f_code).eq("record_id", record_id).execute())
        return r.data or []
    except Exception as e:
        print(f"[leave-dates] events fetch error: {e}", flush=True)
        return None


@app.route('/api/record/leave-dates', methods=['GET'])
@login_required
def api_record_leave_dates():
    """休み連絡1件の「実際の休みの日」を返す。編集画面が開くときに呼ぶ。

    ★記録の leave_date_start / end は範囲しか持てないので、飛び飛びは表せない。
      本当の日付はカレンダー側にある。だからそちらを正とする。
      （古い記録などでカレンダーが1件も無いときだけ、start〜end を広げて返す）
    """
    from datetime import timedelta as _td
    try:
        f_code = session["f_code"]
        rid = (request.args.get("id") or "").strip()
        if not rid:
            return jsonify({"status": "error", "message": "idが必要です"}), 400
        supabase = get_supabase()
        rec = (supabase.table("records")
               .select("id,category,leave_date_start,leave_date_end,calendar_event_id")
               .eq("id", rid).eq("facility_code", f_code).execute())
        if not rec.data:
            return jsonify({"status": "error", "message": "見つかりません"}), 404
        row = rec.data[0]

        dates = set()
        evs = _leave_event_rows(supabase, f_code, rid)
        if evs is None:
            # ★読めないまま「0件」を返すと、画面が「休みなし」と表示して
            #   そのまま保存され、本当の休みが全部消える。必ず失敗として返す。
            return jsonify({"status": "error", "message": "休みの日を読めませんでした"}), 503
        for ev in evs:
            d = (ev.get("event_date") or "")[:10]
            e = (ev.get("end_date") or d)[:10]
            if not d:
                continue
            try:
                a = datetime.strptime(d, "%Y-%m-%d").date()
                b = datetime.strptime(e, "%Y-%m-%d").date()
            except Exception:
                continue
            if b < a:
                b = a
            # 期間で入っている古いイベントは、1日ずつに開いて返す
            cur = a
            while cur <= b and (cur - a).days <= 400:
                dates.add(cur.strftime("%Y-%m-%d"))
                cur += _td(days=1)

        if not dates:
            s = (row.get("leave_date_start") or "")[:10]
            e = (row.get("leave_date_end") or s)[:10]
            if s:
                try:
                    a = datetime.strptime(s, "%Y-%m-%d").date()
                    b = datetime.strptime(e or s, "%Y-%m-%d").date()
                    if b < a:
                        b = a
                    cur = a
                    while cur <= b and (cur - a).days <= 400:
                        dates.add(cur.strftime("%Y-%m-%d"))
                        cur += _td(days=1)
                except Exception:
                    pass

        # ★source: "events" はカレンダーの実物。"range" は
        #   カレンダーが1件も無くて、記録の最初〜最後から【推測で広げた】もの。
        #   推測は飛び飛びを潰してしまうので、画面側で必ず断りを出すこと。
        return jsonify({"status": "success", "dates": sorted(dates),
                        "source": ("events" if evs else "range")})
    except Exception as e:
        print(f"[leave-dates] error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route('/api/update_record', methods=['POST'])
@login_required
def api_update_record():
    try:
        data = request.json
        if not data or not data.get("id") or data.get("content") is None:
            return jsonify({"status": "error", "message": "id と content は必須です"}), 400
        supabase = get_supabase()
        # ★leave-dates-edit-v1 で気づいた抜け：この関数には f_code が無かった。
        #   下の AI要約キャッシュ無効化がずっと NameError で落ちていた（try で握って
        #   いたので誰も気づかなかった）。＝記録を直しても、その日のAI要約が
        #   古いまま残っていた。ここで定義して、あわせて直す。
        f_code = session["f_code"]
        update_payload = {"content": data["content"]}
        # Session 33: 休み連絡カテゴリの編集で送られたら type/relation も更新
        # (payload に含まれない場合は既存値を維持)
        if "leave_reporter_type" in data:
            _t = (data.get("leave_reporter_type") or "").strip() or None
            _r = (data.get("leave_reporter_relation") or "").strip() or None
            update_payload["leave_reporter_type"] = _t
            update_payload["leave_reporter_relation"] = _r
        if "leave_reason" in data:
            update_payload["leave_reason"] = (data.get("leave_reason") or "").strip() or None
        # leave-edit-reason-sync: 休み連絡の編集なら、日付未送信でも既存日付を補完して
        # content再生成・カレンダー同期を行えるようにする(理由だけ変更しても反映される)
        new_leave_start = (data.get("leave_date_start") or "").strip() or None
        new_leave_end = (data.get("leave_date_end") or "").strip() or None
        # leave-dates-edit-v1: 飛び飛びの休みは範囲では表せない。日付の一覧で受け取る。
        _raw_dates = data.get("leave_dates")
        if isinstance(_raw_dates, str):
            _raw_dates = [x.strip() for x in _raw_dates.split(",")]
        new_leave_dates = []
        for _d in (_raw_dates or []):
            _d = (str(_d) or "").strip()[:10]
            if not _d:
                continue
            try:
                datetime.strptime(_d, "%Y-%m-%d")
            except Exception:
                continue
            if _d not in new_leave_dates:
                new_leave_dates.append(_d)
        new_leave_dates.sort()
        if _raw_dates is not None and not new_leave_dates:
            # 送られてきたのに1件も通らなかった＝形がおかしい。黙って捨てない。
            return jsonify({"status": "error",
                            "message": "休みの日付の形が正しくありません（YYYY-MM-DD）"}), 400
        if new_leave_dates:
            # 記録の欄には「いちばん早い日」と「いちばん遅い日」を入れる。
            # 一覧そのものはカレンダー側が正（ここは検索・表示のための目安）。
            new_leave_start = new_leave_dates[0]
            new_leave_end = new_leave_dates[-1]
        else:
            # 一覧が無いときも、start/end は必ず形を確かめてから入れる。
            #   ここが素通しだと、おかしな文字列が records に入り、
            #   送迎の「お休み」判定（文字列の大小比較）が狂う。
            for _v in (new_leave_start, new_leave_end):
                if _v:
                    try:
                        datetime.strptime(_v[:10], "%Y-%m-%d")
                    except Exception:
                        return jsonify({"status": "error",
                                        "message": "休みの日付の形が正しくありません"}), 400
        _is_leave_edit = ("leave_reason" in data) or ("leave_reporter_type" in data)
        if _is_leave_edit and not new_leave_start:
            try:
                _exist = supabase.table("records").select("leave_date_start,leave_date_end,category").eq("id", data["id"]).execute()
                if _exist.data:
                    _row0 = _exist.data[0]
                    if _row0.get("category") == "休み連絡":
                        new_leave_start = (_row0.get("leave_date_start") or "").strip() or None
                        new_leave_end = (_row0.get("leave_date_end") or "").strip() or None
            except Exception as _ex0:
                print(f"[休み編集 既存日付取得エラー] {_ex0}", flush=True)
        if new_leave_start:
            update_payload["leave_date_start"] = new_leave_start
            update_payload["leave_date_end"] = new_leave_end or new_leave_start
            # leave-content-trust-v1: contentはフロントのtextarea値をそのまま使う。
            # 以前はここでサーバ側再生成していたが、ユーザーが編集した内容を上書きしてしまうバグの原因だった。
            # JSのautoUpdateLeaveContent()が日付/理由変更時にtextareaを更新するので、
            # サーバ側の再生成は不要。
        # ★leave-dates-edit-v1: カレンダーの作り直しは【記録を書き換える前】に済ませる。
        #   しかも【作ってから消す】。先に消すと、途中で失敗したときに
        #   「本当の休みの日」がどこにも残らない（records は最初と最後しか持たない）。
        if new_leave_dates:
            _rr = (supabase.table("records").select("calendar_event_id,user_name,content")
                   .eq("id", data["id"]).eq("facility_code", f_code).execute())
            if not _rr.data:
                return jsonify({"status": "error", "message": "記録が見つかりません"}), 404
            _cal_old_id = _rr.data[0].get("calendar_event_id")
            _uname = _rr.data[0].get("user_name") or ""
            _memo = data.get("content") or _rr.data[0].get("content") or ""

            _old = _leave_event_rows(supabase, f_code, data["id"])
            if _old is None:
                return jsonify({"status": "error",
                                "message": "いまのカレンダーを読めませんでした。何も変えていません。"}), 503

            _cal_id = _get_or_create_system_calendar(supabase, f_code, session.get("my_name", ""))
            if not _cal_id:
                return jsonify({"status": "error",
                                "message": "カレンダーを用意できませんでした。何も変えていません。"}), 503

            _new_ids = []
            try:
                for _cd in new_leave_dates:
                    _ins = supabase.table("calendar_events").insert({
                        "facility_code": f_code,
                        "calendar_id": _cal_id,
                        "title": f"{_uname}様 お休み",
                        "event_date": _cd,
                        "end_date": _cd,
                        "all_day": True,
                        "color": "#e53935",
                        "memo": _memo,
                        "created_by": session.get("my_name", ""),
                        "record_id": data["id"],
                    }).execute()
                    if not _ins.data:
                        raise RuntimeError(f"insert returned no row for {_cd}")
                    _new_ids.append(_ins.data[0]["id"])
            except Exception as _ie:
                # 作りかけを片づけて、古いほうをそのまま残す
                print(f"[休み編集] 作り直し失敗 {_ie}。作りかけ {len(_new_ids)}件を戻します", flush=True)
                for _nid in _new_ids:
                    try:
                        supabase.table("calendar_events").delete() \
                            .eq("id", _nid).eq("facility_code", f_code).execute()
                    except Exception:
                        pass
                return jsonify({"status": "error",
                                "message": "カレンダーを作り直せませんでした。日付は元のままです。"}), 503

            # ここまで来たら新しいほうは全部そろっている。古いほうを消す
            _old_ids = [x["id"] for x in _old if x.get("id")]
            if _cal_old_id and _cal_old_id not in _old_ids and _cal_old_id not in _new_ids:
                _old_ids.append(_cal_old_id)     # record_id の無い古い行も必ず消す
            for _oid in _old_ids:
                try:
                    supabase.table("calendar_events").delete() \
                        .eq("id", _oid).eq("facility_code", f_code).execute()
                except Exception as _de:
                    print(f"[休み編集] 旧イベント削除失敗 {_oid}: {_de}", flush=True)
            update_payload["calendar_event_id"] = _new_ids[0]
            print(f"[休み編集] record {data['id']} のカレンダーを {len(_new_ids)}件で作り直しました", flush=True)

        supabase.table("records").update(update_payload) \
            .eq("id", data["id"]).eq("facility_code", f_code).execute()
        # AI要約キャッシュ無効化
        try:
            _rec_info = (supabase.table('records').select('user_name,created_at')
                         .eq('id', data['id']).eq('facility_code', f_code).execute())
            if _rec_info.data:
                _invalidate_daily_summary(supabase, f_code, _rec_info.data[0]['user_name'], _rec_info.data[0].get('created_at'))
        except Exception as _inv_e2:
            print(f"[AI要約キャッシュ無効化エラー(edit)] {_inv_e2}", flush=True)
        # 休み日付変更時にカレンダーイベントも同期
        #   ★日付の一覧が来ているときは、上でもう「作ってから消す」で作り直してある。
        #     ここは【一覧が来ていない古い経路】（理由だけ直した等）のためだけに残す。
        if new_leave_start and not new_leave_dates:
            try:
                rec_row = (supabase.table("records").select("calendar_event_id,user_name")
                           .eq("id", data["id"]).eq("facility_code", f_code).execute())
                if rec_row.data:
                    cal_event_id = rec_row.data[0].get("calendar_event_id")
                    user_name_cal = rec_row.data[0].get("user_name", "")
                    if cal_event_id:
                        # ★イベントが2件以上ある＝飛び飛びの休み。ここで1件だけ
                        #   start〜end に書き換えると、他の日と食い違って壊れる。触らない。
                        #   読めなかったとき（None）も、安全側に倒して触らない。
                        _evs = _leave_event_rows(supabase, f_code, data["id"])
                        if _evs is None or len(_evs) > 1:
                            print(f"[休み編集] 飛び飛び／読めずのため、日付の一覧なしでは触らない", flush=True)
                        else:
                            supabase.table("calendar_events").update({
                                "event_date": new_leave_start,
                                "end_date": new_leave_end or new_leave_start,
                                "title": f"{user_name_cal}様 お休み",
                            }).eq("id", cal_event_id).eq("facility_code", f_code).execute()
                            print(f"[休み編集] カレンダーイベント {cal_event_id} を{new_leave_start}に更新", flush=True)
            except Exception as _cal_upd:
                print(f"[休み編集カレンダー同期エラー] {_cal_upd}", flush=True)

        # Session 36: VAS データの UPSERT(全削除 → 再 INSERT)
        # payload に vas_records が含まれていれば実施。含まれていなければ既存 VAS を維持。
        if "vas_records" in data:
            try:
                # 既存の権限チェック用に records から facility_code, user_name を取得
                rec_row = supabase.table("records").select("facility_code, user_name").eq("id", data["id"]).execute()
                if rec_row.data:
                    rec_facility = rec_row.data[0]["facility_code"]
                    rec_user_name = rec_row.data[0]["user_name"]
                    # 既存 VAS を全削除
                    supabase.table("record_vas").delete().eq("record_id", data["id"]).execute()
                    # 新規 VAS を一括 INSERT(空配列なら何も入れない)
                    vas_list = data.get("vas_records") or []
                    vas_rows = []
                    for v in vas_list:
                        if not isinstance(v, dict):
                            continue
                        part = v.get("part")
                        side = v.get("side")
                        value = v.get("vas_value") if "vas_value" in v else v.get("value")
                        if not part or not side:
                            continue
                        if not isinstance(value, int) or value < 0 or value > 10:
                            continue
                        vas_rows.append({
                            "record_id": data["id"],
                            "facility_code": rec_facility,
                            "user_name": rec_user_name,
                            "part": part,
                            "side": side,
                            "vas_value": value,
                        })
                    if vas_rows:
                        supabase.table("record_vas").insert(vas_rows).execute()
                        print(f"[vas_records] updated {len(vas_rows)} entries for record {data['id']}", flush=True)
                    else:
                        print(f"[vas_records] cleared all entries for record {data['id']}", flush=True)
            except Exception as _vas_upd_err:
                print(f"[vas_records] update failed for record {data['id']}: {_vas_upd_err}", flush=True)

        return jsonify({"status": "success"})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500

@app.route('/api/delete_record', methods=['POST'])
@login_required
def api_delete_record():
    try:
        data = request.json
        if not data or not data.get("id"):
            return jsonify({"status": "error", "message": "id は必須です"}), 400
        f_code = session["f_code"]
        my_name = session["my_name"]
        is_admin = session.get("admin_authenticated", False)
        supabase = get_supabase()
        # 権限チェック：自分の記録か管理者のみ削除可能
        rec = supabase.table("records").select(
            "staff_name,facility_code,calendar_event_id,category,user_name,created_at").eq("id", data["id"]).execute()
        if not rec.data:
            return jsonify({"status": "error", "message": "記録が見つかりません"}), 404
        r = rec.data[0]
        if r["facility_code"] != f_code:
            return jsonify({"status": "error", "message": "権限がありません"}), 403
        if not is_admin and r["staff_name"] != my_name:
            return jsonify({"status": "error", "message": "この記録を削除する権限がありません"}), 403

        # record-cal-delete-sync-v1: 休み連絡・追加利用連絡はカレンダーにイベントを自動生成する。
        # 記録を消したらカレンダー側も消さないと、消したはずの「お休み」が残る（双方向同期の片方向漏れ）。
        # 複数日の休みは複数イベントになるが、全イベントが record_id で紐づくのでまとめて消せる。
        # 念のため旧データ対策として records.calendar_event_id 経由でも1件消す（record_id 未設定の古いイベント用）。
        # ※ カレンダーの delete API 経由ではなく直接 delete するので、記録側を巻き込む再帰は起きない。
        try:
            supabase.table("calendar_events").delete().eq(
                "facility_code", f_code).eq("record_id", data["id"]).execute()
            _legacy_eid = r.get("calendar_event_id")
            if _legacy_eid:
                supabase.table("calendar_events").delete().eq(
                    "facility_code", f_code).eq("id", _legacy_eid).execute()
        except Exception as _cal_del_err:
            # カレンダー削除に失敗しても記録削除は続行（孤児イベントは残るが記録は消える）
            print(f"[record delete] calendar sync failed for record {data['id']}: {_cal_del_err}", flush=True)

        # AI要約キャッシュ無効化（削除前に user_name/created_at を使う）
        _invalidate_daily_summary(supabase, f_code, r.get('user_name', ''), r.get('created_at'))
        supabase.table("records").delete().eq("id", data["id"]).execute()
        return jsonify({"status": "success"})
    except Exception as e:
        return jsonify({"status": "error"}), 500

# ===== mon-no-greeting-v1: 前置き・結びの挨拶を外す =====
# ★外すのは【中身の無い1文】だけ。緩めると記録そのものが消える。
#   ここは「消しすぎない」ことが最優先。挨拶が1つ残るのは困らないが、
#   記録が1文消えるのは、ケアマネジャーに渡す書類が事実と食い違うということ。

# 先頭の1文に出てくる言い回し
_MON_LEAD = ("お伝えします", "お伝えいたします", "ご報告します", "ご報告いたします",
             "報告いたします", "報告します", "ご報告申し上げます", "お知らせします",
             "報告させていただきます", "お伝えさせていただきます")
# 末尾の1文の「終わりかた」
_MON_TAIL_END = ("ご報告いたします。", "ご報告します。", "報告いたします。", "報告します。",
                 "お伝えしました。", "お伝えいたしました。", "まいります。", "参ります。",
                 "お願いいたします。", "お願いします。", "お願い申し上げます。")
# 末尾の1文が挨拶だと分かる言葉（終わりかたと【両方】そろって初めて外す）
_MON_TAIL_WORD = ("以上", "引き続き", "今後とも", "今後も", "よろしくお願い",
                  "ご報告", "お伝え")
# ★この語が入っている文は外さない。挨拶ではなく記録だから。
#   「ご家族へ電話でご報告いたします」「主治医へ連絡し受診いたします」など。
_MON_KEEP = ("家族", "ケアマネ", "医師", "看護", "連絡", "受診", "病院", "主治医")


def _mon_sentences(t):  # mon-no-greeting-v1
    """「。」で切る。区切りの「。」は文のほうに残す（つなぎ直しても元に戻る）。"""
    out, buf = [], ""
    for ch in t:
        buf += ch
        if ch == "。":
            out.append(buf)
            buf = ""
    if buf.strip():
        out.append(buf)
    return out


def _mon_is_lead(s):  # mon-no-greeting-v1
    s = s.strip()
    if len(s) > 60 or any(k in s for k in _MON_KEEP):
        return False
    return any(k in s for k in _MON_LEAD)


def _mon_is_tail(s):  # mon-no-greeting-v1
    s = s.strip()
    if len(s) > 60 or any(k in s for k in _MON_KEEP):
        return False
    # ★数字が入っている文は外さない。数字は中身（回数・体重・血圧など）。
    if any(c.isdigit() for c in s):
        return False
    if not any(s.endswith(e) for e in _MON_TAIL_END):
        return False
    return any(w in s for w in _MON_TAIL_WORD)


def _mon_strip_greeting(text):  # mon-no-greeting-v1
    """前置きと結びを、それぞれ最大1文だけ外す。

    ★短い文には触らない（40文字未満）。
      「今月このカテゴリの報告はありませんでした」「（生成エラー: …）」を
      外してしまうと、記録が無いことと生成が失敗したことが画面から消えて、
      職員が気づけなくなる。それは前の不具合に戻すのと同じ。
    ★全部消えるときは元をそのまま返す。空を返すくらいなら挨拶を残す。
    """
    t0 = (text or "").strip()
    if len(t0) < 40:
        return t0
    ss = _mon_sentences(t0)
    if len(ss) < 2:
        return t0
    if _mon_is_lead(ss[0]):
        ss = ss[1:]
    if ss and _mon_is_tail(ss[-1]):
        ss = ss[:-1]
    return "".join(ss).strip() or t0


def _mon_strip_read(row):  # mon-strip-read-v1
    """保存済みの報告書を【読むとき】に、前置き・結びの挨拶を外して返す。

    ★DBは1件も変えない。読んだものを渡す前に外すだけ。だからいつでも戻せる。
    ★手直し(インライン編集)も /api/monitoring_detail から同じ文を受け取るので、
      「画面では消えているのに編集を開くと挨拶が戻る」という食い違いが起きない。
      手直しして保存すれば、そのときDBの側もきれいになる。
    ★外す処理そのものは _mon_strip_greeting。40文字未満には触らないので
      「今月このカテゴリの報告はありませんでした」は消えない。
      「【この行は書類には印刷されません…】AIの生成に失敗しました…」も、
      前置き・結びのどちらの形にも当たらないので消えない（確認ずみ）。
      ここを緩めると、記録が無いことと生成が失敗したことが画面から消える。
    ★categories は {カテゴリ名: 本文} の辞書。まとめて1本モードは full_text。
    """
    if not isinstance(row, dict):
        return row
    cats = row.get("categories")
    if isinstance(cats, dict):
        row["categories"] = {
            k: (_mon_strip_greeting(v) if isinstance(v, str) else v)
            for k, v in cats.items()
        }
    full = row.get("full_text")
    if isinstance(full, str):
        row["full_text"] = _mon_strip_greeting(full)
    return row


@app.route('/api/generate_monitoring', methods=['POST'])
@login_required
def api_generate_monitoring():
    """モニタリング報告書 AIで生成（カテゴリ別 or まとめて1本）"""
    try:
        data = request.json
        f_code = session["f_code"]
        supabase = get_supabase()

        u_name = data.get("user_name", "").strip()
        month_val = data.get("month", "")       # "2026-04"
        mode = data.get("mode", "category")      # "category" or "full"
        char_limit = int(data.get("char_limit", 200))
        selected_cats = data.get("categories", [])  # カテゴリ別モード時の選択リスト

        if not u_name or not month_val:
            return jsonify({"error": "利用者と対象月を指定してください"}), 400

        CATEGORIES = ["心身状況", "食事", "入浴", "排泄", "コミュニケーション", "訓練状況", "ヒヤリハット", "その他"]
        target_cats = selected_cats if selected_cats else CATEGORIES

        y, m = map(int, month_val.split("-"))
        s_date = tokyo_tz.localize(datetime(y, m, 1))
        e_date = (s_date + timedelta(days=32)).replace(day=1)

        # 記録を取得（AI統合記録・休み連絡を除外）
        res = supabase.table("records").select(
            "content, category, staff_name, created_at"
        ).eq("facility_code", f_code).eq("user_name", u_name).gte(
            "created_at", s_date.isoformat()
        ).lt("created_at", e_date.isoformat()).execute()

        records = [r for r in (res.data or [])
                   if r.get("staff_name") not in ("AI統合記録",)
                   and r.get("category") != "休み連絡"]
        def _replace_kyouha(record):
            content_text = record.get("content") or ""
            created_at = record.get("created_at") or ""
            if not created_at or "今日" not in content_text:
                return record
            try:
                from datetime import datetime as _dt3
                import pytz as _pytz
                _tz = _pytz.timezone("Asia/Tokyo")
                _dt = _dt3.fromisoformat(created_at.replace("Z", "+00:00")).astimezone(_tz)
                _date_str = f"{_dt.month}月{_dt.day}日"
                for _old, _new in [
                    ("今日は", f"{_date_str}は"),
                    ("今日も", f"{_date_str}も"),
                    ("今日、", f"{_date_str}、"),
                    ("今日。", f"{_date_str}。"),
                    ("今日（", f"{_date_str}（"),
                    ("今日の", f"{_date_str}の"),
                    ("今日で", f"{_date_str}で"),
                    ("今日から", f"{_date_str}から"),
                    ("今日まで", f"{_date_str}まで"),
                ]:
                    content_text = content_text.replace(_old, _new)
                return {**record, "content": content_text}
            except Exception:
                return record
        records = [_replace_kyouha(r) for r in records]

        # 休み連絡レコードから実際の休日情報を取得
        leave_res = supabase.table("records").select(
            "leave_date_start, leave_date_end, leave_reporter_type, leave_reason"
        ).eq("facility_code", f_code).eq("user_name", u_name).eq(
            "category", "休み連絡"
        ).gte("created_at", s_date.isoformat()).lt("created_at", e_date.isoformat()).execute()
        leave_records = leave_res.data or []

        # 実際の休日情報をテキストに変換
        leave_notes = []
        for lr in leave_records:
            _ls = lr.get("leave_date_start")
            _le = lr.get("leave_date_end")
            if not _ls:
                continue
            try:
                from datetime import datetime as _dt2
                _ls_d = _dt2.strptime(_ls[:10], "%Y-%m-%d")
                _ls_str = f"{_ls_d.month}月{_ls_d.day}日"
                _lr_reason = (lr.get("leave_reason") or "").strip()
                _lr_type = lr.get("leave_reporter_type") or ""
                _reporter_map_n = {"self": "本人", "family": "家族", "caremanager": "ケアマネ", "other": "その他", "none": "連絡なし"}  # leave-reporter-display-v1
                _reporter_n = _reporter_map_n.get(_lr_type, "")
                if _le and _le[:10] != _ls[:10]:
                    _le_d = _dt2.strptime(_le[:10], "%Y-%m-%d")
                    _period_n = f"{_ls_str}〜{_le_d.month}月{_le_d.day}日"
                else:
                    _period_n = _ls_str
                _note_text = _build_leave_content(_period_n, _lr_type, "", _lr_reason)
                leave_notes.append(_note_text)
            except Exception:
                pass

        if not records and not leave_notes:
            return jsonify({"error": f"{u_name}様の{y}年{m}月の記録が見つかりません"}), 404

        from utils import get_generative_model
        model = get_generative_model()

        BASE_PROMPT = (  # prompt-tone-v1
            "あなたは介護施設のベテランケアマネジャーの補佐をしています。"
            f"【対象の確認(最重要)】\n"
            f"この報告の対象はご利用者「{u_name}」様です。記録には複数の職員や他のご利用者が登場することがありますが、報告対象は常に「{u_name}」様です。主語を取り違えないでください。\n"
            "以下の介護記録を読み、ケアマネジャーへのモニタリング報告書として使える文章を生成してください。\n"
            "【ルール】\n"
            "・事実として記録されていること以外は絶対に書かない（ハルシネーション厳禁）\n"
            "・記録がない場合は文章を作らず「今月このカテゴリの報告はありませんでした」とだけ返す\n"
            "・職員名・利用者名・主語は不要\n"
            "・記録の中に他のご利用者の名前が出てきた場合は、その名前を書かず必ず「他の利用者様」と表現する\n"
            "・箇条書きは使わず、ひとつながりの文章で書く\n"
            "・口調は報告文書として読みやすい丁寧語(です・ます)。二重敬語や過剰な敬語(「お〜になられる」「ございました」等)は避け、硬すぎず砕けすぎない自然な丁寧さにとどめる\n"
            # mon-no-greeting-v1: 前置き・結びの挨拶を書かせない。
            #   ★指示だけでは止まりきらないので、あとで外す処理も入れてある。
            "・前置きの挨拶を書かない。「今月の◯◯をお伝えします」「◯◯についてご報告いたします」のような書き出しは禁止。1文目から記録の中身を書き始める\n"
            "・結びの挨拶を書かない。「以上、ご報告いたします」「引き続き見守ってまいります」「今後ともよろしくお願いいたします」のような、記録に無いことを述べる締めの文は書かない\n"
        )

        if mode == "full":
            # まとめて1本モード
            all_recs = "\n".join(r["content"] for r in records)
            leave_text = ("\n".join(leave_notes) + "\n") if leave_notes else ""
            leave_section = f"『休日情報』\n{leave_text}\n" if leave_text else ""
            prompt = (
                BASE_PROMPT +
                f"・全体をひとまとめにして{char_limit}文字程度で生成\n"
                + (f"・休日情報は必ず文中に含めること\n\n" if leave_text else "\n")
                + leave_section
                + f"『記録』\n{all_recs}"
            )
            # mon-no-greeting-v1: 付いてきた前置き・結びを外す
            result_text = _mon_strip_greeting(
                model.generate_content([prompt]).text.strip())
            return jsonify({
                "mode": "full",
                "full_text": result_text,
                "record_count": len(records)
            })

        else:
            # カテゴリ別モード
            cat_records = {}
            for r in records:
                cat = r.get("category") or "その他"
                cat_records.setdefault(cat, []).append(r["content"])

            results = {}
            counts = {}
            NO_RECORD_MSG = "今月このカテゴリの報告はありませんでした"

            for cat in CATEGORIES:
                if cat not in target_cats:
                    continue
                recs_in_cat = cat_records.get(cat, [])
                counts[cat] = len(recs_in_cat)
                if not recs_in_cat:
                    results[cat] = NO_RECORD_MSG
                    continue
                cat_text = "\n".join(recs_in_cat)
                prompt = (
                    BASE_PROMPT +
                    f"・カテゴリ「{cat}」に関する記録だけをまとめて{char_limit}文字程度で生成\n\n"
                    f"【{cat}の記録】\n{cat_text}"
                )
                try:
                    # mon-no-greeting-v1: 付いてきた前置き・結びを外す
                    results[cat] = _mon_strip_greeting(
                        model.generate_content([prompt]).text.strip())
                except Exception as e:
                    results[cat] = f"（生成エラー: {str(e)[:50]}）"
# 評価データ取得
            eval_res = supabase.table("patient_evaluations").select(
                "changes_by_training,issues_and_causes,special_notes,satisfaction,service_appropriateness,new_requests_exist,new_requests_detail"
            ).eq("facility_code", f_code).eq("user_name", u_name).eq("year_month", month_val).execute()
            eval_data = eval_res.data[0] if eval_res.data else {}
            NO_EVAL_MSG = "評価ページにて評価を済ませてください"
            # 訓練による変化
            changes = eval_data.get("changes_by_training") or ""
            if not changes: changes = NO_EVAL_MSG
            # 課題とその要因
            issues = eval_data.get("issues_and_causes") or ""
            if not issues: issues = NO_EVAL_MSG
            eval_extra = {
                "changes_by_training": changes,
                "issues_and_causes": issues,
                "special_notes": eval_data.get("special_notes") or "",
                "satisfaction": eval_data.get("satisfaction") or "",
                "service_appropriateness": eval_data.get("service_appropriateness") or "",
                "new_requests_exist": eval_data.get("new_requests_exist"),
                "new_requests_detail": eval_data.get("new_requests_detail") or "",
            }
            return jsonify({
                "mode": "category",
                "categories": results,
                "record_counts": counts,
                "total_records": len(records),
                "eval_extra": eval_extra
            })

    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route('/api/shorten_text', methods=['POST'])
@login_required
def api_shorten_text():
    """onepage-fit-v1: 既存の文章を、意味を保ったまま指定文字数程度に短縮する（書類の1枚化・自動調整用）。"""
    try:
        data = request.json or {}
        text = (data.get("text") or "").strip()
        try:
            max_chars = int(data.get("max_chars", 150))
        except (ValueError, TypeError):
            max_chars = 150
        if not text:
            return jsonify({"status": "success", "text": ""})
        if len(text) <= max_chars:
            return jsonify({"status": "success", "text": text, "unchanged": True})
        prompt = (
            "次の介護記録の文章を、意味・事実を変えずに自然な日本語(ですます調)で"
            + f"約{max_chars}文字に短くまとめてください。\n"
            + "・箇条書きにしない。1〜数文の文章にする。\n"
            + "・新しい情報は加えない。固有名詞・数値・重要な事実は残す。\n"
            + "・前置きや補足は書かず、短くした本文だけを出力する。\n\n"
            + "【元の文章】\n" + text
        )
        try:
            from utils import get_generative_model
            model = get_generative_model()
            out = (model.generate_content([prompt]).text or "").strip()
        except Exception as e:
            return jsonify({"status": "error", "message": str(e), "text": text}), 500
        return jsonify({"status": "success", "text": out or text})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route('/api/save_monitoring', methods=['POST'])
@login_required
def api_save_monitoring():
    """モニタリング報告書を下書き保存 or 確定保存"""
    try:
        data = request.json
        f_code = session["f_code"]
        u_name = session.get("my_name", "")  # 確定者名（session キー修正 u_name->my_name）
        supabase = get_supabase()

        user_name = data.get("user_name", "").strip()
        month_val = data.get("month", "")
        mode = data.get("mode", "category")
        char_limit = int(data.get("char_limit", 200))
        categories = data.get("categories", {})
        full_text = data.get("full_text", "")
        record_counts = data.get("record_counts", {})
        confirm = data.get("confirm", False)
        allow_confirmed = data.get("allow_confirmed", False)  # 確定済みでも内容上書きを許可（UI側で確認済みのとき true）

        if not user_name or not month_val:
            return jsonify({"error": "必須項目が不足しています"}), 400

        # 既存レコードを確認（同月・同利用者）
        existing = supabase.table("monitoring_reports").select("id, confirmed_at").eq(
            "facility_code", f_code
        ).eq("user_name", user_name).eq("target_month", month_val).execute()

        payload = {
            "facility_code": f_code,
            "user_name": user_name,
            "target_month": month_val,
            "mode": mode,
            "char_limit": char_limit,
            "categories": categories,
            "full_text": full_text,
            "record_counts": record_counts,
            "updated_at": "now()",
        }
        if confirm:
            payload["confirmed_at"] = "now()"
            payload["confirmed_by"] = u_name

        if existing.data:
            rec = existing.data[0]
            if rec.get("confirmed_at") and not confirm and not allow_confirmed:
                # 確定済みは上書き不可。UI側で確認(confirm)を取り allow_confirmed=true で明示上書き可能
                return jsonify({"error": "確定済みの報告書は上書きできません", "confirmed": True}), 409
            supabase.table("monitoring_reports").update(payload).eq("id", rec["id"]).execute()
            # allow_confirmed の内容上書きでは payload に confirmed_at を含めないため、確定状態は維持される
            return jsonify({"saved": True, "id": rec["id"], "confirmed": bool(rec.get("confirmed_at")) or confirm})
        else:
            result = supabase.table("monitoring_reports").insert(payload).execute()
            new_id = result.data[0]["id"] if result.data else None
            return jsonify({"saved": True, "id": new_id, "confirmed": confirm})

    except Exception as e:
        return jsonify({"error": str(e)}), 500


