@app.route('/api/shift/save', methods=['POST'])
@login_required
def api_shift_save():
    f_code = session['f_code']
    supabase = get_supabase()
    data = request.get_json(silent=True) or {}
    cells = data.get('cells') or []
    me = session.get('my_name', '')
    _is_admin = is_admin_user(supabase, f_code, me)  # shift-self-only-v1
    saved = 0
    now_iso = datetime.now(timezone.utc).isoformat()

    # shift-leave-sync-v1: 対象範囲の既存の休み記録を【1回だけ】まとめて取る。
    #   セルごとに問い合わせると1ヶ月保存で30往復増えて重くなるため。
    lmap = {}
    try:
        _ds = sorted({(c.get('date') or '').strip() for c in cells if (c.get('date') or '').strip()})
        _ns = sorted({(c.get('name') or '').strip() for c in cells if (c.get('name') or '').strip()})
        if _ds and _ns:
            _lr = supabase.table("staff_leave_days").select(
                "id,staff_name,leave_date,leave_type,source").eq(
                "facility_code", f_code).gte("leave_date", _ds[0]).lte(
                "leave_date", _ds[-1]).in_("staff_name", _ns).execute()
            for r in (_lr.data or []):
                lmap[str(r.get("staff_name")) + "|" + str(r.get("leave_date"))] = r
    except Exception as e:
        print(f"[shift-leave-sync] prefetch: {e}", flush=True)

    for c in cells:
        nm = (c.get('name') or '').strip()
        dt = (c.get('date') or '').strip()
        if not nm or not dt:
            continue
        if (not _is_admin) and nm != me:  # 管理者以外は本人分のみ保存
            continue
        try:
            _dt = c.get('day_type')  # youshiki-daytype-v1: 'full'|'half'|None
            if _dt not in ('full', 'half'):
                _dt = None
            _st = c.get('status') or 'off'
            # shift-leave-sync-v1: 休みの日だけ区分を持つ。出勤日には残さない
            _lt = (c.get('leave_type') or '').strip()
            if _st != 'off' or _lt not in _SHIFT_LEAVE_TYPES:
                _lt = None
            supabase.table("staff_shift_plan").upsert({
                "facility_code": f_code, "staff_name": nm, "plan_date": dt,
                "status": _st,
                "start_time": c.get('start'), "end_time": c.get('end'),
                "day_type": _dt,
                "leave_type": _lt,          # shift-leave-sync-v1
                "updated_at": now_iso,
            }, on_conflict="facility_code,staff_name,plan_date").execute()
            saved += 1
            _shift_leave_sync(supabase, f_code, nm, dt, _st, _lt,
                              lmap.get(nm + "|" + dt), me, now_iso)
        except Exception as e:
            print(f"[shift save] {e}", flush=True)
    return jsonify({"status": "success", "saved": saved})


@app.route('/api/shift/default', methods=['POST'])
@login_required
def api_shift_default():
    f_code = session['f_code']
    supabase = get_supabase()
    data = request.get_json(silent=True) or {}
    nm = (data.get('name') or '').strip()
    _me = session.get('my_name', '')
    if not is_admin_user(supabase, f_code, _me):  # shift-self-only-v1: 管理者以外は本人のみ
        nm = _me
    if not nm:
        return jsonify({"status": "error", "message": "職員名が必要です"}), 400
    wd = data.get('weekdays')
    if not (isinstance(wd, list) and len(wd) == 7):
        wd = [True, True, True, True, True, False, False]
    # shift-weekday-times-v1: 曜日ごとの時間。
    #   start_time / end_time にも値を残す（古い画面や過去データとの互換のため）。
    #   入れるのは「チェックが入っている最初の曜日」の時間。全部休みなら送られてきた共通値。
    _base_s = data.get('start') or '09:00'
    _base_e = data.get('end') or '18:00'
    times = _shift_times_norm(data.get('weekday_times'), _base_s, _base_e)
    for i in range(7):
        if wd[i]:
            _base_s, _base_e = times[i]["start"], times[i]["end"]
            break
    try:
        supabase.table("staff_shift_defaults").upsert({
            "facility_code": f_code, "staff_name": nm,
            "weekdays": [bool(x) for x in wd],
            "start_time": _base_s,
            "end_time": _base_e,
            "weekday_times": times,          # shift-weekday-times-v1
            "updated_at": datetime.now(timezone.utc).isoformat(),
        }, on_conflict="facility_code,staff_name").execute()
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500
    return jsonify({"status": "success"})


@app.route('/api/shift/copy', methods=['POST'])
@login_required
def api_shift_copy():
    f_code = session['f_code']
    supabase = get_supabase()
    data = request.get_json(silent=True) or {}
    try:
        src = datetime.strptime(data.get('from_start'), '%Y-%m-%d').date()
        dst = datetime.strptime(data.get('to_start'), '%Y-%m-%d').date()
    except Exception:
        return jsonify({"status": "error", "message": "日付が不正です"}), 400
    src_dates = [(src + timedelta(days=i)).isoformat() for i in range(7)]
    try:
        r = supabase.table("staff_shift_plan").select("*").eq(
            "facility_code", f_code).gte("plan_date", src_dates[0]).lte("plan_date", src_dates[6]).execute()
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500
    n = 0
    now_iso = datetime.now(timezone.utc).isoformat()
    _me = session.get('my_name', '')
    _is_admin = is_admin_user(supabase, f_code, _me)  # shift-self-only-v1
    for row in (r.data or []):
        if (not _is_admin) and str(row.get("staff_name")) != _me:  # 本人分のみ
            continue
        try:
            pd = datetime.strptime(str(row.get("plan_date")), '%Y-%m-%d').date()
        except Exception:
            continue
        newd = (dst + timedelta(days=(pd - src).days)).isoformat()
        try:
            supabase.table("staff_shift_plan").upsert({
                "facility_code": f_code, "staff_name": row.get("staff_name"), "plan_date": newd,
                "status": row.get("status"), "start_time": row.get("start_time"), "end_time": row.get("end_time"),
                "day_type": row.get("day_type"),  # youshiki-daytype-v1: 型もコピー
                # shift-leave-sync-v1: 休暇区分は【コピーしない】。
                #   「先週が有給だったから今週も有給」は明らかに違う。休み(status)だけ複製し、
                #   区分は各自が入れ直す（区分が空の休みは従来どおりタイムカードで聞かれる）。
                "leave_type": None,
                "updated_at": now_iso,
            }, on_conflict="facility_code,staff_name,plan_date").execute()
            n += 1
        except Exception as e:
            print(f"[shift copy] {e}", flush=True)
    return jsonify({"status": "success", "copied": n})


# ===== shift-cal-line-v1: カレンダー月表示に勤務予定の線を出す =====
#   カレンダー画面が「その月の全職員の勤務」をまとめて取りに来るための API。
#   ・勤務予定(staff_shift_plan)に行が無い日は、既定の曜日パターン(staff_shift_defaults)で補う。
#     この補い方は勤務予定画面 templates/kinmu_yotei.html の effDay() と同じ規則にすること
#     （ズレると画面ごとに違う勤務が出る）。
#   ・weekdays は【月曜起点】。kinmu_yotei.html の wdOf() が (getUTCDay()+6)%7 = 月曜0 のため。
#     Python の date.weekday() も月曜0なのでそのまま使える。
#   ・閲覧は施設の全員に開放する（ユーザー判断・2026-08-20）。
#     編集側の本人限定(shift-self-only-v1)は従来どおりで、ここでは変えていない。
def _shift_month_map(supabase, f_code, year, month):
    """{'YYYY-MM-DD': {'work':[{'name','start','end'}], 'off':['名前',...]}} を返す。"""
    import calendar as _cal
    ndays = _cal.monthrange(year, month)[1]
    days = [f"{year:04d}-{month:02d}-{d:02d}" for d in range(1, ndays + 1)]
    names = _shift_staff_names(supabase, f_code)
    defaults = _shift_default_map(supabase, f_code)

    plan = {}
    try:
        r = supabase.table("staff_shift_plan").select(
            "staff_name,plan_date,status,start_time,end_time").eq(
            "facility_code", f_code).gte("plan_date", days[0]).lte("plan_date", days[-1]).execute()
        for row in (r.data or []):
            plan[str(row.get("staff_name")) + "|" + str(row.get("plan_date"))] = row
    except Exception as e:
        print(f"[shift-cal-line] plan fetch: {e}", flush=True)

    _DEF = {"weekdays": [True, True, True, True, True, False, False],
            "start": "09:00", "end": "18:00"}
    out = {}
    for ds in days:
        try:
            widx = datetime.strptime(ds, "%Y-%m-%d").date().weekday()   # 月=0
        except Exception:
            continue
        work, off = [], []
        for nm in names:
            df = defaults.get(nm) or _DEF
            row = plan.get(nm + "|" + ds)
            if row:
                if (row.get("status") or "") == "work":
                    work.append({"name": nm,
                                 "start": row.get("start_time") or df["start"],
                                 "end": row.get("end_time") or df["end"]})
                else:
                    off.append(nm)
            else:
                if df["weekdays"][widx]:
                    # shift-weekday-times-v1: 曜日ごとの時間を使う（未設定の曜日は共通値で埋まっている）
                    _t = (df.get("times") or [{}] * 7)[widx] or {}
                    work.append({"name": nm,
                                 "start": _t.get("start") or df["start"],
                                 "end": _t.get("end") or df["end"]})
                else:
                    off.append(nm)
        out[ds] = {"work": work, "off": off}
    return out


@app.route('/api/shift/calendar_month', methods=['GET'])
@login_required
def api_shift_calendar_month():
    """shift-cal-line-v1: カレンダー月表示用。その月の全職員の勤務を1回で返す。"""
    try:
        f_code = session["f_code"]
        me = session.get("my_name", "")
        supabase = get_supabase()
        now = _tc_now_jst()
        try:
            year = int(request.args.get("year", now.year))
            month = int(request.args.get("month", now.month))
        except (TypeError, ValueError):
            year, month = now.year, now.month
        if not (1 <= month <= 12) or not (2000 <= year <= 2100):
            year, month = now.year, now.month

        days = _shift_month_map(supabase, f_code, year, month)

        # 自分がその日に出勤か休みかを添える（線の色に使う。名前の突き合わせは1回だけ）
        for ds, v in days.items():
            v["me"] = "work" if any(w["name"] == me for w in v["work"]) else "off"

        return jsonify({"status": "success", "me": me, "year": year, "month": month, "days": days})
    except Exception as e:
        print(f"[shift-cal-line] api_shift_calendar_month error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


# ===== daily-summary-cache-fix-v1 : 日時をきちんと比べる =====
def _ds_parse_ts(v):
    """DBが返す日時を datetime にする。読めなければ None。

    ★文字列のまま大小比較してはいけない。
      '2026-07-17 08:05:29.6+00' と '2026-07-17T08:05:29.600109+00:00' は
      同じ時刻でも文字列としては別物になる。
    """
    if not v:
        return None
    if isinstance(v, datetime):
        return v
    s = str(v).strip().replace(" ", "T")
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    # '+00' のように時差が2桁だけのことがある。fromisoformat は ':00' を要る版がある
    m = re.search(r"([+-]\d{2})$", s)
    if m:
        s = s + ":00"
    # マイクロ秒が7桁以上のことがある。fromisoformat は6桁までしか読めない
    m = re.match(r"^(.*\.\d{6})\d+(.*)$", s)
    if m:
        s = m.group(1) + m.group(2)
    try:
        return datetime.fromisoformat(s)
    except Exception:
        return None


def _ds_ts_ge(a, b):
    """a >= b か。★両方きちんと読めたときだけ日時として比べる。"""
    da, db = _ds_parse_ts(a), _ds_parse_ts(b)
    if da is not None and db is not None:
        return da >= db
    print("[daily-summary] 日時を読めませんでした: %r / %r" % (a, b), flush=True)
    return str(a or "") >= str(b or "")      # 最後の手段


@app.route('/api/daily_summaries', methods=['GET'])   # daily-summary-cache-fix-v1
@login_required
def api_daily_summaries_cached():
    """その日ぶんの【すでにある】要約をまとめて返す。AIは呼ばない。

    ★画面は今まで、利用者の数だけ生成APIを呼んでいた。
      キャッシュが効いていても人数ぶんの通信が走り、それ自体が重かった。
      ここで1回にまとめ、【まだ無い人のぶんだけ】生成を呼ばせる。
    """
    try:
        f_code = session['f_code']
        date_str = (request.args.get('date') or '').strip()
        if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', date_str):
            return jsonify({'status': 'error', 'message': 'date が不正です',
                            'summaries': {}}), 400
        supabase = get_supabase()
        day_start = tokyo_tz.localize(datetime.strptime(date_str, '%Y-%m-%d'))
        day_end = day_start + timedelta(days=1)

        rec = (supabase.table('records')
               .select('user_name, created_at, image_urls')
               .eq('facility_code', f_code)
               .gte('created_at', day_start.isoformat())
               .lt('created_at', day_end.isoformat())
               .neq('staff_name', 'AI統合記録').execute())
        latest, imgs = {}, {}
        for r in (rec.data or []):
            u = r.get('user_name') or ''
            if not u:
                continue
            ca = r.get('created_at') or ''
            # ★同じ列どうしの比較なので、ここは文字列のままで安全
            if u not in latest or str(ca) > str(latest[u]):
                latest[u] = ca
            for x in (r.get('image_urls') or []):
                imgs.setdefault(u, []).append(x)

        cur = (supabase.table('daily_summaries')
               .select('user_name, summary, last_record_at')
               .eq('facility_code', f_code).eq('summary_date', date_str).execute())
        out = {}
        for c in (cur.data or []):
            u = c.get('user_name')
            if u in latest and _ds_ts_ge(c.get('last_record_at'), latest[u]):
                out[u] = {'summary': c.get('summary'), 'image_urls': imgs.get(u, [])}
        return jsonify({'status': 'success', 'summaries': out})
    except Exception as e:
        # ★握りつぶさない。画面は「まだ無い」として生成に回るので、動きは止まらない
        print(f"[daily-summary] 一括取得に失敗: {e}", flush=True)
        return jsonify({'status': 'error', 'message': str(e), 'summaries': {}}), 500


@app.route('/api/generate_daily_summary', methods=['POST'])
@login_required
def api_generate_daily_summary():
    """利用者×日付のAI要約を生成してキャッシュ保存"""
    f_code = session['f_code']
    supabase = get_supabase()
    try:
        data = request.json
        user_name = data['user_name']
        date_str  = data['date']

        day_start = tokyo_tz.localize(datetime.strptime(date_str, '%Y-%m-%d'))
        day_end   = day_start + timedelta(days=1)

        res = supabase.table('records').select(
            'content, staff_name, created_at, image_urls'
        ).eq('facility_code', f_code).eq(
            'user_name', user_name
        ).gte('created_at', day_start.isoformat()).lt(
            'created_at', day_end.isoformat()
        ).neq('staff_name', 'AI統合記録').order('created_at').execute()

        records = res.data or []
        if not records:
            return jsonify({'error': '記録がありません'}), 404

        # daily-summary-cache-fix-v1: 写真のURLは【毎回この記録から組み立てる】。
        #   ★以前は daily_summaries.image_urls を読み書きしていたが、その列は実在しない。
        #     読み取りも保存も失敗し、except: pass で握りつぶされ、
        #     2026-07-17 以降キャッシュが更新されないまま毎回AIを呼び直していた。
        #   ★どのみち記録は全部読んでいる。ここから作れば、列のずれで壊れない。
        all_image_urls = []
        for _r in records:
            _urls = _r.get('image_urls') or []
            if isinstance(_urls, list):
                all_image_urls.extend(_urls)

        latest_record_at = records[-1]['created_at']
        force = data.get('force', False)
        # ★「無かった」と「確かめられなかった」を分ける（患者の重複対策と同じ考え方）
        cache_ok, cached_row = True, None
        try:
            cached = supabase.table('daily_summaries').select(
                'summary, last_record_at'
            ).eq('facility_code', f_code).eq(
                'user_name', user_name
            ).eq('summary_date', date_str).limit(1).execute()
            cached_row = (cached.data or [None])[0]
        except Exception as _ce:
            cache_ok = False
            print(f"[daily-summary] キャッシュ取得に失敗: {_ce}", flush=True)

        if not force and cached_row and _ds_ts_ge(cached_row.get('last_record_at'), latest_record_at):
            # 記録が増えていないので作り直さない
            return jsonify({'summary': cached_row.get('summary'), 'cached': True,
                            'image_urls': all_image_urls})
        if not force and not cache_ok:
            # ★確かめられていないのに作り直すと、AIを無駄に呼び、文章まで変わる。
            return jsonify({'error': 'いま確認できませんでした。少し待ってからもう一度お試しください。'}), 503

        contents = [r['content'] for r in records]
        recs_text = '\n'.join(contents)
        # halluc-guard-v1: 記録が極端に短い場合はAI要約せず記録そのものを返す（創作の余地をゼロに）
        if len(recs_text.strip()) < 20:
            summary = recs_text.strip()
        else:
            from utils import get_generative_model
            model = get_generative_model()
            prompt = (
                f"以下は{date_str}の{user_name}さんに関する介護記録です。\n"
                "この記録に実際に書かれている内容だけを使って、自然な文章で要約してください。\n"
                "【厳守】記録に書かれていない事実・症状・処置・出来事・発言を、絶対に追加・推測・創作しないこと。"
                "記録に無いことは一切書かないでください。\n"
                "記録が短いときは無理に長くせず、書かれている範囲でそのまま短くまとめること"
                "（文字数を埋めるために内容を足してはいけません）。\n"
                "箇条書きは使わず、職員名や主語は不要。最大200文字程度。\n\n"
                "=== 介護記録 ===\n" + recs_text
            )
            summary = model.generate_content([prompt]).text.strip()

        # daily-summary-cache-fix-v1: image_urls は送らない（その列は存在しない）
        try:
            supabase.table('daily_summaries').upsert({
                'facility_code':  f_code,
                'user_name':      user_name,
                'summary_date':   date_str,
                'summary':        summary,
                'last_record_at': latest_record_at,
                'updated_at':     datetime.now(tokyo_tz).isoformat()
            }, on_conflict='facility_code,user_name,summary_date').execute()
        except Exception as _ue:
            # ★握りつぶさない。ここが黙っていたせいで1か月以上だれも気づけなかった。
            #   保存できないと、次に開いたときもまた作り直しになる。
            print(f"[daily-summary] 保存に失敗（次も作り直しになります）: {_ue}", flush=True)

        return jsonify({'summary': summary, 'cached': False, 'image_urls': all_image_urls})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

