@app.route('/api/goal_check')
@login_required
def api_goal_check():
    try:
        f_code = session["f_code"]
        supabase = get_supabase()
        from datetime import date, timedelta
        today = date.today()
        warning_days = 30
        res = supabase.table("patient_profiles").select(
            "id, user_name, care_level, short_goal_period_to, long_goal_period_to"
        ).eq("facility_code", f_code).execute()
        patients = []
        for p in (res.data or []):
            short_to = p.get("short_goal_period_to")
            long_to = p.get("long_goal_period_to")
            short_status = None
            long_status = None
            if short_to:
                d = date.fromisoformat(short_to)
                if d < today:
                    short_status = "期限切れ"
                elif d <= today + timedelta(days=warning_days):
                    short_status = "期限間近"
            if long_to:
                d = date.fromisoformat(long_to)
                if d < today:
                    long_status = "期限切れ"
                elif d <= today + timedelta(days=warning_days):
                    long_status = "期限間近"
            # 全体のステータス（期限切れ優先）
            if short_status == "期限切れ" or long_status == "期限切れ":
                overall_status = "期限切れ"
            elif short_status == "期限間近" or long_status == "期限間近":
                overall_status = "期限間近"
            else:
                overall_status = None
            if overall_status:
                patients.append({
                    "id": str(p["id"]),
                    "user_name": p["user_name"],
                    "care_level": p.get("care_level") or "",
                    "short_goal_to": short_to,
                    "short_status": short_status,
                    "long_goal_to": long_to,
                    "long_status": long_status,
                    "status": overall_status,
                })
        patients.sort(key=lambda x: (x["status"] != "期限切れ", x["user_name"]))

        # 目標変更: 当月または前月の評価で新目標が入力されている人（翌月10日まで表示）
        goal_changes = []
        try:
            # 表示対象月を決定（今月10日以前なら前月も対象）
            if today.day <= 10:
                target_months = [
                    today.strftime('%Y-%m'),
                    (today.replace(day=1) - timedelta(days=1)).strftime('%Y-%m')
                ]
            else:
                target_months = [today.strftime('%Y-%m')]

            # goal-alert-peraxis-fix-v1: 集約列(short_goal_new/long_goal_new)だけでなく
            # 軸別の新目標(機能/活動/参加)と「変更」フラグも見る。
            # 要介護の評価は軸別列に目標を保存するため、集約列だけ見ると軸別変更が漏れていた。
            _GOAL_NEW_FIELDS = [
                "training_goal", "short_goal_new", "long_goal_new",
                "short_goal_function_new", "short_goal_activity_new", "short_goal_participation_new",
                "long_goal_function_new", "long_goal_activity_new", "long_goal_participation_new",
            ]
            _GOAL_CONT_FIELDS = [
                "short_goal_cont", "long_goal_cont",
                "short_goal_function_cont", "short_goal_activity_cont", "short_goal_participation_cont",
                "long_goal_function_cont", "long_goal_activity_cont", "long_goal_participation_cont",
            ]
            _sel = "user_name, year_month, " + ", ".join(_GOAL_NEW_FIELDS + _GOAL_CONT_FIELDS)
            for ym in target_months:
                ev_res = supabase.table("patient_evaluations").select(
                    _sel
                ).eq("facility_code", f_code).eq("year_month", ym).execute()
                for ev in (ev_res.data or []):
                    # 「変更」フラグが立っている軸があれば変更扱い（継続はカウントしない）
                    changed_flag = any(
                        (ev.get(c) or "").strip() == "変更" for c in _GOAL_CONT_FIELDS
                    )
                    # 表示用の新目標テキスト（最初に見つかった2文字以上のもの）。
                    # goal-minlen-fix: 前後空白を除去。1文字や空白のみのゴミ入力は無視。
                    new_goal = ""
                    for f in _GOAL_NEW_FIELDS:
                        v = (ev.get(f) or "").strip()
                        if len(v) >= 2:
                            new_goal = v
                            break
                    if changed_flag or new_goal:
                        # 重複チェック
                        if not any(g["user_name"] == ev["user_name"] for g in goal_changes):
                            goal_changes.append({
                                "user_name": ev["user_name"],
                                "year_month": ym,
                                "new_goal": new_goal or "（目標を変更）",
                            })
            goal_changes.sort(key=lambda x: x["user_name"])
        except Exception:
            pass

        return jsonify({"status": "success", "patients": patients, "goal_changes": goal_changes})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500
# goal-link-history-v1: 評価の新目標を基本情報へ反映＋履歴
@app.route('/api/goal/apply', methods=['POST'])
@login_required
def api_goal_apply():
    try:
        data = request.json or {}
        f_code = session["f_code"]
        my = session.get("my_name", "")
        supabase = get_supabase()
        user_name = (data.get("user_name") or "").strip()
        goals = data.get("goals") or {}
        year_month = (data.get("year_month") or "").strip() or None
        if not user_name or not goals:
            return jsonify({"status": "error", "message": "user_name と goals が必要です"}), 400
        ALLOWED = {"short_goal", "long_goal",
                   "short_goal_function", "short_goal_activity", "short_goal_participation",
                   "long_goal_function", "long_goal_activity", "long_goal_participation",
                   "short_goal_period_from", "short_goal_period_to",
                   "long_goal_period_from", "long_goal_period_to"}  # goal-period-config-v1
        LABEL = {"short_goal": "短期目標", "long_goal": "長期目標",
                 "short_goal_function": "短期目標（心身機能）", "short_goal_activity": "短期目標（活動）",
                 "short_goal_participation": "短期目標（参加）", "long_goal_function": "長期目標（心身機能）",
                 "long_goal_activity": "長期目標（活動）", "long_goal_participation": "長期目標（参加）",
                 "short_goal_period_from": "短期目標期間(開始)", "short_goal_period_to": "短期目標期間(終了)",
                 "long_goal_period_from": "長期目標期間(開始)", "long_goal_period_to": "長期目標期間(終了)"}
        # goal-valid-from-v1: この変更が【いつから有効か】を決める。
        #   ・呼び出し側が valid_from を指定していれば、それを使う
        #     （利用者基本情報からの「月途中の変更」で使う）
        #   ・指定が無く year_month があれば、【評価月の翌月1日】
        #     ★HIROさん判断(2026-08-28)：7月の評価なら8/1から。
        #       8月に7月の評価をしていても8/1から。操作した日に左右されない。
        #   ・どちらも無ければ、今日（日本時間）
        from datetime import date as _gvf_date   # このリポジトリの書き方に合わせる
        _valid_from = (data.get("valid_from") or "").strip() or None
        if not _valid_from:
            if year_month and re.fullmatch(r"\d{4}-\d{2}", year_month):
                _vy, _vm = int(year_month[:4]), int(year_month[5:7])
                _valid_from = (_gvf_date(_vy + 1, 1, 1) if _vm == 12
                               else _gvf_date(_vy, _vm + 1, 1)).isoformat()
            else:
                _valid_from = datetime.now(tokyo_tz).date().isoformat()

        pr = supabase.table("patient_profiles").select("*").eq("facility_code", f_code).eq("user_name", user_name).limit(1).execute()
        prof = (pr.data or [None])[0]
        if not prof:
            return jsonify({"status": "error", "message": "利用者が見つかりません"}), 404
        pid = str(prof.get("id"))
        upd = {}
        hist = []
        for field, val in goals.items():
            if field not in ALLOWED:
                continue
            new_v = (str(val) if val is not None else "").strip()
            old_v = (str(prof.get(field) or "")).strip()
            if old_v.lower() in ("none", "null"):  # goal-none-normalize-v1
                old_v = ""
            if not new_v or new_v == old_v:
                continue
            upd[field] = new_v
            hist.append({"facility_code": f_code, "patient_profile_id": pid, "user_name": user_name,
                         "field": field, "field_label": LABEL.get(field, field),
                         "old_value": old_v, "new_value": new_v, "year_month": year_month,
                         "valid_from": _valid_from, "changed_by": my})   # goal-valid-from-v1
        if not upd:
            return jsonify({"status": "success", "updated": 0, "message": "変更はありません"})
        # goal-history-first-v1: 【記録を先に残してから変える】。
        #   ★以前は書き換えてから履歴を入れ、履歴の失敗は except: pass だった。
        #     そのため「目標だけ変わって、変えた記録が無い」状態が起こり得た。
        #     goal-valid-from-v1 で過去の月の目標は履歴から決めているので、
        #     履歴が欠けると月ごとの目標そのものが狂う。しかも誰も気づけない。
        #   ★先に残せば、残せなかったときは【まだ何も変わっていない】。
        _hist_ids = []
        if hist:
            try:
                _hr = supabase.table("goal_history").insert(hist).execute()
                _hist_ids = [r.get("id") for r in (_hr.data or []) if r.get("id") is not None]
            except Exception as _he:
                print("[goal] 履歴の保存に失敗したため、目標を変更しませんでした: %s" % _he, flush=True)
                return jsonify({"status": "error",
                                "message": "変更の記録を残せませんでした。"
                                           "記録に残らない変更はしない決まりなので、"
                                           "目標は変更していません。"
                                           "少し待ってからもう一度お試しください。"}), 503
        try:
            supabase.table("patient_profiles").update(upd).eq("facility_code", f_code).eq("user_name", user_name).execute()
        except Exception as e:
            # ★目標を変えられなかったのに履歴だけ残ると、
            #   評価の画面が「その月から変わった」ことにしてしまう。入れた履歴を取り消す。
            for _hid in _hist_ids:
                try:
                    supabase.table("goal_history").delete().eq("id", _hid).eq("facility_code", f_code).execute()
                except Exception as _de:
                    print("[goal] 履歴の取り消しに失敗 (id=%s): %s" % (_hid, _de), flush=True)
            return jsonify({"status": "error", "message": f"更新失敗: {e}"}), 500
        return jsonify({"status": "success", "updated": len(upd)})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500


