@app.route('/api/goal_period_config', methods=['POST'])
@login_required
def api_goal_period_config_save():
    try:
        import json as _j
        f_code = session["f_code"]
        data = request.json or {}
        incoming = data.get("config") or {}

        def _iv(x, dflt):
            try:
                n = int(x)
                return n if 1 <= n <= 60 else dflt
            except Exception:
                return dflt
        clean = {}
        for cat in ("jigyou", "youshien", "yokaigo"):
            c = incoming.get(cat) or {}
            clean[cat] = {"short": _iv(c.get("short"), _GOAL_PERIOD_DEFAULT[cat]["short"]), "long": _iv(c.get("long"), _GOAL_PERIOD_DEFAULT[cat]["long"])}
        supabase = get_supabase()
        val = _j.dumps(clean, ensure_ascii=False)
        ex = supabase.table("admin_settings").select("id").eq(
            "facility_code", f_code).eq("key", "goal_period_months").execute()
        if ex.data:
            supabase.table("admin_settings").update({"value": val}).eq(
                "facility_code", f_code).eq("key", "goal_period_months").execute()
        else:
            supabase.table("admin_settings").insert({
                "facility_code": f_code, "key": "goal_period_months", "value": val}).execute()
        return jsonify({"status": "success", "config": clean})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route('/api/patient/care_level_history', methods=['GET'])
@login_required
def api_patient_care_level_history():
    """clh-history-view-v1: 指定利用者の介護度変更履歴を返す（適用開始日の降順）。"""
    try:
        f_code = session["f_code"]
        pid = (request.args.get("patient_id") or "").strip()
        user_name = (request.args.get("user_name") or "").strip()
        supabase = get_supabase()
        if not pid and user_name:
            r = supabase.table("patient_profiles").select("id").eq("facility_code", f_code).eq("user_name", user_name).limit(1).execute()
            if r.data:
                pid = r.data[0].get("id")
        if not pid:
            return jsonify({"status": "error", "message": "patient_id が必要です"}), 400
        res = supabase.table("care_level_history") \
            .select("*") \
            .eq("facility_code", f_code).eq("patient_id", pid) \
            .execute()
        items = res.data or []
        items.sort(key=lambda h: ((h.get("valid_from") or ""), (h.get("id") or 0)), reverse=True)
        out = [{"care_level": h.get("care_level") or "",
                "valid_from": (h.get("valid_from") or "")[:10],
                "created_at": h.get("created_at") or ""} for h in items]
        return jsonify({"status": "success", "items": out})
    except Exception as e:
        print("care_level_history view error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500

@app.route('/api/update_patient_care_level', methods=['POST'])
@login_required
def api_update_patient_care_level():
    """careclass-no-overwrite-v1: この API は【何も書き込まない】。

    ★なぜ書かないか
      旧 /assessment の「介護区分」は 要介護 / 要支援 / 事業対象者 の3択しか無い。
      そこから patient_profiles.care_level を決めようとすると
      「要介護 → 要介護1」と当て推量で書くしかなく、
      要介護4 の利用者が 要介護1 に化けて、元の値がどこにも残らなかった。
      区分を押し間違えて押し戻すだけで壊れる。戻す操作が戻らない。
    ★さらにこの経路は _record_care_level_history() を呼ばないため、
      実績集計表（月末時点の介護度で判定）とプロフィールが食い違う原因にもなっていた。
    ★新しい /assessment2 は最初から「care_level そのものは書き換えない」設計。
      （templates/assessment2.html の a2ClsFromLevel のコメントを参照）旧画面もそれに合わせる。
    ★介護度を実際に変えるのは /patient-info（/api/admin/patient/save）だけ。
      あちらは 要介護1〜5 を正しく選べて、care_level_history も積む。
    ★ルート自体は残す：職員の端末に古い JS が残っていても 404 で騒がせないため。
      呼び出し元が完全に無くなったら、このルートごと削除してよい。
    """
    return jsonify({
        "status": "success",
        "changed": False,
        "message": "介護区分は評価にのみ保存しました。利用者情報の介護度は変更していません。",
    })
