# ----- timecard-monthly-v1 : 月次労働時間集計 -----
def _tc_month_range_jst(year, month):
    """指定年月(JST)の [当月1日00:00, 翌月1日00:00) を UTC ISO で返す。"""
    start = _tc_dt(year, month, 1, 0, 0, 0, tzinfo=_TC_JST)
    if month == 12:
        end = _tc_dt(year + 1, 1, 1, 0, 0, 0, tzinfo=_TC_JST)
    else:
        end = _tc_dt(year, month + 1, 1, 0, 0, 0, tzinfo=_TC_JST)
    return start.astimezone(_tc_tz.utc).isoformat(), end.astimezone(_tc_tz.utc).isoformat()


def _tc_parse_iso(s):
    """SupabaseのISO文字列を aware datetime に。失敗時 None。"""
    if not s:
        return None
    try:
        t = s.replace("Z", "+00:00")
        return _tc_dt.fromisoformat(t)
    except Exception:
        try:
            return _tc_dt.fromisoformat(s[:19] + "+00:00")
        except Exception:
            return None


def _tc_day_key(iso):
    """打刻時刻(UTC ISO)を JST の YYYY-MM-DD に。"""
    dtv = _tc_parse_iso(iso)
    if not dtv:
        return None
    return dtv.astimezone(_TC_JST).strftime("%Y-%m-%d")


def _tc_compute_day(punches):
    """1日分の打刻列(時刻昇順)から労働時間(分)を計算。
    返り値: {"minutes": int|None, "incomplete": bool, "flags": [..],
             "in": iso|None, "out": iso|None, "break_min": int}
    欠損は補完しない: in欠落/out欠落/break_end欠落 は incomplete=True, minutes=None。"""
    flags = []
    in_t = None
    out_t = None
    work_min = 0
    break_min = 0
    cur_in = None
    cur_break = None
    incomplete = False

    for p in punches:
        t = p.get("punch_type")
        at = _tc_parse_iso(p.get("punched_at"))
        if at is None:
            continue
        if t == "in":
            if cur_in is not None:
                flags.append("二重出勤")
                incomplete = True
            cur_in = at
            if in_t is None:
                in_t = at
        elif t == "out":
            if cur_in is None:
                flags.append("出勤なしで退勤")
                incomplete = True
            else:
                # 退勤時に休憩が開いていれば未クローズ→補完せず印
                if cur_break is not None:
                    flags.append("休憩終了の打刻なし")
                    incomplete = True
                    cur_break = None
                work_min += int((at - cur_in).total_seconds() // 60)
                cur_in = None
            out_t = at
        elif t == "break_start":
            if cur_in is None:
                flags.append("勤務外の休憩")
                incomplete = True
            if cur_break is not None:
                flags.append("休憩が連続")
                incomplete = True
            cur_break = at
        elif t == "break_end":
            if cur_break is None:
                flags.append("休憩開始なしで終了")
                incomplete = True
            else:
                break_min += int((at - cur_break).total_seconds() // 60)
                cur_break = None

    # 走査後に開いたままの勤務/休憩がある → 退勤漏れ等
    if cur_in is not None:
        flags.append("退勤の打刻なし")
        incomplete = True
    if cur_break is not None:
        flags.append("休憩終了の打刻なし")
        incomplete = True

    minutes = None if incomplete else max(0, work_min - break_min)
    # 重複フラグを除去(順序維持)
    seen = set()
    uniq = []
    for fl in flags:
        if fl not in seen:
            seen.add(fl)
            uniq.append(fl)
    return {"minutes": minutes, "incomplete": incomplete, "flags": uniq,
            "in": in_t.isoformat() if in_t else None,
            "out": out_t.isoformat() if out_t else None,
            "break_min": break_min}


# youshiki-exclude-v1: 様式（実績）に出力しない日の管理
#   接骨院勤務など介護以外の勤務を、様式（実績）の集計から除外するための仕組み。
#   facilities.youshiki_exclude_enabled がTrueの施設だけUIにトグルが出る（開発者MENUで制御）。
def _youshiki_exclude_enabled(supabase, f_code):
    """施設で「様式除外トグル」を表示してよいか（開発者MENUの設定）。"""
    try:
        fa = supabase.table('facilities').select('youshiki_exclude_enabled').eq('facility_code', f_code).execute()
        return bool(fa.data and fa.data[0].get('youshiki_exclude_enabled'))
    except Exception:
        return False


def _youshiki_excluded_set(supabase, f_code, year, month):
    """当月の除外指定 (_ys_norm(staff_name), 'YYYY-MM-DD') の集合を返す。"""
    s = set()
    try:
        _st = f"{year:04d}-{month:02d}-01"
        _en = f"{year+1:04d}-01-01" if month == 12 else f"{year:04d}-{month+1:02d}-01"
        r = (supabase.table('youshiki_excluded_days').select('staff_name,work_date')
             .eq('facility_code', f_code).gte('work_date', _st).lt('work_date', _en).execute())
        for x in (r.data or []):
            s.add((_ys_norm(x.get('staff_name')), str(x.get('work_date'))))
    except Exception as e:
        print(f"_youshiki_excluded_set error: {e}", flush=True)
    return s


@app.route("/api/timecard/youshiki_exclude/toggle", methods=["POST"])  # youshiki-exclude-v1
@login_required
def api_youshiki_exclude_toggle():
    """個別の日を様式（実績）に出す/出さないを切り替え。管理者＋機能ON施設のみ。"""
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        if not is_admin_user(supabase, f_code, my_name):
            return jsonify({"status": "error", "message": "管理者権限がありません"}), 403
        if not _youshiki_exclude_enabled(supabase, f_code):
            return jsonify({"status": "error", "message": "この機能は無効です"}), 403
        data = request.json or {}
        staff_name = (data.get("staff_name") or "").strip()
        date = (data.get("date") or "").strip()
        exclude = bool(data.get("exclude", False))
        if not staff_name or not date:
            return jsonify({"status": "error", "message": "staff_name/date が必要です"}), 400
        if exclude:
            supabase.table("youshiki_excluded_days").upsert({
                "facility_code": f_code, "staff_name": staff_name, "work_date": date,
            }, on_conflict="facility_code,staff_name,work_date").execute()
        else:
            (supabase.table("youshiki_excluded_days").delete()
             .eq("facility_code", f_code).eq("staff_name", staff_name)
             .eq("work_date", date).execute())
        return jsonify({"status": "success", "excluded": exclude})
    except Exception as e:
        print(f"api_youshiki_exclude_toggle error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/timecard/day_type/set", methods=["POST"])  # youshiki-daytype-v1
@login_required
def api_timecard_day_type_set():
    """個別の日の型（1日型/半日型）を手動指定。'auto'で指定解除。管理者限定。"""
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        if not is_admin_user(supabase, f_code, my_name):
            return jsonify({"status": "error", "message": "管理者権限がありません"}), 403
        data = request.json or {}
        staff_name = (data.get("staff_name") or "").strip()
        date = (data.get("date") or "").strip()
        day_type = (data.get("day_type") or "").strip()  # 'full' | 'half' | 'auto'
        if not staff_name or not date:
            return jsonify({"status": "error", "message": "staff_name/date が必要です"}), 400
        if day_type in ("auto", "", "none"):
            (supabase.table("youshiki_day_type").delete()
             .eq("facility_code", f_code).eq("staff_name", staff_name)
             .eq("work_date", date).execute())
            return jsonify({"status": "success", "day_type": None})
        if day_type not in ("full", "half"):
            return jsonify({"status": "error", "message": "day_type が不正です"}), 400
        supabase.table("youshiki_day_type").upsert({
            "facility_code": f_code, "staff_name": staff_name,
            "work_date": date, "day_type": day_type,
        }, on_conflict="facility_code,staff_name,work_date").execute()
        return jsonify({"status": "success", "day_type": day_type})
    except Exception as e:
        print(f"api_timecard_day_type_set error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/admin/timecard/monthly", methods=["GET"])
@login_required
def admin_timecard_monthly():
    """職員別・日別の労働時間と月合計(JSON)。管理者限定。"""
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        if not is_admin_user(supabase, f_code, my_name):
            return jsonify({"status": "error", "message": "管理者権限がありません"}), 403
        now = _tc_now_jst()
        try:
            year = int(request.args.get("year", now.year))
            month = int(request.args.get("month", now.month))
        except (TypeError, ValueError):
            year, month = now.year, now.month
        if not (1 <= month <= 12):
            return jsonify({"status": "error", "message": "月が不正です。"}), 400

        start_iso, end_iso = _tc_month_range_jst(year, month)
        res = supabase.table("timecard_records").select("*").eq(
            "facility_code", f_code).eq("is_deleted", False).gte(
            "punched_at", start_iso).lt("punched_at", end_iso).order(
            "punched_at", desc=False).execute()
        rows = res.data or []

        # staff -> day -> punches
        by_staff = {}
        for r in rows:
            sn = r.get("staff_name")
            dk = _tc_day_key(r.get("punched_at"))
            if not sn or not dk:
                continue
            by_staff.setdefault(sn, {}).setdefault(dk, []).append(r)

        staff_master = _tc_staff_list(supabase, f_code)
        name_order = [s["name"] for s in staff_master]
        emoji_map = {s["name"]: s["emoji"] for s in staff_master}
        # 明細にしか出てこない退職者等も拾う
        for sn in by_staff.keys():
            if sn not in name_order:
                name_order.append(sn)

        result = []
        for sn in name_order:
            days_map = by_staff.get(sn, {})
            days = []
            total_min = 0
            worked_days = 0
            incomplete_days = 0
            for dk in sorted(days_map.keys()):
                comp = _tc_compute_day(days_map[dk])
                if comp["minutes"] is not None:
                    total_min += comp["minutes"]
                    if comp["minutes"] > 0:
                        worked_days += 1
                if comp["incomplete"]:
                    incomplete_days += 1
                days.append({"date": dk, "minutes": comp["minutes"],
                             "incomplete": comp["incomplete"], "flags": comp["flags"],
                             "in": comp["in"], "out": comp["out"],
                             "break_min": comp["break_min"]})
            result.append({"name": sn, "emoji": emoji_map.get(sn, ""),
                           "days": days, "total_minutes": total_min,
                           "worked_days": worked_days,
                           "incomplete_days": incomplete_days})

        # timecard-leave-grid-v1: 休み申告を日次にマージ
        _tc_merge_leaves_into_monthly(supabase, f_code, year, month, result)

        # youshiki-exclude-v1: 様式除外機能がON施設なら、各日に excluded を付与
        yx_enabled = _youshiki_exclude_enabled(supabase, f_code)
        if yx_enabled:
            yx_set = _youshiki_excluded_set(supabase, f_code, year, month)
            for s0 in result:
                _nn = _ys_norm(s0.get("name"))
                for d0 in s0.get("days", []):
                    d0["excluded"] = (_nn, str(d0.get("date"))) in yx_set

        # youshiki-daytype-v1: 各日に型情報（手動指定・自動判定結果）を付与
        _dt_cfg = _tc_get_config(supabase, f_code)
        _dt_staff_def = _ys_staff_default_types(supabase, f_code)
        _dt_plan = _ys_plan_day_types(supabase, f_code, year, month)
        _dt_manual = _ys_manual_day_types(supabase, f_code, year, month)
        for s0 in result:
            _nn = _ys_norm(s0.get("name"))
            for d0 in s0.get("days", []):
                _ds = str(d0.get("date"))
                try:
                    _pp = _ds.split("-")
                    _dd = _ys_date(int(_pp[0]), int(_pp[1]), int(_pp[2]))
                    _wt = _ys_weekday_rule_type(_dt_cfg, _dd)
                except Exception:
                    _wt = "none"
                _rtype, _unres = _ys_resolve_day_type(
                    _nn, _ds, _wt, _dt_manual, _dt_plan, _dt_staff_def)
                d0["day_type"] = _dt_manual.get((_nn, _ds))  # 手動指定(なければnull=自動)
                d0["day_type_resolved"] = _rtype             # 実際に使われる型 full/half/None
                d0["day_type_unresolved"] = _unres           # both未指定ならTrue

        return jsonify({"status": "success", "year": year, "month": month,
                        "staff": result,
                        "youshiki_exclude_enabled": yx_enabled,
                        "youshiki_daytype_enabled": True})
    except Exception as e:
        print(f"admin_timecard_monthly error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500




# ============================================================
# timecard-pdf-v1 : 勤怠集計のサーバー側PDF生成
#   window.print()が印刷に飛んでPDF保存できない問題を解決。
#   月次データからPDF用HTMLを組み、pdfkit/wkhtmltopdfでPDF化してダウンロード。
# ============================================================

def _tc_merge_leaves_into_monthly(supabase, f_code, year, month, result):
    """timecard-leave-grid-v1: staff_leave_days を月次result へマージ。
    各日dictに day["leave"]、打刻無し休暇日は days に追加、s["leaves"]に一覧。"""
    lstart = f"{year:04d}-{month:02d}-01"
    lend = f"{year+1:04d}-01-01" if month == 12 else f"{year:04d}-{month+1:02d}-01"
    try:
        lr = (supabase.table("staff_leave_days").select("*")
              .eq("facility_code", f_code).gte("leave_date", lstart)
              .lt("leave_date", lend).execute())
        recs = lr.data or []
    except Exception as e:
        print(f"_tc_merge_leaves_into_monthly error: {e}", flush=True)
        recs = []
    by_name = {s0["name"]: s0 for s0 in result}
    emoji_map = {}
    try:
        emoji_map = {x["name"]: x.get("emoji", "") for x in _tc_staff_list(supabase, f_code)}
    except Exception:
        pass
    leaves_by_name = {}
    for r in recs:
        leaves_by_name.setdefault(r.get("staff_name"), []).append(r)
    for name, lrecs in leaves_by_name.items():
        s0 = by_name.get(name)
        if s0 is None:
            s0 = {"name": name, "emoji": emoji_map.get(name, ""),
                  "days": [], "total_minutes": 0, "worked_days": 0,
                  "incomplete_days": 0}
            result.append(s0)
            by_name[name] = s0
        day_idx = {d["date"]: d for d in s0["days"]}
        s_leaves = []
        for r in lrecs:
            code = r.get("leave_type")
            meta = _LEAVE_TYPES.get(code) or {}
            lv = {"type": code, "label": meta.get("label", code or ""),
                  "form": meta.get("form", ""),
                  "substitute_for": r.get("substitute_for"),
                  "note": (r.get("note") or "").strip() or None}
            ds = r.get("leave_date")
            d = day_idx.get(ds)
            if d is not None:
                d["leave"] = lv
            else:
                nd = {"date": ds, "minutes": None, "incomplete": False,
                      "flags": [], "in": None, "out": None, "break_min": 0,
                      "leave": lv}
                s0["days"].append(nd)
                day_idx[ds] = nd
            s_leaves.append({"date": ds, "label": lv["label"], "type": code,
                             "form": lv["form"], "note": lv["note"],
                             "substitute_for": lv["substitute_for"]})
        s0["days"].sort(key=lambda x: x["date"])
        s_leaves.sort(key=lambda x: x["date"] or "")
        s0["leaves"] = s_leaves
    for s0 in result:
        s0.setdefault("leaves", [])
        for d in s0.get("days", []):
            d.setdefault("leave", None)


def _tc_leave_style(code):
    """timecard-leave-grid-v1: 休暇区分ごとの(背景色, 文字色)。"""
    M = {
        "paid":       ("#e8f5e9", "#2e7d32"),
        "substitute": ("#e3f2fd", "#1565c0"),
        "condolence": ("#f3e5f5", "#6a1b9a"),
        "absence":    ("#ffebee", "#c62828"),
        "off":        ("#eceff1", "#546e7a"),
        "half":       ("#fff8e1", "#ef6c00"),
        "hourly":     ("#fff8e1", "#ef6c00"),
        "cancel":     ("#f5f5f5", "#9e9e9e"),
        # leave-obon-newyear-v1
        "obon":       ("#e0f7fa", "#00838f"),
        "newyear":    ("#fce4ec", "#ad1457"),
    }
    return M.get(code, ("#eeeeee", "#555555"))


def _tc_fmt_time_jp(iso):
    """timecard-leave-grid-v1: JST時刻を「H時MM分」表記で返す。無しは空。"""
    if not iso:
        return ""
    dt = _tc_parse_iso(iso)
    if dt is None:
        return ""
    dt = dt.astimezone(_TC_JST)
    return f"{dt.hour}時{dt.minute:02d}分"


def _tc_grid_cell(dd):
    """timecard-leave-grid-v1: 1セルHTML。打刻/休暇/公休(空欄)を出し分け。"""
    import html as _h
    if not dd:
        return ""  # 公休(登録なし)
    lv = dd.get("leave")
    lv_html = ""
    if lv:
        bg, fg = _tc_leave_style(lv.get("type"))
        lv_html = (f'<span class="lv" style="background:{bg};color:{fg}">'
                   f'{_h.escape(lv.get("label", ""))}</span>')
        if lv.get("type") == "substitute" and lv.get("substitute_for"):
            lv_html += (f'<div class="lvsub">振替元 {_tc_day_label(lv.get("substitute_for"))}</div>')
    inv = _tc_fmt_time_jp(dd.get("in"))
    outv = _tc_fmt_time_jp(dd.get("out"))
    has_punch = bool(dd.get("in") or dd.get("out"))
    if dd.get("incomplete"):
        flags = "／".join(dd.get("flags") or [])
        body = (f'<span class="io">{inv}〜{outv}</span><br>'
                f'<span class="bad">⚠{_h.escape(flags)}</span>')
        return (lv_html + "<br>" + body) if lv_html else body
    if has_punch:
        brk = f'（休憩{dd.get("break_min")}分）' if dd.get("break_min") else ""
        mn = dd.get("minutes")
        top = f'<span class="io">{inv}〜{outv}{brk}</span>'
        bot = f'<span class="wk">{_tc_fmt_hm(mn)}勤務</span>' if mn is not None else ""
        cell = top + "<br>" + bot
        if lv_html:
            cell += "<br>" + lv_html
        return cell
    if lv_html:
        return lv_html
    return ""


def _tc_report_grid_html(fac_name, year, month, staff):
    """timecard-leave-grid-v1: 勤怠集計表を職員×日付グリッドHTMLで組む。
    休み申告(有給/振替休/公休/欠勤…)を色ラベルで反映。空欄=公休。"""
    import html as _h
    import calendar as _cal
    from datetime import date as _d
    last_day = _cal.monthrange(year, month)[1]
    wdj = ["月", "火", "水", "木", "金", "土", "日"]
    per = []
    grand_min = 0
    for s0 in staff:
        dmap = {d["date"]: d for d in s0.get("days", [])}
        grand_min += s0.get("total_minutes", 0)
        per.append((s0, dmap))
    P = []
    P.append("""<!DOCTYPE html><html lang="ja"><head><meta charset="utf-8"><style>
  @page { size: A4 landscape; margin: 8mm; }
  * { box-sizing: border-box; }
  body { font-family:'Noto Sans CJK JP','IPAexGothic',sans-serif; color:#222; font-size:9px; }
  .hd { display:flex; justify-content:space-between; align-items:flex-end; margin-bottom:6px; }
  h1 { font-size:15px; margin:0; }
  .sub { color:#666; font-size:9.5px; }
  .tot { font-size:11px; font-weight:bold; color:#2f6b5e; }
  table { width:100%; border-collapse:collapse; table-layout:fixed; }
  th,td { border:1px solid #d9d5cc; padding:2px 3px; text-align:center; vertical-align:middle; line-height:1.3; overflow:hidden; }
  th { background:#f2efe9; font-weight:bold; }
  .stname { font-size:9.5px; } .stsub { font-size:8px; color:#666; font-weight:normal; }
  td.date { background:#faf8f4; font-weight:bold; white-space:nowrap; width:42px; }
  td.sat .wd { color:#1565c0; } td.sun .wd { color:#c62828; }
  .io { font-variant-numeric:tabular-nums; font-weight:bold; font-size:9.5px; }
  .wk { font-weight:normal; color:#666; font-size:8.5px; }
  .bad { color:#c0392b; font-size:8px; }
  .lv { display:inline-block; padding:1px 6px; border-radius:8px; font-weight:bold; font-size:8.5px; }
  .lvsub { font-size:7.5px; color:#1565c0; margin-top:1px; }
  tr.total td { background:#eef5f3; font-weight:bold; }
  .notes { margin-top:8px; border:1px solid #e6d3b3; border-radius:5px; padding:5px 8px; background:#fff8ef; }
  .notes-h { font-weight:bold; color:#c0392b; font-size:9.5px; margin-bottom:2px; }
  .note-row { font-size:8.5px; color:#333; line-height:1.55; }
  .legend { margin-top:6px; font-size:8px; color:#777; line-height:1.55; }
</style></head><body>""")
    P.append('<div class="hd"><div>')
    P.append(f'<h1>勤怠集計表</h1><div class="sub">{_h.escape(fac_name)}　'
             f'{year}年{month}月（1日〜{last_day}日 全日表示）</div></div>')
    P.append(f'<div class="tot">施設合計：{_tc_fmt_hm(grand_min)}</div></div>')
    # ヘッダ
    P.append('<table><colgroup><col style="width:42px">')
    for _ in per:
        P.append('<col>')
    P.append('</colgroup><tr><th>日付</th>')
    for (s0, _dm) in per:
        P.append('<th><div class="stname">' + _h.escape((s0.get("emoji") or "") + s0["name"])
                 + '</div><div class="stsub">計' + _tc_fmt_hm(s0.get("total_minutes", 0))
                 + '<br>' + str(s0.get("worked_days", 0)) + '日勤務</div></th>')
    P.append('</tr>')
    # 日次
    for day in range(1, last_day + 1):
        ds = f"{year:04d}-{month:02d}-{day:02d}"
        wd = _d(year, month, day).weekday()
        cls = "date" + (" sat" if wd == 5 else (" sun" if wd == 6 else ""))
        P.append(f'<tr><td class="{cls}">{day}<span class="wd">({wdj[wd]})</span></td>')
        for (s0, dm) in per:
            P.append('<td>' + _tc_grid_cell(dm.get(ds)) + '</td>')
        P.append('</tr>')
    # 月合計
    P.append('<tr class="total"><td>月合計</td>')
    for (s0, _dm) in per:
        P.append('<td>' + _tc_fmt_hm(s0.get("total_minutes", 0))
                 + '<br><span class="stsub">出勤' + str(s0.get("worked_days", 0)) + '日</span></td>')
    P.append('</tr></table>')
    # 備考
    note_rows = []
    for (s0, _dm) in per:
        for lv in (s0.get("leaves") or []):
            if lv.get("note"):
                note_rows.append((lv["date"], s0["name"], lv.get("label", ""),
                                  lv["note"], lv.get("substitute_for")))
    note_rows.sort(key=lambda x: (x[0] or "", x[1] or ""))
    if note_rows:
        P.append('<div class="notes"><div class="notes-h">備考</div>')
        for (nd, nm, nl, nt, nsf) in note_rows:
            sfx = f'（振替元:{_tc_day_label(nsf)}）' if nsf else ''
            P.append(f'<div class="note-row">{_h.escape(nm)}：{_tc_day_label(nd)}　'
                     f'{_h.escape(nl)}：{_h.escape(nt)}{sfx}</div>')
        P.append('</div>')
    P.append('<div class="legend">※各セル：上段＝出勤‒退勤（）内は休憩、下段＝その日の勤務時間合計。'
             '有給・振替休などは色付きラベルで表示。空欄は公休（登録なしの休み）。⚠は打刻の要確認。</div>')
    P.append('</body></html>')
    return "".join(P)


def _tc_build_monthly_data(supabase, f_code, year, month):
    """月次の職員別・日別集計を返す(admin_timecard_monthlyと同じ構造)。PDF/JSON共用。"""
    start_iso, end_iso = _tc_month_range_jst(year, month)
    res = supabase.table("timecard_records").select("*").eq(
        "facility_code", f_code).eq("is_deleted", False).gte(
        "punched_at", start_iso).lt("punched_at", end_iso).order(
        "punched_at", desc=False).execute()
    rows = res.data or []
    by_staff = {}
    for r in rows:
        sn = r.get("staff_name")
        dk = _tc_day_key(r.get("punched_at"))
        if not sn or not dk:
            continue
        by_staff.setdefault(sn, {}).setdefault(dk, []).append(r)
    staff_master = _tc_staff_list(supabase, f_code)
    name_order = [s["name"] for s in staff_master]
    emoji_map = {s["name"]: s["emoji"] for s in staff_master}
    for sn in by_staff.keys():
        if sn not in name_order:
            name_order.append(sn)
    result = []
    for sn in name_order:
        days_map = by_staff.get(sn, {})
        days = []
        total_min = 0
        worked_days = 0
        incomplete_days = 0
        for dk in sorted(days_map.keys()):
            comp = _tc_compute_day(days_map[dk])
            if comp["minutes"] is not None:
                total_min += comp["minutes"]
                if comp["minutes"] > 0:
                    worked_days += 1
            if comp["incomplete"]:
                incomplete_days += 1
            days.append({"date": dk, "minutes": comp["minutes"],
                         "incomplete": comp["incomplete"], "flags": comp["flags"],
                         "in": comp["in"], "out": comp["out"],
                         "break_min": comp["break_min"]})
        result.append({"name": sn, "emoji": emoji_map.get(sn, ""),
                       "days": days, "total_minutes": total_min,
                       "worked_days": worked_days,
                       "incomplete_days": incomplete_days})
    # timecard-leave-grid-v1: 休み申告を日次にマージ
    _tc_merge_leaves_into_monthly(supabase, f_code, year, month, result)
    return result


def _tc_fmt_hm(minutes):
    if minutes is None:
        return "—"
    h = minutes // 60
    m = minutes % 60
    return f"{h}時間" + (f"{m}分" if m else "")


def _tc_fmt_time_jst(iso):
    if not iso:
        return "--:--"
    dt = _tc_parse_iso(iso)
    if dt is None:
        return "--:--"
    dt = dt.astimezone(_TC_JST)
    return dt.strftime("%H:%M")


def _tc_day_label(dk):
    try:
        y, m, d = dk.split("-")
        from datetime import date as _d
        wd = ["月", "火", "水", "木", "金", "土", "日"][_d(int(y), int(m), int(d)).weekday()]
        return f"{int(d)}日({wd})"
    except Exception:
        return dk


@app.route("/admin/timecard/report_pdf", methods=["GET"])
@login_required
def admin_timecard_report_pdf():
    """勤怠集計をPDFで出力(サーバー生成)。管理者限定。query: year, month"""
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        if not is_admin_user(supabase, f_code, my_name):
            return jsonify({"status": "error", "message": "管理者権限がありません"}), 403
        now = _tc_now_jst()
        try:
            year = int(request.args.get("year", now.year))
            month = int(request.args.get("month", now.month))
        except (TypeError, ValueError):
            year, month = now.year, now.month
        if not (1 <= month <= 12):
            return jsonify({"status": "error", "message": "月が不正です。"}), 400

        staff = _tc_build_monthly_data(supabase, f_code, year, month)

        # timecard-leave-grid-v1: 職員×日付グリッドで休み申告(有給/振替休/公休…)を反映
        fac_name = ""
        try:
            fr = supabase.table("facilities").select("name").eq("facility_code", f_code).execute()
            if fr.data:
                fac_name = fr.data[0].get("name", "") or ""
        except Exception:
            pass
        html_str = _tc_report_grid_html(fac_name, year, month, staff)

        import pdfkit
        import shutil as _sh
        options = {
            "page-size": "A4", "encoding": "UTF-8", "orientation": "Landscape",
            "margin-top": "8mm", "margin-bottom": "8mm",
            "margin-left": "8mm", "margin-right": "8mm",
            "quiet": "",
        }
        wk_path = _sh.which("wkhtmltopdf") or "/usr/local/bin/wkhtmltopdf"
        config = pdfkit.configuration(wkhtmltopdf=wk_path)
        pdf_bytes = pdfkit.from_string(html_str, False, options=options, configuration=config)

        import io as _io
        from flask import send_file as _send
        buf = _io.BytesIO(pdf_bytes)
        buf.seek(0)
        fname = f"kintai_{year}{month:02d}.pdf"
        return _send(buf, as_attachment=True, download_name=fname, mimetype="application/pdf")
    except Exception as e:
        print(f"admin_timecard_report_pdf error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500
