# ============================================================
# timecard-config-v1 : 勤怠の事業所設定(勤務区切時刻・サービス提供時間)
#   admin_settings(key='timecard_config') に JSON で保存。
#   様式(参考様式4)出力で午前/午後の単位振り分けに使う。
#   まず区切り1つ=2単位(半日型)。将来 splits を複数にして可変単位へ拡張可能。
# ============================================================

import json as _tcfg_json

_TC_CONFIG_KEY = "timecard_config"
_TC_CONFIG_DEFAULT = {
    "work_split_times": ["12:30"],          # 勤務区切時刻(N-1個でN単位)。御社=12:30の1つ=2単位
    "service_times": [                        # サービス提供時間帯(参考・単位数把握用)
        {"label": "午前", "start": "09:00", "end": "12:00"},
        {"label": "午後", "start": "13:00", "end": "16:00"},
    ],
    "half_slot_hours": 4,                     # 半日型 1枠の時間
    "full_slot_hours": 8,                     # 1日型 1枠の時間
    "half_service_start": "09:00",           # 半日型 サービス提供時間(型別-svc-v1)
    "half_service_end": "12:30",
    "full_service_start": "09:00",           # 1日型 サービス提供時間
    "full_service_end": "16:00",
    "half_service_slots": [{"start": "09:00", "end": "12:30"}],  # 型別-svc-v2: 複数単位可
    "full_service_slots": [{"start": "09:00", "end": "16:00"}],
    # youshiki-daytype-v1: 曜日→型ルール。月火水木金土日の7要素。
    #   'full'=1日型 / 'half'=半日型 / 'both'=両方同時稼働(個別指定で振り分け) / 'none'=様式に出さない
    #   既定は現行のハードコード踏襲: 日=1日型, 月〜金=半日型, 土=なし
    "day_type_rule": ["half", "half", "half", "half", "half", "none", "full"],
    "role_splits": [],                        # 兼務: [{"name":職員名,"roles":[{"title":役職,"ratio":0.5},...]}]
    # pay-config-default-v1: 給与/残業計算用(社労士向け出力)。施設別に上書き可。
    "work_system": "standard",                # standard=通常制 / monthly_variable / yearly_variable(後者は将来枠)
    "daily_legal_min": 480,                   # 1日法定労働=8時間
    "weekly_legal_min": 2400,                 # 週法定労働=40時間
    "week_start": 6,                          # 週起算曜日 0=月..6=日(御社=日曜起算=6)
    "night_start": "22:00",                   # 深夜割増開始
    "night_end": "05:00",                     # 深夜割増終了(翻日)
    "holiday_mode": "weekly_rest",            # weekly_rest=週休判定 / fixed_weekday / calendar
    "legal_holiday_weekday": None,            # fixed_weekday時の曜日(0=月..6=日)。weekly_restならNone
    "legal_holiday_dates": [],                # calendar時の法定休日(YYYY-MM-DDのリスト)
    "rate_overtime": 1.25,                    # 時間外割増率
    "rate_night": 0.25,                       # 深夜割増(加算分)
    "rate_holiday": 1.35,                     # 法定休日割増率
    "closing_day": 0,                         # 締日 0=月末 / 20 / 15 等(可変)
}


def _tc_get_config(supabase, f_code):
    """事業所の勤怠設定を取得(無ければデフォルト)。"""
    try:
        res = supabase.table("admin_settings").select("value").eq(
            "facility_code", f_code).eq("key", _TC_CONFIG_KEY).execute()
        if res.data and res.data[0].get("value"):
            cfg = _tcfg_json.loads(res.data[0]["value"])
            if isinstance(cfg, dict):
                # デフォルトにマージ(欠けたキーを補完)
                merged = dict(_TC_CONFIG_DEFAULT)
                merged.update(cfg)
                # 型別-svc-v2: 旧単一フィールドしか無い設定を slots に移行
                for _pre in ("half", "full"):
                    _sk = _pre + "_service_slots"
                    if _sk not in cfg:
                        _st = cfg.get(_pre + "_service_start"); _en = cfg.get(_pre + "_service_end")
                        if _st and _en:
                            merged[_sk] = [{"start": _st, "end": _en}]
                return merged
    except Exception as e:
        print(f"_tc_get_config error: {e}", flush=True)
    return dict(_TC_CONFIG_DEFAULT)


@app.route("/admin/timecard/config", methods=["GET"])
@login_required
def admin_timecard_config_get():
    """勤怠設定を返す。管理者限定。"""
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        if not is_admin_user(supabase, f_code, my_name):
            return jsonify({"status": "error", "message": "管理者権限がありません"}), 403
        return jsonify({"status": "success", "config": _tc_get_config(supabase, f_code)})
    except Exception as e:
        print(f"admin_timecard_config_get error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


_TC_TIME_RE = __import__("re").compile(r"^([01]?\d|2[0-3]):[0-5]\d$")


@app.route("/admin/timecard/config", methods=["POST"])
@login_required
def admin_timecard_config_save():
    """勤怠設定を保存。管理者限定。区切時刻・サービス提供時間の妥当性を確認。"""
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        if not is_admin_user(supabase, f_code, my_name):
            return jsonify({"status": "error", "message": "管理者権限がありません"}), 403
        data = request.get_json(silent=True) or {}
        cfg = dict(_TC_CONFIG_DEFAULT)

        # 勤務区切時刻(リスト、HH:MM)
        splits = data.get("work_split_times")
        if isinstance(splits, list):
            clean = []
            for t in splits:
                t = str(t).strip()
                if _TC_TIME_RE.match(t):
                    clean.append(t)
            cfg["work_split_times"] = sorted(set(clean))

        # サービス提供時間帯(リスト of {label,start,end})
        svc = data.get("service_times")
        if isinstance(svc, list):
            clean_svc = []
            for s in svc:
                if not isinstance(s, dict):
                    continue
                st = str(s.get("start", "")).strip()
                en = str(s.get("end", "")).strip()
                lb = str(s.get("label", "")).strip() or "枠"
                if _TC_TIME_RE.match(st) and _TC_TIME_RE.match(en):
                    clean_svc.append({"label": lb, "start": st, "end": en})
            if clean_svc:
                cfg["service_times"] = clean_svc

        # 枠時間
        for k in ("half_slot_hours", "full_slot_hours"):
            v = data.get(k)
            if isinstance(v, (int, float)) and 0 < v <= 24:
                cfg[k] = v

        # 型別サービス提供時間(HH:MM。型別-svc-v1)
        for k in ("half_service_start", "half_service_end", "full_service_start", "full_service_end"):
            v = str(data.get(k, "")).strip()
            if v == "" or _TC_TIME_RE.match(v):
                cfg[k] = v

        # 型別サービス提供時間(複数単位。型別-svc-v2)
        for _sk in ("half_service_slots", "full_service_slots"):
            _arr = data.get(_sk)
            if isinstance(_arr, list):
                _clean = []
                for _s in _arr:
                    if not isinstance(_s, dict):
                        continue
                    _st = str(_s.get("start", "")).strip()
                    _en = str(_s.get("end", "")).strip()
                    if _TC_TIME_RE.match(_st) and _TC_TIME_RE.match(_en):
                        _clean.append({"start": _st, "end": _en})
                cfg[_sk] = _clean

        # 兼務マップ: [{name, roles:[{title, ratio}]}]
        rs = data.get("role_splits")
        if isinstance(rs, list):
            clean_rs = []
            for item in rs:
                if not isinstance(item, dict):
                    continue
                nm = str(item.get("name", "")).strip()
                roles = item.get("roles")
                if not nm or not isinstance(roles, list):
                    continue
                clean_roles = []
                for r in roles:
                    if not isinstance(r, dict):
                        continue
                    title = str(r.get("title", "")).strip()
                    try:
                        ratio = float(r.get("ratio", 0))
                    except (TypeError, ValueError):
                        ratio = 0
                    if title and ratio > 0:
                        clean_roles.append({"title": title, "ratio": ratio})
                if clean_roles:
                    clean_rs.append({"name": nm, "roles": clean_roles})
            cfg["role_splits"] = clean_rs

        # pay-config-save-v1: 残業/給与設定の検証と取り込み。
        _pay_ws = str(data.get("work_system", "")).strip()
        if _pay_ws in ("standard", "monthly_variable", "yearly_variable"):
            cfg["work_system"] = _pay_ws
        for _pk in ("daily_legal_min", "weekly_legal_min"):
            _pv = data.get(_pk)
            if isinstance(_pv, (int, float)) and 0 < _pv <= 100000:
                cfg[_pk] = int(_pv)
        _pw = data.get("week_start")
        if isinstance(_pw, int) and 0 <= _pw <= 6:
            cfg["week_start"] = _pw
        for _pk in ("night_start", "night_end"):
            _pv = str(data.get(_pk, "")).strip()
            if _TC_TIME_RE.match(_pv):
                cfg[_pk] = _pv
        _pm = str(data.get("holiday_mode", "")).strip()
        if _pm in ("weekly_rest", "fixed_weekday", "calendar"):
            cfg["holiday_mode"] = _pm
        _plw = data.get("legal_holiday_weekday")
        if _plw is None or (isinstance(_plw, int) and 0 <= _plw <= 6):
            cfg["legal_holiday_weekday"] = _plw
        _pld = data.get("legal_holiday_dates")
        if isinstance(_pld, list):
            cfg["legal_holiday_dates"] = [str(x).strip() for x in _pld
                                          if _LEAVE_DATE_RE.match(str(x).strip())]
        for _pk in ("rate_overtime", "rate_night", "rate_holiday"):
            _pv = data.get(_pk)
            if isinstance(_pv, (int, float)) and 0 <= _pv <= 10:
                cfg[_pk] = float(_pv)
        _pc = data.get("closing_day")
        if isinstance(_pc, int) and (_pc == 0 or 1 <= _pc <= 28):
            cfg["closing_day"] = _pc

        # youshiki-daytype-v1: 曜日→型ルール(7要素 月〜日)
        _dtr = data.get("day_type_rule")
        if isinstance(_dtr, list) and len(_dtr) == 7:
            _valid = {"full", "half", "both", "none"}
            _clean_dtr = [(str(x).strip() if str(x).strip() in _valid else "none") for x in _dtr]
            cfg["day_type_rule"] = _clean_dtr

        value_json = _tcfg_json.dumps(cfg, ensure_ascii=False)
        existing = supabase.table("admin_settings").select("id").eq(
            "facility_code", f_code).eq("key", _TC_CONFIG_KEY).execute()
        if existing.data:
            supabase.table("admin_settings").update({"value": value_json}).eq(
                "facility_code", f_code).eq("key", _TC_CONFIG_KEY).execute()
        else:
            supabase.table("admin_settings").insert({
                "facility_code": f_code, "key": _TC_CONFIG_KEY, "value": value_json,
            }).execute()
        return jsonify({"status": "success", "config": cfg})
    except Exception as e:
        print(f"admin_timecard_config_save error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500
# ----- /timecard-config-v1 -----


# ============================================================
# youshiki-export-v1 : 参考様式4(勤務の体制及び勤務形態一覧表)への実績転記出力
#   打刻(timecard_records)+休暇(staff_leave_days)+勤怠設定を、
#   同梱テンプレート(templates/youshiki_kinmu.xlsx)に転記して .xlsx を返す。
#   御社運用: 平日=半日型シート, 日曜=1日型シート, 土曜=空欄。月の1〜28日をD〜AE列。
# ============================================================

import os as _ys_os
from datetime import date as _ys_date

_YS_TEMPLATE = _ys_os.path.join(_ys_os.path.dirname(__file__), "templates", "youshiki_kinmu.xlsx")
_YS_SHEET_HALF = "R8.7(半日型）"
_YS_SHEET_FULL = "R8.7 (1日型)"
_YS_LEAVE_FORM = {"paid":"有給","substitute":"振休","condolence":"忌休",
                  "absence":"欠勤","off":"休","half":"半","hourly":"時",
                  # leave-obon-newyear-v1: 様式のマスは狭いので印字は「休」に揃える
                  "obon":"休","newyear":"休"}


def _ys_norm(s):
    return str(s or "").replace(" ", "").replace("　", "").strip()


def _ys_hm(s):
    try:
        h, m = str(s).split(":")
        return int(h) * 60 + int(m)
    except Exception:
        return None


def _ys_to_intervals(punches):
    """打刻[(type, minute)]から在席区間[(in,out)]。休憩は差し引かない。"""
    iv = []
    cur = None
    for t, mn in punches:
        if t == "in":
            cur = mn
        elif t == "out" and cur is not None:
            iv.append((cur, mn))
            cur = None
    return iv


def _ys_side_minutes(intervals, lo, hi):
    tot = 0
    for a, b in intervals:
        x = max(a, lo); y = min(b, hi)
        if y > x:
            tot += y - x
    return tot


def _ys_slot_value(minutes, cap):
    h = minutes / 60.0
    if h <= 0:
        return None
    if h >= cap:
        return cap
    return round(h * 2) / 2


def _ys_build_row_map(ws):
    """様式シートから 職員名(正規化)->[(unit,row,title)] を作る。"""
    m = {}
    unit = 0
    cur_title = None
    for row in range(9, 42):
        a = ws.cell(row=row, column=1).value
        c = ws.cell(row=row, column=3).value
        if a and "単位" in str(a):
            unit += 1
            continue
        if a and _ys_norm(a):
            cur_title = _ys_norm(a)
        nm = _ys_norm(c)
        if nm:
            m.setdefault(nm, []).append((unit, row, cur_title))
    return m


# youshiki-roster-v2: 職種登録(staffs.job_title)から様式へ氏名を動的転記
_YS_ROLE_MAP = {
    "管理者": "管理者",
    "生活相談員": "生活相談員",
    "介護職員": "介護職員",
    "機能訓練指導員": "機能訓練指導員",
    "看護師": "看護職員",
    "看護職員": "看護職員",
}
_YS_ROLE_LABELS = ("管理者", "生活相談員", "介護職員", "看護職員", "機能訓練指導員")
_YS_EMP_ORDER = {"A": 0, "B": 1, "C": 2, "D": 3}


def _ys_load_roster(supabase, f_code):
    """職員登録から {様式の役職ラベル: [(氏名, 形態), ...]} を作る。
    兼務職種(job_title2)も別役職として登録。並びは形態A→B→C→D、次に氏名。"""
    roster = {}
    try:
        res = supabase.table("staffs").select("*").eq(
            "facility_code", f_code).eq("is_active", True).execute()
        rows = res.data or []
    except Exception as e:
        print(f"_ys_load_roster error: {e}", flush=True)
        rows = []
    seen = set()
    for s in rows:
        nm = (s.get("staff_name") or "").strip()
        if not nm:
            continue
        emp = (s.get("employment_type") or "").strip().upper()
        for jt in (s.get("job_title"), s.get("job_title2")):
            t = _YS_ROLE_MAP.get((jt or "").strip())
            if not t:
                continue
            k = (t, nm)
            if k in seen:
                continue
            seen.add(k)
            roster.setdefault(t, []).append((nm, emp))
    for t in roster:
        roster[t].sort(key=lambda x: (_YS_EMP_ORDER.get(x[1], 9), x[0]))
    return roster


def _ys_scan_blocks(ws):
    """本文(10行目以降)を走査し [(unit, title, [rows...]), ...] を返す。"""
    blocks = []
    unit = 0
    for row in range(10, ws.max_row + 1):
        a = _ys_norm(ws.cell(row=row, column=1).value)
        if a and "単位" in a:
            unit += 1
            continue
        if a and ("申請する事業" in a or "勤務形態の区分" in a
                  or a in ("常勤", "非常勤", "専従", "兼務")):
            break
        if a in _YS_ROLE_LABELS:
            blocks.append((unit, a, [row]))
        elif blocks and blocks[-1][2][-1] == row - 1:
            blocks[-1][2].append(row)
    return blocks


def _ys_copy_row_style(ws, src_row, dst_row, ncols=34):
    import copy as _c
    for c in range(1, ncols + 1):
        s = ws.cell(row=src_row, column=c)
        d = ws.cell(row=dst_row, column=c)
        d.border = _c.copy(s.border)
        d.font = _c.copy(s.font)
        d.alignment = _c.copy(s.alignment)
        d.fill = _c.copy(s.fill)
        d.number_format = s.number_format
    ws.row_dimensions[dst_row].height = ws.row_dimensions[src_row].height or 18.0


def _ys_insert_rows_shift(ws, at, n):
    """insert_rowsは結合セルを移動しないため、挿入位置以降の結合セルをn行下へシフトする。"""
    from openpyxl.worksheet.cell_range import CellRange
    to_shift = [str(m) for m in list(ws.merged_cells.ranges) if m.min_row >= at]
    for coord in to_shift:
        ws.unmerge_cells(coord)
    ws.insert_rows(at, n)
    for coord in to_shift:
        cr = CellRange(coord)
        cr.shift(0, n)
        ws.merge_cells(str(cr))


def _ys_apply_roster(ws, roster):
    """役職ブロックに氏名(C列)・形態(B列)を転記。行不足時は自動挿入。
    (氏名->[(unit,row,title)] の rowmap, 単位数) を返す。"""
    blocks = _ys_scan_blocks(ws)
    num_units = max((u for (u, _t, _r) in blocks), default=1) or 1
    # 不足行を下のブロックから順に挿入(上のブロックの行番号を保つ)
    for (unit, title, rows) in sorted(blocks, key=lambda b: -b[2][0]):
        staff = roster.get(title, [])
        need = len(staff) - len(rows)
        if need > 0:
            at = rows[-1] + 1
            _ys_insert_rows_shift(ws, at, need)
            for i in range(need):
                _ys_copy_row_style(ws, rows[-1], at + i)
                ws.cell(row=at + i, column=2).value = None
                ws.cell(row=at + i, column=3).value = None
    # 再走査して最終行位置で転記
    blocks = _ys_scan_blocks(ws)
    rowmap = {}
    for (unit, title, rows) in blocks:
        staff = roster.get(title, [])
        for idx, r in enumerate(rows):
            if idx < len(staff):
                nm, emp = staff[idx]
                ws.cell(row=r, column=3).value = nm
                ws.cell(row=r, column=2).value = emp or None
                rowmap.setdefault(_ys_norm(nm), []).append((unit, r, title))
            else:
                ws.cell(row=r, column=3).value = None
                ws.cell(row=r, column=2).value = None
    return rowmap, num_units


# youshiki-daytype-v1: 1日型/半日型の判定
def _ys_month_bounds(year, month):
    _st = f"{year:04d}-{month:02d}-01"
    _en = f"{year+1:04d}-01-01" if month == 12 else f"{year:04d}-{month+1:02d}-01"
    return _st, _en


def _ys_staff_default_types(supabase, f_code):
    """{_ys_norm(staff_name): 'full'|'half'} 職員ごとの既定の型。未設定は含めない。

    youshiki-yotei-fix-v1: ★staffs の氏名の列は staff_name。"name" という列は無い。
      "name" で select していたので PostgREST が弾き、except に落ちて
      【いつでも必ず {} が返っていた】＝職員ごとの既定の型は一度も効いていない。
      app.py の他33か所は全部 staff_name を使っている。ここだけ取り残されていた。
    ★これを直しても見た目は変わらない。型は ①手動 ②予定の型 ③職員既定
      ④曜日ルール の順で決まり、いまの曜日ルールが④で必ず決めてしまうので
      ③は出番が無い。それでも、動いていない物を動いているふりのままにしない。
    """
    m = {}
    try:
        r = supabase.table("staffs").select("staff_name,youshiki_default_type").eq(
            "facility_code", f_code).execute()
        rows = r.data or []
    except Exception as e:
        # youshiki-yotei-fix-v1: ★黙って空にしない。列が無い場合もここに来る。
        print(f"_ys_staff_default_types error: {e}", flush=True)
        return m
    for x in rows:
        v = (x.get("youshiki_default_type") or "").strip()
        if v in ("full", "half"):
            m[_ys_norm(x.get("staff_name"))] = v
    return m


def _ys_manual_day_types(supabase, f_code, year, month):
    """勤怠集計で手動指定した型 {(_ys_norm(name),'YYYY-MM-DD'): 'full'|'half'}。"""
    m = {}
    try:
        _st, _en = _ys_month_bounds(year, month)
        r = supabase.table("youshiki_day_type").select("staff_name,work_date,day_type").eq(
            "facility_code", f_code).gte("work_date", _st).lt("work_date", _en).execute()
        for x in (r.data or []):
            v = (x.get("day_type") or "").strip()
            if v in ("full", "half"):
                m[(_ys_norm(x.get("staff_name")), str(x.get("work_date")))] = v
    except Exception as e:
        print(f"_ys_manual_day_types error: {e}", flush=True)
    return m


def _ys_plan_day_types(supabase, f_code, year, month):
    """予定(staff_shift_plan)のシフト個別指定の型 {(_ys_norm(name),'YYYY-MM-DD'): 'full'|'half'}。"""
    m = {}
    try:
        _st, _en = _ys_month_bounds(year, month)
        r = supabase.table("staff_shift_plan").select("staff_name,plan_date,day_type").eq(
            "facility_code", f_code).gte("plan_date", _st).lt("plan_date", _en).execute()
        for x in (r.data or []):
            v = (x.get("day_type") or "").strip()
            if v in ("full", "half"):
                m[(_ys_norm(x.get("staff_name")), str(x.get("plan_date")))] = v
    except Exception as e:
        print(f"_ys_plan_day_types error: {e}", flush=True)
    return m


def _ys_weekday_rule_type(cfg, d):
    """曜日ルールの型。'full'|'half'|'both'|'none'。"""
    rule = cfg.get("day_type_rule")
    if not (isinstance(rule, list) and len(rule) == 7):
        rule = _TC_CONFIG_DEFAULT["day_type_rule"]
    v = rule[d.weekday()]
    return v if v in ("full", "half", "both", "none") else "none"


def _ys_resolve_day_type(name_norm, ds, wd_type, manual, plan_types, staff_def):
    """(職員,日)の型を優先順位で決める。
       返り値: (type or None, unresolved)
       優先: ①手動(実績のみ渡す) ②予定の型(実績=継承/予定=個別指定) ③職員既定 ④曜日ルール
       曜日ルールが'both'で①〜③どれも無い → (None, True) 警告対象。'none' → (None, False)出さない。"""
    key = (name_norm, ds)
    if key in manual:
        return manual[key], False
    if key in plan_types:
        return plan_types[key], False
    if name_norm in staff_def:
        return staff_def[name_norm], False
    if wd_type in ("full", "half"):
        return wd_type, False
    if wd_type == "none":
        return None, False
    return None, True  # both かつ未指定


@app.route("/admin/timecard/youshiki", methods=["GET"])
@login_required
def admin_timecard_youshiki():
    """参考様式4に実績を転記した .xlsx をダウンロード。管理者限定。
    query: year, month"""
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        if not is_admin_user(supabase, f_code, my_name):
            return jsonify({"status": "error", "message": "管理者権限がありません"}), 403
        now = _tc_now_jst()
        try:
            year = int(request.args.get("year", now.year))
            month = int(request.args.get("month", now.month))
        except (TypeError, ValueError):
            year, month = now.year, now.month
        if not (1 <= month <= 12):
            return jsonify({"status": "error", "message": "月が不正です。"}), 400
        is_yotei = (request.args.get("mode") == "yotei")  # kinmu-yotei-v1: 勤務予定の様式出力
        if not _ys_os.path.exists(_YS_TEMPLATE):
            return jsonify({"status": "error", "message": "様式テンプレートが見つかりません。"}), 500

        cfg = _tc_get_config(supabase, f_code)
        split_min = None
        if cfg.get("work_split_times"):
            split_min = _ys_hm(cfg["work_split_times"][0])
        half_cap = cfg.get("half_slot_hours", 4)
        full_cap = cfg.get("full_slot_hours", 8)
        role_splits = cfg.get("role_splits", [])
        split_by_name = {}
        for it in role_splits:
            split_by_name[_ys_norm(it.get("name"))] = {
                _ys_norm(r.get("title")): r.get("ratio", 0) for r in it.get("roles", [])}

        # youshiki-daytype-v1: 型判定用のマップを用意（曜日ルール＋職員既定＋予定/手動指定）
        _dt_staff_def = _ys_staff_default_types(supabase, f_code)
        _dt_plan = _ys_plan_day_types(supabase, f_code, year, month)
        # 手動指定(youshiki_day_type)は実績のみ適用。予定出力では使わない。
        _dt_manual = {} if is_yotei else _ys_manual_day_types(supabase, f_code, year, month)
        _dt_unresolved = set()  # (name, ds) 曜日ルール'both'で型が決まらなかった日（警告用）

        # youshiki-yotei-fix-v1: その月に勤務予定が【1行でも保存されている】職員(正規化名)。
        #   ★空欄の理由を分けるために使う。
        #     1行も無い ＝ 保存を押していない（画面には曜日パターンで出勤が見えている）
        #     行はある   ＝ 保存済み。そのシートの型の日が無いだけ
        _ys_plan_seen = set()
        # (name, 'YYYY-MM-DD') -> [(type, minute)]
        punches_map = {}
        if is_yotei:
            # kinmu-yotei-v1: 勤務予定の work日を in/out 打刻として合成（既存の様式ロジックを再利用）
            _pm_start = f"{year:04d}-{month:02d}-01"
            _pm_end = f"{year+1:04d}-01-01" if month == 12 else f"{year:04d}-{month+1:02d}-01"
            pres = supabase.table("staff_shift_plan").select("*").eq(
                "facility_code", f_code).gte("plan_date", _pm_start).lt(
                "plan_date", _pm_end).execute()
            # youshiki-yotei-fix-v1: 出勤・休みを問わず、行があった職員を控える
            _ys_plan_seen = {_ys_norm(r.get("staff_name")) for r in (pres.data or [])}
            for r in (pres.data or []):
                if (r.get("status") or "") != "work":
                    continue
                ds = str(r.get("plan_date"))
                name_norm = _ys_norm(r.get("staff_name"))
                key = (name_norm, ds)
                # 型別-svc-v2: 各日の型を解決し、その型のサービス提供時間(複数単位)で打刻を作る
                _slots = None
                try:
                    _d = datetime.strptime(ds, "%Y-%m-%d")
                    _wd = _ys_weekday_rule_type(cfg, _d)
                    _rt = _ys_resolve_day_type(name_norm, ds, _wd, _dt_manual, _dt_plan, _dt_staff_def)[0]
                    if _rt == "half":
                        _slots = cfg.get("half_service_slots")
                    elif _rt == "full":
                        _slots = cfg.get("full_service_slots")
                except Exception:
                    _slots = None
                _added = False
                if _slots:
                    for _s in _slots:
                        if not isinstance(_s, dict):
                            continue
                        _ss = _ys_hm(_s.get("start")); _ee = _ys_hm(_s.get("end"))
                        if _ss is not None and _ee is not None and _ee > _ss:
                            punches_map.setdefault(key, []).append(("in", _ss))
                            punches_map[key].append(("out", _ee))
                            _added = True
                if not _added:
                    sm = _ys_hm(r.get("start_time")); em = _ys_hm(r.get("end_time"))
                    if sm is not None and em is not None and em > sm:
                        punches_map.setdefault(key, []).append(("in", sm))
                        punches_map[key].append(("out", em))
        else:
            # 月の打刻を取得(1〜28日)
            start_iso, end_iso = _tc_month_range_jst(year, month)
            res = supabase.table("timecard_records").select("*").eq(
                "facility_code", f_code).eq("is_deleted", False).gte(
                "punched_at", start_iso).lt("punched_at", end_iso).order(
                "punched_at", desc=False).execute()
            rows = res.data or []
            # youshiki-exclude-v1: 「様式に出さない」指定の (職員, 日付) を除外
            _yx_set = _youshiki_excluded_set(supabase, f_code, year, month) \
                if _youshiki_exclude_enabled(supabase, f_code) else set()
            for r in rows:
                at = _tc_parse_iso(r.get("punched_at"))
                if at is None:
                    continue
                at_jst = at.astimezone(_TC_JST)
                ds = at_jst.strftime("%Y-%m-%d")
                key = (_ys_norm(r.get("staff_name")), ds)
                if key in _yx_set:  # youshiki-exclude-v1: 除外日はスキップ
                    continue
                punches_map.setdefault(key, []).append(
                    (r.get("punch_type"), at_jst.hour * 60 + at_jst.minute))
        for k in punches_map:
            punches_map[k].sort(key=lambda x: x[1])

        # 休暇を取得
        leaves_map = {}
        note_rows = []  # timecard-leave-note-v1: 備考一覧（表の下に出す）
        if is_yotei:
            # youshiki-yotei-fix-v1: ★予定でも休みのマスに印を出す。
            #   前は「予定出力では使わない」として一度も読んでいなかったので、
            #   休みの日はただの空欄だった。空欄が「休み」なのか
            #   「予定が入っていない」のか、見て分からなかった。
            #   ★予定の休みは staff_leave_days ではない。あちらは実績側の記録。
            #     予定の休みは staff_shift_plan の status が 'work' でない日。
            #   ★区分(leave_type)が入っていればその印（有給/振休/忌休/欠勤）、
            #     入っていなければ 'off' ＝ 「休」。
            #   ★土曜は曜日ルールが 'none' でどちらのシートにも出ない日なので
            #     印も出ない。日曜は1日型シート側に出る。
            for r in (pres.data or []):
                if (r.get("status") or "") == "work":
                    continue
                _lv = (r.get("leave_type") or "").strip()
                leaves_map[(_ys_norm(r.get("staff_name")), str(r.get("plan_date")))] = (
                    _lv if _lv in _YS_LEAVE_FORM else "off")
        else:
            lstart = f"{year:04d}-{month:02d}-01"
            lend = f"{year+1:04d}-01-01" if month == 12 else f"{year:04d}-{month+1:02d}-01"
            lres = supabase.table("staff_leave_days").select("*").eq(
                "facility_code", f_code).gte("leave_date", lstart).lt(
                "leave_date", lend).execute()
            for r in (lres.data or []):
                leaves_map[(_ys_norm(r.get("staff_name")), r.get("leave_date"))] = r.get("leave_type")
                _nt = (r.get("note") or "").strip()
                if _nt:
                    _lt = _LEAVE_TYPES.get(r.get("leave_type"))
                    _lbl = _lt["label"] if _lt else (r.get("leave_type") or "")
                    note_rows.append((r.get("leave_date"), r.get("staff_name"), _lbl, _nt, r.get("substitute_for")))
            note_rows.sort(key=lambda x: (x[0] or "", x[1] or ""))

        import openpyxl as _ys_xl
        from openpyxl.styles import Font as _YS_Font
        from copy import copy as _ys_copy
        wb = _ys_xl.load_workbook(_YS_TEMPLATE)

        def _ys_set_cell(cell, value, is_leave):
            # youshiki-color-v1: 数値は黒、休暇文字は赤。既存フォントを保ちつつ色だけ変える。
            cell.value = value
            f = cell.font
            new_color = "FFFF0000" if is_leave else "FF000000"
            cell.font = _YS_Font(name=f.name, size=f.size, bold=f.bold,
                                 italic=f.italic, color=new_color)

        # youshiki-jisseki-v1: タイトルを「予定」→「実績」に、月表記を出力年月に更新
        _ys_wareki = year - 2018  # 令和 = 西暦-2018
        _ys_month_str = f"（令和{_ys_wareki}年{month}月分）"
        for _sn in wb.sheetnames:
            _ws = wb[_sn]
            for _r in range(1, 4):
                for _c in range(1, 35):
                    _cell = _ws.cell(row=_r, column=_c)
                    _v = _cell.value
                    if not isinstance(_v, str):
                        continue
                    if (not is_yotei) and "予定" in _v:
                        _v = _v.replace("予定", "実績")
                    # 月表記「（令和X年Y月分）」を出力年月に置換
                    import re as _ys_re2
                    _v = _ys_re2.sub(r"（令和\d+年\d+月分）", _ys_month_str, _v)
                    _cell.value = _v

        # 半日型(平日)と1日型(日曜)の両シートに転記
        # youshiki-d8-fix-v1: D8(起点日付)を出力対象月の1日で全シート上書き。
        #   -> E8以降の=D8+1 と D9以降の=TEXT(D8,"aaa") が日付・曜日とも自動追従。
        #   テンプレ固定値(12月始まり)によるズレを根絶する。
        import calendar as _ys_cal
        _ys_wd = ["月", "火", "水", "木", "金", "土", "日"]  # 月火水木金土日
        _ys_ndays = _ys_cal.monthrange(year, month)[1]
        for _sn2 in wb.sheetnames:
            _ws2 = wb[_sn2]
            # youshiki-date-explicit-v1: 日付(行8)・曜日(行9)を明示値で書き込む
            #   （openpyxlは =D8+1 / =TEXT(..,"aaa") を再計算しないため空欄になるのを防ぐ）
            for _day in range(1, 29):
                if _day > _ys_ndays:
                    break
                _c = 4 + (_day - 1)
                _dd = _ys_date(year, month, _day)
                _ws2.cell(row=8, column=_c).value = _dd
                _ws2.cell(row=9, column=_c).value = _ys_wd[_dd.weekday()]
            # 1日型はタイトルが M2/Q2 に分裂しているため明示的に統一する
            _ys_lbl = "\u4e88\u5b9a" if is_yotei else "\u5b9f\u7e3e"
            if isinstance(_ws2["Q2"].value, str) and _ys_lbl in _ws2["Q2"].value:
                _ws2["M2"] = "\u52e4\u52d9" + _ys_lbl + _ys_month_str
                _ws2["Q2"] = None

        _ys_roster = _ys_load_roster(supabase, f_code)  # youshiki-roster-v2: 職種登録から氏名を取得
        # youshiki-yotei-fix-v1: 1件も入らなかった職員を控える {氏名: [空だったシート名]}
        _ys_blank = {}
        _ys_sheets_seen = []
        for sheet_name, is_full in ((_YS_SHEET_HALF, False), (_YS_SHEET_FULL, True)):
            if sheet_name not in wb.sheetnames:
                continue
            ws = wb[sheet_name]
            rowmap, _num_units = _ys_apply_roster(ws, _ys_roster)  # youshiki-roster-v2: 職種登録から氏名を動的転記(不足行は自動挿入)
            cap = full_cap if is_full else half_cap
            sheet_type = "full" if is_full else "half"
            for day in range(1, 29):
                try:
                    d = _ys_date(year, month, day)
                except ValueError:
                    break
                # youshiki-daytype-v1: 曜日ルール＋個別指定で型を決め、一致するシートにだけ書く
                #   （半日型と1日型は必ず別シート。同一シートに混在させない）
                wd_type = _ys_weekday_rule_type(cfg, d)
                col = 4 + (day - 1)
                ds = f"{year:04d}-{month:02d}-{day:02d}"
                for name, occurs in rowmap.items():
                    leave = leaves_map.get((name, ds))
                    punches = punches_map.get((name, ds))
                    rtype, _dt_unres = _ys_resolve_day_type(
                        name, ds, wd_type, _dt_manual, _dt_plan, _dt_staff_def)
                    if _dt_unres:
                        # 曜日ルール'both'で型が決まらない：実働/休暇がある日だけ警告に記録
                        if punches or leave:
                            _dt_unresolved.add((name, ds))
                        continue
                    if rtype != sheet_type:
                        continue  # このシートの型と違う日は書かない
                    # 型別-svc-hours-v2: 値は「時間」。基準＝1枠の時間(cap)、兼務は役職比率で按分。
                    #   単位に属さない役職(unit=0。例:管理者)は1日分(単位数×枠)、単位に属する役職は枠1つ分。
                    sp = split_by_name.get(name)
                    for (unit, row, title) in occurs:
                        if leave:
                            _ys_set_cell(ws.cell(row=row, column=col), _YS_LEAVE_FORM.get(leave, leave), True)
                            continue
                        if not punches:
                            continue
                        ratio = sp[title] if (sp and title in sp) else 1.0
                        base = (_num_units * cap) if unit == 0 else cap
                        val = round(base * ratio * 2) / 2
                        if val <= 0:
                            continue
                        _ys_set_cell(ws.cell(row=row, column=col), val, False)

            # youshiki-yotei-fix-v1: このシートで1件も入らなかった職員を控える。
            #   ★書いた側を数えるのではなく、【出来上がったシートの中身】を見る。
            #     書く場所が増えても減っても、この見方なら食い違わない。
            #   D列(4)から28日分。休みの印も「入っている」に数える。
            for _bn, _boccurs in rowmap.items():
                _bhas = False
                for (_bu, _brow, _bt) in _boccurs:
                    for _bc in range(4, 4 + 28):
                        if ws.cell(row=_brow, column=_bc).value not in (None, ""):
                            _bhas = True
                            break
                    if _bhas:
                        break
                if not _bhas:
                    _ys_blank.setdefault(_bn, []).append(sheet_name)
            _ys_sheets_seen.append(sheet_name)

        # youshiki-yotei-fix-v1: 1件も入らなかった職員を、シートの下に赤字で出す。
        #   ★様式の不具合ではなく【データが無い】ことを伝えるのが目的。
        #     常勤換算(AG列)がその人だけ 0 になる。届出に使う前に必ず見てほしい。
        #   ★理由を2つに分ける。ここが分かれば読むだけで直せる。
        #     (a) その月の勤務予定が1行も保存されていない
        #         → 画面には曜日パターンで出勤が見えているが、DBには無い。
        #           勤務予定の画面でその月を開いて「保存」を押す。
        #     (b) 保存はされている → そのシートの型に当たる日が無いだけ。
        if _ys_blank and _ys_sheets_seen:
            from openpyxl.styles import Font as _BFont, PatternFill as _BFill
            _bfont = _BFont(name="MS PGothic", size=11, bold=True, color="FFCC0000")
            _bfill = _BFill(fill_type="solid", fgColor="FFFFF2CC")
            _bym = "%d年%d月" % (year, month)
            _blines = []
            for _bn in sorted(_ys_blank.keys()):
                _bss = _ys_blank[_bn]
                if is_yotei and (_bn not in _ys_plan_seen):
                    _blines.append((_bn, _bym + "の勤務予定が一度も保存されていません。"
                                         "勤務予定の画面でこの月を開いて「保存」を押してください。"))
                elif len(_bss) >= len(_ys_sheets_seen):
                    _blines.append((_bn, "どのシートにも1件もありません。"))
                else:
                    _blines.append((_bn, "「" + "」「".join(_bss) + "」に出る日がありません。"))
            for _bs in _ys_sheets_seen:
                _bws = wb[_bs]
                _br = _bws.max_row + 3
                _bc0 = _bws.cell(
                    row=_br, column=1,
                    value="⚠ 勤務が1件も入っていない職員がいます。"
                          "様式の不具合ではなく、勤務予定/実績のデータがありません。")
                _bc0.font = _bfont
                for _cc in range(1, 8):
                    _bws.cell(row=_br, column=_cc).fill = _bfill
                for (_bn, _bmsg) in _blines:
                    _br += 1
                    _bws.cell(row=_br, column=1, value=_bn)
                    _bws.cell(row=_br, column=2, value=_bmsg)

        # youshiki-daytype-v1: 曜日ルール'both'で型が決まらなかった日を警告として明示（黙って落とさない）
        if _dt_unresolved:
            from openpyxl.styles import Font as _WFont, PatternFill as _WFill
            _wf = _WFont(name="MS PGothic", size=11, bold=True, color="FFCC0000")
            _wfill = _WFill(fill_type="solid", fgColor="FFFFF2CC")
            _wlist = sorted(_dt_unresolved, key=lambda x: (x[1], x[0]))
            for _ns in (_YS_SHEET_HALF, _YS_SHEET_FULL):
                if _ns not in wb.sheetnames:
                    continue
                _wsn = wb[_ns]
                _wr = _wsn.max_row + 3
                _wc = _wsn.cell(row=_wr, column=1,
                                value="⚠ 区分（1日型/半日型）が未指定の日があります。勤怠集計で型を指定してください。")
                _wc.font = _wf
                for _cc in range(1, 6):
                    _wsn.cell(row=_wr, column=_cc).fill = _wfill
                for (_un, _uds) in _wlist:
                    _wr += 1
                    _wsn.cell(row=_wr, column=1, value=_uds)
                    _wsn.cell(row=_wr, column=2, value=_un)

        # timecard-leave-note-v1 / prominent-v2: 表の下に「備考一覧」を追記（様式本体は崩さない）。
        # 様式の下部には長い説明文があり見落としやすいので、赤字・太字・区切り線で目立たせる。
        if note_rows:
            from openpyxl.styles import Font as _NoteFont, PatternFill as _NoteFill, Border as _NoteBorder, Side as _NoteSide
            _red = _NoteFont(name="MS PGothic", size=12, bold=True, color="FFCC0000")
            _hdrf = _NoteFont(name="MS PGothic", size=10, bold=True, color="FF000000")
            _bodyf = _NoteFont(name="MS PGothic", size=10, color="FF000000")
            _fill = _NoteFill(fill_type="solid", fgColor="FFFDE9D9")
            _thin = _NoteBorder(bottom=_NoteSide(style="thin", color="FFBBBBBB"))
            for _ns in (_YS_SHEET_HALF, _YS_SHEET_FULL):
                if _ns not in wb.sheetnames:
                    continue
                _wsn = wb[_ns]
                _r0 = _wsn.max_row + 3  # 説明文との間を1行以上あけて分離
                _tc = _wsn.cell(row=_r0, column=1, value="■ 備考一覧（振替・経緯など）　※打刻時に入力できなかった経緯はここに記載")
                _tc.font = _red
                for _cc in range(1, 6):
                    _wsn.cell(row=_r0, column=_cc).fill = _fill
                _r0 += 1
                for _ci, _hd in enumerate(("日付", "職員", "区分", "備考"), start=1):
                    _hc = _wsn.cell(row=_r0, column=_ci, value=_hd)
                    _hc.font = _hdrf
                    _hc.border = _thin
                for (_ds2, _nm2, _lbl2, _nt2, _sf2) in note_rows:
                    _r0 += 1
                    _dnote = _nt2 + (f"（振替元:{_sf2}）" if _sf2 else "")
                    for _ci2, _vv in enumerate((_ds2, _nm2, _lbl2, _dnote), start=1):
                        _bc = _wsn.cell(row=_r0, column=_ci2, value=_vv)
                        _bc.font = _bodyf

        import io as _ys_io
        buf = _ys_io.BytesIO()
        wb.save(buf)
        buf.seek(0)
        from flask import send_file as _ys_send
        fname = f"kinmu_{'yotei' if is_yotei else 'jisseki'}_{year}{month:02d}.xlsx"
        return _ys_send(buf, as_attachment=True, download_name=fname,
                        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
    except Exception as e:
        print(f"admin_timecard_youshiki error: {e}", flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500
# ----- /youshiki-export-v1 -----


# ============================================================
# pay-export-v1 : 勤怠出力(シンプル勤怠 / 社労士向け給与計算)
#   出力形式: CSV(cp932) / Excel(openpyxl) / PDF(pdfkit)
#   出力単位: 施設全体(scope=all) / 職員個別(scope=staff&staff_name=..)
#   期間: 締日可変(timecard_config.closing_day)。0=月末, 20=前月21〜当月20 等。
#   残業算出: 通常制(standard)。日次8h超/深夜割増/週40h超(二重計上防止)/法定休日。
#   設定は timecard_config(admin_settings) を _tc_get_config で読む。DDL不要。
# ============================================================
import csv as _pay_csv
import io as _pay_io
from datetime import date as _pay_date, timedelta as _pay_td


def _pay_hm(s):
    try:
        h, m = str(s).split(":")
        return int(h) * 60 + int(m)
    except Exception:
        return None


def _pay_period_range_jst(year, month, closing_day):
    """締日から集計期間[start_iso, end_iso)(UTC)と表示ラベルを返す。
    closing_day=0: 当月1日〜翌月1日(月末締め)。
    closing_day=N(1..28): 前月(N+1)日〜当月N日翌日。対象月=末日が属する月。"""
    if not closing_day or closing_day <= 0:
        s_start, s_end = _tc_month_range_jst(year, month)
        label = f"{year}\u5e74{month}\u6708"
        d_start = _pay_date(year, month, 1)
        # 当月末日
        if month == 12:
            d_end = _pay_date(year + 1, 1, 1) - _pay_td(days=1)
        else:
            d_end = _pay_date(year, month + 1, 1) - _pay_td(days=1)
        return s_start, s_end, label, d_start, d_end
    # 締日あり: 対象は「当月 closing_day 締め」。期間=前月(cd+1)〜当月cd。
    end_d = _pay_date(year, month, closing_day)
    # 前月の closing_day+1
    if month == 1:
        pm_y, pm_m = year - 1, 12
    else:
        pm_y, pm_m = year, month - 1
    start_d = _pay_date(pm_y, pm_m, closing_day) + _pay_td(days=1)
    # iso範囲(JST 0:00基準 -> UTC)
    s_start = _tc_dt(start_d.year, start_d.month, start_d.day, 0, 0, 0,
                     tzinfo=_TC_JST).astimezone(_tc_tz.utc).isoformat()
    end_plus = end_d + _pay_td(days=1)
    s_end = _tc_dt(end_plus.year, end_plus.month, end_plus.day, 0, 0, 0,
                   tzinfo=_TC_JST).astimezone(_tc_tz.utc).isoformat()
    label = f"{year}\u5e74{month}\u6708(\u7de0\u65e5{closing_day}\u65e5)"
    return s_start, s_end, label, start_d, end_d


def _pay_build_monthly_range(supabase, f_code, start_iso, end_iso):
    """任意期間[start_iso,end_iso)の職員別・日別集計(構造は_tc_build_monthly_dataと同一)。
    締日可変対応のため月境界に依存しない版。"""
    res = supabase.table("timecard_records").select("*").eq(
        "facility_code", f_code).eq("is_deleted", False).gte(
        "punched_at", start_iso).lt("punched_at", end_iso).order(
        "punched_at", desc=False).execute()
    rows = res.data or []
    by_staff = {}
    for r in rows:
        sn = r.get("staff_name")
        dk = _tc_day_key(r.get("punched_at"))
        if not sn or not dk:
            continue
        by_staff.setdefault(sn, {}).setdefault(dk, []).append(r)
    staff_master = _tc_staff_list(supabase, f_code)
    name_order = [s["name"] for s in staff_master]
    emoji_map = {s["name"]: s["emoji"] for s in staff_master}
    for sn in by_staff.keys():
        if sn not in name_order:
            name_order.append(sn)
    result = []
    for sn in name_order:
        days_map = by_staff.get(sn, {})
        days = []
        total_min = 0
        worked_days = 0
        incomplete_days = 0
        for dk in sorted(days_map.keys()):
            comp = _tc_compute_day(days_map[dk])
            if comp["minutes"] is not None:
                total_min += comp["minutes"]
                if comp["minutes"] > 0:
                    worked_days += 1
            if comp["incomplete"]:
                incomplete_days += 1
            days.append({"date": dk, "minutes": comp["minutes"],
                         "incomplete": comp["incomplete"], "flags": comp["flags"],
                         "in": comp["in"], "out": comp["out"],
                         "break_min": comp["break_min"]})
        result.append({"name": sn, "emoji": emoji_map.get(sn, ""),
                       "days": days, "total_minutes": total_min,
                       "worked_days": worked_days,
                       "incomplete_days": incomplete_days})
    return result


def _pay_night_minutes(in_iso, out_iso, ns, ne):
    """在席[in,out]のうち深夜帯(ns,ne分)の重なり(分)。日跨ぎ対応。"""
    din = _tc_parse_iso(in_iso)
    dout = _tc_parse_iso(out_iso)
    if din is None or dout is None:
        return 0
    din = din.astimezone(_TC_JST)
    dout = dout.astimezone(_TC_JST)
    a = din.hour * 60 + din.minute
    b = dout.hour * 60 + dout.minute
    if b < a:
        b += 1440
    bands = []
    if ns < ne:
        bands.append((ns, ne))
        bands.append((ns + 1440, ne + 1440))
    else:
        bands.append((ns - 1440, ne))
        bands.append((ns, ne + 1440))
        bands.append((ns + 1440, ne + 1440))
    tot = 0
    for bs, be in bands:
        x = max(a, bs)
        y = min(b, be)
        if y > x:
            tot += y - x
    return tot


def _pay_week_key(d, week_start):
    delta = (d.weekday() - week_start) % 7
    return d - _pay_td(days=delta)


def _pay_legal_holiday_flag(d, cfg):
    mode = cfg.get("holiday_mode", "weekly_rest")
    if mode == "fixed_weekday":
        wd = cfg.get("legal_holiday_weekday")
        return wd is not None and d.weekday() == wd
    if mode == "calendar":
        return d.isoformat() in set(cfg.get("legal_holiday_dates") or [])
    return False


def _pay_compute_staff(days, cfg):
    """1職員の日次リストから残業集計。返り値は work/ot/night/holiday と日次付与。"""
    daily_legal = cfg.get("daily_legal_min", 480)
    weekly_legal = cfg.get("weekly_legal_min", 2400)
    week_start = cfg.get("week_start", 6)
    holiday_mode = cfg.get("holiday_mode", "weekly_rest")
    ns = _pay_hm(cfg.get("night_start", "22:00"))
    ne = _pay_hm(cfg.get("night_end", "05:00"))
    if ns is None:
        ns = 1320
    if ne is None:
        ne = 300

    out_days = []
    weeks = {}
    for idx, dd in enumerate(days):
        ds = dd.get("date")
        try:
            y, mo, dy = [int(x) for x in ds.split("-")]
            d = _pay_date(y, mo, dy)
        except Exception:
            out_days.append(dict(dd, ot_min=0, night_min=0, holiday_min=0, is_legal_holiday=False))
            continue
        mn = dd.get("minutes")
        worked = (mn is not None and mn > 0)
        night = _pay_night_minutes(dd.get("in"), dd.get("out"), ns, ne) if worked else 0
        is_lh = _pay_legal_holiday_flag(d, cfg) if worked else False
        rec = dict(dd, ot_min=0, night_min=night, holiday_min=0, is_legal_holiday=is_lh)
        out_days.append(rec)
        wk = _pay_week_key(d, week_start)
        w = weeks.setdefault(wk, {"worked_dates": set(), "indices": []})
        w["indices"].append(idx)
        if worked:
            w["worked_dates"].add(d)

    if holiday_mode == "weekly_rest":
        for wk, w in weeks.items():
            if len(w["worked_dates"]) >= 7:
                last_worked = max(w["worked_dates"])
                for idx in w["indices"]:
                    if out_days[idx].get("date") == last_worked.isoformat():
                        out_days[idx]["is_legal_holiday"] = True

    total_work = 0
    worked_days = 0
    ot_daily = 0
    night_total = 0
    holiday_total = 0
    week_normal = {}
    for rec in out_days:
        mn = rec.get("minutes")
        if mn is None or mn <= 0:
            continue
        total_work += mn
        worked_days += 1
        night_total += rec.get("night_min", 0)
        y, mo, dy = [int(x) for x in rec.get("date").split("-")]
        wk = _pay_week_key(_pay_date(y, mo, dy), week_start)
        if rec.get("is_legal_holiday"):
            rec["holiday_min"] = mn
            holiday_total += mn
            continue
        od = max(0, mn - daily_legal)
        rec["ot_min"] = od
        ot_daily += od
        week_normal[wk] = week_normal.get(wk, 0) + mn

    week_daily_ot = {}
    for rec in out_days:
        mn = rec.get("minutes")
        if mn is None or mn <= 0 or rec.get("is_legal_holiday"):
            continue
        y, mo, dy = [int(x) for x in rec.get("date").split("-")]
        wk = _pay_week_key(_pay_date(y, mo, dy), week_start)
        week_daily_ot[wk] = week_daily_ot.get(wk, 0) + rec.get("ot_min", 0)
    ot_weekly = 0
    for wk, wmin in week_normal.items():
        over = max(0, wmin - weekly_legal)
        add = max(0, over - week_daily_ot.get(wk, 0))
        ot_weekly += add

    return {
        "work_min": total_work, "worked_days": worked_days,
        "ot_daily_min": ot_daily, "ot_weekly_min": ot_weekly,
        "overtime_min": ot_daily + ot_weekly,
        "night_min": night_total, "holiday_min": holiday_total,
        "days": out_days,
    }


def _pay_leaves_map(supabase, f_code, start_d, end_d):
    """期間の休暇を (staff_name, 'YYYY-MM-DD') -> leave_type で返す。"""
    lstart = start_d.isoformat()
    lend = (end_d + _pay_td(days=1)).isoformat()
    m = {}
    try:
        lres = supabase.table("staff_leave_days").select("*").eq(
            "facility_code", f_code).gte("leave_date", lstart).lt(
            "leave_date", lend).execute()
        for r in (lres.data or []):
            m[(r.get("staff_name"), r.get("leave_date"))] = r.get("leave_type")
    except Exception as e:
        print(f"_pay_leaves_map error: {e}", flush=True)
    return m


def _pay_wd_label(dk):
    try:
        y, m, d = [int(x) for x in dk.split("-")]
        return ["\u6708", "\u706b", "\u6c34", "\u6728", "\u91d1", "\u571f", "\u65e5"][_pay_date(y, m, d).weekday()]
    except Exception:
        return ""


def _pay_facility_name(supabase, f_code):
    try:
        fr = supabase.table("facilities").select("name").eq("facility_code", f_code).execute()
        if fr.data:
            return fr.data[0].get("name", "") or ""
    except Exception:
        pass
    return ""


def _pay_resolve_params():
    """共通: year/month/scope/staff_name を解決。返り値 (year,month,scope,staff_name) or None。"""
    now = _tc_now_jst()
    try:
        year = int(request.args.get("year", now.year))
        month = int(request.args.get("month", now.month))
    except (TypeError, ValueError):
        year, month = now.year, now.month
    if not (1 <= month <= 12):
        return None
    scope = (request.args.get("scope", "all") or "all").strip()
    staff_name = (request.args.get("staff_name", "") or "").strip()
    return year, month, scope, staff_name


def _pay_filter_scope(staff_list, scope, staff_name):
    if scope == "staff" and staff_name:
        return [s for s in staff_list if s["name"] == staff_name]
    return staff_list


