# ===== soge-settings-v1 : 送迎設定（単位数・便の定義） =====
# 便は「迎え専用/送り専用」ではない。2単位運営の中間便は
# 「1単位目を送る + 2単位目を迎える」が同一車両で混在する。
# 単位は既存の patient_visit_days.ampm_per_day（AM=1単位目 / PM=2単位目）に対応。

# soge-trip-cars-v1: max_cars = その便で使う台数の上限（0 = 自動）。
#   ★本当の制約は「車の台数」ではなく「その時間に運転できる職員の数」で、
#     それは便ごとに違う（昼は職員が少ない、など）。施設全体の車両マスタだけでは表せない。
SOGE_DEFAULT_TRIPS = {
    1: [
        {"key": "t1", "name": "迎え便", "depart": "08:30", "pickup_units": [1], "dropoff_units": [], "max_cars": 0},
        {"key": "t2", "name": "送り便", "depart": "16:00", "pickup_units": [], "dropoff_units": [1], "max_cars": 0},
    ],
    2: [
        {"key": "t1", "name": "迎え便", "depart": "08:30", "pickup_units": [1], "dropoff_units": [], "max_cars": 0},
        {"key": "t2", "name": "中間便", "depart": "12:00", "pickup_units": [2], "dropoff_units": [1], "max_cars": 0},
        {"key": "t3", "name": "送り便", "depart": "16:00", "pickup_units": [], "dropoff_units": [2], "max_cars": 0},
    ],
}


def _soge_norm_trips(raw, unit_count):  # soge-settings-v1
    """便の定義を正規化。空なら単位数に応じた既定値。"""
    out = []
    for i, t in enumerate(raw or []):
        if not isinstance(t, dict):
            continue
        name = (t.get("name") or "").strip()
        if not name:
            continue
        depart = (t.get("depart") or "").strip()
        if depart and not (len(depart) == 5 and depart[2] == ":"):
            depart = ""
        def _units(v):
            out2 = []
            for u in (v or []):
                try:
                    u = int(u)
                except (TypeError, ValueError):
                    continue
                if u in (1, 2) and u <= unit_count and u not in out2:
                    out2.append(u)
            return out2
        # soge-trip-cars-v1: その便で使う台数の上限。空欄・0 は「自動」（従来どおり）。
        try:
            max_cars = int(t.get("max_cars") or 0)
        except (TypeError, ValueError):
            max_cars = 0
        if max_cars < 0:
            max_cars = 0
        if max_cars > 20:
            max_cars = 20      # ★0 に倒すと「自動」になり、絞ったつもりが効かない
        out.append({
            "key": (t.get("key") or "t%d" % (i + 1)),
            "name": name,
            "depart": depart,
            "pickup_units": _units(t.get("pickup_units")),
            "dropoff_units": _units(t.get("dropoff_units")),
            "max_cars": max_cars,
        })
    if not out:
        out = [dict(t) for t in SOGE_DEFAULT_TRIPS.get(unit_count, SOGE_DEFAULT_TRIPS[1])]

    # soge-allday-v1: 「終日（1日型）」＝区分3 が、どの便に乗るかを決める。
    #   ★設定画面で選ばせない。便の【形】から決まるため。
    #     迎えだけの便（送りが無い）で迎え、送りだけの便（迎えが無い）で送る。
    #     送りと迎えが混ざる便＝中間便には入れない。1日型は昼に帰らないので。
    #   ★迎えだけの便が2本ある施設に備えて、最初の1本と最後の1本にだけ付ける。
    #     全部に付けると、同じ人を2回迎えに行くことになる。
    #   ★毎回いったん外してから付け直す。古い設定が保存されていても必ず正しくなる。
    for t in out:
        t["pickup_units"] = [u for u in t["pickup_units"] if u != 3]
        t["dropoff_units"] = [u for u in t["dropoff_units"] if u != 3]
    if unit_count == 2:
        first_pick, last_drop = None, None
        for i, t in enumerate(out):
            has_p, has_d = bool(t["pickup_units"]), bool(t["dropoff_units"])
            if has_p and not has_d and first_pick is None:
                first_pick = i
            if has_d and not has_p:
                last_drop = i
        if first_pick is not None:
            out[first_pick]["pickup_units"].append(3)
        if last_drop is not None:
            out[last_drop]["dropoff_units"].append(3)
    return out


SOGE_TIME_DEFAULTS = {          # soge-time-v1
    "target_minutes": 30,       # これを超えたら車を増やす
    "max_minutes": 40,          # これを超えたら警告
    "stop_minutes": 2,          # 1人あたりの乗降時間
    "stop_minutes_wc": 5,       # 車いす1名あたりの乗降時間
}


def get_soge_settings(supabase, f_code):  # soge-settings-v1
    """送迎設定。未登録なら1単位の既定値を返す（DBには書かない）。"""
    try:
        r = supabase.table("soge_settings").select("*").eq("facility_code", f_code).execute()
        if r.data:
            s = r.data[0]
            uc = int(s.get("unit_count") or 1)
            uc = 2 if uc == 2 else 1
            out = {
                "unit_count": uc,
                "trips": _soge_norm_trips(s.get("trips"), uc),
                "mid_dropoff_first": bool(s.get("mid_dropoff_first", True)),
                "configured": True,
            }
            for k, dv in SOGE_TIME_DEFAULTS.items():   # soge-time-v1
                v = s.get(k)
                try:
                    out[k] = int(v) if v is not None else dv
                except (TypeError, ValueError):
                    out[k] = dv
            return out
    except Exception as e:
        print("soge settings get error: %s" % e, flush=True)
    out = {
        "unit_count": 1,
        "trips": [dict(t) for t in SOGE_DEFAULT_TRIPS[1]],
        "mid_dropoff_first": True,
        "configured": False,
    }
    out.update(SOGE_TIME_DEFAULTS)
    return out


@app.route("/api/soge/settings", methods=["GET"])  # soge-settings-v1
@login_required
def api_soge_settings_get():
    """送迎設定の参照。送迎表を組むのに全職員が使うので参照は制限しない。"""
    try:
        f_code = session["f_code"]
        supabase = get_supabase()
        s = get_soge_settings(supabase, f_code)
        s["status"] = "success"
        return jsonify(s)
    except Exception as e:
        print("soge settings error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/soge/settings", methods=["PUT"])  # soge-settings-v1
@login_required
def api_soge_settings_save():
    """送迎設定の更新（管理者のみ）。"""
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        if not is_admin_user(supabase, f_code, my_name):
            return jsonify({"status": "error", "message": "管理者権限がありません"}), 403

        data = request.json or {}
        try:
            uc = int(data.get("unit_count") or 1)
        except (TypeError, ValueError):
            return jsonify({"status": "error", "message": "単位数が不正です"}), 400
        if uc not in (1, 2):
            return jsonify({"status": "error", "message": "単位数は1か2です"}), 400

        trips = _soge_norm_trips(data.get("trips"), uc)
        if not trips:
            return jsonify({"status": "error", "message": "便が1つも設定されていません"}), 400

        payload = {
            "facility_code": f_code,
            "unit_count": uc,
            "trips": trips,
            "mid_dropoff_first": bool(data.get("mid_dropoff_first", True)),
            "updated_at": datetime.now(timezone.utc).isoformat(),
        }
        # soge-time-v1: 目標時間・上限時間・乗降時間
        for k, dv in SOGE_TIME_DEFAULTS.items():
            v = data.get(k)
            if v in (None, ""):
                payload[k] = dv
                continue
            try:
                v = int(v)
            except (TypeError, ValueError):
                return jsonify({"status": "error", "message": "時間の設定が不正です"}), 400
            if v < 0 or v > 240:
                return jsonify({"status": "error", "message": "時間の設定が不正です"}), 400
            payload[k] = v
        if payload["max_minutes"] < payload["target_minutes"]:
            return jsonify({"status": "error", "message": "上限時間は目標時間以上にしてください"}), 400
        existing = supabase.table("soge_settings").select("facility_code").eq("facility_code", f_code).execute()
        if existing.data:
            supabase.table("soge_settings").update(payload).eq("facility_code", f_code).execute()
        else:
            supabase.table("soge_settings").insert(payload).execute()

        return jsonify({"status": "success", "trips": trips})
    except Exception as e:
        print("soge settings save error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500

# ===== /soge-settings-v1 =====



# ===== visit-nth-v1 : 利用曜日の「第N週のみ」 =====
# 「第2火曜だけ利用」のような月N回の利用者に対応する。
# patient_visit_days.nth_per_day = {"2": 2} なら 火曜は第2週のみ。
# キーが無い曜日は「毎週」。既存データは {} なので挙動は変わらない。


def visit_week_of_month(date_str):  # visit-nth-v1
    """その日が「第何週」か。曜日基準（1日〜7日=第1週, 8〜14日=第2週 …）。
    介護現場の「第2火曜」はこの数え方。"""
    try:
        d = int(str(date_str)[8:10])
    except (TypeError, ValueError, IndexError):
        return 0
    if d < 1:
        return 0
    return (d - 1) // 7 + 1


def visit_nth_ok(nth_per_day, weekday, date_str):  # visit-nth-v1
    """その曜日の第N週指定に、その日付が該当するか。
    指定が無ければ常に True（毎週）。"""
    if not isinstance(nth_per_day, dict):
        return True
    v = nth_per_day.get(str(weekday))
    if v in (None, "", 0):
        return True
    try:
        v = int(v)
    except (TypeError, ValueError):
        return True
    if v < 1 or v > 5:
        return True
    return visit_week_of_month(date_str) == v


def _visit_norm_nth(raw):  # visit-nth-v1
    """nth_per_day を正規化。1..5 以外は捨てる（= 毎週）。"""
    out = {}
    if not isinstance(raw, dict):
        return out
    for k, v in raw.items():
        k = str(k)
        if k not in "0123456" or len(k) != 1:
            continue
        try:
            v = int(v)
        except (TypeError, ValueError):
            continue
        if 1 <= v <= 5:
            out[k] = v
    return out


@app.route('/api/save_weekday_nth', methods=['POST'])  # visit-nth-v1
@login_required
def api_save_weekday_nth():
    """単一曜日の第N週指定を保存。
    payload: {patient_id, weekday("0"-"6"), nth(0=毎週 / 1..5)}
    patient_id は patients.id（整数ID）。ampm_per_day と同じ持ち方。
    """
    try:
        data = request.json or {}
        f_code = session["f_code"]
        patient_id = str(data.get("patient_id") or "")
        weekday = str(data.get("weekday") or "")
        if not patient_id:
            return jsonify({"status": "error", "message": "patient_id が必要です"}), 400
        if weekday not in "0123456" or len(weekday) != 1:
            return jsonify({"status": "error", "message": "invalid weekday"}), 400
        try:
            nth = int(data.get("nth") or 0)
        except (TypeError, ValueError):
            return jsonify({"status": "error", "message": "invalid nth"}), 400
        if nth < 0 or nth > 5:
            return jsonify({"status": "error", "message": "第N週は1〜5です"}), 400

        supabase = get_supabase()
        existing = (supabase.table("patient_visit_days")
                    .select("id,nth_per_day")
                    .eq("facility_code", f_code).eq("patient_id", patient_id).execute())

        if existing.data:
            row = existing.data[0]
            cur = _visit_norm_nth(row.get("nth_per_day"))
            if nth == 0:
                cur.pop(weekday, None)   # 毎週に戻す
            else:
                cur[weekday] = nth
            supabase.table("patient_visit_days").update({"nth_per_day": cur}).eq("id", row["id"]).execute()
            return jsonify({"status": "success", "nth_per_day": cur})

        # 曜日設定がまだ無い利用者。行だけ作る（weekdays は曜日トグル側が入れる）
        user_name = (data.get("user_name") or "").strip()
        if not user_name:
            p_res = (supabase.table("patients").select("user_name")
                     .eq("facility_code", f_code).eq("id", patient_id).execute())
            if p_res.data:
                user_name = p_res.data[0].get("user_name", "")
        initial = {} if nth == 0 else {weekday: nth}
        supabase.table("patient_visit_days").insert({
            "facility_code": f_code,
            "patient_id": patient_id,
            "user_name": user_name,
            "weekdays": "",
            "ampm_per_day": {},
            "nth_per_day": initial,
        }).execute()
        return jsonify({"status": "success", "nth_per_day": initial})
    except Exception as e:
        print("save_weekday_nth error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500

# ===== /visit-nth-v1 =====



# ===== jihi-validfrom-v1 : 自費曜日ルールの有効期間 =====
# ルールに valid_from / valid_to を持たせ、「その来所日に有効だったルール」で判定する。
# これが無いと、今日ルールを変えたときに過去の月の実績まで遡って変わってしまう。
# 既存行は valid_from='1900-01-01' なので、導入しても過去の集計は変わらない。


def is_uuid_like(v):  # jisseki-uuid-guard-v1
    """UUID形式か。vitals.patient_id に整数IDが混ざっている行があり、
    uuid列への照会で Postgres がエラーを返して集計が丸ごと落ちるのを防ぐ。"""
    s = str(v or "")
    if len(s) != 36:
        return False
    if s[8] != "-" or s[13] != "-" or s[18] != "-" or s[23] != "-":
        return False
    hexs = s.replace("-", "")
    if len(hexs) != 32:
        return False
    return all(c in "0123456789abcdefABCDEF" for c in hexs)


def jihi_active_on(rules, weekday, date_str):  # jihi-validfrom-v1
    """その日付・その曜日が自費かどうか。rules は
    [{'weekday':int, 'valid_from':'YYYY-MM-DD', 'valid_to':'YYYY-MM-DD'|None}, ...]"""
    ds = str(date_str)[:10]
    for r in (rules or []):
        if int(r.get("weekday", -1)) != int(weekday):
            continue
        vf = (r.get("valid_from") or "1900-01-01")[:10]
        vt = r.get("valid_to")
        vt = (vt or "")[:10] or None
        if ds < vf:
            continue
        if vt and ds >= vt:   # valid_to はその日を含まない
            continue
        return True
    return False


def _jihi_rules_for(supabase, f_code, pid):  # jihi-validfrom-v1
    res = (supabase.table("patient_jihi_weekdays")
           .select("id, weekday, valid_from, valid_to")
           .eq("facility_code", f_code).eq("patient_id", pid).execute())
    return res.data or []


@app.route("/api/jisseki/patient_jihi_weekdays_v2", methods=["GET"])  # jihi-validfrom-v1
@login_required
def api_jisseki_jihi_wd_get_v2():
    """指定日時点の自費曜日を返す。as_of 省略時は今日。
    履歴も返すので、いつから自費になったかを画面で出せる。"""
    f_code = session.get("f_code")
    supabase = get_supabase()
    pid = (request.args.get("patient_id") or "").strip()
    if not pid:
        return jsonify({"status": "error", "message": "patient_id必須"}), 400
    try:
        as_of = (request.args.get("as_of") or "").strip() or datetime.now(tokyo_tz).strftime("%Y-%m-%d")
        rows = _jihi_rules_for(supabase, f_code, pid)
        rules = [{
            "weekday": int(r.get("weekday")),
            "valid_from": (r.get("valid_from") or "1900-01-01")[:10],
            "valid_to": ((r.get("valid_to") or "")[:10] or None),
        } for r in rows]
        weekdays = sorted([wd for wd in range(0, 7) if jihi_active_on(rules, wd, as_of)])
        return jsonify({"status": "success", "as_of": as_of,
                        "weekdays": weekdays, "history": rules})
    except Exception as e:
        print("api_jisseki_jihi_wd_get_v2 error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/jisseki/patient_jihi_weekdays_v2", methods=["POST"])  # jihi-validfrom-v1
@login_required
def api_jisseki_jihi_wd_save_v2():
    """自費曜日を保存する。過去を壊さない。

    body: {patient_id, weekdays: [1,5], apply_from: "YYYY-MM-DD" | "all"}

      apply_from = "YYYY-MM-DD"
          その日から新しいルールを適用する。
          それまで有効だったルールは valid_to = その日 で閉じる（過去はそのまま残る）。
      apply_from = "all"
          過去にさかのぼって全部書き換える（意図的な訂正）。既存行は削除。
    """
    f_code = session.get("f_code")
    supabase = get_supabase()
    try:
        data = request.json or {}
        pid = (data.get("patient_id") or "").strip()
        if not pid:
            return jsonify({"status": "error", "message": "patient_id必須"}), 400

        wds, seen = [], set()
        for w in (data.get("weekdays") or []):
            try:
                wi = int(w)
            except (TypeError, ValueError):
                continue
            if 0 <= wi <= 6 and wi not in seen:
                seen.add(wi)
                wds.append(wi)

        apply_from = (data.get("apply_from") or "").strip()
        retroactive = (apply_from == "all")
        if not retroactive:
            if not apply_from:
                apply_from = datetime.now(tokyo_tz).strftime("%Y-%m-%d")
            if len(apply_from) != 10 or apply_from[4] != "-" or apply_from[7] != "-":
                return jsonify({"status": "error", "message": "適用開始日が不正です"}), 400

        if retroactive:
            # 意図的な訂正: 過去も含めて全部このルールにする
            supabase.table("patient_jihi_weekdays").delete() \
                .eq("facility_code", f_code).eq("patient_id", pid).execute()
            rows = [{"facility_code": f_code, "patient_id": pid, "weekday": w,
                     "valid_from": "1900-01-01", "valid_to": None} for w in wds]
            if rows:
                supabase.table("patient_jihi_weekdays").insert(rows).execute()
            return jsonify({"status": "success", "mode": "all", "weekdays": wds})

        # 通常: apply_from から適用。過去のルールは閉じて残す。
        existing = _jihi_rules_for(supabase, f_code, pid)
        for r in existing:
            vf = (r.get("valid_from") or "1900-01-01")[:10]
            vt = ((r.get("valid_to") or "")[:10] or None)
            if vt and vt <= apply_from:
                continue                      # すでに閉じている過去の行はそのまま
            if vf >= apply_from:
                # 適用開始日以降に始まる行 = まだ実績に効いていない。作り直すので消す
                supabase.table("patient_jihi_weekdays").delete().eq("id", r["id"]).execute()
            else:
                # 適用開始日より前から有効な行 = その日で閉じる（過去は保持）
                supabase.table("patient_jihi_weekdays").update({"valid_to": apply_from}) \
                    .eq("id", r["id"]).execute()

        rows = [{"facility_code": f_code, "patient_id": pid, "weekday": w,
                 "valid_from": apply_from, "valid_to": None} for w in wds]
        if rows:
            supabase.table("patient_jihi_weekdays").insert(rows).execute()

        return jsonify({"status": "success", "mode": "from", "apply_from": apply_from, "weekdays": wds})
    except Exception as e:
        print("api_jisseki_jihi_wd_save_v2 error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500

