# ===== soge-week-v1 : 週次の送迎表（曜日別テンプレート） =====

# ===== soge-unassigned-v1 : 「車が決まっていない人」と「送迎なし」の枠 =====
#  ★以前は、席に乗り切らなかった人（overflow）を warnings に1行出すだけで、
#    配車表のどこにも表示していなかった。保存すると警告ごと消えるため、
#    その人は二度と画面に出てこなかった。実在の利用者が黙って消える状態だった。
#  → 車と同じ形の「枠」に入れて必ず見せる。vehicle_no を負の値・0 で区別するので、
#    新しいテーブルも列も要らない（soge_routes にそのまま入る）。
SOGE_VNO_UNASSIGNED = 0     # まだ車が決まっていない人（赤い箱・運行画面にも出す）
SOGE_VNO_NORIDE = -1        # 送迎なし（家族送迎など。たたんでおく・運行画面には出さない）

SOGE_DEFAULT_SEATS = 7          # soge_seats 未登録の車で使う既定値
SOGE_DEFAULT_WC_SEATS = 2       # 車いす1台が使う席数の既定値


def _soge_vehicle_spec(v):  # soge-week-v1
    """車1台の席数仕様。定員(capacity)ではなく送迎の席数を使う。"""
    seats = v.get("soge_seats")
    if not seats:
        cap = v.get("capacity")
        # 定員しか無い場合は運転手の1席を引く
        seats = (int(cap) - 1) if cap else SOGE_DEFAULT_SEATS
    wc_seats = v.get("wheelchair_seats")
    wc_seats = int(wc_seats) if wc_seats else SOGE_DEFAULT_WC_SEATS
    wc_max = v.get("wheelchair_max")
    wc_max = int(wc_max) if wc_max is not None else 0
    return {"seats": max(1, int(seats)), "wc_seats": max(1, wc_seats), "wc_max": max(0, wc_max)}


def _soge_seats_needed(people, spec):  # soge-week-v1
    """その人たちを「同時に」乗せるのに要る席数。"""
    n_wc = sum(1 for m in people if m.get("is_wheelchair"))
    n_walk = len(people) - n_wc
    return n_walk + n_wc * spec["wc_seats"], n_wc


def _soge_peak_seats(people, spec, trip):  # soge-peak-seats-v1
    """1台の便で必要な席数（同時乗車のピーク）。

    中間便は「1単位目を送りながら2単位目を迎える」ので、
    送りで降ろすと席が空き、その席に迎えの人を乗せられる。
    延べ人数ではなく、同時に乗っている人数のピークで判定する。

    送りを先に全部済ませてから迎えに回るため:
        ピーク = max(送る人たち, 迎える人たち)
    （出発時は送りの人だけが乗車。全員降ろしてから迎え始める。）

    戻り値: (必要席数, 車いすの同時最大数)
    """
    if not trip:
        return _soge_seats_needed(people, spec)

    pu = set(trip.get("pickup_units") or [])
    du = set(trip.get("dropoff_units") or [])

    drop_people = [m for m in people if m.get("unit") in du]
    pick_people = [m for m in people if m.get("unit") in pu]

    # 便の単位に当てはまらない人が混ざっていたら、黙って0席と数えない。
    # （そういう人がいる時点で呼び出し側の間違いなので、安全側に全員分で数える）
    if people and not drop_people and not pick_people:
        return _soge_seats_needed(people, spec)

    d_seats, d_wc = _soge_seats_needed(drop_people, spec)
    p_seats, p_wc = _soge_seats_needed(pick_people, spec)
    return max(d_seats, p_seats), max(d_wc, p_wc)


def _soge_fits(people, spec, trip=None):  # soge-peak-seats-v1
    need, n_wc = _soge_peak_seats(people, spec, trip)
    return need <= spec["seats"] and n_wc <= spec["wc_max"]


def _soge_targets(supabase, f_code, weekday, unit_count=1):  # soge-week-v1
    """その曜日に来る利用者。
    [{patient_id, user_name, unit(1|2|3), nth(0=毎週/1..5), is_wheelchair}]

    unit … 1=午前のみ / 2=午後のみ / 3=終日（1日型）   # soge-allday-v1
      ★以前は ALL（終日）を 1（午前のみ）に潰していた。
        そのため2単位運営では、1日型の方が
          迎え便で迎える → 中間便で【昼に送られる】 → 夕方の送り便に入らない
        という扱いになっていた。1日型は昼に帰らないので、これは誤り。
      ★1単位運営では全員が同じ枠なので、これまでどおり 1 のままにする。
        3 にすると便の定義（1単位目）に当たらなくなり、誰も出なくなる。
    """
    plist = get_patients(supabase, f_code)
    by_int = {}
    for p in plist:
        if p.get("patient_int_id"):
            by_int[str(p["patient_int_id"])] = p

    # 車いすフラグ（get_patients は返さないので直接引く）
    wc = {}
    try:
        wr = (supabase.table("patient_profiles").select("id,is_wheelchair")
              .eq("facility_code", f_code).execute())
        for r in (wr.data or []):
            wc[str(r["id"])] = bool(r.get("is_wheelchair"))
    except Exception as e:
        print("soge wheelchair fetch error: %s" % e, flush=True)

    try:
        r = (supabase.table("patient_visit_days")
             .select("patient_id,weekdays,ampm_per_day,nth_per_day")
             .eq("facility_code", f_code).execute())
        rows = r.data or []
    except Exception as e:
        print("soge targets error: %s" % e, flush=True)
        return []

    wd = str(weekday)
    out = []
    for row in rows:
        p = by_int.get(str(row.get("patient_id")))
        if not p or not patient_active_on(p):   # patient-active-v1: 利用終了した人は出さない
            continue
        apd = row.get("ampm_per_day")
        apd = apd if isinstance(apd, dict) else {}
        state = apd.get(wd)
        # soge-allday-v1: "pm" のような小文字も正しく読む。
        #   記録側（_t = ....upper()）は前から大文字にそろえていたが、送迎だけ素通しだった。
        if isinstance(state, str):
            state = state.strip().upper()
        if not state:
            if wd not in (row.get("weekdays") or ""):
                continue
            state = "ALL"
        if state == "NONE":
            continue

        # soge-allday-v1: 区分は 午前のみ / 午後のみ / 終日 の3つ
        if state == "ALL" and unit_count == 2:
            _unit = 3
        elif state == "PM":
            _unit = 2
        else:
            _unit = 1

        pid = str(p["id"])
        out.append({
            "patient_id": pid,
            "user_name": p.get("user_name") or "",
            "user_kana": p.get("user_kana") or "",
            "unit": _unit,
            "nth": int(_visit_norm_nth(row.get("nth_per_day")).get(wd) or 0),
            "is_wheelchair": wc.get(pid, False),
        })
    return out


def _soge_bearing_order(members, geo):  # soge-week-v1
    """方位角で並べ、円環のいちばん空いているところを切れ目にする。
    座標が無い人は末尾。"""
    known = [m for m in members if str(m["patient_id"]) in geo]
    unknown = [m for m in members if str(m["patient_id"]) not in geo]
    if not known:
        return [], unknown

    known.sort(key=lambda m: geo[str(m["patient_id"])]["bearing"])
    n = len(known)
    if n == 1:
        return known, unknown

    gaps = []
    for i in range(n):
        a = geo[str(known[i]["patient_id"])]["bearing"]
        b = geo[str(known[(i + 1) % n]["patient_id"])]["bearing"]
        gaps.append(((b - a) % 360.0, i))
    _, cut = max(gaps)
    return known[cut + 1:] + known[:cut + 1], unknown


def _soge_assign(members, geo, vehicles, trip=None):  # soge-peak-seats-v1
    """方面順に並べた人を、席数を守りながら車へ順に詰める。

    方位角順に並べてから前から詰めるので、同じ方面の人が自然と同じ車になる。
    席が余っていれば1台で回す（無駄に車を増やさない）。
    車いすは wheelchair_max を超えられないので、その場合だけ次の車へ送る。

    戻り値: (groups, overflow)  overflow = どの車にも乗らなかった人
    """
    specs = [_soge_vehicle_spec(v) for v in vehicles]
    if not specs:
        specs = [{"seats": SOGE_DEFAULT_SEATS, "wc_seats": SOGE_DEFAULT_WC_SEATS, "wc_max": 1}]

    ordered, unknown = _soge_bearing_order(members, geo)
    queue = ordered + unknown

    groups = [[] for _ in specs]
    overflow = []

    cur = 0
    for m in queue:
        placed = False
        # 今の車から後ろの車へ順に試す（前の車には戻らない＝方面の連続性を保つ）
        for idx in range(cur, len(specs)):
            if _soge_fits(groups[idx] + [m], specs[idx], trip):
                groups[idx].append(m)
                cur = idx
                placed = True
                break
        if placed:
            continue
        # 車いすが上限で今の車に乗れないだけ、というケースを救う
        for idx in range(0, cur):
            if _soge_fits(groups[idx] + [m], specs[idx], trip):
                groups[idx].append(m)
                placed = True
                break
        if not placed:
            overflow.append(m)
    return groups, overflow


def _soge_assign_balanced(members, geo, vehicles, trip):  # soge-balance-v1
    """指定された台数に、席数の比で均等に配分する。

    貪欲に詰めると先頭の車が満席になり、台数を増やしても時間が減らない。
    そこで「その車の席数 ÷ 全体の席数」の比率で人数の枠(quota)を決め、
    方位角の並び順を保ったまま、前から順にその枠だけ入れていく。

    例) キャラバン8席 / タント3席 / セレナ7席 = 18席 に 11名
        → 5名 / 2名 / 4名

    戻り値: (groups, overflow)
    """
    specs = [_soge_vehicle_spec(v) for v in vehicles]
    if not specs:
        specs = [{"seats": SOGE_DEFAULT_SEATS, "wc_seats": SOGE_DEFAULT_WC_SEATS, "wc_max": 1}]

    ordered, unknown = _soge_bearing_order(members, geo)
    queue = ordered + unknown
    n = len(queue)
    if not n:
        return [[] for _ in specs], []

    # 席数の比で枠を決める。端数は「小数点以下が大きい車」から配る（最大剰余方式）。
    #   例) 8席/3席/7席 = 18席 に 11名
    #       4.89 / 1.83 / 4.28 -> 整数部 4/1/4 (計9)、残り2名を .89 と .83 の車へ -> 5/2/4
    total_seats = sum(s["seats"] for s in specs) or 1
    exact = [n * s["seats"] / float(total_seats) for s in specs]
    quotas = [int(x) for x in exact]
    rest = n - sum(quotas)
    by_frac = sorted(range(len(specs)), key=lambda i: -(exact[i] - quotas[i]))
    for i in range(rest):
        quotas[by_frac[i % len(specs)]] += 1

    groups = [[] for _ in specs]
    overflow = []

    ci = 0
    for m in queue:
        placed = False
        # 枠が空いていて、席にも収まる車を、今の車から順に探す
        for step in range(len(specs)):
            idx = (ci + step) % len(specs)
            if len(groups[idx]) >= quotas[idx]:
                continue
            if _soge_fits(groups[idx] + [m], specs[idx], trip):
                groups[idx].append(m)
                ci = idx
                placed = True
                break
        if placed:
            continue
        # 枠を無視してでも、乗れる車があるなら乗せる（あふれさせない）
        for idx in range(len(specs)):
            if _soge_fits(groups[idx] + [m], specs[idx], trip):
                groups[idx].append(m)
                placed = True
                break
        if not placed:
            overflow.append(m)

    return groups, overflow


def _soge_km(a, b):  # soge-routeopt-v1
    """2点間の直線距離(km)。a, b = (lat, lng)"""
    return _soge_dist_bearing(a[0], a[1], b[0], b[1])[0]


def _soge_tsp_path(pts, start, end):  # soge-routeopt-v1
    """start から出て pts を全部回り end に着く、短い順番を返す。

    立ち寄り先はせいぜい10件前後なので、最近傍法 + 2-opt で十分。
      最近傍法 … 今いる場所から一番近い人へ、を繰り返してたたき台を作る
      2-opt   … 途中の区間をひっくり返して短くなるなら採用（交差をほどく）

    pts: [(lat, lng, payload), ...]
    戻り値: payload を並べ替えたリスト
    """
    n = len(pts)
    if n <= 1:
        return [p[2] for p in pts]

    xy = [(p[0], p[1]) for p in pts]

    remaining = list(range(n))
    seq = []
    cur = start
    while remaining:
        i = min(remaining, key=lambda k: _soge_km(cur, xy[k]))
        seq.append(i)
        remaining.remove(i)
        cur = xy[i]

    def cost(order):
        c = 0.0
        prev = start
        for k in order:
            c += _soge_km(prev, xy[k])
            prev = xy[k]
        return c + _soge_km(prev, end)

    best = cost(seq)
    for _ in range(60):                      # 念のため回数を切る（無限ループ防止）
        improved = False
        for i in range(n - 1):
            for j in range(i + 1, n):
                cand = seq[:i] + seq[i:j + 1][::-1] + seq[j + 1:]
                c = cost(cand)
                if c < best - 1e-9:
                    seq, best, improved = cand, c, True
        if not improved:
            break

    return [pts[k][2] for k in seq]


def _soge_order_stops(stops, geo, dropoff_first, fac=None):  # soge-routeopt-v1
    """1台分の立ち寄り順。

    座標がそろっていれば、実際に短く回れる順番を計算する（最近傍 + 2-opt）。
    座標が無い人が混ざっている便では、今まで通りの距離順にする。

      迎え(pickup)  … 遠くから拾って施設に近づく
      送り(dropoff) … 近い人から降ろして遠くへ
    送り→迎えの順序（1単位目を降ろしてから2単位目を迎えに行く）は必ず守る。
    """
    def dist(s):
        g = geo.get(str(s["patient_id"]))
        return g["dist_km"] if g else 0.0

    def xy(s):
        g = geo.get(str(s["patient_id"])) or {}
        if g.get("lat") is None or g.get("lng") is None:
            return None
        return (float(g["lat"]), float(g["lng"]), s)

    pick = [s for s in stops if s["type"] == "pickup"]
    drop = [s for s in stops if s["type"] == "dropoff"]

    pick_xy = [xy(s) for s in pick]
    drop_xy = [xy(s) for s in drop]
    ok = fac and all(p is not None for p in pick_xy) and all(d is not None for d in drop_xy)

    if not ok:
        # 従来どおり（施設からの距離順）。座標が無い人がいるときの逃げ道。
        pick.sort(key=dist, reverse=True)
        drop.sort(key=dist)
        return drop + pick

    fac = (float(fac[0]), float(fac[1]))

    if drop and pick:
        # 送りで外へ出て、そのまま迎えに回って施設へ戻る。
        # 送りの終点は「一番遠い迎え先」に寄せておくと、乗り継ぎが自然になる。
        far = max(pick_xy, key=lambda p: _soge_km(fac, (p[0], p[1])))
        drop_sorted = _soge_tsp_path(drop_xy, fac, (far[0], far[1]))
        last_s = drop_sorted[-1]
        lg = geo[str(last_s["patient_id"])]
        pick_sorted = _soge_tsp_path(pick_xy, (float(lg["lat"]), float(lg["lng"])), fac)
        return drop_sorted + pick_sorted

    if drop:
        return _soge_tsp_path(drop_xy, fac, fac)
    return _soge_tsp_path(pick_xy, fac, fac)


def _soge_special_car(vno, pairs, geo):  # soge-unassigned-v1
    """「まだ車が決まっていない人」「送迎なし」の枠を、車と同じ形で作る。

    ★車と同じ形にしておくと、配車画面のドラッグ・保存・並べ替えの仕組みを
      そのまま使える。この枠のためだけに別の操作を作らずに済む。

    pairs = [(利用者, "pickup"|"dropoff"), ...]

    ★席数は持たせない（seats=None）。まだ乗る車が決まっていないので、
      「席が足りない」と出しても意味が無いため。
    """
    stops = []
    for m, stype in (pairs or []):
        pid = str(m.get("patient_id"))
        is_guest = bool(m.get("guest"))
        stops.append({
            "patient_id": pid,
            "user_name": m.get("user_name") or "",
            "guest": is_guest,
            "type": stype,
            "nth": int(m.get("nth") or 0),
            "is_wheelchair": bool(m.get("is_wheelchair")),
            "dist_km": round((geo.get(pid) or {}).get("dist_km", 0.0), 2),
            # 登録の無い方は住所が無いので、座標が無いのは当たり前。警告に混ぜない
            "no_geo": (pid not in geo) and not is_guest,
            "planned_at": None,
        })
    return {
        "vehicle_no": vno,
        "unassigned": (vno == SOGE_VNO_UNASSIGNED),
        "noride": (vno == SOGE_VNO_NORIDE),
        "vehicle_id": None, "vehicle_name": "", "plate_no": "",
        "seats": None, "seats_used": 0,
        "wheelchair_count": 0, "wheelchair_max": None,
        "driver_name": "",
        "minutes": None, "drive_minutes": None, "stop_minutes": None,
        "distance_km": None, "over_target": False,
        "stops": stops,
    }


def _soge_want_pairs(members, trip):  # soge-unassigned-v1
    """その便で、その人に必要な立ち寄り（送り／迎え）を並べる。
    ★_soge_stops_of と同じ規則（送りが先）にそろえること。
      規則を2か所に分けて書くと、片方だけ直したときに必ず食い違う。"""
    pu = set(trip.get("pickup_units") or [])
    du = set(trip.get("dropoff_units") or [])
    out = []
    for m in (members or []):
        if m.get("unit") in du:
            out.append((m, "dropoff"))
        if m.get("unit") in pu:
            out.append((m, "pickup"))
    return out


def soge_build_week(supabase, f_code, weekday, settings=None):  # soge-week-v1
    """その曜日の送迎表を自動生成する（保存はしない）。"""
    settings = settings or get_soge_settings(supabase, f_code)
    geo = soge_geo_map(supabase, f_code)
    targets = _soge_targets(supabase, f_code, weekday, settings["unit_count"])

    # soge-routeopt-v1: 立ち寄り順の最適化に施設の座標が要る（取れなければ従来の距離順）
    _flat, _flng, _ferr = _soge_facility_latlng(supabase, f_code)
    settings["_fac"] = (_flat, _flng) if _flat is not None else None

    try:
        vr = (supabase.table("rec_cars")
              .select("id,name,plate_no,capacity,soge_seats,wheelchair_seats,wheelchair_max")
              .eq("facility_code", f_code).eq("is_active", True)
              .order("sort_order").execute())
        vehicles = vr.data or []
    except Exception:
        vehicles = []

    by_id = dict((str(t["patient_id"]), t) for t in targets)
    trips_out = []
    warnings = []

    for trip in settings["trips"]:
        pu = set(trip.get("pickup_units") or [])
        du = set(trip.get("dropoff_units") or [])

        people = [t for t in targets if t["unit"] in pu or t["unit"] in du]
        if not people:
            trips_out.append({"trip_key": trip["key"], "trip_name": trip["name"],
                              "depart": trip.get("depart") or "", "vehicles": []})
            continue

        # soge-time-v1: 席数だけでなく「事業所に戻るまでの時間」で台数を決める
        groups, overflow, times = _soge_split_by_time(
            supabase, f_code, geo, people, vehicles, trip, settings)

        # soge-unassigned-v1: あふれた人を【黙って消さない】。
        #   以前はこの警告文に名前を最大5名まで出すだけで、配車表には出さなかった。
        #   保存すると警告ごと消えるので、その人は二度と画面に出てこなかった。
        if overflow:
            warnings.append("%s: %d名がどの車にも乗れませんでした。"
                            "「まだ車が決まっていない人」から車へ移してください。"
                            % (trip["name"], len(overflow)))

        cars_out = []
        for i, grp in enumerate(groups):
            if not grp:
                continue
            v = vehicles[i] if i < len(vehicles) else {}
            spec = _soge_vehicle_spec(v) if v else {"seats": SOGE_DEFAULT_SEATS,
                                                    "wc_seats": SOGE_DEFAULT_WC_SEATS, "wc_max": 1}
            gstops = _soge_stops_of(grp, trip, geo, settings)
            used, n_wc = _soge_peak_seats(grp, spec, trip)
            tm = times[i] if i < len(times) else {"drive": 0, "stop": 0, "total": 0,
                                                  "km": 0.0, "legs": None}
            planned = _soge_planned_times(trip.get("depart") or "", gstops, tm["drive"],
                                          settings, tm.get("legs"))   # soge-legtime-v1

            _tgt, _max = _soge_trip_target(trip, settings)   # soge-trip-target-v1
            if tm["total"] > _max:
                warnings.append("%s の %s は %d分かかる見込みです（上限 %d分）。分担を見直してください。"
                                % (trip["name"], (v.get("name") if v else "車%d" % (i + 1)),
                                   tm["total"], _max))

            cars_out.append({
                "vehicle_no": i + 1,
                "vehicle_id": (str(v["id"]) if v else None),
                "vehicle_name": (v.get("name") if v else ""),
                "plate_no": (v.get("plate_no") if v else ""),
                "seats": spec["seats"],
                "seats_used": used,
                "wheelchair_count": n_wc,
                "wheelchair_max": spec["wc_max"],
                "driver_name": "",
                "minutes": tm["total"],          # soge-time-v1
                "drive_minutes": tm["drive"],
                "stop_minutes": tm["stop"],
                "distance_km": tm["km"],
                "over_target": tm["total"] > _tgt,   # soge-trip-target-v1
                "stops": [{
                    "patient_id": s["patient_id"], "user_name": s["user_name"],
                    "type": s["type"], "nth": s.get("nth") or 0,
                    "is_wheelchair": bool(s.get("is_wheelchair")),
                    "planned_at": (planned[j] if j < len(planned) else None),
                    "dist_km": round((geo.get(str(s["patient_id"])) or {}).get("dist_km", 0.0), 2),
                    "no_geo": str(s["patient_id"]) not in geo,
                } for j, s in enumerate(gstops)],
            })

        # soge-unassigned-v1: あふれた人の枠を先頭に置く。いちばん最初に目に入る場所。
        if overflow:
            cars_out.insert(0, _soge_special_car(
                SOGE_VNO_UNASSIGNED, _soge_want_pairs(overflow, trip), geo))

        trips_out.append({
            "trip_key": trip["key"], "trip_name": trip["name"],
            "depart": trip.get("depart") or "",
            "vehicles": cars_out,
        })

    no_geo = [t["user_name"] for t in targets if str(t["patient_id"]) not in geo]
    if no_geo:
        warnings.append("座標が無い利用者が %d名います（住所の登録・変換を確認してください）。" % len(no_geo))

    return {
        "weekday": weekday,
        "unit_count": settings["unit_count"],
        "trips": trips_out,
        "target_count": len(targets),
        "wheelchair_count": sum(1 for t in targets if t["is_wheelchair"]),
        "warnings": warnings,
    }


def _soge_saved_week(supabase, f_code, weekday, settings):  # soge-week-v1
    """保存済み（soge_routes）を画面用に組み立てる。無ければ None。"""
    try:
        r = (supabase.table("soge_routes").select("*")
             .eq("facility_code", f_code).eq("weekday", weekday).execute())
        rows = r.data or []
    except Exception as e:
        print("soge saved week error: %s" % e, flush=True)
        return None
    if not rows:
        return None
    return _soge_rows_view(supabase, f_code, weekday, settings, rows)


def _soge_rows_view(supabase, f_code, weekday, settings, rows):  # soge-date-plan-v1
    """保存済みの行を、画面用の形に組み立てる。

    ★曜日の配車（soge_routes）と、その日だけの配車（soge_date_routes）で
      【まったく同じ組み立て】を使うために切り出した。中身は変えていない。
      2つ書くと、片方だけ直したときに食い違う。
    ★weekday は「その日に来る予定の人」を調べるのに要る。
      日付の配車のときは、その日付の曜日を渡す。
    """
    geo = soge_geo_map(supabase, f_code)
    plist = get_patients(supabase, f_code)
    pmap = dict((str(p["id"]), p) for p in plist)
    # soge-unassigned-v1: 保存済みの表に入っていない対象者を拾うために要る
    targets = _soge_targets(supabase, f_code, weekday, settings["unit_count"])

    wc = {}
    try:
        wr = (supabase.table("patient_profiles").select("id,is_wheelchair")
              .eq("facility_code", f_code).execute())
        for x in (wr.data or []):
            wc[str(x["id"])] = bool(x.get("is_wheelchair"))
    except Exception as _we:
        # visit-guard-failclosed-v1: 取れないと【全員「車椅子でない」扱い】になり、
        #   車椅子の方の座席が確保されない送迎表ができる。
        #   表は人が見て確定するので止めはしないが、黙って進めてはいけない。
        print("[soge] 車椅子情報を取得できませんでした（全員なし扱いになります）: %s"
              % _we, flush=True)

    try:
        vr = (supabase.table("rec_cars")
              .select("id,name,plate_no,capacity,soge_seats,wheelchair_seats,wheelchair_max")
              .eq("facility_code", f_code).execute())
        vmap = dict((str(v["id"]), v) for v in (vr.data or []))
    except Exception:
        vmap = {}

    by_trip = {}
    for row in rows:
        by_trip.setdefault(row.get("trip_key"), []).append(row)

    trips_out = []
    for trip in settings["trips"]:
        # soge-unassigned-v1: 未割当(0)を先頭、ふつうの車、送迎なし(-1)を最後にする。
        #   ★"or 1" で並べると 0 が 1 になって車に紛れるので、None だけを 1 に倒す。
        def _vsort(x):
            k = x.get("vehicle_no")
            try:
                k = int(k) if k is not None else 1
            except (TypeError, ValueError):
                k = 1      # 読めない値で配車画面ごと落とさない
            return (2 if k == SOGE_VNO_NORIDE else (0 if k == SOGE_VNO_UNASSIGNED else 1), k)

        cars = sorted(by_trip.get(trip["key"], []), key=_vsort)
        cars_out = []
        for c in cars:
            _vno = c.get("vehicle_no")
            try:
                _vno = int(_vno) if _vno is not None else 1
            except (TypeError, ValueError):
                _vno = 1
            v = vmap.get(str(c.get("vehicle_id"))) or {}
            spec = _soge_vehicle_spec(v) if v else {"seats": SOGE_DEFAULT_SEATS,
                                                    "wc_seats": SOGE_DEFAULT_WC_SEATS, "wc_max": 1}
            stops, seen = [], []
            for s in (c.get("stop_order") or []):
                pid = str(s.get("patient_id") or "")
                prof = pmap.get(pid) or {}
                is_guest = bool(s.get("guest"))
                # patient-active-v1: 利用を中止した方は配車表からも外す。
                #   ★保存済みの週次表は「その時の顔ぶれ」がそのまま残るので、
                #     ここで外さないと、中止した方が配車画面に出続ける。
                #   ★登録の無い方(guest)はマスタに居なくて当たり前なので触らない。
                if prof and not is_guest and not patient_active_on(prof):
                    continue
                stops.append({
                    "patient_id": pid,
                    # soge-guest-v1: マスタに居なければ、保存しておいた名前を使う
                    "user_name": prof.get("user_name") or (s.get("name") or ""),
                    "guest": is_guest,
                    "type": s.get("type") or "pickup",
                    "nth": int(s.get("nth") or 0),
                    "is_wheelchair": wc.get(pid, False),
                    "dist_km": round((geo.get(pid) or {}).get("dist_km", 0.0), 2),
                    # 登録の無い方は住所が無いので、座標が無いのは当たり前。警告に混ぜない。
                    "no_geo": (pid not in geo) and not is_guest,
                })
                if pid not in seen:
                    seen.append(pid)
            # soge-peak-seats-v1: 表示も同時乗車のピークで数える
            unit_of = {}
            for s in (c.get("stop_order") or []):
                pid2 = str(s.get("patient_id") or "")
                if s.get("type") == "dropoff":
                    unit_of.setdefault(pid2, set()).add("d")
                else:
                    unit_of.setdefault(pid2, set()).add("p")
            drop_p = [{"is_wheelchair": wc.get(pid, False)} for pid in seen if "d" in unit_of.get(pid, set())]
            pick_p = [{"is_wheelchair": wc.get(pid, False)} for pid in seen if "p" in unit_of.get(pid, set())]
            d_used, d_wc = _soge_seats_needed(drop_p, spec)
            p_used, p_wc = _soge_seats_needed(pick_p, spec)
            used, n_wc = max(d_used, p_used), max(d_wc, p_wc)

            cars_out.append({
                "vehicle_no": _vno,
                # soge-unassigned-v1: 席数は持たせない。乗る車が決まっていないので
                #   「席が足りない」と出しても意味が無い
                # ★-1 以外の非正は「未割当」に倒す（画面側の振り分けと同じ規則）
                "unassigned": (_vno <= SOGE_VNO_UNASSIGNED and _vno != SOGE_VNO_NORIDE),
                "noride": (_vno == SOGE_VNO_NORIDE),
                "vehicle_id": (str(c["vehicle_id"]) if c.get("vehicle_id") else None),
                "vehicle_name": v.get("name") or "",
                "plate_no": v.get("plate_no") or "",
                "seats": (None if _vno <= 0 else spec["seats"]),
                "seats_used": (0 if _vno <= 0 else used),
                "wheelchair_count": (0 if _vno <= 0 else n_wc),
                "wheelchair_max": (None if _vno <= 0 else spec["wc_max"]),
                "driver_name": c.get("driver_name") or "",
                "stops": stops,
            })
        # soge-unassigned-v1: 保存済みの表は「保存した時の顔ぶれ」がそのまま残る。
        #   そのあとに利用が始まった方はどの車にも入っておらず、
        #   これまでは【配車表に一度も出てこなかった】。必ず未割当に出す。
        #   ★「送迎なし」に入れた方は、意図して外しているので補わない。
        seen = set()
        for c2 in cars_out:
            for s2 in (c2.get("stops") or []):
                seen.add((s2["patient_id"], s2["type"]))
        missing = [(m, st) for (m, st) in _soge_want_pairs(targets, trip)
                   if (str(m["patient_id"]), st) not in seen]
        if missing:
            box = None
            for c2 in cars_out:
                if c2.get("unassigned"):
                    box = c2
                    break
            add = _soge_special_car(SOGE_VNO_UNASSIGNED, missing, geo)
            if box:
                box["stops"].extend(add["stops"])
            else:
                cars_out.insert(0, add)

        trips_out.append({
            "trip_key": trip["key"], "trip_name": trip["name"],
            "depart": trip.get("depart") or "",
            "vehicles": cars_out,
        })

    # soge-unassigned-v1: 未割当が残っていることは、画面の上にも文字で出す。
    #   箱を見落としたまま当日を迎えるのを防ぐ。
    warns = []
    for t in trips_out:
        cnt = 0
        for c in t["vehicles"]:
            if c.get("unassigned"):
                cnt += len(c.get("stops") or [])
        if cnt:
            warns.append("%s: %d件、まだ乗る車が決まっていません。" % (t["trip_name"], cnt))

    return {"weekday": weekday, "unit_count": settings["unit_count"],
            "trips": trips_out, "saved": True, "warnings": warns}


def _soge_weekday_arg(v, default=1):  # soge-weekday-zero-v1
    """画面から来た曜日を数字にする。0=日曜。

    ★★`int(v or 1)` と書かないこと。
      JSONで数字の 0（日曜）が来ると 0 は【偽】なので 1（月曜）に化ける。
      実際にそうなっていた：配車画面で日曜を選んで「自動で組み直す」を押すと、
      月曜の顔ぶれで組まれ、日曜には無いはずの中間便にも人が入っていた。
      そのまま保存すれば、日曜の配車表が月曜の内容で上書きされる。
      （URLの引数は文字列の "0" なので偽にならず、そちらは無事だった。
        JSONで来る経路だけが踏む。同じ形の穴が他にも無いか、必ず grep すること）
    """
    if v is None or v == "":
        return default
    try:
        w = int(v)
    except (TypeError, ValueError):
        return default
    return w if 0 <= w <= 6 else default


# ==========================================================
# soge-keep-build-v1 : 「いつもの並びで組み直す」
#
#   ★なぜ必要か（現場の依頼）
#     `soge_routes` は DDL のコメントどおり「学習の実体」で、
#     職員が手で直した割り振りと周り順が、そのまま次週の初期値になる。
#     ところが「自動で組み直す」（soge_build_week）は soge_routes を一切見ず、
#     利用者・座標・席数から【ゼロから】組み直す。
#     つまり押した瞬間に、覚えさせた癖が全部消える。
#     そのため現場は「組み直したいのに押せない」という板挟みになっていた。
#
#   ★やること
#     保存済みの並びを土台にして、【変わったところだけ】直す。
#       ① その曜日に来なくなった人を抜く
#       ② 新しく来るようになった人を、いちばん近い人が乗っている車へ入れる
#       ③ 席・車いす枠に入らない人は「まだ車が決まっていない人」に残す
#
#   ★入れられるか迷ったら、入れずに赤い箱へ残すこと。
#     間違った車に入れるより、人が判断できる状態で見せるほうがよい。
# ==========================================================
def _soge_stops_used(stops, spec):  # soge-keep-build-v1
    """その車の立ち寄りから、同時乗車のピーク席数と車いす人数を出す。
    ★_soge_saved_week の数え方にそろえること。送りと迎えを別々に数えて多いほうを取る。"""
    d, p = {}, {}
    for s in (stops or []):
        pid = str(s.get("patient_id"))
        (d if (s.get("type") == "dropoff") else p)[pid] = bool(s.get("is_wheelchair"))
    def calc(m):
        n_wc = sum(1 for v in m.values() if v)
        n_walk = len(m) - n_wc
        return n_walk + n_wc * spec["wc_seats"], n_wc
    du, dw = calc(d)
    pu, pw = calc(p)
    return max(du, pu), max(dw, pw)


def _soge_insert_near(v, stop, geo):  # soge-keep-build-v1
    """その車の中で、いちばん近い人の隣に差し込む。

    ★送り → 迎え の順は崩さない。
      同じ種別の中でいちばん近い人の【次】に入れる。
      同じ種別が1人も居なければ、送りは先頭、迎えは末尾へ。
    """
    stops = v.setdefault("stops", [])
    g = geo.get(str(stop.get("patient_id")))
    same = [i for i, s in enumerate(stops) if s.get("type") == stop.get("type")]
    if not same:
        if stop.get("type") == "dropoff":
            stops.insert(0, stop)
        else:
            stops.append(stop)
        return
    best_i, best_km = same[-1], None
    if g and g.get("lat") is not None:
        for i in same:
            g2 = geo.get(str(stops[i].get("patient_id")))
            if not g2 or g2.get("lat") is None:
                continue
            km = _soge_km((float(g["lat"]), float(g["lng"])),
                          (float(g2["lat"]), float(g2["lng"])))
            if best_km is None or km < best_km:
                best_km, best_i = km, i
    stops.insert(best_i + 1, stop)


def _soge_nearest_car(cars, stop, geo, specs):  # soge-keep-build-v1
    """その人をいちばん近い人が乗っている車へ。席・車いす枠に入る車だけを見る。

    ★入る車が無ければ None。呼び出し側は「まだ車が決まっていない人」に残す。
      間違った車に押し込むより、人が決められる形で見せるほうがよい。
    """
    g = geo.get(str(stop.get("patient_id")))
    best, best_km = None, None
    for v in cars:
        spec = specs.get(id(v))
        if not spec:
            continue
        used, n_wc = _soge_stops_used((v.get("stops") or []) + [stop], spec)
        if v.get("seats") is not None and used > v["seats"]:
            continue
        if spec["wc_max"] is not None and n_wc > spec["wc_max"]:
            continue
        # 距離が測れないときは「入る車のうち、いま人数がいちばん少ない車」に寄せる
        km = None
        if g and g.get("lat") is not None:
            for s in (v.get("stops") or []):
                g2 = geo.get(str(s.get("patient_id")))
                if not g2 or g2.get("lat") is None:
                    continue
                d = _soge_km((float(g["lat"]), float(g["lng"])),
                             (float(g2["lat"]), float(g2["lng"])))
                if km is None or d < km:
                    km = d
        if km is None:
            km = 9999.0 + len(v.get("stops") or [])
        if best_km is None or km < best_km:
            best_km, best = km, v
    return best


def soge_build_week_keep(supabase, f_code, weekday, settings=None):  # soge-keep-build-v1
    """いつもの並びを土台に、変わったところだけ直す。

    ★保存済みが1件も無い曜日は、ゼロから組むのと同じ結果を返す（kept=False）。
    """
    settings = settings or get_soge_settings(supabase, f_code)
    week = _soge_saved_week(supabase, f_code, weekday, settings)
    if not week:
        out = soge_build_week(supabase, f_code, weekday, settings)
        out["kept"] = False
        return out

    geo = soge_geo_map(supabase, f_code)
    targets = _soge_targets(supabase, f_code, weekday, settings["unit_count"])

    # 車両の席仕様（_soge_saved_week は wc_seats を返さないので引き直す）
    try:
        vr = (supabase.table("rec_cars")
              .select("id,soge_seats,capacity,wheelchair_seats,wheelchair_max")
              .eq("facility_code", f_code).execute())
        vmap = dict((str(x["id"]), x) for x in (vr.data or []))
    except Exception as e:
        print("soge keep specs error: %s" % e, flush=True)
        vmap = {}

    tdefs = dict((t["key"], t) for t in settings["trips"])
    n_out, n_in, n_left = 0, 0, 0

    for trip in (week.get("trips") or []):
        tdef = tdefs.get(trip.get("trip_key"))
        if not tdef:
            continue
        want = set()
        for m, st in _soge_want_pairs(targets, tdef):
            want.add((str(m["patient_id"]), st))

        vs = trip.get("vehicles") or []
        real = [v for v in vs
                if not (v.get("unassigned") or v.get("noride"))]
        box = None
        for v in vs:
            if v.get("unassigned"):
                box = v
                break

        # ---------- ① その曜日に来なくなった人を抜く ----------
        #   ★「送迎なし」の箱は触らない。意図して外している人なので。
        #   ★登録の無い方(guest)も触らない。マスタに居なくて当たり前。
        for v in vs:
            if v.get("noride"):
                continue
            keep = []
            for s in (v.get("stops") or []):
                if s.get("guest") or (str(s.get("patient_id")), s.get("type")) in want:
                    keep.append(s)
                else:
                    n_out += 1
            v["stops"] = keep

        # ---------- ② 赤い箱の人を、入る車へ入れる ----------
        if box and box.get("stops"):
            specs = {}
            for v in real:
                vv = vmap.get(str(v.get("vehicle_id"))) or {}
                specs[id(v)] = _soge_vehicle_spec(vv) if vv else {
                    "seats": v.get("seats") or SOGE_DEFAULT_SEATS,
                    "wc_seats": SOGE_DEFAULT_WC_SEATS,
                    "wc_max": v.get("wheelchair_max") if v.get("wheelchair_max") is not None else 1,
                }
            rest = []
            # 遠い人から先に置く。近い人はあとからでも入る先が見つかりやすい
            for s in sorted(box["stops"],
                            key=lambda x: -((geo.get(str(x.get("patient_id"))) or {}).get("dist_km") or 0)):
                v = _soge_nearest_car(real, s, geo, specs)
                if v is None:
                    rest.append(s)
                    n_left += 1
                    continue
                _soge_insert_near(v, s, geo)
                n_in += 1
            box["stops"] = rest

        # ---------- ③ 後片づけ ----------
        #   空になった赤い箱は消す。人数と所要時間は数え直す。
        trip["vehicles"] = [v for v in vs
                            if not ((v.get("unassigned") or v.get("noride"))
                                    and not (v.get("stops") or []))]
        for v in trip["vehicles"]:
            if v.get("unassigned") or v.get("noride"):
                continue
            vv = vmap.get(str(v.get("vehicle_id"))) or {}
            spec = _soge_vehicle_spec(vv) if vv else {
                "seats": v.get("seats") or SOGE_DEFAULT_SEATS,
                "wc_seats": SOGE_DEFAULT_WC_SEATS, "wc_max": 1}
            used, n_wc = _soge_stops_used(v.get("stops"), spec)
            v["seats_used"] = used
            v["wheelchair_count"] = n_wc
            # 顔ぶれか順番が変わっているので、時刻は保存時に引き直す
            for s in (v.get("stops") or []):
                s["planned_at"] = None
            v["stale"] = True
            v["minutes"] = None
            v["distance_km"] = None
            v["over_target"] = False

    warns = []
    if n_out:
        warns.append("その曜日に来なくなった方を %d件 外しました。" % n_out)
    if n_in:
        warns.append("新しく来る方を %d件 車に入れました。並びを確かめてください。" % n_in)
    if n_left:
        warns.append("%d件は入る車がありませんでした。"
                     "「まだ車が決まっていない人」から移すか、車を足してください。" % n_left)
    week["warnings"] = warns
    week["kept"] = True
    week["saved"] = False        # 画面で確かめてから保存する
    return week


@app.route("/api/soge/week", methods=["GET"])  # soge-week-v1
@login_required
def api_soge_week_get():
    """その曜日の送迎表。保存済みがあればそれを、無ければ自動生成案。"""
    try:
        f_code = session["f_code"]
        supabase = get_supabase()
        weekday = _soge_weekday_arg(request.args.get("weekday"))   # soge-weekday-zero-v1
        if not (0 <= weekday <= 6):
            return jsonify({"status": "error", "message": "曜日が不正です"}), 400

        settings = get_soge_settings(supabase, f_code)
        saved = _soge_saved_week(supabase, f_code, weekday, settings)
        if saved:
            saved["status"] = "success"
            return jsonify(saved)

        out = soge_build_week(supabase, f_code, weekday, settings)
        out["status"] = "success"
        out["saved"] = False
        return jsonify(out)
    except Exception as e:
        print("api_soge_week_get error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


