# ===== soge-time-v1 : 所要時間で車両を割り当てる =====
# 現場の本当の制約は席数ではなく「事業所に戻ってくるまでの時間」。
# 席が空いていても1台で16か所回るのは現実的でない。


def _soge_route_hash(origin, stops):  # soge-time-v1
    """立ち寄り順のハッシュ。同じ順なら所要時間は変わらないのでキャッシュに使う。"""
    import hashlib
    key = (origin or "") + "|" + "|".join(str(s.get("patient_id")) for s in (stops or []))
    return hashlib.sha256(key.encode("utf-8")).hexdigest()[:32]


def _soge_legs_ok(legs, n):  # soge-legtime-v1
    """キャッシュから読んだ区間時間が、いまの立ち寄り人数と合っているか確かめる。

    ★合っていないものは【使わない】で None を返す。ずれた配列をそのまま使うと、
      別の人の区間時間で到着予定時刻を作ってしまう。等分に戻す方が安全。
    ★legs 列を足す前に保存された古い行は null なので、ここで None になる。
    """
    if not isinstance(legs, list) or len(legs) != n or n == 0:
        return None
    out = []
    for v in legs:
        try:
            f = float(v)
        except (TypeError, ValueError):
            return None
        if f < 0 or f > 600:        # 1区間10時間超は明らかにおかしい
            return None
        out.append(f)
    return out if any(out) else None


def _soge_stop_minutes(stops, settings):  # soge-time-v1
    """乗降にかかる時間。車いすは時間がかかる。"""
    m = 0
    for s in (stops or []):
        m += settings["stop_minutes_wc"] if s.get("is_wheelchair") else settings["stop_minutes"]
    return m


def _soge_drive_detail(supabase, f_code, geo, stops):  # soge-time-v1 / soge-legtime-v1
    """施設 → 各立ち寄り → 施設 の走行時間（分）。Routes API。結果はキャッシュ。
    戻り値: (分, 距離km, error, legs)

    ★legs は stops と【同じ長さ】の配列。legs[i] は「1つ前の地点から stops[i] の家に
      着くまでの走行時間（分）」。到着予定時刻を区間ごとに積み上げるために使う。
      これが無いと n+1 等分になり、家が遠い人のうしろが全部ずれる。
    ★地図の座標が無い人は 0.0（Googleへの経路にそもそも含めていないため）。
    ★取れなかったとき・古いキャッシュには None。呼び出し側は None なら等分に戻すこと。
    ★区間ごとの時間は Google の一番安い区分（Essentials）に含まれる。
      合計だけ貰うのと【料金は同じ】。呼ぶ回数も変わらない。
    """
    import json as _json
    import urllib.error
    import urllib.request

    if not stops:
        return 0, 0.0, None, []

    # 施設の住所
    try:
        fr = (supabase.table("facilities").select("facility_address")
              .eq("facility_code", f_code).execute())
        origin = (fr.data[0].get("facility_address") or "").strip() if fr.data else ""
    except Exception:
        origin = ""
    if not origin:
        return None, None, "施設の住所が未登録です", None

    h = _soge_route_hash(origin, stops)
    cached = None               # soge-legtime-v1: 保存済みの (分, km)。下の失敗時に使う
    try:
        cr = (supabase.table("soge_route_time").select("drive_minutes,distance_km,legs")
              .eq("facility_code", f_code).eq("route_hash", h).execute())
        if cr.data:
            cached = (int(cr.data[0]["drive_minutes"]), cr.data[0].get("distance_km"))
            if cr.data[0].get("legs") is not None:
                return (cached[0], cached[1], None,
                        _soge_legs_ok(cr.data[0].get("legs"), len(stops)))
        # soge-legtime-v1: legs が null = legs列を足す前に保存した古い行。
        #   周り順が同じだとハッシュも同じで永久にここに来てしまうので、
        #   【1回だけ】取り直して埋める。取れなかったときは空配列を書き、
        #   null と区別する（そうしないと毎回Googleを呼びに行ってしまう）。
    except Exception:
        pass

    def _fail(msg):             # soge-legtime-v1
        """★Googleに聞けなかったときは、【保存済みの分数を捨てないこと】。
          捨てて None を返すと呼び出し側が drive=0 とみなし、
          ・所要時間の上限チェックが効かなくなって全員1台に詰め込まれる
          ・到着予定時刻が走行0分で作られ、実際よりずっと早い時刻が出る
          という壊れ方をする。区間ごとの時間だけ諦めて、等分に戻すのが正しい。"""
        if cached is not None:
            return cached[0], cached[1], None, None
        return None, None, msg, None

    key = get_secret("GOOGLE_MAPS_API_KEY")
    if not key:
        return _fail("GOOGLE_MAPS_API_KEY が設定されていません")

    # 座標で投げる（住所文字列より速く、確実）
    inter = []
    geo_idx = []            # soge-legtime-v1: 何番目の stop を経路に入れたか
    for i, s in enumerate(stops):
        g = geo.get(str(s.get("patient_id")))
        if not g:
            continue
        inter.append({"location": {"latLng": {"latitude": g["lat"], "longitude": g["lng"]}}})
        geo_idx.append(i)
    if not inter:
        return 0, 0.0, None, [0.0] * len(stops)

    body = {
        "origin": {"address": origin},
        "destination": {"address": origin},   # 施設に戻る
        "intermediates": inter,
        "travelMode": "DRIVE",
        "units": "METRIC",
        "languageCode": "ja",
        "regionCode": "JP",
    }
    req = urllib.request.Request(
        REC_ROUTES_URL,
        data=_json.dumps(body).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "X-Goog-Api-Key": key,
            # soge-legtime-v1: routes.legs.duration も一番安い区分に含まれる（料金は同じ）
            "X-Goog-FieldMask": "routes.duration,routes.distanceMeters,routes.legs.duration",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=REC_ROUTES_TIMEOUT) as res:
            data = _json.loads(res.read().decode("utf-8"))
    except Exception as e:
        print("soge route time error: %s" % type(e).__name__, flush=True)
        return _fail("経路の所要時間を取得できませんでした")

    routes = data.get("routes") or []
    if not routes:
        return _fail("経路が見つかりませんでした")

    dur = routes[0].get("duration") or "0s"
    try:
        secs = int(str(dur).rstrip("s"))
    except (TypeError, ValueError):
        secs = 0
    minutes = int(round(secs / 60.0))
    dist_km = round((routes[0].get("distanceMeters") or 0) / 1000.0, 1)

    # soge-legtime-v1: 区間ごとの時間を stops と同じ並びに直す
    #   Google の legs は 施設→1人目→2人目→…→施設 の順。legs[k] は k人目に着くまで。
    #   座標が無い人は経路に入れていないので 0.0 のまま。
    #   ★区間の数が足りないものは【一部だけ使わない】こと。足りない人が 0.0 のままだと
    #     「その人には一瞬で着く」ことになり、予定時刻が実際より早く出る。
    #     早い方に外れるのは送迎では危ない（利用者を待たせる）ので、全部捨てて等分に戻す。
    legs = [0.0] * len(stops)
    raw = routes[0].get("legs") or []
    if len(raw) != len(geo_idx) + 1:        # 施設→…→施設 なので 経由地+1 本が正しい
        legs = []
    else:
        for k, i in enumerate(geo_idx):
            try:
                legs[i] = round(int(str(raw[k].get("duration") or "0s").rstrip("s")) / 60.0, 2)
            except (TypeError, ValueError, AttributeError):
                legs = []
                break
    if not any(legs):
        legs = []               # 1つも取れなかった → 等分に戻す（null とは区別する）

    try:
        supabase.table("soge_route_time").upsert({
            "facility_code": f_code, "route_hash": h,
            "drive_minutes": minutes, "distance_km": dist_km,
            "legs": legs,                       # soge-legtime-v1
            "computed_at": datetime.now(timezone.utc).isoformat(),
        }, on_conflict="facility_code,route_hash").execute()
    except Exception as e:
        print("soge route time save error: %s" % e, flush=True)

    return minutes, dist_km, None, (legs or None)


def _soge_trip_legs(trip):  # soge-trip-target-v1
    """その便が何本ぶんの仕事か。

    迎えだけ / 送りだけ → 1本
    送り + 迎えの混在（2単位運営の中間便）→ 2本

    中間便は「1単位目を送りながら2単位目を迎える」ので、
    立ち寄り件数が他の便の2倍になる。時間もそのぶん要る。
    """
    legs = 0
    if trip.get("dropoff_units"):
        legs += 1
    if trip.get("pickup_units"):
        legs += 1
    return max(1, legs)


def _soge_trip_target(trip, settings):  # soge-trip-target-v1
    """その便の目標時間・上限時間（分）。仕事量に応じて掛ける。"""
    legs = _soge_trip_legs(trip)
    return settings["target_minutes"] * legs, settings["max_minutes"] * legs


def _soge_path_km(grp, trip, geo, settings):  # soge-refine-v1
    """その車の周り順を直線距離でつないだ長さ（施設 → 各所 → 施設）。

    Routes API を呼ばずに「どっちが長いか」を比べるための目安。
    実際の道路距離ではないが、比べるぶんには十分。
    """
    fac = settings.get("_fac")
    if not fac or not grp:
        return 0.0
    stops = _soge_stops_of(grp, trip, geo, settings)
    if not stops:
        return 0.0

    start = (float(fac[0]), float(fac[1]))
    total, prev = 0.0, start
    for s in stops:
        g = geo.get(str(s["patient_id"]))
        if not g or g.get("lat") is None:
            return 0.0                       # 座標が欠けている便では概算しない
        p = (float(g["lat"]), float(g["lng"]))
        total += _soge_km(prev, p)
        prev = p
    total += _soge_km(prev, start)
    return total


def _soge_refine_by_time(supabase, f_code, geo, groups, vehicles, trip, settings, times):
    """時間のかかる車から空いている車へ、人を1人ずつ移してならす。  # soge-refine-v1

    席の比で割っただけだと、遠方を担当した車だけ時間が伸びる。
    席が空いていても時間が超えていたら移す。

    戻り値: (groups, changed)
    """
    target, _max_m = _soge_trip_target(trip, settings)
    n = len(groups)
    if n < 2:
        return groups, False

    specs = [_soge_vehicle_spec(v) for v in vehicles]
    if len(specs) < n:
        specs += [{"seats": SOGE_DEFAULT_SEATS, "wc_seats": SOGE_DEFAULT_WC_SEATS,
                   "wc_max": 1}] * (n - len(specs))

    # 実測から「直線距離1kmあたり何分か」を出す。以後はこれで概算する。
    tot_km = sum(_soge_path_km(g, trip, geo, settings) for g in groups)
    tot_drive = sum((t or {}).get("drive", 0) for t in times)
    if tot_km <= 0.3 or tot_drive <= 0:
        return groups, False                 # 概算の土台が無い（座標欠けなど）。触らない。
    min_per_km = tot_drive / tot_km

    def est(grp):
        if not grp:
            return 0.0
        stops = _soge_stops_of(grp, trip, geo, settings)
        return _soge_path_km(grp, trip, geo, settings) * min_per_km + \
            _soge_stop_minutes(stops, settings)

    cur = [est(g) for g in groups]
    changed = False

    for _ in range(12):                      # 念のため回数を切る
        if max(cur) <= target:
            break
        i = max(range(n), key=lambda k: cur[k])   # いちばん時間のかかる車
        j = min(range(n), key=lambda k: cur[k])   # いちばん空いている車
        if i == j or len(groups[i]) <= 1:
            break

        moved = False
        # 端の人（方面の並びの先頭か末尾）だけ試す。真ん中を抜くと経路が裂ける。
        for pos in ([0] if len(groups[i]) == 1 else [0, len(groups[i]) - 1]):
            m = groups[i][pos]
            cand_j = groups[j] + [m]
            if not _soge_fits(cand_j, specs[j], trip):
                continue
            cand_i = groups[i][:pos] + groups[i][pos + 1:]
            before = max(cur[i], cur[j])
            ei, ej = est(cand_i), est(cand_j)
            if max(ei, ej) < before - 0.5:   # 0.5分以上よくなるときだけ動かす
                groups[i], groups[j] = cand_i, cand_j
                cur[i], cur[j] = ei, ej
                moved = True
                changed = True
                break
        if not moved:
            break                            # これ以上よくならない

    return groups, changed


def _soge_split_by_time(supabase, f_code, geo, people, vehicles, trip, settings):  # soge-time-v1
    """席数で割り当てたあと、所要時間が目標を超える車があれば台数を増やして割り直す。

    戻り値: (groups, overflow, times)
        times[i] = {"drive": 分, "stop": 分, "total": 分, "km": 距離}
    """
    target, _max_m = _soge_trip_target(trip, settings)   # soge-trip-target-v1
    max_v = len(vehicles) if vehicles else 1

    # soge-trip-cars-v1: その便で使う台数が指定されていたら、そこで打ち切る。
    #   ★指定した台数に乗り切らなかった人は overflow に入り、
    #     配車画面の「まだ車が決まっていない人」に必ず出る（黙って消さない）。
    try:
        cap = int(trip.get("max_cars") or 0)
    except (TypeError, ValueError):
        cap = 0
    if cap > 0:
        max_v = min(max_v, cap)

    best = None
    for n_cars in range(1, max_v + 1):
        vs = vehicles[:n_cars] if vehicles else []
        # soge-balance-v1: 台数を増やしたら、その台数で均等に配分し直す。
        # 貪欲に詰めると先頭の車が満席のままで、台数を増やしても時間が減らない。
        groups, overflow = _soge_assign_balanced(people, geo, vs, trip)

        times = _soge_measure(supabase, f_code, geo, groups, trip, settings)  # soge-refine-v1
        over_target = any(t["total"] > target for t in times)

        best = (groups, overflow, times)
        if not overflow and not over_target:
            break                            # 目標時間に収まった。これ以上車を増やさない

    # soge-refine-v1: 席の比で割っただけだと時間が偏る。
    # 時間のかかる車から空いている車へ人を移してならす（ここでは Google を呼ばない）。
    groups, overflow, times = best
    if any(t["total"] > target for t in times):
        groups, changed = _soge_refine_by_time(
            supabase, f_code, geo, groups, vehicles, trip, settings, times)
        if changed:
            times = _soge_measure(supabase, f_code, geo, groups, trip, settings)
        best = (groups, overflow, times)

    return best


def _soge_measure(supabase, f_code, geo, groups, trip, settings):  # soge-refine-v1
    """各車の所要時間を実測する（Routes API。同じ周り順ならキャッシュが効く）。"""
    times = []
    for grp in groups:
        if not grp:
            times.append({"drive": 0, "stop": 0, "total": 0, "km": 0.0, "legs": None})
            continue
        stops = _soge_stops_of(grp, trip, geo, settings)
        drive, km, _err, legs = _soge_drive_detail(supabase, f_code, geo, stops)  # soge-legtime-v1
        if drive is None:
            drive, km, legs = 0, 0.0, None  # 取れなかったら時間制約は効かせない
        stop_m = _soge_stop_minutes(stops, settings)
        times.append({"drive": drive, "stop": stop_m,
                      "total": drive + stop_m, "km": km, "legs": legs})
    return times


def _soge_stops_of(grp, trip, geo, settings):  # soge-time-v1
    """1台分の立ち寄り（送り→迎えの順）。"""
    pu = set(trip.get("pickup_units") or [])
    du = set(trip.get("dropoff_units") or [])
    stops = []
    for m in grp:
        if m.get("unit") in du:
            stops.append({"patient_id": m["patient_id"], "user_name": m["user_name"],
                          "type": "dropoff", "nth": m.get("nth") or 0,
                          "is_wheelchair": m.get("is_wheelchair", False)})
        if m.get("unit") in pu:
            stops.append({"patient_id": m["patient_id"], "user_name": m["user_name"],
                          "type": "pickup", "nth": m.get("nth") or 0,
                          "is_wheelchair": m.get("is_wheelchair", False)})
    return _soge_order_stops(stops, geo, bool(settings.get("mid_dropoff_first", True)),
                             settings.get("_fac"))  # soge-routeopt-v1


def _soge_planned_times(depart, stops, drive_minutes, settings, legs=None):  # soge-time-v1
    """各立ち寄りの到着予定時刻。走行時間を区間ごとに積み上げ、乗降時間を足していく。

    ★soge-legtime-v1: legs（区間ごとの分）があればそれを使う。
      無いときだけ n+1 等分に戻す。等分だと、家が近い人が続いても遠い人を挟んでも
      同じ間隔になり、【うしろの人ほど予定時刻がずれる】。
    ★legs は _soge_drive_detail が stops と同じ並びで返す。長さが違うものは
      _soge_legs_ok が None にしているので、ここでは長さだけ最後にもう一度見る。
    """
    if not depart or len(depart) != 5 or not stops:
        return [None] * len(stops or [])
    try:
        h, mm = int(depart[:2]), int(depart[3:5])
    except (TypeError, ValueError):
        return [None] * len(stops)

    n = len(stops)
    use_legs = legs if (isinstance(legs, list) and len(legs) == n and any(legs)) else None
    per_leg = (drive_minutes / float(n + 1)) if n else 0   # 施設→…→施設 で n+1 区間
    out, acc = [], 0.0
    for i, s in enumerate(stops):
        if use_legs is not None:
            try:
                acc += float(use_legs[i])
            except (TypeError, ValueError):
                acc += per_leg
        else:
            acc += per_leg
        t = h * 60 + mm + int(round(acc))
        out.append("%02d:%02d" % ((t // 60) % 24, t % 60))
        acc += settings["stop_minutes_wc"] if s.get("is_wheelchair") else settings["stop_minutes"]
    return out

# ===== /soge-time-v1 =====



