# ===== soge-run-v1 : 当日の運行画面（打刻） =====
# 配車を組むのは /soge。実際に走る日に使うのがこの画面。
# 運転手は自分の車のタブを開いて、着いた順にボタンを押すだけ。
# 押した時刻は上書きしない（2度押し防止をサーバ側でも守る）。


def _soge_jst():  # soge-run-v1
    return timezone(timedelta(hours=9))


def _soge_hhmm(ts):  # soge-run-v1
    """timestamptz(文字列) -> "HH:MM"（日本時間）。無ければ空文字。"""
    if not ts:
        return ""
    try:
        s = str(ts).replace("Z", "+00:00")
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(_soge_jst()).strftime("%H:%M")
    except Exception:
        return ""


def _soge_at_iso(date_str, hhmm):  # soge-run-v1
    """その日の "HH:MM"(日本時間) -> UTC の ISO 文字列。"""
    y, m, d = [int(x) for x in date_str.split("-")]
    h, mi = int(hhmm[:2]), int(hhmm[3:5])
    dt = datetime(y, m, d, h, mi, 0, tzinfo=_soge_jst())
    return dt.astimezone(timezone.utc).isoformat()


# ============================================================
# soge-lock-v1 : 運行表の「確定」
#
#   これまでは【その日を一度開いた瞬間】に配車表からコピーされ、
#   以降は配車表を直しても運行表に反映されなかった。
#   走り出したあとに表が変わる事故を防ぐための作りだったが、
#   現場からは「配車を直したのに運行表が変わらない」という不具合に見えていた。
#
#   ★考え方を変えた。止めるかどうかは【人が決める】。
#     確定していない日 … 開くたびに配車表から作り直す（常に最新）
#     確定した日       … 何があっても作り直さない
#   打刻が始まっている日は、確定していなくても自動では作り直さない。
#   （確定を押し忘れたまま走り出した場合の保険。作り直しはボタンから明示的に行う）
# ============================================================
def _soge_day_locked(supabase, f_code, date_str):
    try:
        r = (supabase.table("soge_day_locks").select("service_date")
             .eq("facility_code", f_code).eq("service_date", date_str)
             .limit(1).execute())
        return bool(r.data)
    except Exception as e:
        # 表がまだ無い等で読めないときは【確定扱い】にする。
        # 読めないことを理由に、走っている表を作り直してしまうほうが危ない。
        print("soge lock check error: %s" % e, flush=True)
        return True


def _soge_day_touched(days, stops):
    """その日が「もう動き出している」かどうか。

    ★「欠席（✕）」は数えない。 ← 実機で見つけた判定ミス（2026-08-21）
      来週の予定に前もって休みを入れておくのは、ごく普通の運用。
      それを「動き出した」と見なすと、その日は配車表の直しが
      いつまでも反映されなくなる（実際にそうなった）。
      欠席は【予定】であって【実績】ではない。
      作り直しても消えないよう、soge_materialize_day で付け直している。

    動き出しの印は「実際にその日が動いた跡」だけにする：
      到着の打刻 / 事業所の出発・帰着 / メーター / メモ / 臨時便
    """
    for d in (days or []):
        if d.get("is_extra"):
            return True
        for k in ("departed_at", "returned_at", "odo_start", "odo_end", "note"):
            v = d.get(k)
            if v not in (None, "", 0):
                return True
    for s in (stops or []):
        if s.get("arrived_at"):
            return True
        # soge-touch-edit-v1: 人が運行画面で手で直した跡も「動き出した」に数える。
        #   ★これが無いと、まだ1件も打刻が無いうちに「後にする」で
        #     並べ替えたり車を移したりしても touched にならず、
        #     次に画面を読み込んだ瞬間に作り直されて【並びが消える】。
        #     作り直しは行ごと入れ替えなので立ち寄りの id も変わり、
        #     手元の画面から送った打刻が「対象が見つかりません」で弾かれる。
        #     2026-09-01 の夜に本番で実際に起きた。
        #   ★edited_at を書くのは運行画面の3つの操作だけ（確認ずみ）。
        #     並べ替え(order) / 車を移す(move) / 時刻・欠席・取り消し(stop)。
        #     配車編集の保存は書かないので、配車の直しが当日に届かなくなる
        #     ことはない（保存側は走り出した日なら差分だけ当てる）。
        #   ★【欠席にしただけの行は数えない】。2026-08-21 に実機で決めたこと。
        #     来週の予定に前もって休みを入れるのは普通の運用で、それを
        #     「動き出した」と見なすと配車表の直しが反映されなくなる。
        if s.get("edited_at") and not s.get("is_absent"):
            return True
    return False


_SOGE_PAST_NG = ("過ぎた日の記録は、管理者だけが直せます。"
                 "管理者に依頼してください。")      # soge-past-admin-v1


def _soge_past_admin_ok(supabase, f_code, date_str, my_name):  # soge-past-admin-v1
    """その日の記録を直してよいか。今日より前の日は【管理者だけ】。

    ★HIROさんの決め（2026-08-31）：線引きは「今日より前の日」。
      その日のうちは、これまでどおり誰でも整える（現場の流れを変えない）。
      変わるのは【あとから書き換えるとき】だけ。
    ★確かめられないときは【断る】（fail closed）。
      読めないことを理由に通すと、権限の確認が事実上なくなる。
    """
    try:
        today = datetime.now(_soge_jst()).strftime("%Y-%m-%d")
    except Exception as e:
        print("[soge-past-admin] 今日が分かりませんでした: %s" % e, flush=True)
        return False
    d = str(date_str or "")[:10]
    if len(d) != 10:
        # 日付が分からないものは触らせない
        return False
    if d >= today:
        return True
    try:
        return bool(is_admin_user(supabase, f_code, my_name))
    except Exception as e:
        print("[soge-past-admin] 権限を確かめられませんでした: %s" % e, flush=True)
        return False


def _soge_day_state(supabase, f_code, date_str):
    """確定しているか／動き出しているかをまとめて返す。

    ★soge-day-guard-v1: 「読めたかどうか」も返す（read_ok）。
      これまでは読めなくても days=[] / stops=[] のまま進んでいた。
      その結果 touched が False になり、【打刻が入っている日でも作り直され、
      打刻が消える】ことがありえた。作り直しは行ごと入れ替えるので、
      消えた跡も残らない。
      すぐ下の _soge_day_locked は、わざと逆（読めなければ確定扱い）にしてある。
      同じ考えを touched にも効かせる。使う側で read_ok を見ること。
    """
    days, stops = [], []
    read_ok = True
    try:
        dr = (supabase.table("soge_days").select("*")
              .eq("facility_code", f_code).eq("service_date", date_str).execute())
        days = dr.data or []
        if days:
            # soge-touch-edit-v1: edited_at も持ってくる。
            #   これが無いと _soge_day_touched が「手で直した跡」を見られない。
            sr = (supabase.table("soge_stops")
                  .select("id,arrived_at,is_absent,edited_at")
                  .eq("facility_code", f_code).eq("service_date", date_str).execute())
            stops = sr.data or []
    except Exception as e:
        read_ok = False
        print("soge day state error: %s" % e, flush=True)
    return {"exists": bool(days),
            "read_ok": read_ok,
            "locked": _soge_day_locked(supabase, f_code, date_str),
            "touched": _soge_day_touched(days, stops),
            "past": date_str < datetime.now(_soge_jst()).strftime("%Y-%m-%d")}


def _soge_clear_day(supabase, f_code, date_str):
    """その日の運行表を消す。★立ち寄りから先に消すこと（親子の順）。"""
    try:
        (supabase.table("soge_stops").delete()
         .eq("facility_code", f_code).eq("service_date", date_str).execute())
        (supabase.table("soge_days").delete()
         .eq("facility_code", f_code).eq("service_date", date_str).execute())
        return True
    except Exception as e:
        print("soge clear day error: %s" % e, flush=True)
        return False


def _soge_leave_names_range(supabase, f_code, d_from, d_to):  # soge-print-leave-v1
    """d_from〜d_to の【日ごと】に、「休み連絡」が入っている利用者名の集合を返す。

        {'2026-09-04': {'板倉條麿', ...}, '2026-09-05': {...}, ...}

    ★飛び飛びの休みは、記録の start〜end を機械展開すると間の日まで休みになる。
      実際の休み日はカレンダー(calendar_events)が正。
      これは visit_records の月表示(leave-scattered-fix-v1)とまったく同じ規則。
      規則を2つに分けると、片方だけ直したときに食い違う。

    ★判定の中身は【この関数だけ】に置く。
      1日ぶんの _soge_leave_names は、これを1日切り出す薄い包みにしてある。
      （soge-print-leave-v1 で、記録表が1か月ぶんを一度に要るため移した。
        日ごとに呼ぶと 31日 × 2問い合わせ になり、印刷前に何秒も待たされる）
    """
    from datetime import datetime as _lv_dt, timedelta as _lv_td
    out = {}
    try:
        lv = (supabase.table("records")
              .select("id,user_name,leave_date_start,leave_date_end")
              .eq("facility_code", f_code).eq("category", "休み連絡")
              .lte("leave_date_start", d_to).execute())
        rows = lv.data or []
        if not rows:
            return out
        ids = [r.get("id") for r in rows if r.get("id") is not None]
        ev_by_rec = {}
        if ids:
            try:
                ce = (supabase.table("calendar_events")
                      .select("record_id,event_date,end_date")
                      .eq("facility_code", f_code).in_("record_id", ids).execute())
                for e in (ce.data or []):
                    ev_by_rec.setdefault(e.get("record_id"), []).append(e)
            except Exception as ee:
                print("soge leave cal fetch error: %s" % ee, flush=True)

        def _mark(ds, de, nm):
            """ds〜de の各日に nm を足す。欲しい期間の外は切り捨てる。
            ★もとの _covers は「ds <= その日 <= de」だった。ここも同じ。
              de が ds より前という壊れた記録は、もとと同じく【数えない】。"""
            if not ds:
                return
            a = str(ds)[:10]
            b = str(de or ds)[:10]
            if b < a:
                return
            if b < d_from or a > d_to:
                return
            if a < d_from:
                a = d_from
            if b > d_to:
                b = d_to
            try:
                cur = _lv_dt.strptime(a, "%Y-%m-%d")
                end = _lv_dt.strptime(b, "%Y-%m-%d")
            except Exception:
                return
            while cur <= end:
                out.setdefault(cur.strftime("%Y-%m-%d"), set()).add(nm)
                cur += _lv_td(days=1)

        for r in rows:
            nm = (r.get("user_name") or "").strip()
            if not nm:
                continue
            evs = ev_by_rec.get(r.get("id"))
            if evs:
                # カレンダー連携済み＝飛び日は各日単独のイベントになっている
                for e in evs:
                    _mark(e.get("event_date"), e.get("end_date"), nm)
            else:
                # 旧データ（カレンダー未連携）だけ、記録の start〜end で見る
                _mark(r.get("leave_date_start"), r.get("leave_date_end"), nm)
    except Exception as e:
        print("soge leave names error: %s" % e, flush=True)
    return out


def _soge_leave_names(supabase, f_code, date_str):  # soge-leave-v1
    """その日に「休み連絡」が入っている利用者名の集合。
    ★中身は _soge_leave_names_range に移した（soge-print-leave-v1）。
      判定の規則は1か所だけ。ここは1日ぶんを切り出す包み。
      呼び方も返す形も、これまでとまったく同じ（set）。
    """
    return _soge_leave_names_range(supabase, f_code, date_str, date_str).get(date_str, set())
def _soge_week_for_day(supabase, f_code, date_str, settings):  # soge-day-merge-v1
    """その日に使う配車を1か所で決める。日付の配車がいちばん強い。

    ★作り直し(soge_materialize_day)と差分当て(_soge_merge_day)で
      【同じ順番】を使うために切り出した。2か所に書くと、
      片方だけ直したときに食い違う。中身はこれまでと同じ。
    """
    weekday = _soge_date_weekday(date_str)
    week = _soge_saved_date(supabase, f_code, date_str, settings)
    if not week:
        week = _soge_saved_week(supabase, f_code, weekday, settings)
    if not week:
        week = soge_build_week(supabase, f_code, weekday, settings)
    return week


def _soge_merge_day(supabase, f_code, date_str):  # soge-day-merge-v1
    """走り出したあとでも、配車の直しを当日の運行表に当てる（差分だけ）。

    ★作り直しは使わない。作り直しは行ごと入れ替えるので打刻が消える。
    ★返り値は soge_materialize_day と同じ形。
    """
    st = _soge_day_state(supabase, f_code, date_str)
    # ★読めなかったら何もしない（soge-day-guard-v1 と同じ考え）
    if not st.get("read_ok", True):
        print("[soge-merge] %s %s の状態を読めなかったので、当てませんでした"
              % (f_code, date_str), flush=True)
        return {"built": False, "reason": "unknown"}
    if not st["exists"]:
        return {"built": False, "reason": "not_yet"}
    if st["locked"]:
        return {"built": False, "reason": "locked"}
    if date_str < datetime.now(_soge_jst()).strftime("%Y-%m-%d"):
        return {"built": False, "reason": "past"}

    settings = get_soge_settings(supabase, f_code)
    week = _soge_week_for_day(supabase, f_code, date_str, settings)
    if not week:
        return {"built": False, "reason": "no_week"}
    _by_date = bool(week.get("has_plan"))

    try:
        _dr = (supabase.table("soge_days").select("*")
               .eq("facility_code", f_code).eq("service_date", date_str).execute())
        cur_days = _dr.data or []
        _sr = (supabase.table("soge_stops").select("*")
               .eq("facility_code", f_code).eq("service_date", date_str).execute())
        cur_stops = _sr.data or []
    except Exception as e:
        print("[soge-merge] いまの運行表を読めませんでした: %s" % e, flush=True)
        return {"built": False, "reason": "unknown"}

    now_iso = datetime.now(timezone.utc).isoformat()
    geo = soge_geo_map(supabase, f_code)
    leave_names = _soge_leave_names(supabase, f_code, date_str)
    _wk = visit_week_of_month(date_str)

    # 利用を中止した方は、日付を名指ししても乗せない
    active = {}
    try:
        pr = (supabase.table("patient_profiles")
              .select("id,is_discontinued,discontinued_date")
              .eq("facility_code", f_code).execute())
        for x in (pr.data or []):
            active[str(x["id"])] = patient_active_on(x, date_str)
    except Exception as e:
        print("[soge-merge] 利用者を読めませんでした: %s" % e, flush=True)

    def _active_today(s):
        v = active.get(str(s.get("patient_id")))
        return True if v is None else v      # 分からない人は出す（消すより安全）

    def _nth_ok_today(s):
        # soge-day-guard-v1 と同じ規則。日付の配車は曜日の条件で外さない。
        if _by_date:
            return True
        n = int(s.get("nth") or 0)
        return (n < 1) or (n == _wk)

    def _vno_of(v):
        k = v.get("vehicle_no")
        try:
            return int(k) if k is not None else 1
        except (TypeError, ValueError):
            return 1

    # いまある便を (便, 車番) で引けるようにする。★臨時便は配車表に無いので外す。
    day_by_key = {}
    for d in cur_days:
        if d.get("is_extra"):
            continue
        try:
            _k = int(d.get("vehicle_no")) if d.get("vehicle_no") is not None else 1
        except (TypeError, ValueError):
            _k = 1
        day_by_key[(d.get("trip_key"), _k)] = d

    # いまある立ち寄りを (利用者, 迎え/送り) で引けるようにする。
    #   ★車をまたいで探す。車が変わっただけの人を、消して作り直さないため
    #     （消すと到着時刻も消える）。
    #   ★臨時便に入っている人は触らない。臨時便は配車表の外のもの。
    extra_day_ids = set(str(d["id"]) for d in cur_days if d.get("is_extra"))
    stop_by_key, extra_keys = {}, set()
    for s in cur_stops:
        _pk = (str(s.get("patient_id")), s.get("stop_type") or "pickup")
        if str(s.get("day_id")) in extra_day_ids:
            extra_keys.add(_pk)
            continue
        stop_by_key[_pk] = s

    used_keys, used_day_ids = set(), set()
    n_add, n_move, n_del, n_keep = 0, 0, 0, 0
    _wfail = 0               # soge-guard4-v1: 書き込みに失敗した数

    for trip in (week.get("trips") or []):
        for v in (trip.get("vehicles") or []):
            _vno = _vno_of(v)
            if _vno == SOGE_VNO_NORIDE:
                continue
            stops = [s for s in (v.get("stops") or [])
                     if _nth_ok_today(s) and _active_today(s)]
            # ★臨時便に移した人は、配車表側にも残っている。二重に作らない。
            stops = [s for s in stops
                     if (str(s.get("patient_id")), s.get("type") or "pickup") not in extra_keys]

            key = (trip.get("trip_key"), _vno)
            day = day_by_key.get(key)

            if not stops and not day:
                continue

            # 到着予定。作り直しと同じ出し方。
            riding = [s for s in stops
                      if (s.get("user_name") or "").strip() not in leave_names]
            if _vno <= SOGE_VNO_UNASSIGNED:
                planned = [None] * len(stops)
            elif len(riding) != len(stops):
                drive, _km, _err, _lg = _soge_drive_detail(supabase, f_code, geo, riding)
                times = _soge_planned_times(trip.get("depart") or "",
                                            riding, drive or 0, settings, _lg)
                tmap = {}
                for _s, _t in zip(riding, times):
                    tmap[id(_s)] = _t
                planned = [tmap.get(id(s)) for s in stops]
            else:
                planned = [s.get("planned_at") for s in stops]
                if not any(planned):
                    drive, _km, _err, _lg = _soge_drive_detail(supabase, f_code, geo, stops)
                    planned = _soge_planned_times(trip.get("depart") or "",
                                                  stops, drive or 0, settings, _lg)

            head = {
                "trip_name": trip.get("trip_name"),
                "vehicle_id": v.get("vehicle_id") or None,
                "vehicle_name": v.get("vehicle_name") or "",
                "plate_no": v.get("plate_no") or "",
                "driver_name": v.get("driver_name") or "",
                "depart_at": (trip.get("depart") or None),
                "updated_at": now_iso,
            }
            # soge-guard4-v1: その日にもう運転手が入っているなら、配車表で上書きしない。
            #   ★土壇場の交代（soge-driver-change-v1）は【実績寄り】の値。
            #     型（配車表）で塗り替えると、朝に替えた運転手が
            #     画面を開き直した瞬間に元の名前へ戻る。
            #   ★touched に driver_name を足す直し方は間違い。配車表から作った日は
            #     最初から driver_name が入っているので、作った瞬間に touched になり、
            #     配車表の直しが一切届かなくなる。
            #   ★空に戻せば（画面から「未設定」にできる）、また配車表の名前が入る。
            #     「ゼロから作り直す」は行ごと作り直すので、これまで通り配車表に戻る。
            if day and (day.get("driver_name") or "").strip():
                head["driver_name"] = day.get("driver_name")
            if day:
                day_id = day["id"]
                # ★出発・帰着・備考は触らない。実績なので。
                # soge-stable-id-v1: 中身が同じなら書かない。
                #   ★差分当ては運行画面を読むたびに走るようになった。
                #     毎回 updated_at だけ動かすと、あとから
                #     「誰がいつ直したのか」がログから読めなくなる。
                _dsame = True
                for _hk, _hv in head.items():
                    if _hk == "updated_at":
                        continue
                    if (day.get(_hk) or "") != (_hv or ""):
                        _dsame = False
                        break
                if not _dsame:
                    try:
                        (supabase.table("soge_days").update(head)
                         .eq("facility_code", f_code).eq("id", day_id).execute())
                    except Exception as e:
                        print("[soge-merge] 便を直せませんでした: %s" % e, flush=True)
                        _wfail += 1              # soge-guard4-v1
                        continue
            else:
                try:
                    _ins = dict(head)
                    _ins.update({"facility_code": f_code, "service_date": date_str,
                                 "trip_key": trip.get("trip_key"), "vehicle_no": _vno,
                                 "created_at": now_iso})
                    _r = supabase.table("soge_days").insert(_ins).execute()
                    day_id = _r.data[0]["id"]
                except Exception as e:
                    print("[soge-merge] 便を作れませんでした: %s" % e, flush=True)
                    _wfail += 1                  # soge-guard4-v1
                    continue
            used_day_ids.add(str(day_id))

            new_rows = []
            for i, s in enumerate(stops):
                pk = (str(s.get("patient_id")), s.get("type") or "pickup")
                used_keys.add(pk)
                old = stop_by_key.get(pk)
                _pl = (planned[i] if i < len(planned) else None) or None
                if old:
                    # ★行ごと移す。到着時刻・欠席・打刻者はそのまま。
                    upd = {"day_id": day_id, "seq": i, "planned_at": _pl,
                           "user_name": s.get("user_name") or old.get("user_name") or ""}
                    # soge-stable-id-v1: 何も変わらない行は書かない。
                    #   ★これが無いと、運行画面を開くたびに人数ぶんの
                    #     書き込みが走る（14人なら14回）。運転席のタブレットで
                    #     開くものなので、読むだけの回は読むだけで終わらせる。
                    if (str(old.get("day_id")) == str(day_id)
                            and old.get("seq") == i
                            and (old.get("planned_at") or None) == _pl
                            and (old.get("user_name") or "") == upd["user_name"]):
                        continue
                    try:
                        (supabase.table("soge_stops").update(upd)
                         .eq("facility_code", f_code).eq("id", old["id"]).execute())
                        if str(old.get("day_id")) != str(day_id):
                            n_move += 1
                    except Exception as e:
                        print("[soge-merge] 立ち寄りを直せませんでした: %s" % e, flush=True)
                        _wfail += 1              # soge-guard4-v1
                else:
                    new_rows.append({
                        "day_id": day_id,
                        "facility_code": f_code,
                        "service_date": date_str,
                        "patient_id": str(s.get("patient_id")),
                        "user_name": s.get("user_name") or "",
                        "stop_type": s.get("type") or "pickup",
                        "seq": i,
                        "planned_at": _pl,
                        "created_at": now_iso,
                    })
            if new_rows:
                try:
                    supabase.table("soge_stops").insert(new_rows).execute()
                    n_add += len(new_rows)
                except Exception as e:
                    print("[soge-merge] 立ち寄りを足せませんでした: %s" % e, flush=True)
                    _wfail += 1                  # soge-guard4-v1

    # ---- 配車から消えた人 ----
    #   ★打刻・欠席が付いていたら消さない。実際に乗せた記録・意図して付けた印。
    gone_ids = []
    for pk, s in stop_by_key.items():
        if pk in used_keys:
            continue
        if s.get("arrived_at") or s.get("is_absent"):
            n_keep += 1
            continue
        gone_ids.append(s["id"])
    if gone_ids:
        try:
            (supabase.table("soge_stops").delete()
             .eq("facility_code", f_code).in_("id", gone_ids).execute())
            n_del = len(gone_ids)
        except Exception as e:
            print("[soge-merge] 立ち寄りを消せませんでした: %s" % e, flush=True)

    # ---- 空になった便 ----
    #   ★出発・帰着・備考が入っている便は残す（実際に走った跡）。
    #   ★臨時便は触らない。
    try:
        _sr2 = (supabase.table("soge_stops").select("day_id")
                .eq("facility_code", f_code).eq("service_date", date_str).execute())
        left = set(str(x.get("day_id")) for x in (_sr2.data or []))
    except Exception as e:
        print("[soge-merge] 残りを数えられませんでした: %s" % e, flush=True)
        left = None
    if left is not None:
        drop = []
        for d in cur_days:
            if d.get("is_extra"):
                continue
            if str(d["id"]) in left or str(d["id"]) in used_day_ids:
                continue
            if _soge_day_touched([d], []):
                continue
            drop.append(d["id"])
        if drop:
            try:
                (supabase.table("soge_days").delete()
                 .eq("facility_code", f_code).in_("id", drop).execute())
            except Exception as e:
                print("[soge-merge] 便を消せませんでした: %s" % e, flush=True)

    print("[soge-merge] %s %s に配車の直しを当てました（足した%d 移した%d 消した%d "
          "残した%d）" % (f_code, date_str, n_add, n_move, n_del, n_keep), flush=True)
    # soge-guard4-v1: 1件でも書けていないなら、成功と言わない。
    if _wfail:
        print("[soge-merge] %s %s の取り込みで %d 件書けませんでした"
              % (f_code, date_str, _wfail), flush=True)
        return {"built": False, "reason": "write_failed"}
    return {"built": True, "reason": "merged"}


def soge_materialize_day(supabase, f_code, date_str, force=False):  # soge-run-v1 / soge-lock-v1
    """その日の運行（soge_days / soge_stops）を配車表から作る。

    元になるのは確定済みの週次表。無ければ自動生成案から作る。

    ★soge-lock-v1 で作り直しの条件を変えた（それまでは「一度作ったら二度と作り直さない」）。
      ・確定済みの日          → 絶対に作り直さない
      ・打刻などが始まった日  → 自動では作り直さない（force のときだけ）
      ・それ以外              → 差分だけ当てる（soge-stable-id-v1）
                                配車表の直しはそのまま出るが、立ち寄りの
                                id は変わらない。以前はここで行ごと
                                作り直していて、同じ日を2人が開くと
                                先に開いた側の打刻が弾かれていた。
    """
    keep_absent = set()      # soge-lock-v2: 作り直しても消さない「欠席（✕）」
    # soge-guard4-v1: 書き込みに失敗した数。★1件でもあれば built を立てない。
    #   force は【先に全部消してから】作り直すので、作る側が落ちると
    #   打刻も臨時便も消えたうえに運行表が空になる。それを
    #   「作り直しました」と出していた。
    _wfail = 0
    st = _soge_day_state(supabase, f_code, date_str)
    # soge-day-guard-v1: 状態が読めなかったら、何もしない。
    #   ★「読めなかった」と「打刻が無い」を混ぜない。混ぜると、
    #     入っている打刻を消して作り直してしまう（消えた跡も残らない）。
    #   ★exists も当てにならない（読めていれば有ったかもしれない）ので、
    #     exists を見る前に止める。でないと、もう1組の当日データを作ってしまう。
    if not st.get("read_ok", True):
        print("[soge-guard] %s %s の状態を読めなかったので、作り直しませんでした"
              % (f_code, date_str), flush=True)
        return {"built": False, "reason": "unknown"}
    # ★過ぎた日は絶対に作らない・作り直さない（soge-lock-v1 の重要な歯止め）。
    #   過去の運行表は「実際にどう走ったか」の記録で、月の記録表の元にもなる。
    #   打刻が1つも無い日（誰も押し忘れた日など）でも、今の配車表で
    #   書き換えてしまえば記録の改ざんになる。確定の有無とは関係なく止める。
    # soge-guard4-v1: ★この歯止めを if st["exists"] の【外】に出した。
    #   中にあったので、運行表がまだ無い過去日はこの分岐に入らず、
    #   そのまま下の作成処理へ落ちて【作られてしまっていた】。
    #   運行画面の日付欄で先月の日を選んで開くだけで、その日の運行表ができ、
    #   走っていない日が月間の運行記録表に載っていた。
    if date_str < datetime.now(_soge_jst()).strftime("%Y-%m-%d"):
        return {"built": False, "reason": "past"}
    if st["exists"]:
        if st["locked"]:
            return {"built": False, "reason": "locked"}
        if st["touched"] and not force:
            return {"built": False, "reason": "touched"}
        # soge-stable-id-v1: 手つかずの日も【消して作り直さない】。差分だけ当てる。
        #   ★作り直しは行ごと入れ替えるので、立ち寄りの id が毎回変わる。
        #     運行画面は id で打刻を送るので、誰かが同じ日を開いた瞬間に
        #     先に開いていた画面の id が全部死ぬ。押した打刻は
        #     「対象が見つかりません」で弾かれ、送り直しの列に
        #     【死んだ id のまま】積まれて、電波が戻っても入らない。
        #     2026-09-02 に DEMO001 で再現（0.6秒あけて2回読んだだけで
        #     3人ぶんの id が全部別物になった）。
        #   ★差分当ての元にする配車表は _soge_week_for_day で
        #     作り直しと同じものを見ているので、出てくる並びは変わらない。
        #   ★force（「ゼロから作り直す」）は、これまで通り下の道を通る。
        #     あれは「配車表そのままに戻す」ためのボタンなので変えない。
        if not force:
            return _soge_merge_day(supabase, f_code, date_str)
        # ★消す前に「欠席（✕）」を覚えておく。
        #   前もって入れた休みが、作り直しのたびに消えては使い物にならない。
        try:
            ar = (supabase.table("soge_stops").select("patient_id,stop_type")
                  .eq("facility_code", f_code).eq("service_date", date_str)
                  .eq("is_absent", True).execute())
            for x in (ar.data or []):
                keep_absent.add((str(x.get("patient_id")), x.get("stop_type") or "pickup"))
        except Exception as e:
            print("soge_materialize_day keep_absent error: %s" % e, flush=True)
        # soge-day-guard-v1: ログに出すために、消す前の中身を控える。
        _st_days, _st_stops = [], []
        try:
            _dr = (supabase.table("soge_days").select("id")
                   .eq("facility_code", f_code).eq("service_date", date_str).execute())
            _st_days = _dr.data or []
            _sr = (supabase.table("soge_stops").select("arrived_at")
                   .eq("facility_code", f_code).eq("service_date", date_str).execute())
            _st_stops = _sr.data or []
        except Exception:
            pass
        # soge-day-guard-v1: 消す前に、何を消すのかをログに残す。
        #   ★作り直しは行ごと入れ替えるので、消えた跡がデータに残らない。
        #     あとから「打刻が消えた」と言われたときに、作り直しなのか
        #     そもそも届いていなかったのかを、ログで分けられるようにする。
        try:
            _n_day = len([1 for _x in (_st_days or [])])
            _n_tap = len([1 for _x in (_st_stops or []) if _x.get("arrived_at")])
            print("[soge-guard] %s %s を作り直します（便%d 打刻%d 力ずく=%s）"
                  % (f_code, date_str, _n_day, _n_tap, bool(force)), flush=True)
        except Exception:
            pass
        if not _soge_clear_day(supabase, f_code, date_str):
            return {"built": False, "reason": "clear_failed"}

    # soge-day-merge-v1: 曜日の計算は _soge_week_for_day に移した（ここでは使わない）
    settings = get_soge_settings(supabase, f_code)
    # soge-date-plan-v1: ★ここが肝。日付の配車が【先】。
    #   その日だけの配車があれば、いつもの曜日の配車より優先する。
    #   （HIROさん「日付で決めた配車を運行画面では優先する」）
    #   ここ1か所を直せば、運行画面も印刷も、その先すべてが日付の配車で動く。
    # soge-day-merge-v1: 元をどれにするかは _soge_week_for_day に1本化した。
    #   ★差分当て(_soge_merge_day)と同じ順番を使うため。
    week = _soge_week_for_day(supabase, f_code, date_str, settings)
    if not week:
        return {"built": False, "reason": "no_week"}
    # soge-day-guard-v1: いま使っているのが【その日だけの配車】かどうか。
    #   _soge_saved_date だけが has_plan を立てる（曜日の配車は立てない）。
    _by_date = bool(week.get("has_plan"))

    # patient-active-v1: 利用を中止した方は、中止日より後の日には出さない。
    #   ★過去の日を見るときは、その日を基準に判定するので、中止前はちゃんと出る。
    active = {}
    try:
        pr = (supabase.table("patient_profiles")
              .select("id,is_discontinued,discontinued_date")
              .eq("facility_code", f_code).execute())
        for x in (pr.data or []):
            active[str(x["id"])] = patient_active_on(x, date_str)
    except Exception as e:
        print("soge_materialize_day patients error: %s" % e, flush=True)

    def _active_today(s):
        v = active.get(str(s.get("patient_id")))
        return True if v is None else v      # 分からない人は出す（消してしまうより安全）

    # soge-leave-plan-v1: 休みの人の家は回らないので、予定時刻の計算からも外す。
    #   ★名前は残す（画面には「お休み」と出す）。外すのは【時間の計算だけ】。
    leave_names = _soge_leave_names(supabase, f_code, date_str)

    geo = soge_geo_map(supabase, f_code)
    now_iso = datetime.now(timezone.utc).isoformat()

    # visit-nth-apply-v1: 週次テンプレートは日付を持たないので「第2火曜だけ」の人も
    # 常に入っている。その日に当たらない人は、当日データを作るときに落とす。
    _y, _m, _d = [int(x) for x in date_str.split("-")]
    _wk = visit_week_of_month(date_str)

    def _nth_ok_today(s):
        # soge-day-guard-v1: ★その日だけの配車は、日付を名指しで決めたもの。
        #   「第2火曜だけ」のような【曜日の条件】で外してはいけない。
        #   外していたので、今日だけの配車に入れた人が運行画面に出ず、
        #   記録も残らなかった（2026-09-01 に実際に起きた）。
        #   ★曜日の配車のときは、これまでどおり絞る。曜日の表は日付を持たず、
        #     「第2火曜だけ」の人も全部の火曜に入っているため。
        if _by_date:
            return True
        n = int(s.get("nth") or 0)
        return (n < 1) or (n == _wk)

    for trip in (week.get("trips") or []):
        for v in (trip.get("vehicles") or []):
            # soge-unassigned-v1
            #   -1（送迎なし）… 当日の運行表には作らない。乗らないと決めた方なので
            #   0（まだ車が決まっていない人）… 作る。運転手にも見せて、
            #      誰も乗せ忘れないようにする（乗る車が無いこと自体が申し送り）
            _vno = v.get("vehicle_no")
            try:
                _vno = int(_vno) if _vno is not None else 1
            except (TypeError, ValueError):
                _vno = 1
            # ★-1 ちょうどでなくても、非正の値はすべて「送迎なし」以外＝未割当として扱う。
            #   想定外の値を「ふつうの車」として当日データにすると、
            #   運転手のタブに「車 -2」が出て打刻までできてしまう。
            if _vno == SOGE_VNO_NORIDE:
                continue

            stops = [s for s in (v.get("stops") or [])
                     if _nth_ok_today(s) and _active_today(s)]
            if not stops:
                continue

            # 到着予定。保存済みの週次表には予定時刻が入っていないので、ここで出す。
            # soge-leave-plan-v1: 休みの人が居る便は、その人を抜いた並びで計算し直す。
            #   抜かないと、回らない家の分の走行時間が全員の予定に乗ってしまう。
            riding = [s for s in stops
                      if (s.get("user_name") or "").strip() not in leave_names]
            if _vno <= SOGE_VNO_UNASSIGNED:
                # 乗る車が決まっていないので、到着予定時刻は出しようがない
                planned = [None] * len(stops)
            elif len(riding) != len(stops):
                drive, _km, _err, _lg = _soge_drive_detail(supabase, f_code, geo, riding)
                times = _soge_planned_times(trip.get("depart") or "",
                                            riding, drive or 0, settings, _lg)
                tmap = {}
                for _s, _t in zip(riding, times):
                    tmap[id(_s)] = _t
                planned = [tmap.get(id(s)) for s in stops]   # 休みの人は空にする
            else:
                planned = [s.get("planned_at") for s in stops]
                if not any(planned):
                    drive, _km, _err, _lg = _soge_drive_detail(supabase, f_code, geo, stops)
                    planned = _soge_planned_times(trip.get("depart") or "",
                                                  stops, drive or 0, settings, _lg)

            try:
                dr = supabase.table("soge_days").insert({
                    "facility_code": f_code,
                    "service_date": date_str,
                    "trip_key": trip.get("trip_key"),
                    "trip_name": trip.get("trip_name"),
                    "vehicle_no": _vno,
                    "vehicle_id": v.get("vehicle_id") or None,
                    "vehicle_name": v.get("vehicle_name") or "",
                    "plate_no": v.get("plate_no") or "",
                    "driver_name": v.get("driver_name") or "",
                    "depart_at": (trip.get("depart") or None),
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }).execute()
                day_id = dr.data[0]["id"]
            except Exception as e:
                print("soge_materialize_day insert day error: %s" % e, flush=True)
                _wfail += 1                      # soge-guard4-v1
                continue

            rows = []
            for i, s in enumerate(stops):
                rows.append({
                    "day_id": day_id,
                    "facility_code": f_code,
                    "service_date": date_str,
                    "patient_id": str(s.get("patient_id")),
                    "user_name": s.get("user_name") or "",
                    "stop_type": s.get("type") or "pickup",
                    "seq": i,
                    "planned_at": (planned[i] if i < len(planned) else None) or None,
                    "created_at": now_iso,
                })
            if rows:
                try:
                    supabase.table("soge_stops").insert(rows).execute()
                except Exception as e:
                    print("soge_materialize_day insert stops error: %s" % e, flush=True)
                    _wfail += 1                  # soge-guard4-v1

    # soge-lock-v2: 覚えておいた「欠席（✕）」を付け直す。
    #   ★同じ人が同じ種別（迎え／送り）で残っている場合だけ。
    #     車が変わっていても、その人が休みであることは変わらない。
    if keep_absent:
        try:
            nr = (supabase.table("soge_stops").select("id,patient_id,stop_type")
                  .eq("facility_code", f_code).eq("service_date", date_str).execute())
            ids = [x["id"] for x in (nr.data or [])
                   if (str(x.get("patient_id")), x.get("stop_type") or "pickup") in keep_absent]
            if ids:
                (supabase.table("soge_stops").update({"is_absent": True})
                 .in_("id", ids).execute())
                print("[soge] 欠席を %d 件 引き継ぎました date=%s" % (len(ids), date_str), flush=True)
        except Exception as e:
            print("soge_materialize_day restore absent error: %s" % e, flush=True)

    # soge-guard4-v1: 1件でも書けていないなら、成功と言わない。
    if _wfail:
        print("[soge-guard] %s %s の作り直しで %d 件書けませんでした"
              % (f_code, date_str, _wfail), flush=True)
        return {"built": False, "reason": "write_failed"}
    return {"built": True, "reason": "built"}


def _soge_run_payload(supabase, f_code, date_str):  # soge-run-v1
    """運行画面のデータ。車ごとにまとめる（運転手は自分の車だけ見ればいい）。"""
    dr = (supabase.table("soge_days").select("*")
          .eq("facility_code", f_code).eq("service_date", date_str).execute())
    days = dr.data or []
    if not days:
        return {"date": date_str, "vehicles": [],
                "locked": _soge_day_locked(supabase, f_code, date_str), "touched": False,
                "past": date_str < datetime.now(_soge_jst()).strftime("%Y-%m-%d")}

    ids = [d["id"] for d in days]
    sr = (supabase.table("soge_stops").select("*")
          .eq("facility_code", f_code).eq("service_date", date_str).execute())
    stops = [s for s in (sr.data or []) if s.get("day_id") in ids]

    wc = {}
    addr = {}    # soge-addr-v1: 運転手が現地で見るので、住所も出す
    active = {}  # patient-active-v1: その日に在籍しているか
    try:
        wr = (supabase.table("patient_profiles")
              .select("id,is_wheelchair,address,is_discontinued,discontinued_date")
              .eq("facility_code", f_code).execute())
        for x in (wr.data or []):
            wc[str(x["id"])] = bool(x.get("is_wheelchair"))
            addr[str(x["id"])] = _soge_addr_short(x.get("address"))   # soge-run-addr2-v1
            active[str(x["id"])] = patient_active_on(x, date_str)
    except Exception:
        pass

    # patient-active-v1: 利用を中止した方は、中止日より後の日には出さない。
    #   ★すでに作られていた表からも外す（確定済みの日でも同じ）。
    #     過去の日を見るときはその日を基準に判定するので、中止前はちゃんと出る。
    stops = [s for s in stops if active.get(str(s.get("patient_id")), True)]

    # soge-leave-v1: その日に休み連絡が入っている方は「お休み」と出す。
    #   ★DBには書かない。連絡が取り消されたら、そのまま元に戻ってほしいため。
    leave_names = _soge_leave_names(supabase, f_code, date_str)

    by_day = {}
    for s in stops:
        by_day.setdefault(s["day_id"], []).append(s)

    # 便の並び（迎え便 → 中間便 → 送り便 → 臨時便）
    # soge-extra-v1: 臨時便は出発時刻の順で、定期便のあとに並べる。
    settings = get_soge_settings(supabase, f_code)
    order = dict((t["key"], i) for i, t in enumerate(settings["trips"]))

    def _vno_of(d):
        k = d.get("vehicle_no")
        try:
            return int(k) if k is not None else 1
        except (TypeError, ValueError):
            return 1

    def _order_key(d):
        # soge-unassigned-v1: 未割当(0)は、その便の先頭に出す
        if d.get("is_extra"):
            return (90, str(d.get("depart_at") or ""), _vno_of(d))
        return (order.get(d.get("trip_key"), 89), "", _vno_of(d))

    days.sort(key=_order_key)

    cmap = soge_color_map(supabase, f_code)      # soge-car-color-v1
    vehicles = {}
    for d in days:
        # soge-unassigned-v1: 未割当は車ではないので、車両IDで束ねずに専用のタブにする
        _vno = _vno_of(d)
        _un = (_vno <= SOGE_VNO_UNASSIGNED)      # 非正はすべて「車が未定」に倒す
        key = "unassigned" if _un else str(d.get("vehicle_id") or ("no%s" % _vno))
        v = vehicles.setdefault(key, {
            "key": key,
            "unassigned": _un,
            "vehicle_id": (None if _un else d.get("vehicle_id")),
            # タブは短く。本文で「この人まだ乗る車が決まっていません」と出す
            "vehicle_name": ("⚠ 車が未定" if _un
                             else (d.get("vehicle_name") or ("車 %s" % _vno))),
            "plate_no": ("" if _un else (d.get("plate_no") or "")),
            "driver_name": ("" if _un else (d.get("driver_name") or "")),
            # soge-car-color-v1: 車の色。IDで引けなければ、そのときの車名で引く。
            #   ★車両マスタから消された車でも、記録には名前が残っている。
            "trips": [],
        })
        # soge-car-color-v2: 色と、その色の上に置く文字の色を入れる。
        #   ★白い車も選べるので、文字色を決め打ちにできない。
        if "color_hex" not in v:
            v.update(soge_color_pack("" if _un else (
                cmap["byid"].get(str(d.get("vehicle_id") or ""))
                or cmap["byname"].get((d.get("vehicle_name") or "").strip())
                or "")))
            # soge-car-icon-v1: 車のアイコン。「車が未定」には付けない。
            v["icon_svg"] = ("" if _un else (
                cmap["svgid"].get(str(d.get("vehicle_id") or ""))
                or cmap["svgname"].get((d.get("vehicle_name") or "").strip())
                or ""))
        ss = sorted(by_day.get(d["id"], []), key=lambda x: x.get("seq") or 0)
        v["trips"].append({
            "day_id": d["id"],
            "unassigned": _un,                                   # soge-unassigned-v1
            "trip_key": d.get("trip_key"),
            "trip_name": d.get("trip_name") or "",
            # soge-driver-per-trip-v1: 運転手は【便ごと】に決まる。
            #   ★車ごとに1人しか渡していなかったので、その車の最初の便の
            #     運転手が、あとの便にも出ていた（迎えと送りで人を分ける施設で化ける）。
            "driver_name": d.get("driver_name") or "",
            "is_extra": bool(d.get("is_extra")),                 # soge-extra-v1
            "extra_reason": d.get("extra_reason") or "",         # soge-extra-v1
            "depart": (str(d.get("depart_at") or ""))[:5],       # 予定の出発
            "departed_at": _soge_hhmm(d.get("departed_at")),     # soge-note-v1 実際の出発
            "returned_at": _soge_hhmm(d.get("returned_at")),
            "note": d.get("note") or "",                          # soge-note-v1
            "stops": [{
                "id": s["id"],
                # soge-move-v1: いまどの便に居るか。移動先を選ぶときに自分を外すのに使う
                "day_id": d["id"],
                # soge-move-v1: 移した跡。★列がまだ無い環境では空で返るだけ（壊れない）
                "moved_from": s.get("moved_from") or "",
                "moved_by": s.get("moved_by") or "",
                "moved_at": _soge_hhmm(s.get("moved_at")),
                "patient_id": str(s.get("patient_id")),
                "user_name": s.get("user_name") or "",
                "type": s.get("stop_type") or "pickup",
                "seq": s.get("seq") or 0,
                "planned_at": (str(s.get("planned_at") or ""))[:5],
                "arrived_at": _soge_hhmm(s.get("arrived_at")),
                "is_absent": bool(s.get("is_absent")),
                # soge-leave-v1: 休み連絡から来た「お休み」。手で付けた欠席とは分けて持つ
                "is_leave": bool((s.get("user_name") or "").strip() in leave_names),
                "is_wheelchair": wc.get(str(s.get("patient_id")), False),
                "address": addr.get(str(s.get("patient_id")), ""),   # soge-addr-v1
            } for s in ss],
        })

    # soge-lock-v1: 確定しているか／もう動き出しているかを画面に伝える
    st = _soge_day_state(supabase, f_code, date_str)
    # soge-past-admin-v1: 過ぎた日を直せる人かどうか。画面はこれを見てボタンを出し分ける。
    #   ★画面の出し分けは【親切のため】。守りはAPI側にある。
    _can = _soge_past_admin_ok(supabase, f_code, date_str, session.get("my_name", ""))
    return {"date": date_str, "vehicles": list(vehicles.values()),
            "can_edit": bool(_can),                      # soge-past-admin-v1
            "locked": st["locked"], "touched": st["touched"], "past": st["past"]}


@app.route("/soge/run")  # soge-run-v1
@login_required
def soge_run_page():
    """当日の運行画面（打刻）。"""
    return render("soge_run.html")


@app.route("/api/soge/run", methods=["GET"])  # soge-run-v1
@login_required
def api_soge_run_get():
    try:
        f_code = session["f_code"]
        supabase = get_supabase()
        date_str = (request.args.get("date") or "").strip()
        if not date_str:
            date_str = datetime.now(_soge_jst()).strftime("%Y-%m-%d")
        soge_materialize_day(supabase, f_code, date_str)
        out = _soge_run_payload(supabase, f_code, date_str)
        out["status"] = "success"
        return jsonify(out)
    except Exception as e:
        print("api_soge_run_get error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


def _soge_vno_of(d):  # soge-lock-unassigned-v1
    """その枠の車番号。読めない値は「車が未定(0)」に倒す。

    ★`int(x or 1)` と書いてはいけない。0 は「車が未定」の意味を持つ値なのに
      偽なので、`0 or 1` が 1 になって守りが素通りする（別の直しで実際に踏んだ）。
    """
    v = d.get("vehicle_no")
    if v is None:
        return SOGE_VNO_UNASSIGNED
    try:
        return int(v)
    except (TypeError, ValueError):
        return SOGE_VNO_UNASSIGNED


def _soge_unassigned_names(supabase, f_code, date_str):  # soge-lock-unassigned-v1
    """その日、まだ乗る車が決まっていない方の名前（重複なし・並び順のまま）。

    ★数えない人
      ・「送迎なし」の枠にいる方（家族送迎など。決めたうえでそうしている）
      ・当日欠席の方、休み連絡が入っている方（乗らないと決まっている）

    ★読めなかったら【例外を上げる】。空で返してはいけない。
      空で返すと「誰も居ない」ことになり、黙って確定できてしまう。
      「無かった」と「聞けなかった」は別のこと。
    """
    dr = (supabase.table("soge_days").select("id,vehicle_no")
          .eq("facility_code", f_code).eq("service_date", date_str).execute())

    ids = set()
    for d in (dr.data or []):
        vno = _soge_vno_of(d)
        # 車が決まっていない枠だけ。「送迎なし」は決めた結果なので外す。
        if vno <= SOGE_VNO_UNASSIGNED and vno != SOGE_VNO_NORIDE:
            ids.add(d["id"])
    if not ids:
        return []

    sr = (supabase.table("soge_stops").select("day_id,user_name,is_absent")
          .eq("facility_code", f_code).eq("service_date", date_str).execute())

    leave = _soge_leave_names(supabase, f_code, date_str)
    out = []
    for s in (sr.data or []):
        if s.get("day_id") not in ids:
            continue
        if s.get("is_absent"):
            continue
        nm = (s.get("user_name") or "").strip()
        if not nm or nm in leave or nm in out:
            continue
        out.append(nm)
    return out


@app.route("/api/soge/run/lock", methods=["POST"])  # soge-lock-v1
@login_required
def api_soge_run_lock():
    """その日の運行表を確定する／確定を解除する。

    ★確定した日は、配車表を直しても運行表は変わらない。
      走り出したあとに表が変わる事故を防ぐのは、この確定だけ。
    """
    try:
        f_code = session["f_code"]
        supabase = get_supabase()
        d = request.json or {}
        date_str = (d.get("date") or "").strip()
        if not date_str:
            return jsonify({"status": "error", "message": "日付が必要です"}), 400
        want = bool(d.get("locked"))
        if want:
            # soge-lock-unassigned-v1: 乗る車が決まっていない方が残っていたら、
            #   一度止めて名前を出す。★確定そのものを禁止はしない。
            #   車が足りない日もあるので、禁止にすると「確定しないまま走る」
            #   というもっと危ないほうへ倒れる。承知して進んだ人は
            #   locked_by に残るので、あとから誰が通したか分かる。
            _un = _soge_unassigned_names(supabase, f_code, date_str)
            if _un and not bool(d.get("ack_unassigned")):
                return jsonify({
                    "status": "confirm",          # ★"success" ではない。画面は必ず止まる
                    "reason": "unassigned",
                    "names": _un,
                    "message": "乗る車が決まっていない方がいます",
                }), 409
            if _un:
                print("[soge-lock] 車が未定のまま確定: %s / %s / %s"
                      % (date_str, session.get("my_name", ""), "、".join(_un)), flush=True)
            supabase.table("soge_day_locks").upsert({
                "facility_code": f_code, "service_date": date_str,
                "locked_by": session.get("my_name", ""),
                "locked_at": datetime.now(timezone.utc).isoformat(),
            }).execute()
        else:
            (supabase.table("soge_day_locks").delete()
             .eq("facility_code", f_code).eq("service_date", date_str).execute())
        return jsonify({"status": "success", "locked": want})
    except Exception as e:
        print("api_soge_run_lock error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/soge/run/rebuild", methods=["POST"])  # soge-lock-v1
@login_required
def api_soge_run_rebuild():
    """配車表から今の日の運行表を作り直す。★打刻や臨時便は消える。

    確定済みの日は作り直さない。解除してからにする（事故防止の最後の砦）。
    """
    try:
        f_code = session["f_code"]
        supabase = get_supabase()
        date_str = ((request.json or {}).get("date") or "").strip()
        if not date_str:
            return jsonify({"status": "error", "message": "日付が必要です"}), 400
        if _soge_day_locked(supabase, f_code, date_str):
            return jsonify({"status": "error",
                            "message": "この日は確定されています。先に確定を解除してください。"}), 400
        if date_str < datetime.now(_soge_jst()).strftime("%Y-%m-%d"):
            return jsonify({"status": "error",
                            "message": "過ぎた日の運行表は作り直せません（実際に走った記録のため）。"}), 400
        r = soge_materialize_day(supabase, f_code, date_str, force=True)
        if not r.get("built"):
            # soge-guard4-v1: 理由を出し分ける。
            #   ★これまでは何が起きても「配車表がありません」と出していた。
            #     書き込みに失敗して運行表が空になった場合まで
            #     そう言うので、直す人が配車表を疑って回り道をする。
            _rbwhy = {
                "write_failed": "一部が作れませんでした。運行画面を開いて確かめ、"
                                "もう一度お試しください。",
                "no_week": "作り直せませんでした（配車表がありません）",
                "unknown": "いま状態を確かめられませんでした。少し時間をおいてお試しください。",
                "clear_failed": "いまの運行表を消せませんでした。少し時間をおいてお試しください。",
                "past": "過ぎた日の運行表は作り直せません（実際に走った記録のため）。",
                "locked": "この日は確定されています。先に確定を解除してください。",
            }.get(r.get("reason") or "", "作り直せませんでした（配車表がありません）")
            return jsonify({"status": "error", "message": _rbwhy}), 400
        return jsonify({"status": "success"})
    except Exception as e:
        print("api_soge_run_rebuild error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/soge/run/merge", methods=["POST"])  # soge-merge-btn-v1
@login_required
def api_soge_run_merge():
    """配車表の直しを、いまの運行表に【差分だけ】当てる。★打刻・欠席は消さない。

    ★「配車表から作り直す」との違い
        作り直し … 行ごと入れ替える。打刻・欠席・臨時便が消える。
        こちら   … 増えた人を足し、外れた人を消し、車を移された人は行ごと移す。
                   並び順も配車表に合わせる。
                   打刻・欠席が付いている人は、配車から外れていても残す。
                   出発・帰着・備考・臨時便は触らない。
    ★人が押したときだけ走らせる。自動で走らせてはいけない。
      運転席で「後にする」で並べ替えた順番が、画面を開くたびに
      配車表の順番へ戻ってしまう。どちらを採るかは場面によるので、
      押した人に決めてもらう。
    ★確定済み・過ぎた日・状態が読めないときは、_soge_merge_day の中で止まる。
    """
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        date_str = ((request.json or {}).get("date") or "").strip()
        if not _soge_date_ok(date_str):
            return jsonify({"status": "error", "message": "日付が正しくありません"}), 400
        # soge-past-admin-v1: 過ぎた日は管理者だけ
        if not _soge_past_admin_ok(supabase, f_code, date_str, my_name):
            return jsonify({"status": "error", "past_admin": True,
                            "message": _SOGE_PAST_NG}), 403
        res = _soge_merge_day(supabase, f_code, date_str)
        if not res.get("built"):
            _why = {
                "locked": "この日は確定済みです。先に確定を解除してください。",
                "past": "過ぎた日には取り込めません。",
                "not_yet": "この日の運行表がまだありません。",
                "no_week": "元になる配車が見つかりませんでした。",
                "unknown": "いま状態を確かめられませんでした。少し時間をおいてお試しください。",
                # soge-guard4-v1: 一部だけ入った場合。★成功と言わない。
                "write_failed": "一部が入りませんでした。画面を確かめて、"
                                "もう一度お試しください。",
            }.get(res.get("reason") or "", "取り込めませんでした")
            return jsonify({"status": "error", "message": _why}), 400
        print("[soge-merge-btn] %s %s を取り込みました (%s)"
              % (f_code, date_str, my_name), flush=True)
        return jsonify({"status": "success"})
    except Exception as e:
        print("api_soge_run_merge error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/soge/run/replan", methods=["POST"])  # soge-leave-plan-v1
@login_required
def api_soge_run_replan():
    """その日の到着予定時刻を計算し直す。★休みの人を抜いた並びで出す。

    休み連絡は当日の朝に入ることが多い。そのときにはもう運行表が作られているので、
    予定時刻だけをあとから引き直せるようにする。

    ★触るのは planned_at だけ。打刻・欠席・臨時便には一切さわらない。
      だから【確定済みの日でも押せる】。予定が変わるだけで記録は変わらない。
    """
    try:
        f_code = session["f_code"]
        supabase = get_supabase()
        date_str = ((request.json or {}).get("date") or "").strip()
        if not date_str:
            return jsonify({"status": "error", "message": "日付が必要です"}), 400
        if date_str < datetime.now(_soge_jst()).strftime("%Y-%m-%d"):
            return jsonify({"status": "error",
                            "message": "過ぎた日の予定時刻は引き直しません。"}), 400

        dr = (supabase.table("soge_days").select("id,depart_at,vehicle_no")
              .eq("facility_code", f_code).eq("service_date", date_str).execute())
        days = dr.data or []
        # soge-unassigned-v1: 「まだ車が決まっていない人」(vehicle_no=0)は
        #   乗る車が無いので、到着予定時刻を引き直しても意味が無い。飛ばす。
        def _real(d):
            k = d.get("vehicle_no")
            try:
                k = int(k) if k is not None else 1
            except (TypeError, ValueError):
                k = 1
            return k > 0
        days = [d for d in days if _real(d)]
        if not days:
            return jsonify({"status": "error", "message": "この日の運行表がありません"}), 400
        sr = (supabase.table("soge_stops")
              .select("id,day_id,patient_id,user_name,seq,is_absent")
              .eq("facility_code", f_code).eq("service_date", date_str).execute())
        stops = sr.data or []

        wc = {}
        try:
            wr = (supabase.table("patient_profiles").select("id,is_wheelchair")
                  .eq("facility_code", f_code).execute())
            for x in (wr.data or []):
                wc[str(x["id"])] = bool(x.get("is_wheelchair"))
        except Exception as _we:
            # visit-guard-failclosed-v1: 理由は _soge_saved_week と同じ
            print("[soge] 車椅子情報を取得できませんでした（全員なし扱いになります）: %s"
                  % _we, flush=True)

        leave_names = _soge_leave_names(supabase, f_code, date_str)
        settings = get_soge_settings(supabase, f_code)
        geo = soge_geo_map(supabase, f_code)

        by_day = {}
        for s in stops:
            by_day.setdefault(s.get("day_id"), []).append(s)

        changed = 0
        for d in days:
            ss = sorted(by_day.get(d["id"], []), key=lambda x: x.get("seq") or 0)
            if not ss:
                continue
            for x in ss:
                x["is_wheelchair"] = wc.get(str(x.get("patient_id")), False)
            # 休みの人・欠席の人の家は回らない
            riding = [x for x in ss
                      if not x.get("is_absent")
                      and (x.get("user_name") or "").strip() not in leave_names]
            times = []
            if riding:
                drive, _km, _err, _lg = _soge_drive_detail(supabase, f_code, geo, riding)
                times = _soge_planned_times((str(d.get("depart_at") or ""))[:5],
                                            riding, drive or 0, settings, _lg)
            tmap = {}
            for x, t in zip(riding, times):
                tmap[x["id"]] = t
            for x in ss:
                nt = tmap.get(x["id"])          # 回らない人は空にする
                supabase.table("soge_stops").update({"planned_at": nt}).eq("id", x["id"]).execute()
                changed += 1
        return jsonify({"status": "success", "changed": changed})
    except Exception as e:
        print("api_soge_run_replan error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/soge/run/arrive", methods=["POST"])  # soge-run-v1
@login_required
def api_soge_run_arrive():
    """到着の打刻。すでに時刻が入っていたら上書きしない（2度押し防止）。"""
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        stop_id = str((request.json or {}).get("stop_id") or "").strip()
        if not stop_id:
            return jsonify({"status": "error", "message": "対象がありません"}), 400

        # soge-past-admin-v1: 日付も引く（過ぎた日かどうかを見るため）
        r = (supabase.table("soge_stops").select("id,arrived_at,is_absent,service_date")
             .eq("facility_code", f_code).eq("id", stop_id).execute())
        if not r.data:
            return jsonify({"status": "error", "message": "対象が見つかりません"}), 404
        cur = r.data[0]
        # soge-past-admin-v1: 過ぎた日への打刻は管理者だけ。
        #   ★そもそも打刻は「いま」を書くので、過ぎた日に押すと
        #     昨日の記録に今日の時刻が入る。止めるほうが正しい。
        if not _soge_past_admin_ok(supabase, f_code, cur.get("service_date"), my_name):
            return jsonify({"status": "error", "past_admin": True,
                            "message": _SOGE_PAST_NG}), 403
        if cur.get("arrived_at"):
            # 2度押し。最初の時刻を正とする。
            return jsonify({"status": "success", "already": True,
                            "arrived_at": _soge_hhmm(cur["arrived_at"])})

        now = datetime.now(timezone.utc)
        supabase.table("soge_stops").update({
            "arrived_at": now.isoformat(), "arrived_by": my_name,
        }).eq("facility_code", f_code).eq("id", stop_id).execute()
        return jsonify({"status": "success", "already": False,
                        "arrived_at": _soge_hhmm(now.isoformat())})
    except Exception as e:
        print("api_soge_run_arrive error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/soge/run/stop", methods=["PUT"])  # soge-run-v1
@login_required
def api_soge_run_stop_edit():
    """時刻の手修正 / 休み（欠席）の切り替え / 打刻の取り消し。"""
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        data = request.json or {}
        stop_id = str(data.get("stop_id") or "").strip()
        if not stop_id:
            return jsonify({"status": "error", "message": "対象がありません"}), 400

        r = (supabase.table("soge_stops").select("id,service_date")
             .eq("facility_code", f_code).eq("id", stop_id).execute())
        if not r.data:
            return jsonify({"status": "error", "message": "対象が見つかりません"}), 404
        date_str = str(r.data[0]["service_date"])[:10]
        if not _soge_past_admin_ok(supabase, f_code, date_str, my_name):   # soge-past-admin-v1
            return jsonify({"status": "error", "past_admin": True,
                            "message": _SOGE_PAST_NG}), 403

        upd = {"edited_at": datetime.now(timezone.utc).isoformat(), "edited_by": my_name}

        if "absent" in data:
            upd["is_absent"] = bool(data.get("absent"))
            if upd["is_absent"]:
                upd["arrived_at"] = None      # 休みなら打刻は消す
                upd["arrived_by"] = None

        if "time" in data:
            t = (data.get("time") or "").strip()
            if not t:
                upd["arrived_at"] = None
                upd["arrived_by"] = None
            else:
                if len(t) != 5 or t[2] != ":":
                    return jsonify({"status": "error", "message": "時刻は HH:MM で入れてください"}), 400
                try:
                    upd["arrived_at"] = _soge_at_iso(date_str, t)
                except Exception:
                    return jsonify({"status": "error", "message": "時刻は HH:MM で入れてください"}), 400
                upd["is_absent"] = False

        supabase.table("soge_stops").update(upd) \
            .eq("facility_code", f_code).eq("id", stop_id).execute()
        return jsonify({"status": "success"})
    except Exception as e:
        print("api_soge_run_stop_edit error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/soge/run/order", methods=["PUT"])  # soge-print-admin-v1
@login_required
def api_soge_run_order():
    """その便の【周る順番】を並べ替える。

    body: {"day_id": "...", "stop_ids": ["...", "..."]}  並べたい順に

    ★その便の【全員】を受け取る。一部だけは受け取らない。
      一部だと、抜けた人の seq が宙に浮いて重複や飛びが出る。
      受け取った顔ぶれがその便の顔ぶれとぴったり同じでなければ断る。
    ★予定時刻(planned_at)は触らない。順番と予定は別のもので、
      勝手に引き直すと「何時に着いたか」を直したい場面で隣の予定まで動く。
      引き直したいときは「予定時刻を計算し直す」を使う。
    """
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        data = request.json or {}
        day_id = str(data.get("day_id") or "").strip()
        ids = [str(x).strip() for x in (data.get("stop_ids") or []) if str(x).strip()]
        if not day_id or not ids:
            return jsonify({"status": "error", "message": "対象がありません"}), 400

        dr = (supabase.table("soge_days").select("id,service_date")
              .eq("facility_code", f_code).eq("id", day_id).execute())
        if not dr.data:
            return jsonify({"status": "error", "message": "対象が見つかりません"}), 404
        date_str = str(dr.data[0]["service_date"])[:10]
        if not _soge_past_admin_ok(supabase, f_code, date_str, my_name):
            return jsonify({"status": "error", "past_admin": True,
                            "message": _SOGE_PAST_NG}), 403

        sr = (supabase.table("soge_stops").select("id")
              .eq("facility_code", f_code).eq("day_id", day_id).execute())
        have = set(str(x["id"]) for x in (sr.data or []))
        want = set(ids)
        # ★ぴったり同じでなければ断る。数が同じでも中身が違えば断る。
        if len(ids) != len(want):
            return jsonify({"status": "error", "message": "同じ方が2回入っています"}), 400
        if have != want:
            return jsonify({"status": "error",
                            "message": "この便の顔ぶれと合いません。画面を開き直してください"}), 409

        now_iso = datetime.now(timezone.utc).isoformat()
        for i, sid in enumerate(ids):
            (supabase.table("soge_stops")
             .update({"seq": i, "edited_at": now_iso, "edited_by": my_name})
             .eq("facility_code", f_code).eq("id", sid).execute())

        print("[soge-order] %s day=%s %d人 (%s)" % (date_str, day_id, len(ids), my_name), flush=True)
        return jsonify({"status": "success", "n": len(ids)})
    except Exception as e:
        print("api_soge_run_order error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/soge/run/move", methods=["POST"])  # soge-move-v1
@login_required
def api_soge_run_move():
    """その人を、別の車（別の便でも）へ移す。

    ★これまで移す手段が無かった。直前の乗せ替えができず、
      臨時便を作るか、その日を丸ごと作り直す（打刻が全部消える）しかなかった。
    ★確定済み・過ぎた日でも移せる（HIROさんの決め）。
      記録の書き換えになるので confirm を明示的に受け取り、
      いつ・誰が・どこから移したかを残す。
    """
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")
        supabase = get_supabase()
        data = request.json or {}
        stop_id = str(data.get("stop_id") or "").strip()
        to_day = str(data.get("to_day_id") or "").strip()
        if not stop_id or not to_day:
            return jsonify({"status": "error", "message": "対象がありません"}), 400

        r = (supabase.table("soge_stops")
             .select("id,day_id,service_date,patient_id,stop_type,user_name,arrived_at")
             .eq("facility_code", f_code).eq("id", stop_id).execute())
        if not r.data:
            return jsonify({"status": "error", "message": "対象が見つかりません"}), 404
        s = r.data[0]
        if str(s.get("day_id")) == to_day:
            return jsonify({"status": "error", "message": "すでにその車です"}), 400
        date_str = str(s.get("service_date"))[:10]
        who = (s.get("user_name") or "この方")

        # ★移せるのは【同じ日の中】だけ。日をまたぐと別の日の運行になり、
        #   出発時刻も記録表の行も意味が変わる。
        dr = (supabase.table("soge_days").select("*")
              .eq("facility_code", f_code).eq("service_date", date_str).execute())
        days = dict((str(d["id"]), d) for d in (dr.data or []))
        dst = days.get(to_day)
        if not dst:
            return jsonify({"status": "error",
                            "message": "移す先の車が、その日の運行表にありません"}), 404
        src = days.get(str(s.get("day_id"))) or {}

        # ★「車が未定」へは移せない。走らない枠なので、
        #   入れた瞬間にその人は誰にも運ばれなくなる。
        # ★`int(x or 1)` と書いてはいけない。vehicle_no は 0 が「車が未定」で、
        #   0 は偽なので `0 or 1` が 1 になり、守りがまるごと素通りする（実際に踏んだ）。
        #   app.py の他の場所（_vno_of）と同じく、None かどうかで見る。
        _dv = dst.get("vehicle_no")
        try:
            _dvno = int(_dv) if _dv is not None else 1
        except (TypeError, ValueError):
            _dvno = 1
        if _dvno <= SOGE_VNO_UNASSIGNED:
            return jsonify({"status": "error",
                            "message": "「車が未定」へは移せません。"
                                       "乗せないのであれば ✕（休み）を使ってください"}), 400

        # ★二重登録の先回り。soge_stops には
        #   unique (day_id, patient_id, stop_type) が張ってある。
        #   このまま更新すればDBエラーになり、職員には意味の分からない画面が出る。
        ex = (supabase.table("soge_stops").select("id")
              .eq("facility_code", f_code).eq("day_id", to_day)
              .eq("patient_id", str(s.get("patient_id")))
              .eq("stop_type", s.get("stop_type") or "pickup").execute())
        if ex.data:
            return jsonify({"status": "error",
                            "message": "その便には %s さんがすでに入っています" % who}), 409

        # soge-past-admin-v1: 過ぎた日は管理者だけ。
        #   ★下の confirm は「本当にいいですか」を聞くだけで、誰かは見ていない。
        #     誰が直してよいかは、こちらで見る。
        if not _soge_past_admin_ok(supabase, f_code, date_str, my_name):
            return jsonify({"status": "error", "past_admin": True,
                            "message": _SOGE_PAST_NG}), 403

        st = _soge_day_state(supabase, f_code, date_str)
        if (st["locked"] or st["past"]) and not data.get("confirm"):
            # ★画面側でも確認を出しているが、サーバ側でも止める。
            #   画面を通さない呼び方でも、記録が黙って書き換わらないようにする。
            return jsonify({"status": "error", "need_confirm": True,
                            "message": "この日は記録として閉じています"}), 409

        # 並び順は移す先の【最後】。途中に割り込ませない。
        sr = (supabase.table("soge_stops").select("seq")
              .eq("facility_code", f_code).eq("day_id", to_day).execute())
        seqs = [int(x.get("seq") or 0) for x in (sr.data or [])]
        new_seq = (max(seqs) + 1) if seqs else 0

        now_iso = datetime.now(timezone.utc).isoformat()
        moved_from = ("%s %s" % (src.get("vehicle_name") or "",
                                 src.get("trip_name") or "")).strip() or "別の車"
        upd = {
            "day_id": to_day,
            "seq": new_seq,
            "moved_at": now_iso,
            "moved_by": my_name,
            "moved_from": moved_from,
            "edited_at": now_iso,
            "edited_by": my_name,
        }
        # ★まだ着いていない人の到着予定は、車が変わった時点で意味を失う。
        #   残すと、走ってもいない車の予定時刻が紙に出る。
        #   すでに着いている人（＝記録の訂正）は、実績も当時の予定も触らない。
        if not s.get("arrived_at"):
            upd["planned_at"] = None

        try:
            (supabase.table("soge_stops").update(upd)
             .eq("facility_code", f_code).eq("id", stop_id).execute())
        except Exception as e:
            # ★DDL（moved_* の3列）がまだ入っていない環境でも移せるようにする。
            #   記録が残らないことだけは、はっきり画面に伝える。
            msg = str(e)
            if "moved_" not in msg:
                raise
            for k in ("moved_at", "moved_by", "moved_from"):
                upd.pop(k, None)
            (supabase.table("soge_stops").update(upd)
             .eq("facility_code", f_code).eq("id", stop_id).execute())
            print("[soge-move] moved_* 列が無いため記録なしで移しました: %s" % msg, flush=True)
            return jsonify({"status": "success", "to": (dst.get("vehicle_name") or ""),
                            "replan": (not s.get("arrived_at")),
                            "warn": "移しましたが、変更の記録（誰がいつ）は残っていません。"
                                    "db/ddl_soge_move_v1.sql を流してください"})

        print("[soge-move] %s %s: %s → %s (%s)" % (
            date_str, who, moved_from, dst.get("vehicle_name") or "", my_name), flush=True)
        return jsonify({"status": "success", "to": (dst.get("vehicle_name") or ""),
                        "replan": (not s.get("arrived_at"))})
    except Exception as e:
        print("api_soge_run_move error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/soge/run/depart", methods=["POST"])  # soge-note-v1
@login_required
def api_soge_run_depart():
    """出発の打刻。すでに入っていたら上書きしない（2度押し防止）。"""
    try:
        f_code = session["f_code"]
        supabase = get_supabase()
        day_id = str((request.json or {}).get("day_id") or "").strip()
        if not day_id:
            return jsonify({"status": "error", "message": "対象がありません"}), 400

        r = (supabase.table("soge_days").select("id,departed_at,service_date")
             .eq("facility_code", f_code).eq("id", day_id).execute())
        if not r.data:
            return jsonify({"status": "error", "message": "対象が見つかりません"}), 404
        # soge-guard4-v1: 過ぎた日は管理者だけ（soge-past-admin-v1）。
        #   ★この1本だけガードが無く、日をまたぐと昨日の便に今日の時刻が入った。
        #     画面側の止めは読み込んだ時の past を見ているだけなので、
        #     開きっぱなしのタブレットでは効かない。
        if not _soge_past_admin_ok(supabase, f_code,
                                   str(r.data[0].get("service_date"))[:10],
                                   session.get("my_name", "")):
            return jsonify({"status": "error", "past_admin": True,
                            "message": _SOGE_PAST_NG}), 403
        if r.data[0].get("departed_at"):
            return jsonify({"status": "success", "already": True,
                            "departed_at": _soge_hhmm(r.data[0]["departed_at"])})

        now = datetime.now(timezone.utc)
        supabase.table("soge_days").update({
            "departed_at": now.isoformat(), "updated_at": now.isoformat(),
        }).eq("facility_code", f_code).eq("id", day_id).execute()
        return jsonify({"status": "success", "already": False,
                        "departed_at": _soge_hhmm(now.isoformat())})
    except Exception as e:
        print("api_soge_run_depart error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/soge/run/day", methods=["PUT"])  # soge-note-v1
@login_required
def api_soge_run_day_edit():
    """出発 / 帰着 / 備考 を直す。時刻は "HH:MM"、空文字で消える。"""
    try:
        f_code = session["f_code"]
        my_name = session.get("my_name", "")            # soge-past-admin-v1
        supabase = get_supabase()
        data = request.json or {}
        day_id = str(data.get("day_id") or "").strip()
        if not day_id:
            return jsonify({"status": "error", "message": "対象がありません"}), 400

        r = (supabase.table("soge_days").select("id,service_date")
             .eq("facility_code", f_code).eq("id", day_id).execute())
        if not r.data:
            return jsonify({"status": "error", "message": "対象が見つかりません"}), 404
        date_str = str(r.data[0]["service_date"])[:10]
        if not _soge_past_admin_ok(supabase, f_code, date_str, my_name):   # soge-past-admin-v1
            return jsonify({"status": "error", "past_admin": True,
                            "message": _SOGE_PAST_NG}), 403

        upd = {"updated_at": datetime.now(timezone.utc).isoformat()}

        for key, col in (("departed", "departed_at"), ("returned", "returned_at")):
            if key not in data:
                continue
            t = (data.get(key) or "").strip()
            if not t:
                upd[col] = None
                continue
            if len(t) != 5 or t[2] != ":":
                return jsonify({"status": "error", "message": "時刻は HH:MM で入れてください"}), 400
            try:
                upd[col] = _soge_at_iso(date_str, t)
            except Exception:
                return jsonify({"status": "error", "message": "時刻は HH:MM で入れてください"}), 400

        # soge-driver-change-v1: 土壇場の運転手交代。
        #   ★替わるのは【この便】だけ。車ごと・一日ぶんには広げない。
        #     運転手は便ごとに決まるので（soge-driver-per-trip-v1）、
        #     広げると迎えと送りで人を分けている日がまとめて化ける。
        #   ★触るのは soge_days（その日の便）。soge_plans（曜日ごとの配車）は
        #     触らない。触ると「1回替えたら毎週そうなった」になる。
        #   ★空文字で「未設定」に戻せる。戻せないと、間違えて入れた名前が残る。
        if "driver_name" in data:
            upd["driver_name"] = (data.get("driver_name") or "").strip()[:60] or None

        if "note" in data:
            upd["note"] = (data.get("note") or "").strip()[:500] or None

        supabase.table("soge_days").update(upd) \
            .eq("facility_code", f_code).eq("id", day_id).execute()
        return jsonify({"status": "success"})
    except Exception as e:
        print("api_soge_run_day_edit error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


def _soge_drop_elsewhere(supabase, f_code, date_str, day_id, pid, stype):  # soge-extra-v1
    """同じ日の他の便から、その人のその立ち寄りを外す。

    早退の人が送り便にも残っていると、迎えに行って誰もいない、という事故になる。
    ただし、すでに打刻されたものは実際に運んだ記録なので消さない。
    """
    try:
        r = (supabase.table("soge_stops").select("id,day_id,arrived_at")
             .eq("facility_code", f_code).eq("service_date", date_str)
             .eq("patient_id", pid).eq("stop_type", stype).execute())
        for row in (r.data or []):
            if row.get("day_id") == day_id:
                continue
            if row.get("arrived_at"):
                continue              # 打刻済み。触らない。
            supabase.table("soge_stops").delete().eq("id", row["id"]).execute()
    except Exception as e:
        print("soge drop elsewhere error: %s" % e, flush=True)


@app.route("/api/soge/run/extra", methods=["POST"])  # soge-extra-v1
@login_required
def api_soge_run_extra_create():
    """臨時便を作る。早退・遅刻・通院など、その日かぎりの便。"""
    try:
        f_code = session["f_code"]
        supabase = get_supabase()
        data = request.json or {}

        my_name = session.get("my_name", "")            # soge-past-admin-v1
        date_str = (data.get("date") or "").strip()
        if len(date_str) == 10 and not _soge_past_admin_ok(
                supabase, f_code, date_str, my_name):   # soge-past-admin-v1
            return jsonify({"status": "error", "past_admin": True,
                            "message": _SOGE_PAST_NG}), 403
        if len(date_str) != 10:
            return jsonify({"status": "error", "message": "日付が不正です"}), 400
        reason = (data.get("reason") or "その他").strip()[:20]
        depart = (data.get("depart") or "").strip()
        if depart and (len(depart) != 5 or depart[2] != ":"):
            return jsonify({"status": "error", "message": "出発時刻は HH:MM で入れてください"}), 400
        stops = data.get("stops") or []
        if not stops:
            return jsonify({"status": "error", "message": "利用者を1名以上入れてください"}), 400

        # 臨時便の通し番号。既存の一意制約(facility_code,date,trip_key,vehicle_no)と衝突させない。
        try:
            ex = (supabase.table("soge_days").select("trip_key")
                  .eq("facility_code", f_code).eq("service_date", date_str)
                  .eq("is_extra", True).execute())
            used = set(str(x.get("trip_key") or "") for x in (ex.data or []))
        except Exception:
            used = set()
        n = 1
        while ("extra%d" % n) in used:
            n += 1
        trip_key = "extra%d" % n

        vid = (data.get("vehicle_id") or "").strip() or None
        vname, plate = "", ""
        if vid:
            try:
                vr = (supabase.table("rec_cars").select("name,plate_no")
                      .eq("facility_code", f_code).eq("id", vid).execute())
                if vr.data:
                    vname = vr.data[0].get("name") or ""
                    plate = vr.data[0].get("plate_no") or ""
            except Exception:
                pass

        now_iso = datetime.now(timezone.utc).isoformat()
        dr = supabase.table("soge_days").insert({
            "facility_code": f_code,
            "service_date": date_str,
            "trip_key": trip_key,
            "trip_name": "臨時便（%s）" % reason,
            "vehicle_no": 90 + n,        # 定期便の車番と衝突させない
            "vehicle_id": vid,
            "vehicle_name": vname,
            "plate_no": plate,
            "driver_name": (data.get("driver_name") or "").strip(),
            "depart_at": depart or None,
            "is_extra": True,
            "extra_reason": reason,
            "created_at": now_iso,
            "updated_at": now_iso,
        }).execute()
        day_id = dr.data[0]["id"]

        rows = []
        for i, s in enumerate(stops):
            pid = str(s.get("patient_id") or "").strip()
            stype = (s.get("type") or "pickup").strip()
            if not pid or stype not in ("pickup", "dropoff"):
                continue
            rows.append({
                "day_id": day_id,
                "facility_code": f_code,
                "service_date": date_str,
                "patient_id": pid,
                "user_name": (s.get("user_name") or "").strip()[:40],
                "stop_type": stype,
                "seq": i,
                "created_at": now_iso,
            })
        if not rows:
            supabase.table("soge_days").delete().eq("id", day_id).execute()
            return jsonify({"status": "error", "message": "利用者を1名以上入れてください"}), 400

        supabase.table("soge_stops").insert(rows).execute()

        # 二重送迎の防止。臨時便に入れた人は、同じ日の他の便から外す。
        for r0 in rows:
            _soge_drop_elsewhere(supabase, f_code, date_str, day_id,
                                 r0["patient_id"], r0["stop_type"])

        return jsonify({"status": "success", "day_id": day_id})
    except Exception as e:
        print("api_soge_run_extra_create error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route("/api/soge/run/extra/stop", methods=["POST"])  # soge-extra-v1
@login_required
def api_soge_run_extra_add_stop():
    """すでにある臨時便に、あとから1名足す。"""
    try:
        f_code = session["f_code"]
        supabase = get_supabase()
        data = request.json or {}
        day_id = str(data.get("day_id") or "").strip()
        pid = str(data.get("patient_id") or "").strip()
        stype = (data.get("type") or "pickup").strip()
        if not day_id or not pid or stype not in ("pickup", "dropoff"):
            return jsonify({"status": "error", "message": "入力が不正です"}), 400

        dr = (supabase.table("soge_days").select("id,service_date,is_extra")
              .eq("facility_code", f_code).eq("id", day_id).execute())
        if not dr.data or not dr.data[0].get("is_extra"):
            return jsonify({"status": "error", "message": "臨時便が見つかりません"}), 404
        date_str = str(dr.data[0]["service_date"])[:10]
        if not _soge_past_admin_ok(supabase, f_code, date_str,
                                   session.get("my_name", "")):   # soge-past-admin-v1
            return jsonify({"status": "error", "past_admin": True,
                            "message": _SOGE_PAST_NG}), 403

        sr = (supabase.table("soge_stops").select("seq")
              .eq("day_id", day_id).execute())
        seq = max([int(x.get("seq") or 0) for x in (sr.data or [])] + [-1]) + 1

        supabase.table("soge_stops").insert({
            "day_id": day_id,
            "facility_code": f_code,
            "service_date": date_str,
            "patient_id": pid,
            "user_name": (data.get("user_name") or "").strip()[:40],
            "stop_type": stype,
            "seq": seq,
            "created_at": datetime.now(timezone.utc).isoformat(),
        }).execute()

        _soge_drop_elsewhere(supabase, f_code, date_str, day_id, pid, stype)
        return jsonify({"status": "success"})
    except Exception as e:
        print("api_soge_run_extra_add_stop error: %s" % e, flush=True)
        return jsonify({"status": "error", "message": str(e)}), 500


