# ===== /soge-run-v1 =====



# ===== soge-print-v2 : 運行記録表（車両ごとの月間） =====
# 運行記録表は車両単位で綴じるもの。日毎に1枚ずつ出すと1か月で数十枚になるので、
# 車1台につき1か月ぶんを詰めて並べる。走行距離と到着予定は載せない（現場で不要）。


# soge-print-noaddr-v1: 運行記録表（印刷）に住所は載せない。住所は運行画面だけ。


def _soge_addr_short(a):  # soge-run-addr2-v1 / soge-addr-none-v1
    """運行画面に出す住所。都道府県を落として市から始める。

    運転手が見るのは市以下だけ（同一県内の利用者しかいない）。
    先頭の「◯◯県」を削るだけで、狭い画面でも1行に収まりやすくなる。
    削ったあと空になるようなら、元の文字列をそのまま返す（壊さない）。
    """
    a = (a or "").strip()
    # soge-addr-none-v1: 中身の無い言葉は「住所なし」として扱う。
    #   ★patient_profiles.address に、文字列の "None" が入っている行がある。
    #     空でも NULL でもなく、Python の str(None) がそのまま4文字で入っている。
    #     画面側は「住所があれば出す」なので、中身のある文字列として
    #     運行画面に None と出てしまう（2026-09-02 DEMO001 で確認）。
    #   ★住所が本当にこの言葉だけ、ということはあり得ないので、
    #     正しい住所を消してしまう心配はない。
    #   ★これは見え方の応急処置。データそのものは直っていない。
    if a.lower() in ("none", "null", "nan", "undefined", "-", "ー", "―"):
        return ""
    if not a:
        return ""
    # soge-addr-none-v1: 都道府県の名前を正面から見る。
    #   ★前は「先頭5文字に 都/道/府/県 が出たら、そこまで捨てる」だった。
    #     京【都】府 は2文字目が「都」なので、そこで切れて
    #       京都府京都市中京区… → 府京都市中京区…   と頭が欠けた。
    #     県名が無い「京都市…」も → 市中京区… になっていた。
    for _pref in ("東京都", "北海道", "大阪府", "京都府"):
        if a.startswith(_pref):
            return a[len(_pref):].strip() or a
    # 県名は2〜4文字（神奈川県・和歌山県・鹿児島県）。
    #   ★「県」が4文字目までに出たときだけ落とす。
    #     住所の途中に出てくる「県」（県道◯号など）で切らないため。
    _i = a.find("県")
    if 0 < _i <= 3:
        return a[_i + 1:].strip() or a
    return a


def _soge_month_range(ym):  # soge-print-v2
    """'YYYY-MM' -> (月初, 翌月初) の 'YYYY-MM-DD'。"""
    y, m = int(ym[:4]), int(ym[5:7])
    ny, nm = (y + 1, 1) if m == 12 else (y, m + 1)
    return "%04d-%02d-01" % (y, m), "%04d-%02d-01" % (ny, nm)


def _soge_month_payload(supabase, f_code, ym):  # soge-print-v2
    """その月の運行を車両ごとにまとめる。

    戻り値: [{vehicle_name, plate_no, rows: [{day_label, day_first, trip_name,
                                              driver_name, returned_at, stops}]}]
    """
    start, end = _soge_month_range(ym)

    dr = (supabase.table("soge_days").select("*")
          .eq("facility_code", f_code)
          .gte("service_date", start).lt("service_date", end).execute())
    days = dr.data or []

    # soge-unassigned-v1: 「まだ車が決まっていない人」の枠(vehicle_no=0)は、
    #   実際に走った記録ではないので運行記録表には絶対に出さない。
    #   ★"or 1" で判定すると 0 が 1 になって車1号車に混ざる。int で見ること。
    def _is_real_car(d):
        k = d.get("vehicle_no")
        try:
            k = int(k) if k is not None else 1
        except (TypeError, ValueError):
            k = 1
        return k > 0

    days = [d for d in days if _is_real_car(d)]
    if not days:
        return []

    sr = (supabase.table("soge_stops").select("*")
          .eq("facility_code", f_code)
          .gte("service_date", start).lt("service_date", end).execute())
    by_day = {}
    for s in (sr.data or []):
        by_day.setdefault(s.get("day_id"), []).append(s)

    settings = get_soge_settings(supabase, f_code)
    torder = dict((t["key"], i) for i, t in enumerate(settings["trips"]))
    cmap = soge_color_map(supabase, f_code)      # soge-car-color-v1

    # 車 → 日付 → 便 の順に並べる
    days.sort(key=lambda d: (str(d.get("vehicle_name") or ""),
                             str(d.get("service_date")),
                             torder.get(d.get("trip_key"), 99),
                             d.get("vehicle_no") or 1))

    # soge-print-leave-v1: その月の休みを【1回だけ】引く。
    #   ★日ごとに引くと 31日 × 2問い合わせ になり、印刷前に待たされる。
    from datetime import datetime as _lvm_dt, timedelta as _lvm_td
    _lv_from = ym + "-01"
    try:
        _lv_y, _lv_m = int(ym[:4]), int(ym[5:7])
        _lv_ny, _lv_nm = (_lv_y + 1, 1) if _lv_m == 12 else (_lv_y, _lv_m + 1)
        _lv_to = (_lvm_dt(_lv_ny, _lv_nm, 1) - _lvm_td(days=1)).strftime("%Y-%m-%d")
    except Exception:
        _lv_to = ym + "-31"
    leave_map = _soge_leave_names_range(supabase, f_code, _lv_from, _lv_to)
    out, cur, last_date = [], None, None
    for d in days:
        key = str(d.get("vehicle_id") or d.get("vehicle_name") or d.get("vehicle_no"))
        if not cur or cur["key"] != key:
            # soge-car-color-v1: 記録表は /api/vehicles を読んでいないので、
            #   サーバ側で引いて渡す。★色を決めるのは soge_color_map の1か所。
            cur = {"key": key,
                   "vehicle_name": d.get("vehicle_name") or ("車 %s" % (d.get("vehicle_no") or 1)),
                   "plate_no": d.get("plate_no") or "",
                   "rows": []}
            # soge-car-color-v2: 紙に出す色。車名は白地の文字なので ink を使う。
            cur.update(soge_color_pack(
                cmap["byid"].get(str(d.get("vehicle_id") or ""))
                or cmap["byname"].get((d.get("vehicle_name") or "").strip())
                or ""))
            # soge-car-icon-v1: 紙にも出す。★白黒で刷っても形で見分けられる。
            cur["icon_svg"] = (cmap["svgid"].get(str(d.get("vehicle_id") or ""))
                               or cmap["svgname"].get((d.get("vehicle_name") or "").strip())
                               or "")
            out.append(cur)
            last_date = None

        ds = str(d.get("service_date"))[:10]
        try:
            y, m, dd = [int(x) for x in ds.split("-")]
            wd = "月火水木金土日"[datetime(y, m, dd).weekday()]
            day_label = "%d/%d(%s)" % (m, dd, wd)
        except Exception:
            day_label = ds

        stops = sorted(by_day.get(d["id"], []), key=lambda x: x.get("seq") or 0)
        cur["rows"].append({
            "day_id": d["id"],                                   # soge-note-v1
            # soge-print-admin-v1: 同じ日の【他の便】。車を移す先に使う。
            #   ★「車が未定」(vehicle_no<=0)は走らない枠なので入れない。
            "targets": [{
                "day_id": x["id"],
                "name": x.get("vehicle_name") or ("車 %s" % (x.get("vehicle_no") or 1)),
                "trip": x.get("trip_name") or "",
                "extra": bool(x.get("is_extra")),
            } for x in days
                if str(x.get("service_date"))[:10] == ds
                and str(x["id"]) != str(d["id"])
                and _is_real_car(x)],
            # soge-past-admin-v1: 行ごとに「過ぎた日か」。記録表は1か月ぶんが
            #   1つの表に並ぶので、日ごとに分かれていないと出し分けられない。
            "past": (ds < datetime.now(_soge_jst()).strftime("%Y-%m-%d")),
            "day_label": day_label,
            "day_first": (ds != last_date),
            "trip_name": d.get("trip_name") or "",
            # soge-print-v3: 便の列は幅を取らせない（迎え便→迎 / 中間便→中 / 送り便→送）
            "trip_short": (d.get("trip_name") or "")[:1] or "",
            "driver_name": d.get("driver_name") or "",
            "departed_at": _soge_hhmm(d.get("departed_at")),     # soge-note-v1
            "returned_at": _soge_hhmm(d.get("returned_at")),
            "note": d.get("note") or "",                         # soge-note-v1
            "stops": [{
                # soge-print-edit-v1: どれを直すか指すのに要る
                "id": s.get("id"),
                "user_name": s.get("user_name") or "",
                "type": s.get("stop_type") or "pickup",
                "arrived_at": _soge_hhmm(s.get("arrived_at")),
                "is_absent": bool(s.get("is_absent")),
                # soge-print-leave-v1: 休み連絡から来た「お休み」。
                #   ★これを渡していなかったので、記録表では「—」のままだった。
                #     運行画面のAPIだけが作っていた（現場報告 2026-09-04 板倉さん）。
                "is_leave": bool((s.get("user_name") or "").strip() in leave_map.get(ds, set())),
            } for s in stops],
        })
        last_date = ds

    return out


@app.route("/soge/print")  # soge-print-v2
@login_required
def soge_print_page():
    """運行記録表。車1台につき1か月ぶん。"""
    f_code = session["f_code"]
