                '.rep-free { min-height:0 !important; padding:5px 8px !important; } '
                '.rep-mon-tbl { margin-bottom:6px !important; } '
                '.rep-mon-tbl td { padding:4px 7px !important; min-height:0 !important; '
                'line-height:1.4 !important; } '
