@app.route('/api/reactivate_request', methods=['POST'])
def api_reactivate_request():
    data = request.get_json(silent=True) or {}
    fc = (data.get('facility_code') or '').strip()
    message = (data.get('message') or '').strip()
    contact = (data.get('contact') or '').strip()
    if not fc:
        return jsonify({"error": "施設コードを入力してください。"}), 400
    fac_name = None
    try:
        supabase = get_supabase()
        fres = supabase.table("facilities").select("facility_name").eq("facility_code", fc).execute()
        if fres.data:
            fac_name = fres.data[0].get("facility_name")
    except Exception:
        pass
    # 施設コードの存在有無に関わらず同じ応答（情報漏えい防止）。存在する場合のみ通知。
    if fac_name is not None:
        try:
            line_notify_admin("\n".join([
                "【TASUKARU】ご利用再開のお申し込み/相談",
                "施設: " + fc + "（" + (fac_name or "") + "）",
                "連絡先: " + (contact or "（未記入）"),
                "内容: " + (message or "（未記入）"),
            ]))
        except Exception as e:
            print("[reactivate] notify error: " + str(e), flush=True)
    return jsonify({"status": "ok", "message": "受け付けました。担当者より折り返しご連絡します。"})


# pricing-rebuild-v1 : 契約リマインド（Cloud Scheduler から毎日1回叩く。token で保護）
#   トライアル終了 7日前/3日前/当日 → 施設の管理者LINEへ（自動課金の予告＋辞退導線）
#   年契約 満了 90日前/30日前/7日前 → 施設の管理者LINEへ（更新案内）
#   年契約 満了 60日前 → 岸本さんへ（更新交渉タイミング）
@app.route('/api/cron/contract_notices', methods=['GET', 'POST'])
def api_cron_contract_notices():
    token = request.args.get('token') or request.headers.get('X-Cron-Token', '')
    if not token or token != get_secret("CRON_TOKEN"):
        return jsonify({"error": "forbidden"}), 403

    supabase = get_supabase()
    today = datetime.now(tokyo_tz).date()
    base = request.host_url.rstrip("/")
    sent = {"trial": 0, "contract": 0, "operator": 0}

    def _admin_lines(fc):
        try:
            r = supabase.table("staffs").select("line_user_id").eq(
                "facility_code", fc).eq("is_active", True).execute()
            return [s.get("line_user_id") for s in (r.data or []) if s.get("line_user_id")]
        except Exception:
            return []

    def _dparse(d):
        if not d or str(d) in ("None", ""):
            return None
        try:
            return datetime.fromisoformat(str(d).replace("Z", "+00:00")).date()
        except (ValueError, TypeError):
            try:
                return datetime.strptime(str(d)[:10], "%Y-%m-%d").date()
            except (ValueError, TypeError):
                return None

    try:
        res = supabase.table("facilities").select(
            "facility_code,facility_name,payment_type,contract_term,contract_end,trial_ends_at,is_active,is_monitor"
        ).eq("is_active", True).execute()
        facs = res.data or []
    except Exception as e:
        print("[cron] fetch error: " + str(e), flush=True)
        return jsonify({"error": "db"}), 500

    for f in facs:
        fc = f.get("facility_code")
        if not fc or f.get("is_monitor"):
            continue

        # --- トライアル終了リマインド ---
        te = _dparse(f.get("trial_ends_at"))
        if te:
            d = (te - today).days
            if d in (7, 3, 0):
                lines = _admin_lines(fc)
                if lines:
                    when = "本日" if d == 0 else ("%d日後" % d)
                    msg = "\n".join([
                        "【TASUKARU】無料期間終了の" + ("お知らせ（本日）" if d == 0 else "お知らせ"),
                        "施設: " + (f.get("facility_name") or fc),
                        "無料期間は%s（%s）で終了します。" % (when, te.isoformat()),
                        "終了後は選択中のプランで自動的に課金が始まります。",
                        "このまま継続する場合はお手続き不要です。",
                        "解約する場合は無料期間の間に：" + base + "/pricing",
                    ])
                    for uid in lines:
                        try:
                            line_send_message(uid, [{"type": "text", "text": msg}])
                            sent["trial"] += 1
                        except Exception:
                            pass

        # --- 年契約 満了リマインド ---
        term = int(f.get("contract_term") or 0)
        ce = _dparse(f.get("contract_end"))
        if term >= 1 and ce:
            d = (ce - today).days
            if d in (90, 30, 7):
                lines = _admin_lines(fc)
                if lines:
                    msg = "\n".join([
                        "【TASUKARU】契約満了のお知らせ",
                        "施設: " + (f.get("facility_name") or fc),
                        "現在の契約は %s（あと%d日）で満了します。" % (ce.isoformat(), d),
                        "更新・プランのご相談はこちら：" + base + "/pricing",
                    ])
                    for uid in lines:
                        try:
                            line_send_message(uid, [{"type": "text", "text": msg}])
                            sent["contract"] += 1
                        except Exception:
                            pass
            if d == 60:
                try:
                    line_notify_admin("\n".join([
                        "【TASUKARU】更新交渉タイミング（満了60日前）",
                        "施設: " + (f.get("facility_name") or fc) + "（" + fc + "）",
                        "契約満了: " + ce.isoformat(),
                    ]))
                    sent["operator"] += 1
                except Exception:
                    pass

    print("[cron] contract_notices sent=%s" % sent, flush=True)
    return jsonify({"status": "ok", "sent": sent})


# pricing-rebuild-v1 : Stripe価格チェック（開発者専用・Secret Keyは表示しない）
#   21個の STRIPE_PRICE_* が Stripe に正しく登録され、金額・課金種別が想定と一致するか検証
_PRICE_ID_CACHE = {}  # stripe-price-setup-v1: lookup_key -> price_id


def _resolve_price_id(env_key):  # stripe-price-setup-v1
    """Price ID を解決。環境変数優先、無ければ Stripe の lookup_key から取得（キャッシュ）。
    これにより STRIPE_PRICE_* を環境変数に入れなくても、作成済み価格を自動で使える。"""
    try:
        pid = get_secret(env_key) or ""
    except Exception:
        pid = ""
    if pid:
        return pid
    if env_key in _PRICE_ID_CACHE:
        return _PRICE_ID_CACHE[env_key]
    try:
        stripe.api_key = get_secret("STRIPE_SECRET_KEY")
        r = stripe.Price.list(lookup_keys=[env_key], limit=1)
        if r.data:
            _PRICE_ID_CACHE[env_key] = r.data[0].id
            return r.data[0].id
    except Exception as e:
        print("_resolve_price_id error %s: %s" % (env_key, e), flush=True)
    return ""


def _check_stripe_prices():
    spec = []  # (env_key, plan_label, term_label, expected_amount, expected_mode)
    for plan_key, plan_label in (("STARTER", "スターター"), ("STANDARD", "スタンダード"), ("PRO", "プロ")):
        p = PLAN_PRICES.get(plan_key.lower(), {})
        spec.append(("STRIPE_PRICE_%s_M" % plan_key, plan_label, "月払い(単月)", p.get("monthly"), "recurring"))
        for y in (1, 2, 3):
            spec.append(("STRIPE_PRICE_%s_%dY_M" % (plan_key, y), plan_label, "%d年・月払い" % y, p.get("%dy_m" % y), "recurring"))
            spec.append(("STRIPE_PRICE_%s_%dY_L" % (plan_key, y), plan_label, "%d年・一括" % y, p.get("%dy_l" % y), "one_time"))
    try:
        stripe.api_key = get_secret("STRIPE_SECRET_KEY")
    except Exception:
        pass
    out = []
    for env_key, plan_label, term_label, exp_amount, exp_mode in spec:
        row = {"env_key": env_key, "plan": plan_label, "term": term_label,
               "expected_amount": exp_amount, "expected_mode": exp_mode,
               "price_id": None, "amount": None, "mode": None, "active": None,
               "ok": False, "issue": ""}
        pid = None
        try:
            pid = _resolve_price_id(env_key)  # stripe-price-setup-v1: 環境変数 or lookup_key
        except Exception:
            pid = None
        if not pid:
            row["issue"] = "価格が見つかりません（未作成/未設定）"
            out.append(row)
            continue
        row["price_id"] = pid
        try:
            pr = stripe.Price.retrieve(pid)
            row["amount"] = getattr(pr, "unit_amount", None)
            row["active"] = getattr(pr, "active", None)
            rec = getattr(pr, "recurring", None)
            row["mode"] = "recurring" if rec else "one_time"
            issues = []
            if exp_amount is not None and row["amount"] != exp_amount:
                issues.append("金額不一致(実%s/想定%s)" % (row["amount"], exp_amount))
            if row["mode"] != exp_mode:
                issues.append("種別不一致(実%s/想定%s)" % (row["mode"], exp_mode))
            if rec and getattr(rec, "interval", None) != "month":
                issues.append("継続周期が月でない(%s)" % getattr(rec, "interval", None))
            if row["active"] is False:
                issues.append("price が無効(active=false)")
            cur = getattr(pr, "currency", None)
            if cur and cur != "jpy":
                issues.append("通貨がjpyでない(%s)" % cur)
            row["ok"] = (len(issues) == 0)
            row["issue"] = "／".join(issues)
        except Exception as e:
            row["issue"] = "Stripe取得失敗: " + str(e)
        out.append(row)
    return out


@app.route('/dev/stripe_check')
@login_required
def dev_stripe_check():
    if not session.get("dev_authenticated"):
        return redirect(url_for("dev_login"))
    rows = _check_stripe_prices()
    ok_count = sum(1 for r in rows if r.get("ok"))
    return render_template("dev_stripe_check.html", rows=rows, ok_count=ok_count, total=len(rows))


def _stripe_price_spec():  # stripe-price-setup-v1
    """21価格の仕様。 _check_stripe_prices と同じ規則で (env_key, plan, plan_label, term, amount, mode)。"""
    spec = []
    labels = {"starter": "スターター", "standard": "スタンダード", "pro": "プロ"}
    for plan in ("starter", "standard", "pro"):
        P = plan.upper()
        p = PLAN_PRICES.get(plan, {})
        spec.append(("STRIPE_PRICE_%s_M" % P, plan, labels[plan], "月払い(単月)", p.get("monthly"), "recurring"))
        for y in (1, 2, 3):
            spec.append(("STRIPE_PRICE_%s_%dY_M" % (P, y), plan, labels[plan], "%d年・月払い" % y, p.get("%dy_m" % y), "recurring"))
            spec.append(("STRIPE_PRICE_%s_%dY_L" % (P, y), plan, labels[plan], "%d年・一括" % y, p.get("%dy_l" % y), "one_time"))
    return spec


def _stripe_find_or_create_product(plan, label):  # stripe-price-setup-v1
    tag = "tasukaru_plan"
    try:
        res = stripe.Product.search(query="metadata['%s']:'%s'" % (tag, plan), limit=1)
        if getattr(res, "data", None):
            return res.data[0].id
    except Exception:
        try:
            for pr in stripe.Product.list(limit=100).auto_paging_iter():
                if getattr(getattr(pr, "metadata", None), tag, None) == plan:
                    return pr.id
        except Exception:
            pass
    prod = stripe.Product.create(name="TASUKARU %s" % label, metadata={tag: plan})
    return prod.id


def _create_stripe_prices():  # stripe-price-setup-v1
    """21価格を Stripe に冪等に作成し、結果一覧を返す。lookup_key=env_key で重複防止。"""
    key = ""
    try:
        key = get_secret("STRIPE_SECRET_KEY") or ""
    except Exception:
        key = ""
    mode = "live" if key.startswith("sk_live_") else ("test" if (key.startswith("sk_test_") or key.startswith("rk_test_")) else "unknown")
    if not key:
        return {"ok": False, "error": "STRIPE_SECRET_KEY が未設定です。先にサーバーの環境変数に設定してください。",
                "mode": mode, "rows": [], "env_lines": [], "made": 0, "reused": 0, "failed": 0}
    stripe.api_key = key
    rows = []
    env_lines = []
    made = reused = failed = 0
    product_ids = {}
    for env_key, plan, label, term, amount, kind in _stripe_price_spec():
        row = {"env_key": env_key, "plan": label, "term": term, "amount": amount,
               "mode": kind, "price_id": None, "status": "", "issue": ""}
        try:
            if plan not in product_ids:
                product_ids[plan] = _stripe_find_or_create_product(plan, label)
            existing = None
            try:
                r = stripe.Price.list(lookup_keys=[env_key], limit=1)
                if r.data:
                    existing = r.data[0]
            except Exception:
                existing = None
            if existing:
                row["price_id"] = existing.id
                row["status"] = "reused"
                env_lines.append("%s=%s" % (env_key, existing.id))
                reused += 1
            else:
                params = dict(currency="jpy", unit_amount=amount, product=product_ids[plan],
                              lookup_key=env_key, transfer_lookup_key=True,
                              nickname="%s %s" % (label, term),
                              metadata={"tasukaru_env_key": env_key, "tasukaru_plan": plan, "tasukaru_term": term})
                if kind == "recurring":
                    params["recurring"] = {"interval": "month"}
                price = stripe.Price.create(**params)
                row["price_id"] = price.id
                row["status"] = "created"
                env_lines.append("%s=%s" % (env_key, price.id))
                made += 1
        except Exception as e:
            row["status"] = "failed"
            row["issue"] = str(e)
            failed += 1
        rows.append(row)
    return {"ok": failed == 0, "mode": mode, "rows": rows, "env_lines": env_lines,
            "made": made, "reused": reused, "failed": failed}


@app.route('/api/dev/create_stripe_prices', methods=['POST'])  # stripe-price-setup-v1
@login_required
def api_dev_create_stripe_prices():
    if not session.get("dev_authenticated"):
        return jsonify({"ok": False, "error": "dev auth required"}), 403
    try:
        result = _create_stripe_prices()
        return jsonify(result)
    except Exception as e:
        return jsonify({"ok": False, "error": "作成処理でエラー: %s" % e, "rows": [], "env_lines": []}), 200


# --- Stripe 決済セッション作成 ---
@app.route('/api/stripe/create_checkout', methods=['POST'])
def stripe_create_checkout():
    f_code = session.get("f_code")
    if not f_code:
        return jsonify({"error": "not logged in"}), 401
    stripe.api_key = get_secret("STRIPE_SECRET_KEY")
    data = request.get_json()
    plan = (data.get("plan") or "starter").lower()
    term = (data.get("term") or "monthly").lower()
    base_url = request.host_url.rstrip("/")

    # --- プラン妥当性チェック ---
    if plan not in ("starter", "standard", "pro"):
        return jsonify({"error": "invalid plan: " + plan}), 400

    # --- term → (環境変数サフィックス, 決済モード) の明示マッピング ---
    # _M系=毎月課金(subscription) / _L系=一括(payment)
    TERM_MAP = {
        "monthly": ("M",    "subscription"),
        "1y_m":    ("1Y_M", "subscription"),
        "1y_l":    ("1Y_L", "payment"),
        "2y_m":    ("2Y_M", "subscription"),
        "2y_l":    ("2Y_L", "payment"),
        "3y_m":    ("3Y_M", "subscription"),
        "3y_l":    ("3Y_L", "payment"),
    }
    if term not in TERM_MAP:
        return jsonify({"error": "invalid term: " + term}), 400
    suffix, checkout_mode = TERM_MAP[term]

    env_key = "STRIPE_PRICE_" + plan.upper() + "_" + suffix
    price_id = _resolve_price_id(env_key)  # stripe-price-setup-v1: 環境変数 or lookup_key
    if not price_id:
        return jsonify({"error": "price not configured: " + env_key}), 400

    # --- 任意割引クーポンの自動適用判定 ---
    # facilities.discount_rate（0.5/0.3/0.2）と discount_until（期限・空なら無期限）を見る
    discounts = None
    applied_discount_rate = 0
    try:
        supabase = get_supabase()
        fres = supabase.table("facilities").select(
            "discount_rate,discount_until"
        ).eq("facility_code", f_code).execute()
        if fres.data:
            d_rate = fres.data[0].get("discount_rate") or 0
            d_until = fres.data[0].get("discount_until")
            in_period = True
            if d_until not in (None, "", "None"):
                try:
                    du = datetime.fromisoformat(str(d_until).replace("Z", "+00:00"))
                    in_period = du >= datetime.now(timezone.utc)
                except (ValueError, TypeError):
                    in_period = True  # 日付が壊れていても割引は活かす（安全側はユーザー利益）
            if d_rate and in_period:
                coupon_map = {0.5: "STRIPE_COUPON_50", 0.3: "STRIPE_COUPON_30", 0.2: "STRIPE_COUPON_20"}
                coupon_env = coupon_map.get(round(float(d_rate), 2))
                if coupon_env:
                    coupon_id = get_secret(coupon_env)
                    if coupon_id:
                        discounts = [{"coupon": coupon_id}]
                        applied_discount_rate = d_rate
                    else:
                        print("[Stripe] coupon env not set: " + coupon_env, flush=True)
                else:
                    # 想定外の割引率は誤割引防止のため適用しない
                    print("[Stripe] unsupported discount_rate (skipped): " + str(d_rate), flush=True)
    except Exception as e:
        print("[Stripe] discount lookup error: " + str(e), flush=True)

    try:
        params = dict(
            mode=checkout_mode,
            line_items=[{"price": price_id, "quantity": 1}],
            success_url=base_url + "/pricing?stripe=success",
            cancel_url=base_url + "/pricing?stripe=cancel",
            metadata={
                "facility_code": f_code,
                "plan": plan,
                "term": term,
                "discount_rate": str(applied_discount_rate),
            },
            locale="ja",
        )
        if discounts:
            params["discounts"] = discounts
        checkout = stripe.checkout.Session.create(**params)
        return jsonify({"url": checkout.url})
    except Exception as e:
        print("[Stripe] checkout error: " + str(e), flush=True)
        return jsonify({"error": str(e)}), 500


# onboard-checkout-v1 : 施設オンボーディング用 Checkout 作成(ログイン不要)
# LIFFフォームから施設名・管理者名・LINE userId・plan・term を受け取り、
# onboard_id を発番して metadata に載せる。決済完了で stripe_webhook の
# onboard-webhook-v1 分岐が施設を自動発行する。
@app.route('/api/onboard/create_checkout', methods=['POST'])
def onboard_create_checkout():
    import secrets as _oc_secrets
    stripe.api_key = get_secret("STRIPE_SECRET_KEY")
    data = request.get_json(silent=True) or {}
    facility_name = (data.get("facility_name") or "").strip()
    admin_name = (data.get("admin_name") or "").strip()
    contact_email = (data.get("email") or "").strip()  # onboard-email-v1
    line_user_id = (data.get("line_user_id") or "").strip()
    plan = (data.get("plan") or "starter").lower()
    term = (data.get("term") or "monthly").lower()
    base_url = request.host_url.rstrip("/")

    if not facility_name or not admin_name:
        return jsonify({"error": "facility_name and admin_name required"}), 400
    # onboard-line-required-v1 : 初回管理者を必ず2FA可能にするため line_user_id を必須化
    if not line_user_id:
        return jsonify({"error": "line_required",
            "message": "お申し込みにはLINEの友だち追加が必要です。LINEから開いてやり直してください。"}), 400
    if plan not in ("starter", "standard", "pro"):
        return jsonify({"error": "invalid plan: " + plan}), 400

    # 既存 create_checkout と同一の term マッピング
    TERM_MAP = {
        "monthly": ("M",    "subscription"),
        "1y_m":    ("1Y_M", "subscription"),
        "1y_l":    ("1Y_L", "payment"),
        "2y_m":    ("2Y_M", "subscription"),
        "2y_l":    ("2Y_L", "payment"),
        "3y_m":    ("3Y_M", "subscription"),
        "3y_l":    ("3Y_L", "payment"),
    }
    if term not in TERM_MAP:
        return jsonify({"error": "invalid term: " + term}), 400
    suffix, checkout_mode = TERM_MAP[term]
    env_key = "STRIPE_PRICE_" + plan.upper() + "_" + suffix
    price_id = _resolve_price_id(env_key)  # stripe-price-setup-v1: 環境変数 or lookup_key
    if not price_id:
        return jsonify({"error": "price not configured: " + env_key}), 400

    onboard_id = _oc_secrets.token_urlsafe(24)
    try:
        params = dict(
            mode=checkout_mode,
            line_items=[{"price": price_id, "quantity": 1}],
            success_url=base_url + "/onboard/done?st=success",
            cancel_url=base_url + "/onboard/done?st=cancel",
            metadata={
                "onboard_id": onboard_id,
                "facility_name": facility_name,
                "admin_name": admin_name,
                "line_user_id": line_user_id,
                "plan": plan,
                "term": term,
                "email": contact_email,
            },
            locale="ja",
        )
        # subscription のときは無料トライアルを付与(トライアル中は無課金) pricing-rebuild-v1
        if contact_email:  # onboard-email-v1 : Stripe顧客にもメールを設定
            params["customer_email"] = contact_email
        if checkout_mode == "subscription":
            params["subscription_data"] = {
                "trial_period_days": TRIAL_DAYS,  # 2ヶ月無料トライアル
                "metadata": {"onboard_id": onboard_id},
            }
        checkout = stripe.checkout.Session.create(**params)
        return jsonify({"url": checkout.url})
    except Exception as e:
        print("[Onboard] checkout error: " + str(e), flush=True)
        return jsonify({"error": str(e)}), 500


# pricing-rebuild-v1 : Stripeサブスクの期間末+猶予を expires_at 用ISOで返す
def _stripe_sub_expiry(sub_id, grace_days=SUB_GRACE_DAYS):
    """current_period_end + 猶予日数 をISO文字列で返す（取得失敗時 None）。
    トライアル中は current_period_end = トライアル終了日 なので、そのまま使える。"""
    try:
        if not sub_id:
            return None
        sub = stripe.Subscription.retrieve(sub_id)
        cpe = getattr(sub, "current_period_end", None)
        if cpe:
            from datetime import datetime as _dt, timedelta as _td, timezone as _tz
            return (_dt.fromtimestamp(int(cpe), _tz.utc) + _td(days=grace_days)).isoformat()
    except Exception as e:
        print("[Stripe] sub expiry lookup error: " + str(e), flush=True)
    return None


# --- Stripe Webhook ---
@app.route('/api/stripe/webhook', methods=['POST'])
def stripe_webhook():
    """Stripe決済完了時のWebhook → 自動有効化"""
    stripe.api_key = get_secret("STRIPE_SECRET_KEY")
    webhook_secret = get_secret("STRIPE_WEBHOOK_SECRET")
    payload = request.get_data()
    sig = request.headers.get("Stripe-Signature", "")

    try:
        event = stripe.Webhook.construct_event(payload, sig, webhook_secret)
    except Exception as e:
        print(f"[Stripe webhook] verify error: {e}", flush=True)
        return jsonify({"error": "invalid"}), 400

    if event["type"] == "checkout.session.completed":
        session_obj = event["data"]["object"]
        # Stripeオブジェクトはdict()変換でKeyErrorになることがあるため、
        # to_dict()→JSON経由で確実にプレーンな辞書へ変換する
        def _to_plain_dict(obj):
            # cancel-guard-failclosed-v1: 2通り試すのはよい。
            #   ★どちらも駄目だったときに黙って {} を返すのが問題。
            #     {} になると metadata が空になり、
            #     【入金があったのに何も起きない】まま誰も気づけない。
            try:
                return json.loads(json.dumps(obj.to_dict()))
            except Exception:
                pass
            try:
                return json.loads(json.dumps(dict(obj)))
            except Exception:
                pass
            print("[stripe] 受け取った内容を辞書にできませんでした。"
                  "この決済は処理されません: type=%s" % type(obj), flush=True)
            return {}
        session_data = _to_plain_dict(session_obj)
        meta = session_data.get("metadata") or {}
        if not isinstance(meta, dict):
            meta = {}
        # onboard-webhook-v1 : 新規施設オンボーディング(まだ施設が存在しない状態での決済)
        onboard_id = meta.get("onboard_id")
        if onboard_id:
            try:
                import secrets as _ob_secrets
                import hashlib as _ob_hashlib
                from datetime import datetime as _ob_dt, timedelta as _ob_td, timezone as _ob_tz
                supabase = get_supabase()
                # 冪等: 同じ onboard_id の施設が既にあれば再発行しない(Stripeの再送対策)
                dup = supabase.table("facilities").select("facility_code").eq("onboard_id", onboard_id).execute()
                if dup.data:
                    print(f"[Onboard] onboard_id {onboard_id} already provisioned; skip", flush=True)
                    return jsonify({"status": "ok"}), 200
                ob_plan = meta.get("plan", "starter")
                ob_term = meta.get("term", "monthly")
                ob_fac_name = (meta.get("facility_name") or "").strip() or "新規施設"
                ob_admin_name = (meta.get("admin_name") or "").strip() or "管理者"
                ob_user_id = (meta.get("line_user_id") or "").strip()
                # 施設コード: 意味を持たないランダム(f + 10桁hex)。衝突時は数回リトライ
                new_code = None
                for _ in range(5):
                    cand = "f" + _ob_secrets.token_hex(5)
                    ex = supabase.table("facilities").select("facility_code").eq("facility_code", cand).execute()
                    if not ex.data:
                        new_code = cand
                        break
                if not new_code:
                    print("[Onboard] failed to allocate facility_code", flush=True)
                    return jsonify({"status": "ok"}), 200
                _ob_now = _ob_dt.now(_ob_tz.utc)
                ob_sub_id = session_data.get("subscription")
                ob_is_lump = ob_term.endswith("_l")  # pricing-rebuild-v1
                _OB_TERM_YEARS = {"1y_m": 1, "1y_l": 1, "2y_m": 2, "2y_l": 2, "3y_m": 3, "3y_l": 3}
                ob_term_years = _OB_TERM_YEARS.get(ob_term, 0)
                _fac_row = {
                    "facility_code": new_code,
                    "facility_name": ob_fac_name,
                    "plan": ob_plan,
                    "is_active": True,
                    "stripe_subscription_id": ob_sub_id,
                    "stripe_customer_id": session_data.get("customer"),
                    "onboard_id": onboard_id,
                    "contact_email": (meta.get("email") or "").strip() or None,  # onboard-email-v1
                    "contract_start": _ob_now.date().isoformat(),
                    "contract_term": ob_term_years,
                    "payment_type": "lump" if ob_is_lump else "monthly",
                }
                if ob_is_lump:
                    # 一括前払い: トライアルなし。契約満了まで利用可・自動更新なし・返金なし
                    _OB_TERM_DAYS = {"1y_l": 365, "2y_l": 730, "3y_l": 1095}
                    _ob_end = _ob_now + _ob_td(days=_OB_TERM_DAYS.get(ob_term, 365))
                    _fac_row["trial_ends_at"] = None
                    _fac_row["expires_at"] = _ob_end.isoformat()
                    _fac_row["contract_end"] = _ob_end.date().isoformat()
                else:
                    # subscription(月払い/年契約月払い): 2ヶ月トライアル。
                    # expires_at=サブスク期間末+猶予(トライアル中は=トライアル終了日+猶予)
                    trial_end = _ob_now + _ob_td(days=TRIAL_DAYS)
                    _fac_row["trial_ends_at"] = trial_end.isoformat()
                    _fac_row["expires_at"] = _stripe_sub_expiry(ob_sub_id) or (
                        trial_end + _ob_td(days=SUB_GRACE_DAYS)).isoformat()
                    if ob_term_years:
                        _fac_row["contract_end"] = (
                            _ob_now + _ob_td(days=365 * ob_term_years)).date().isoformat()
                supabase.table("facilities").insert(_fac_row).execute()
                # 管理者職員を作成(パスワードは未設定=空。初回設定リンクで本人が設定する)
                setup_token = _ob_secrets.token_urlsafe(32)
                setup_exp = (_ob_now + _ob_td(hours=24)).isoformat()
                supabase.table("staffs").insert({
                    "facility_code": new_code,
                    "staff_name": ob_admin_name,
                    "password_hash": "",
                    "is_active": True,
                    "setup_token": setup_token,
                    "setup_token_expires": setup_exp,
                    "email": (meta.get("email") or "").strip() or None,  # onboard-email-v1
                    "line_user_id": ob_user_id or None,  # onboard-admin-line-link-v1 : 初回管理者を2FA可能に紐付け
                }).execute()
                # LINEで初回設定リンクを本人(userId)に送信。パスワードは送らない=履歴に残さない
                setup_url = request.host_url.rstrip("/") + "/setup?token=" + setup_token
                if ob_user_id:
                    line_send_message(ob_user_id, [{
                        "type": "text",
                        "text": "\n".join([
                            "【TASUKARU】ご登録ありがとうございます。",
                            "",
                            "施設名: " + ob_fac_name,
                            "施設コード: " + new_code,
                            "管理者: " + ob_admin_name,
                            "",
                            "下のリンクから初回パスワードを設定してください(24時間有効)。",
                            setup_url,
                        ])
                    }])
                # 開発者にも新規契約を通知(施設コードのみ。トークン等は載せない)
                line_notify_admin("\n".join([
                    "【TASUKARU】新規オンボーディング",
                    "施設名: " + ob_fac_name,
                    "施設コード: " + new_code,
                    "プラン: " + ob_plan,
                ]))
                print(f"[Onboard] provisioned {new_code} (plan={ob_plan})", flush=True)
            except Exception as _ob_e:
                print(f"[Onboard] error: {_ob_e}", flush=True)
            return jsonify({"status": "ok"}), 200

        f_code = meta.get("facility_code")
        plan = meta.get("plan", "starter")
        term = meta.get("term", "monthly")
        try:
            discount_rate = float(meta.get("discount_rate", 0) or 0)
        except (ValueError, TypeError):
            discount_rate = 0
        if f_code:
            try:
                supabase = get_supabase()
                from datetime import datetime, timedelta, timezone
                # 契約満了日を算出（違約金/通知の基準）
                TERM_DAYS = {
                    "monthly": 30,
                    "1y_m": 365, "1y_l": 365,
                    "2y_m": 730, "2y_l": 730,
                    "3y_m": 1095, "3y_l": 1095,
                }
                days = TERM_DAYS.get(term, 30)
                now = datetime.now(timezone.utc)
                contract_end = now + timedelta(days=days)
                # 契約年数（違約金計算等で参照）
                TERM_YEARS = {"1y_m": 1, "1y_l": 1, "2y_m": 2, "2y_l": 2, "3y_m": 3, "3y_l": 3}
                contract_term_years = TERM_YEARS.get(term, 0)
                is_lump = term.endswith("_l")
                payment_type = "lump" if is_lump else "monthly"
                sub_id = session_data.get("subscription")
                # pricing-rebuild-v1 : アクセス期限
                #   一括=満了日 / subscription=期間末+猶予（invoice.paidで毎期延長）
                if is_lump:
                    expires_iso = contract_end.isoformat()
                else:
                    expires_iso = _stripe_sub_expiry(sub_id) or (
                        (contract_end if term == "monthly"
                         else now + timedelta(days=30 + SUB_GRACE_DAYS)).isoformat())

                update_data = {
                    "is_active": True,
                    "plan": plan,
                    "expires_at": expires_iso,
                    "contract_start": now.date().isoformat(),
                    "contract_end": contract_end.date().isoformat(),
                    "contract_term": contract_term_years,
                    "payment_type": payment_type,
                    "stripe_subscription_id": sub_id,
                    "stripe_customer_id": session_data.get("customer"),
                }
                supabase.table("facilities").update(update_data).eq("facility_code", f_code).execute()
                print(f"[Stripe] facility {f_code} activated (plan={plan}, term={term})", flush=True)
                line_notify_admin(
                    "\n".join([
                        "【TASUKARU】新規契約",
                        "施設コード: " + f_code,
                        "プラン: " + plan,
                        "契約: " + term + ("（割引" + str(int(discount_rate*100)) + "%）" if discount_rate else ""),
                        "",
                        "Stripeダッシュボードで確認してください。",
                    ])
                )
            except Exception as e:
                print(f"[Stripe webhook] DB update error: {e}", flush=True)

    elif event["type"] == "invoice.paid":
        # pricing-rebuild-v1 : 継続課金の成功（毎月/更新/トライアル明け）→ アクセス期限を延長
        inv = event["data"]["object"]
        try:
            inv_sub_id = inv.get("subscription") if isinstance(inv, dict) else None
        except Exception:
            inv_sub_id = None
        if inv_sub_id:
            try:
                supabase = get_supabase()
                new_exp = _stripe_sub_expiry(inv_sub_id)
                if new_exp:
                    supabase.table("facilities").update({
                        "is_active": True,
                        "expires_at": new_exp,
                    }).eq("stripe_subscription_id", inv_sub_id).execute()
                    print(f"[Stripe] invoice.paid → expires extended (sub {inv_sub_id})", flush=True)
            except Exception as e:
                print(f"[Stripe webhook] invoice.paid error: {e}", flush=True)

    elif event["type"] == "customer.subscription.deleted":
        # サブスク解約時
        sub_id = event["data"]["object"]["id"]
        try:
            supabase = get_supabase()
            supabase.table("facilities").update({
                "is_active": False
            }).eq("stripe_subscription_id", sub_id).execute()
            print(f"[Stripe] subscription {sub_id} cancelled", flush=True)
        except Exception as e:
            print(f"[Stripe webhook] cancel error: {e}", flush=True)

    return jsonify({"status": "ok"}), 200



# ============================================================
# 書類出力ページ
# ============================================================
@app.route('/api/check_data_bulk')
@login_required
def api_check_data_bulk():
    """書類出力: 全利用者のデータ充足チェック(モニタリング/訓練記録/体力測定/体重)を一括取得
    判定基準:
      モニタリング : monitoring_reports に当月レコードがある(生成済み)
      訓練記録    : patient_evaluations の changes_by_training と issues_and_causes が両方入力済み
      体力測定    : fitness_tests に3ヶ月以内の記録がある
      体重        : body_weights に当月の記録がある
      全OK        : 上記4項目すべてOK
    """
    import re as _re
    import calendar as _cal
    f_code = session.get("f_code", "")
    if not f_code:
        return jsonify({"status": "error", "message": "auth required"}), 401
    supabase = get_supabase()
    year_month = request.args.get("year_month", "")
    if not _re.match(r"^\d{4}-\d{2}$", year_month):
        return jsonify({"status": "error", "message": "year_monthパラメータ不正 (YYYY-MM)"}), 400
    try:
        y, m = int(year_month[:4]), int(year_month[5:7])
        last_day = _cal.monthrange(y, m)[1]
        ym_start = f"{year_month}-01"
        ym_end = f"{year_month}-{last_day:02d}"

        # --- モニタリング: 当月に monitoring_reports レコードがあるか ---
        mr = supabase.table("monitoring_reports").select("user_name").eq("facility_code", f_code).eq("target_month", year_month).execute()
        mon_set = set(r["user_name"] for r in (mr.data or []))

        # --- 訓練記録: changes_by_training と issues_and_causes が両方入力済み ---
        ev = supabase.table("patient_evaluations").select(
            "user_name, changes_by_training, issues_and_causes"
        ).eq("facility_code", f_code).eq("year_month", year_month).execute()
        eval_set = set(
            r["user_name"] for r in (ev.data or [])
            if (r.get("changes_by_training") or "").strip() and (r.get("issues_and_causes") or "").strip()
        )

        # --- 体力測定: 3ヶ月以内に記録あり ---
        # 3ヶ月前の先頭日を計算
        m3 = m - 3
        y3 = y
        if m3 <= 0:
            m3 += 12
            y3 -= 1
        fit_start = f"{y3}-{m3:02d}-01"
        ft = supabase.table("fitness_tests").select("user_name").eq("facility_code", f_code).gte("measured_date", fit_start).lte("measured_date", ym_end).execute()
        fit_set = set(r["user_name"] for r in (ft.data or []))

        # --- 体重: 当月に記録あり (user_nameで直接検索) ---
        pts = supabase.table("patients").select("user_name").eq("facility_code", f_code).execute()
        all_names = [r["user_name"] for r in (pts.data or [])]
        # 当月の体重記録を user_name で取得
        bw = supabase.table("body_weights").select("user_name").eq("facility_code", f_code).gte("measured_date", ym_start).lte("measured_date", ym_end).execute()
        weight_set = set(r["user_name"] for r in (bw.data or []) if r.get("user_name"))

        # --- 全利用者分をまとめる ---
        data = []
        for name in all_names:
            has_mon = name in mon_set
            has_eval = name in eval_set
            has_fit = name in fit_set
            has_weight = name in weight_set
            data.append({
                "user_name": name,
                "has_monitoring": has_mon,
                "has_evaluation": has_eval,
                "has_fitness": has_fit,
                "has_weight": has_weight,
                "all_ok": has_mon and has_eval and has_fit and has_weight,
            })
        return jsonify({"status": "success", "data": data})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500


@app.route('/print_output')
@login_required
def print_output():
    f_code = session.get("f_code", "")
    my_name = session.get("my_name", "")
    is_admin = session.get("is_admin", False)
    supabase = get_supabase()
    patients_list = []
    try:
        res = supabase.table("patient_profiles").select(
            "user_name, user_name_kana, care_manager_name, support_office, care_level, is_discontinued, discontinued_date"
        ).eq("facility_code", f_code).order("user_name_kana").execute()
        if res.data:
            # 利用者選択リストは全員表示(月別の対象外判定は print_preview 側で行う)
            patients_list = res.data
    except Exception:
        pass
    staff_list = []
    try:
        st_res = supabase.table("staffs").select("staff_name").eq("facility_code", f_code).eq("is_active", True).order("staff_name").execute()
        if st_res.data:
            staff_list = [s["staff_name"] for s in st_res.data if s.get("staff_name")]
    except Exception:
        pass
    return render("print_output.html",
        patients=patients_list,
        staff_list=staff_list,
        my_name=my_name,
        is_admin=is_admin,
        f_code=f_code,
    )


