@login_required
def api_staff_minutes_delete():
    """議事録1件を削除。他施設IDは弾く。"""
    ok, f_code, my_name = _staff_minutes_gate_ok()
    if not ok:
        return jsonify({"status": "error", "message": "この機能は有効化されていません"}), 403
    try:
        supabase = get_supabase()
        data = request.get_json(silent=True) or {}
        rec_id = (data.get("id") or "").strip()
        if not _SM_UUID_RE.match(rec_id):
            return jsonify({"status": "error", "message": "id が不正です"}), 400
        # record-owner-perm-v1: 削除は作成者または管理者のみ
        _own = supabase.table("staff_meetings").select("created_by").eq("id", rec_id).eq("facility_code", f_code).execute()
        if not _own.data:
            return jsonify({"status": "error", "message": "記録が見つかりません"}), 404
        if (_own.data[0].get("created_by") or "") != my_name and not is_admin_user(supabase, f_code, my_name):
            return jsonify({"status": "error", "message": "削除は作成者または管理者のみ可能です"}), 403
        supabase.table("staff_meetings").delete()\
            .eq("id", rec_id).eq("facility_code", f_code).execute()
        return jsonify({"status": "success"})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500


def _staff_minutes_pdf_html(meeting, style="a"):
    """社内議事録PDFのHTML生成。担当者会議の _MTG_PDF_BASE_CSS と装飾スタイルを
    流用しつつ、中身は 会議情報/議題/議論/決定事項/ToDo/その他 の構成にする。"""
    import json as _json_p
    esc = _mtg_pdf_esc
    title = esc(meeting.get("title") or "会議記録")
    date = esc(meeting.get("meeting_date") or "")
    attendees = esc(meeting.get("attendees") or "（記載なし）")
    # 構造化
    st = None
    raw = meeting.get("minutes_struct")
    if raw:
        try:
            st = _json_p.loads(raw) if isinstance(raw, str) else raw
        except Exception:
            st = None

    def _arr(v):
        if not v:
            return []
        if isinstance(v, str):
            try:
                v = _json_p.loads(v)
            except Exception:
                return [x.strip() for x in v.split("\n") if x.strip()]
        return v if isinstance(v, list) else []

    topics = _arr((st or {}).get("topics"))
    discussion = (st or {}).get("discussion") or []
    if isinstance(discussion, list):
        discussion = "\n".join(discussion)
    decisions = _arr(meeting.get("decisions")) or _arr((st or {}).get("decisions"))
    todos = _arr(meeting.get("todos")) or _arr((st or {}).get("todos"))
    other = (st or {}).get("other") or []
    if isinstance(other, list):
        other = "\n".join(other)

    # staff-minutes-unified-v1: 担当者会議と同じデザイン言語で、勉強会・職員会議も
    # 1枚に収める。構成は 議題／議論の内容／決定事項／ToDo／その他。style は互換のため残すが同一レイアウト。
    _u_css = """
      * { box-sizing:border-box; }
      body { font-family:'Noto Sans CJK JP','IPAexGothic',sans-serif; color:#202124;
             font-size:10.5pt; line-height:1.5; margin:0; padding:0; }
      .u-ttl { display:flex; align-items:center; gap:6px; color:#0C447C; font-size:12pt; font-weight:bold; }
      .u-tag { font-size:8pt; color:#888; border:0.5pt solid #bbb; border-radius:4px; padding:0 5px; font-weight:normal; }
      .u-name-row { border-bottom:1.5pt solid #b8c2cc; padding:2px 0 5px; margin:5px 0 8px; }
      .u-name { font-size:15pt; font-weight:bold; }
      .u-date { text-align:right; font-size:10pt; color:#5f6368; }
      .u-date b { color:#202124; font-size:11pt; }
      .u-info td { font-size:9.5pt; padding:1px 0; color:#5f6368; }
      .u-h { color:#0C447C; font-weight:bold; border-left:3pt solid #185FA5; padding-left:6px; margin:9px 0 3px; font-size:10.5pt; }
      .u-body { padding-left:2px; }
      .u-cn { margin:1px 0; padding-left:2px; }
      .u-cn-n { display:inline-block; min-width:15px; color:#185FA5; font-weight:bold; }
      .u-todo { border:0.5pt solid #b8c2cc; border-radius:6px; padding:4px 10px; margin-bottom:3px; }
    """
    def _items_line(arr):
        return "　".join("・" + esc(x) for x in arr) if arr else "（記載なし）"
    _dec = "".join(
        f'<div class="u-cn"><span class="u-cn-n">{i+1}</span><span>{esc(x)}</span></div>'
        for i, x in enumerate(decisions)
    ) or '<div class="u-cn"><span>（記載なし）</span></div>'
    _todo = "".join(f'<div class="u-todo">{esc(x)}</div>' for x in todos) or '<div class="u-body">（記載なし）</div>'
    _other = (esc(other).replace("\n", "／") if other else "（記載なし）")
    return f"""<!DOCTYPE html><html><head><meta charset="utf-8"><style>{_u_css}</style></head><body>
    <div class="u-ttl">勉強会・会議の記録　<span class="u-tag">社内</span></div>
    <table width="100%" class="u-name-row"><tr>
      <td><span class="u-name">{title}</span></td>
      <td class="u-date">開催日　<b>{date or "（記載なし）"}</b></td>
    </tr></table>
    <table width="100%" class="u-info"><tr><td>参加者：{attendees}</td></tr></table>

    <div class="u-h">議題</div>
    <div class="u-body">{_items_line(topics)}</div>

    <div class="u-h">議論の内容</div>
    <div class="u-body">{esc(discussion) or "（記載なし）"}</div>

    <div class="u-h">決定事項</div>
    <div class="u-body">{_dec}</div>

    <div class="u-h">ToDo</div>
    <div class="u-body">{_todo}</div>

    <div class="u-h">その他・次回に向けて</div>
    <div class="u-body">{_other}</div>
    </body></html>"""


def _staff_minutes_style_css(style):
    """8スタイルの装飾。担当者会議のテイストを社内議事録向けに簡易化。"""
    style = (style or "a").lower()
    palette = {
        "a": "#2e7d32", "b": "#1565c0", "c": "#424242", "d": "#00838f",
        "e": "#6a1b9a", "f": "#ad1457", "g": "#4527a0", "h": "#37474f",
    }
    c = palette.get(style, "#2e7d32")
    base = f".sec {{ border-left-color: {c}; color: {c}; }} h1 {{ color: {c}; }}"
    if style == "b":  # ビジネス: 見出しに下線
        base += f" .sec {{ border-bottom: 1px solid {c}33; padding-bottom:2px; }}"
    elif style == "c":  # フォーマル: 罫線強め
        base += " table.grid td, table.grid th { border-color:#888; }"
    elif style == "d":  # サイドバー: 見出し帯
        base += f" .sec {{ background:{c}12; padding:4px 8px; border-left-width:6px; }}"
    elif style == "e":  # カード: box影
        base += " .box { box-shadow:0 1px 3px rgba(0,0,0,.12); border-radius:6px; }"
    elif style == "f":  # タイムライン: 議題に丸
        base += f" ul li {{ list-style:none; position:relative; padding-left:14px; }} ul li:before {{ content:'●'; color:{c}; position:absolute; left:0; font-size:8pt; }}"
    elif style == "g":  # エグゼクティブ: 大見出し
        base += " .sec { font-size:13pt; }"
    elif style == "h":  # モダンミニマル: 細字・余白
        base += " .sec { font-weight:600; border-left-width:3px; } body { line-height:1.7; }"
    return base


@app.route("/api/staff_minutes/pdf", methods=["GET"])
@login_required
def api_staff_minutes_pdf():
    """議事録PDFを出力。style=a〜h で装飾切替。"""
    ok, f_code, my_name = _staff_minutes_gate_ok()
    if not ok:
        return jsonify({"status": "error", "message": "この機能は有効化されていません"}), 403
    try:
        supabase = get_supabase()
        rec_id = (request.args.get("id") or "").strip()
        if not _SM_UUID_RE.match(rec_id):
            return jsonify({"status": "error", "message": "id が不正です"}), 400
        style = (request.args.get("style") or "a").strip().lower()
        if style not in ("a", "b", "c", "d", "e", "f", "g", "h"):
            style = "a"
        r = supabase.table("staff_meetings").select("*")\
            .eq("id", rec_id).eq("facility_code", f_code).execute()
        if not r.data:
            return jsonify({"status": "error", "message": "議事録が見つかりません"}), 404
        meeting = r.data[0]
        html_str = _staff_minutes_pdf_html(meeting, style)
        pdf_bytes = _mtg_pdf_render_fit(html_str)  # staff-minutes-unified-v1: 必ず1ページ
        from urllib.parse import quote as _quote_p
        from flask import make_response
        fname = "議事録_" + (meeting.get("meeting_date") or "") + ".pdf"
        response = make_response(pdf_bytes)
        response.headers["Content-Type"] = "application/pdf"
        response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
        response.headers["Content-Disposition"] = 'attachment; filename="staff_minutes.pdf"; filename*=UTF-8\'\'' + _quote_p(fname)
        return response
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500
